window.JASTROW_CHUNKS[50]={"20000":{"h":"*נֵס II","r":"N00912","html":"<div class=\"sense\"><i>island</i>. <span class=\"citation\">Deut. R. s. 2</span>, v. <a href=\"#\" data-headword=\"נִיסָא\">נִיסָא</a>.—Pl. <span dir=\"rtl\">נִיסִים</span>, <span dir=\"rtl\">נִיסִין</span>, <span dir=\"rtl\">נֵסִין</span>, v. <a href=\"#\" data-headword=\"נִיסָא\">נִיסָא</a>.</div>","alt":[]},"20001":{"h":"נֵס","r":"N00913","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>flag, sign, miraculous event</i>. <span class=\"citation\">Targ. Y. Num. XXV, 8</span>; a. fr.—Y. Pes. V, 32ᶜ bot. <span dir=\"rtl\">נסא הוה רב</span> a great event (delivery from danger) had occurred; <span class=\"citation\">Y. Taan. III, end, 67ᵃ</span> <span dir=\"rtl\">ניסא</span>. <span class=\"citation\">Ber. 54ᵃ</span> <span dir=\"rtl\">נ׳ דרבים</span> a providential event which concerns the community, opp. <span dir=\"rtl\">נ׳ דיחיד</span>. <span class=\"citation\">Meg. 3ᵇ</span> <span dir=\"rtl\">משום פרסומי נ׳</span> because it is a duty to proclaim the wonderful event (in the Book of Esther); <span class=\"citation\">Sabb. 23ᵇ</span> <span dir=\"rtl\">פרסומי נ׳</span> to proclaim the wonderful events (of the Maccabean days, by lighting the candles); a. v. fr.—Pl. <span dir=\"rtl\">נִסִּין</span>, <a href=\"#\" data-headword=\"נסיא\">נִסַּיָּא</a>, <a href=\"#\" data-headword=\"נְסֵי\">נִסֵּי</a>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Targ. O. Ex. XVII, 15</span>. <span class=\"citation\">Targ. Y. II, Num. XXI, 14</span>; a. fr.—Y. Ter. VIII, end, 46ᶜ. <span class=\"citation\">Yoma 21ᵃ</span> <span dir=\"rtl\">נ׳ דגואי</span> wonders which happened within the Temple; <span dir=\"rtl\">נ׳ דבראי</span> outside of the Temple. Ib.ᵇ <span dir=\"rtl\">נ׳ דקביעי</span> permanent, regularly recurring wonders; a. fr.</div><div class=\"sense\"><b>—2)</b>  (= <a href=\"#\" data-headword=\"נִסָּיוֹן\">נִסָּיוֹן</a>) <i>trial.</i>—<i>Pl.</i> as ab. <span class=\"citation\">Targ. Y. II, Ex. XV, 25</span>.—Y. Maas. Sh. V, end, 55ᶜ (oneirocritical play on <a href=\"#\" data-headword=\"נִיסַן\">נִיסַן</a>) <span dir=\"rtl\">וניסין לית את חמי</span> and thou shalt experience no trials; (<span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\"><span dir=\"rtl\">רבתי נִסְיוֹנִין</span> (חד מתלמ׳</span>); <span class=\"citation\">Ber. 56ᵇ</span> <span dir=\"rtl\">ולא אתית לידי נסיון</span>).</div>","alt":["נִסָּא","נִי׳ I"]},"20002":{"h":"נִסָּא II","r":"N00914","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Nissa</i>, an Amora. <span class=\"citation\">Y. Erub. II, 20ᵃ</span> bot. Y. B. Bath. II, beg. 13ᵇ. <span class=\"citation\">Y. Ter. XI, end, 48ᵇ</span>; a. fr.</div>","alt":["נִסָּה","נִי׳"]},"20003":{"h":"נָסָא","r":"N00915","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נסי\">נסי</a></div>","alt":["נְסָא"]},"20004":{"h":"נסאטאי","r":"N00916","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גַּסְיוֹטָאֵי\">גַּסְיוֹטָאֵי</a></div>","alt":[]},"20005":{"h":"נְסַב","r":"N00917","html":"<div class=\"sense\"> (corresp. to h. <a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a> a. <a href=\"#\" data-headword=\"נָטַל\">נָטַל</a>) <i>to lift up; to take; to carry</i>. <span class=\"citation\">Targ. Gen. II, 21</span>; a. fr.—<span dir=\"rtl\">נ׳ ויהב</span> (= h. <span dir=\"rtl\">נשא ונתן</span>) <i>to deal</i>. <span class=\"citation\">Targ. Zech. V, 6</span>, sq.—<a href=\"#\" data-headword=\"נ׳\">נ׳</a> (<span dir=\"rtl\">איתתא</span>) <i>to take to wife, marry</i>. <span class=\"citation\">Targ. Gen. IV, 19</span>; a. fr.—<span dir=\"rtl\">נ׳ אפין</span> (= h. <span dir=\"rtl\">נשא פנים</span>) <i>to be partial, favor</i>. <span class=\"citation\">Targ. O. Gen. XXXII, 21</span>. <span class=\"citation\">Targ. Y. Ex. XXIII, 3</span>.—Part. pass. <a href=\"#\" data-headword=\"נְסֵיב\">נְסִיב</a>; f. <a href=\"#\" data-headword=\"נְסִיבָא I\">נְסִיבָא</a>, <a href=\"#\" data-headword=\"נְסִיבָא II\">נְסִיבְתָּא</a>; pl. <span dir=\"rtl\">נְסִיבִין</span>; <span dir=\"rtl\">נְסִיבָן</span>. <span class=\"citation\">Targ. O. Gen. II, 23</span>. <span class=\"citation\">Targ. Y. Num. V, 22</span> <a href=\"#\" data-headword=\"נְסִיבָא II\">נסיבתא</a> wedded.—נ׳ אפין <i>respected</i>. <span class=\"citation\">Targ. Is. III, 3</span> (not <a href=\"#\" data-headword=\"נְסֵיב\">נְסֵב</a>); a. fr.—Y. B. Mets. II, 8ᶜ bot. <span dir=\"rtl\">וחוא נָסֵיב כולא וכ׳</span> and he takes everything (entrusted to him) and runs away. <span class=\"citation\">Gen. R. s. 84</span>, beg. <span dir=\"rtl\">דיִסַּב מאה וכ׳</span> that he should receive one hundred lashes; <span class=\"citation\">Yalk. Job 904</span>; <span class=\"citation\">Yalk. Gen. 140</span> <span dir=\"rtl\">דיהיב</span> (corr. acc.). <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">סַב מובלא וכ׳</span> take that load &amp;c. Ib. <span dir=\"rtl\">סב לי טימיתהון וכ׳</span> take their price at my hands and carry them &amp;c. Y. Kidd. IV, 66ᵃ <span dir=\"rtl\">נחות דרג וסב איתתא</span>; <span class=\"citation\">Yeb. 63ᵃ</span> <span dir=\"rtl\">נְסַיב איתתא וכ׳</span>, v. <a href=\"#\" data-headword=\"דְּרַג\">דְּרַג</a>. <span class=\"citation\">Macc. 11ᵃ</span>; <span class=\"citation\">Gen. R. s. 80</span>, v. <a href=\"#\" data-headword=\"גְּזַר\">גְּזַר</a>; a. v. fr.—<span class=\"citation\">Zeb. 11ᵇ</span> <span dir=\"rtl\">היא אַגְּרָרָהּ נַסְבָהּ</span> the redactor took this up (inserted it) by the way, v. <a href=\"#\" data-headword=\"גְּרָרָא II\"><span dir=\"rtl\">גְּרָרָא</span> II</a>.—<span class=\"citation\">Cant. R. to II, 16</span> <span dir=\"rtl\">והוה נ׳ נפש</span> and he took courage, felt better; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ואיתנסיב נפש</span> read: <span dir=\"rtl\">והוית נסיב נפש</span> and I felt better.—<span class=\"citation\">Y. Sabb. I, 3ᵃ</span> bot. <span dir=\"rtl\">נ׳ לידוי</span> washed his hands (v. <a href=\"#\" data-headword=\"נָטַל\">נָטַל</a>). <span class=\"citation\">Y. Ber. VIII, 12ᵃ</span> bot. <span dir=\"rtl\">נַסְבוּן ידיכון</span> (not <span dir=\"rtl\">נסבין</span>) wash your hands; <span class=\"citation\">ib.</span> <span dir=\"rtl\">סב בריך</span> wash thy hands and say grace.—[<span class=\"citation\">Y. Maasr. IV, 51ᵇ</span> bot. <span dir=\"rtl\">והוון סבין מיניה</span>, perh. to be read: <span dir=\"rtl\">והוון נסבין</span>, they took from him.]</div><div class=\"sense\"><b>Af. אַנְסֵיב  אַסֵּיב</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"נְסַב\">אֲסֵיב</a> <i>to cause to take</i>, esp. <i>to give in marriage to, to allow to marry</i>. <span class=\"citation\">Targ. Zech. III, 5</span>. <span class=\"citation\">Targ. Y. Gen. XXXVI, 3</span> <span dir=\"rtl\">דאֲסִיבָהּ</span> (not … <a href=\"#\" data-headword=\"בָּא I\">בא</a>); a. e.—<span class=\"citation\">Yeb. 121ᵃ</span> <span dir=\"rtl\">ואַנְסְבָהּ רב … לדביתהו</span> (not <span dir=\"rtl\">ואנסבו</span>) and R. D. allowed his wife to marry again; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ואנסבוה</span> (corr. acc.). <span class=\"citation\">Ib. 120ᵃ</span> top <span dir=\"rtl\">לאַנְסוּבֵי לצרה וכ׳</span> (Rashi: <span dir=\"rtl\">לאִינְּס׳</span>, <i>Ithpe.</i>) to permit her rival to marry before her. <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">ואַסְּבוּן יתיה איתתא וכ׳</span> and they made him marry another wife; <span class=\"citation\">Yalk. Is. 352</span> <span dir=\"rtl\">אסביתיה</span>, read: <span dir=\"rtl\">אַסַּב יתיה</span>; a. fr.—[<span class=\"citation\">Sabb. 123ᵃ</span> אַסּוּבֵי ינוקא <i>to handle</i>, treat the infant; v., however, <a href=\"#\" data-headword=\"*אֲסַב\">אֲסַב</a>.]</div></div><div class=\"sense\"><b>Pa. נַסֵּב</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נסאטאי\">same</a>. <span class=\"citation\">B. Mets. 105ᵃ</span> <span dir=\"rtl\">קא מְנַסְּבַת וכ׳</span> thou causest my land to bear a bad reputation. Yeb. l. c. <span dir=\"rtl\">מְנַסְּבִינָן לה לצרה</span> we allow the rival to marry; a. fr.</div></div><div class=\"sense\"><b>Ithpa. אִתְנַסֵּיב</b> </div><div class=\"sense\"><b>Ithpe. אִתְנְסִיב  אִינְּסִּיב</b> <div class=\"sense\"><i>to be taken; to be taken away; to be married</i>. <span class=\"citation\">Targ. O. Num. XXXV, 17</span>. <span class=\"citation\">Targ. Y. Gen. II, 23</span>. <span class=\"citation\">Targ. Jud. XVII, 2</span>; a. fr.—<span class=\"citation\">Snh. 51ᵃ</span> <span dir=\"rtl\">משום דאִינְּסִיבָא להו להני</span> because she is married to one of those. <span class=\"citation\">Yeb. 120ᵃ</span> (repeatedly) <a href=\"#\" data-headword=\"נְסַב\">אינסיב</a> (read <span dir=\"rtl\">אינסיבא</span>). <span class=\"citation\">Ib. 43ᵇ</span> <span dir=\"rtl\">אִינְּסוּבֵי הוא דלא וכ׳</span> to marry she is not allowed, but to be betrothed &amp;c.; a. fr.—<span class=\"citation\">Cant. R. to II, 16</span> <span dir=\"rtl\">איתנסיב</span>, v. supra.</div></div>","alt":["נְסֵיב"]},"20006":{"h":"נִסְבָּא","r":"N00918","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַב\">preced.</a>) <i>selection, choice</i>. <span class=\"citation\">Targ. Ez. XVII, 5</span> <span dir=\"rtl\">גפן נ׳</span> ed. Lag. a choice vine (ed. <a href=\"#\" data-headword=\"נִצְבָּא\">נִצְבָּא</a>; h. text <a href=\"#\" data-headword=\"צַפְצָפָה\">צפצפה</a>).</div>","alt":[]},"20007":{"h":"נִסְבָא","r":"N00919","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נִסְבָּא\">preced.</a>) <i>free-will offering</i>.—Pl. <span dir=\"rtl\">נִסְבָאתָא</span>, <a href=\"#\" data-headword=\"נִסְבָא\">נִסְבָתָא</a>. <span class=\"citation\">Targ. Ps. CXIX, 108</span> (ed. Wil. <span dir=\"rtl\">נִכְסְ׳</span>, corr. acc.). <span class=\"citation\">Targ. Y. Deut. XII, 17</span> (ed. Amst. a. oth. <span dir=\"rtl\">נסכ׳</span>, corr. acc.); v. <a href=\"#\" data-headword=\"נְסִיבָא I\">נְסִיבָא</a>.</div>","alt":["נִסְבְּתָא"]},"20008":{"h":"נָסוֹחָא","r":"N00920","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַח\">נְסַח</a>) <i>one who removes, sweeper</i>. <span class=\"citation\">Y. Yoma III, 40ᶜ</span> top, v. <a href=\"#\" data-headword=\"מַגְלְיינָא\">מגְלְיָינָא</a>.</div>","alt":["נָסוֹחָה"]},"20009":{"h":"נְסוֹרֶת","r":"N00921","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָסַר\">נָסַר</a>) <i>chips, saw-dust</i>. <span class=\"citation\">Sabb. IV, 1</span> (<span class=\"citation\">49ᵃ</span>) <span dir=\"rtl\">נ׳ של חרשין וכ׳</span> (Talm. ed. <span dir=\"rtl\">נְסוֹרוֹת</span> <i>pl.</i>) (fine) saw-dust of the carpenters; Y. ib. 6ᵈ bot. <span dir=\"rtl\">אנן תנינן נ׳ … נעורת וכ׳</span> we read <i>n’soreth</i>, the teachers of the house of Rabbi read <i>n’ʿoreth</i>, which shows that both mean the same. <span class=\"citation\">B. Kam. X, 10</span> (<span class=\"citation\">119ᵃ</span>) <span dir=\"rtl\">אף הנ׳ של בעה&quot;ב</span> Y. ed. (Mish. ed. <span dir=\"rtl\">הנִסָּרוֹת</span>, some Bab. ed. <span dir=\"rtl\">הנִסָּרִים</span>; v. Rabb. D. S. a. l. note 200; Ar. <span dir=\"rtl\">הנסורות</span>) even the saw-dust belongs to the employer.</div>","alt":[]},"20010":{"h":"*נְסוֹרְתָּה","r":"N00922","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסוֹרֶת\">preced.</a>) <i>saw-dust</i>, name of a certain <i>aromatic plant</i>. <span class=\"citation\">Y. Shebi. VII, beg. 37ᵇ</span></div>","alt":[]},"20011":{"h":"נָסַח","r":"N00923","html":"<div class=\"sense\"><i>to remove</i>. <span class=\"citation\">Sot. 42ᵇ</span>; <span class=\"citation\">Yoma 75ᵃ</span> (ref. to <span dir=\"rtl\">יַשְׁחֶנָה</span>, <span class=\"citation\">Prov. XII, 25</span>) <span dir=\"rtl\">יִשְׂחֶנָּה מדעתו</span> (Ms. M. 2 <span dir=\"rtl\">יַסִּיחֶנָּה</span>, v. Rabb. D. S. a. l. note 50) let him banish it from his mind; <span class=\"citation\">Yalk. Prov. 950</span>; <span class=\"citation\">Snh. 100ᵇ</span> <span dir=\"rtl\">יַשִּׂיחֶנָּה</span>; v. <a href=\"#\" data-headword=\"סוּחַ\">סוּחַ</a>.</div><div class=\"sense\"><b>Hif. הִסִּיחַ</b> <div class=\"sense\"> (with <a href=\"#\" data-headword=\"דַּעַת\">דעת</a>) <i>to divert the mind, to discard</i>. <span class=\"citation\">Sabb. 82ᵃ</span> <span dir=\"rtl\">יַסִּיחַ דעתו</span>, expl. <span dir=\"rtl\">יסיח דעתו מדברים אחרים</span> he must discard from his mind everything else. Y. Ber. VI, end, 10ᵈ <span dir=\"rtl\">ה׳ דעתו</span> (ed. Krot. <a href=\"#\" data-headword=\"נָסַע\">הִסִּיעַ</a>) if he has abandoned the thought (of drinking more wine); a. e.—Snh. l. c.; Yoma l. c., v. supra.—V. <a href=\"#\" data-headword=\"הֶסֵּיחַ\">הֶסֵּיחַ</a>.</div></div>","alt":["(נָשַׂח)"]},"20012":{"h":"נְסַח","r":"N00924","html":"<div class=\"sense\"><b>1)</b> <i>to remove, take out</i>. <span class=\"citation\">Targ. Jud. XIV, 9</span> (h. text <a href=\"#\" data-headword=\"רָדָה\">רדה</a>).—Part. pass. <span dir=\"rtl\">נְסִיחַ</span>. Ib.—<span class=\"citation\">Cant. R. to V, 14</span> <span dir=\"rtl\">אימיה נָסְחָא וכ׳</span> his mother took the bread out of the oven, and he ate; Pesik. B’shall., p. 90ᵇ, sq. <span dir=\"rtl\">נשא</span> (corr. acc.).—[</div><div class=\"sense\"><b>2)</b> <i>to lift, weigh</i>.—Denom. <a href=\"#\" data-headword=\"מְסָחָא\">מְסָחָא</a>, <a href=\"#\" data-headword=\"מִסְחֲתָא\">מִסְחֲתָא</a>.]</div><div class=\"sense\"><b>Pa. נַסַּח</b> <div class=\"sense\"><i>to remove, sweep out; to exile</i>. <span class=\"citation\">Lam. R. to I, 13</span> (expl. <span dir=\"rtl\">וירדנה</span>, ib., with ref. to Jud. l. c.) <span dir=\"rtl\">נַסְּחָהּ</span> (not <span dir=\"rtl\">נסחא</span>) he removed (exiled) her.—Part. pass. <a href=\"#\" data-headword=\"מִנַּסָּח\">מְנַסַּח</a>. <span class=\"citation\">Targ. Prov. XXIX, 21</span> (h. text <a href=\"#\" data-headword=\"מָנוֹן\">מנון</a>!).</div></div><div class=\"sense\"><b>Ithpe. אִתְנְסַח</b> <div class=\"sense\"><i>to be pulled out</i>. <span class=\"citation\">Targ. Esth. VII, 9</span> (fr. <span class=\"citation\">Ezra VI, 11</span>).</div></div><div class=\"sense\"><b>Af. אַסַּח</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"נָסַח\">preced.</a> <i>Hif.</i> <span class=\"citation\">Zeb. 20ᵇ</span> <span dir=\"rtl\">אַסּוּחֵי מַסַּח דעתיה</span> he discards (the service) from his mind; <span dir=\"rtl\">לא מַסַּח</span> he does not. <span class=\"citation\">Pes. 103ᵇ</span> <span dir=\"rtl\">אַסְּחִיתוּ דעתייכו</span> you have abandoned the thought (of drinking). <span class=\"citation\">Gitt. 53ᵇ</span> <span dir=\"rtl\">א׳ דעתיה</span> he ceased to have his mind on it (as sacred matter that must be guarded); a. fr.</div></div>","alt":[]},"20013":{"h":"נסי","r":"N00925","html":"<div class=\"sense\"><i>to lift up, take, carry</i>, v. <a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>.</div>","alt":["נָסָא"]},"20014":{"h":"נסי ²","r":"N00926","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"נסי\">preced.</a>) <i>to lift up</i>.</div><div class=\"sense\"><b>Pi. נִסָּה</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נסי\">same</a>; 2) (denom. of <a href=\"#\" data-headword=\"נֵס\">נֵס</a>) <i>to put up a sign; to ask for a test</i> (cmp. <span class=\"citation\">Is. VII, 11</span>, sq.); <i>to try, test</i>. <span class=\"citation\">Gen. R. s. 55</span>, beg. (interpret. <a href=\"#\" data-headword=\"נִסָּא II\">נִסָּה</a>, <span class=\"citation\">Gen. XXII, 1</span>) <span dir=\"rtl\">בשביל לנַסּוֹתָן … לגדלן וכ׳</span> in order to lift them up (as a standard) for the world, to raise them &amp;c., v. <a href=\"#\" data-headword=\"נֵס\">נֵס</a>. Ib. (ref. to Gen. l. c.) R. J. says <span dir=\"rtl\">גדלו כנס וכ׳</span> he raised him &amp;c.; R. A. says, <span dir=\"rtl\">נ׳ אותן בוודאי</span> he really tried him, v. <a href=\"#\" data-headword=\"וַדַּאי\">וַדַּאי</a>. Ib. <span dir=\"rtl\">אין הקב&quot;ה מְנַסֶּה וכ׳</span> the Lord does not test the wicked, but only the righteous; ib. s. 32; s. 34. Mekh. B’shall., Vayassa, s. 1 (ref. to <span class=\"citation\">Ex. XV, 25</span>) <span dir=\"rtl\"><span dir=\"rtl\">גדולה</span>(<a href=\"#\" data-headword=\"ל\">ל</a>) <span dir=\"rtl\">שם נשא לו</span></span> there he raised him (Moses) to greatness; … <span dir=\"rtl\">שם נסה המקום את ישראל</span> there God tested Israel. Ib. Yithro, Baḥod., s. 9 <span dir=\"rtl\">לבעבור נַסּוֹת אתכם בשביל לגדל אתכם</span> (<span class=\"citation\">Ex. XX, 28</span>) ‘to lift you up’, to raise you. <span class=\"citation\">Arakh. 15ᵃ</span> <span dir=\"rtl\">עשר נסיונות נִיסּוּ וכ׳</span> ten times did our ancestors try the Lord; <span class=\"citation\">Ab. V, 4</span>; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְנַסֶּה</b> </div><div class=\"sense\"><b>Nithpa. נִתְנַסֶּה</b> <div class=\"sense\"><i>to be tried</i>. Ib. 3. <span class=\"citation\">Yalk. Ps. 777</span> <span dir=\"rtl\">הראשונים מִתְנַסִּים ביד הקב&quot;ה … אבל האחרונים נִתְנַסּוּ וכ׳</span> the ancients were tried by the Lord …, but the latter generations were tried by the nations; a. fr.</div></div>","alt":["נָסָה"]},"20015":{"h":"נְסֵי","r":"N00927","html":"<div class=\"sense\"><b>1)</b> <i>to lift up</i>. <span class=\"citation\">Targ. O. Deut. XXVIII, 56</span> <span dir=\"rtl\">נְסִיאַת</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"נְשִׂיאוּתָא\">נַסִּי׳</a>, Pa.); Y. <span dir=\"rtl\">נַסְיַית</span> (h. text <span dir=\"rtl\">נִסְּתָה</span>). <span class=\"citation\">Targ. Ps. IV, 7</span> <a href=\"#\" data-headword=\"נְשָׂא\">נְשָׂא</a> (h. text <a href=\"#\" data-headword=\"נסי ²\">נְסָה</a>).—[Pesik. B’shall., p. 91ᵃ, v. <a href=\"#\" data-headword=\"נְסַח\">נְסַח</a>.]</div><div class=\"sense\"><b>—2)</b> <i>to take, receive, carry</i> (v. <a href=\"#\" data-headword=\"נְסַב\">נְסַב</a>). <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">לא נַסְיָין להון</span> they (the areas described) could not receive (would have no room for) them; <span class=\"citation\">Y. Taan. IV, 69ᵇ</span> <span dir=\"rtl\">לא נַסְיָיהּ</span>. Y. Maas. Sh. IV, 54ᵈ נַסְתּוֹן בר קפר Bar Ḳ. took them. <span class=\"citation\">Lev. R. s. 6</span> <span dir=\"rtl\">נַסְתֵּיה לקניא וכ׳</span> he took the cane and knocked it down. <span class=\"citation\">Lev. R. s. 34</span>, end <span dir=\"rtl\">נסאתיה וחמאי ליה וכ׳</span>, read: <span dir=\"rtl\">נסא יתיה ואחמי וכ׳</span> he took him along and showed to him &amp;c.; (<span class=\"citation\">Yalk. Is. 355</span> <span dir=\"rtl\">נסביה ואחמתיה וכ׳</span>).—<span class=\"citation\">Pesik. R. s. 22</span> <span dir=\"rtl\">נשא ואפקדיה וכ׳</span> he took (his money) and put it in trust with him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נַסְתָּהּ ויהבה ליה</span> she took it (the deposited money) and gave it to him; a. fr.</div><div class=\"sense\"><b>Pa. נֵסֵּי</b> <div class=\"sense\"><b>1)</b> <i>to find out by sign, to divine</i>. <span class=\"citation\">Targ. O. Gen. XXX, 27</span>.</div><div class=\"sense\"><b>—2)</b> <i>to try, test; to attempt</i>. <span class=\"citation\">Targ. O. Deut. XXVIII, 56</span>, v. supra.—<span class=\"citation\">Targ. Esth. V, 14</span> <span dir=\"rtl\">למְנֵסְיָא צליבא</span> to test the (strength of) the gallows. <span class=\"citation\">Targ. Ex. XVI, 4</span>; a. fr.—<span class=\"citation\">Snh. 107ᵃ</span> מְנַסִּינָא לך I will try thee. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אמר מינסנא לך</span> (corr. acc.). <span class=\"citation\">Ab. Zar. 15ᵃ</span> <span dir=\"rtl\">ניסייה ניהלי</span>, read: <span dir=\"rtl\">נִינַסְּיָיהּ</span> let us try the animal for me; a. e.</div></div><div class=\"sense\"><b>Af. אַנְסֵי  הַנְסֵי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נסי ²\">same</a>. <span class=\"citation\">Targ. Ps. LXXVIII, 56</span> (Ms. <i>Pa</i>.). <span class=\"citation\">Targ. Y. II, Gen. XXII, 1</span>.</div></div><div class=\"sense\"><b>Ithpa. אִיתְנַסֵּי  אִינַּסֵּי</b> <div class=\"sense\"><b>1)</b> <i>to be lifted up</i>. <span class=\"citation\">Targ. Ps. LX, 6</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be tried</i>. Targ. II Esth. V, 14.—Snh. l. c. <span dir=\"rtl\">אינהו מִינַּסּוּ לי … מִינַּסְּיַת לי</span> they have been tried (proved true) to me, thou hast not.</div></div>","alt":["נְסָא","(נְשָׂא)"]},"20016":{"h":"נסיא","r":"N00928","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲתָאנַסְיָא\">אֲתָאנַסְיָא</a>.—<span dir=\"rtl\">חניס נ׳</span>, v. <a href=\"#\" data-headword=\"חֲנִיסְנְסַיָּא\">חֲנִיסְנְסַיָּא</a>.</div>","alt":["נסייא","אתא נ׳"]},"20017":{"h":"נְסֵיב","r":"N00929","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְסַב\">נְסַב</a></div>","alt":[]},"20018":{"h":"נְסִיבָא I","r":"N00930","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסֵיב\">preced.</a>) <i>that which is taken, assessment, tax</i>. <span class=\"citation\">Targ. O. Num. XXXI, 28</span> (h. text <span dir=\"rtl\">מכס</span>); <span class=\"citation\">ib. 39</span>; a. fr.—<span class=\"citation\">Targ. O. Lev. XXVII, 23</span> (h. text <span dir=\"rtl\">מכסת</span>).</div>","alt":[]},"20019":{"h":"נְסִיבָא II","r":"N00931","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> 1) <a href=\"#\" data-headword=\"נְסִיבָא I\">same</a>. f. </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נְסִיבָא I\">same</a>. <span class=\"citation\">Targ. Y. Num. XXXI, 37</span>; <span class=\"citation\">39</span>; a. fr.—2) <i>that which is lifted up</i> <a href=\"#\" data-headword=\"תְּרוּמָה\">(תרומה</a>), <i>free-will offering</i>. <span class=\"citation\">Targ. Y. Lev. XXII, 23</span>; <span class=\"citation\">21</span>; a. e.—[נְסִיבְתָּא <i>married</i>, v. <a href=\"#\" data-headword=\"נְסַב\">נְסַב</a>.]—V. <a href=\"#\" data-headword=\"נִסְבָא\">נִסְבָא</a>.</div>","alt":["נְסִיבְתָּא"]},"20020":{"h":"נַסְיוּבֵי","r":"N00932","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">נסיבבי</span>; <a href=\"#\" data-headword=\"נְסִיבָא II\">preced.</a> wds.; cmp. <a href=\"#\" data-headword=\"פָּרַשׁ\">פָּרַשׁ</a> a. <a href=\"#\" data-headword=\"פֶּרֶשׁ\">פֶּרֶשׁ</a>) [<i>that which is separated</i>,] <span dir=\"rtl\">נ׳ דחלבא</span>, or <a href=\"#\" data-headword=\"נ׳\">נ׳</a> <i>whey</i>. <span class=\"citation\">Pes. 42ᵃ</span>. <span class=\"citation\">B. Mets. 68ᵇ</span> <span dir=\"rtl\">נ׳ ותותרי</span> whey and refuse of wool. <span class=\"citation\">Ab. Zar. 35ᵇ</span> <span dir=\"rtl\">איכא נ׳ דלא קיימי</span> there is the whey which does not curdle (and which may contain unclean milk).</div>","alt":[]},"20021":{"h":"נסיוטאי","r":"N00933","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גַּסְיוֹטָאֵי\">גַּסְיוֹטָאֵי</a></div>","alt":[]},"20022":{"h":"נִסָּיוֹן","r":"N00934","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נסי ²\">נָסָה</a>) </div><div class=\"sense\"><b>1)</b> <i>lifting up</i>. <span class=\"citation\">Gen. R. s. 55</span>, beg. <span dir=\"rtl\">נ׳ אחר נ׳ גידולין וכ׳</span> (ref. to <span class=\"citation\">Ps. LX, 6</span></div><div class=\"sense\"><b>—2)</b> <i>trial, test; temptation</i>. <span class=\"citation\">Snh. 107ᵃ</span> דוד … הביא עצמו לידי נ׳ David … placed himself in the power of trial (asked to be tried, <span class=\"citation\">Ps. XXVI, 2</span>). <span class=\"citation\">Ber. 60ᵇ</span> <span dir=\"rtl\">אל תביאני … לידי נ׳</span> suffer me not to come within the power of sin, iniquity, or temptation. <span class=\"citation\">Sifré Deut. 21</span> <span dir=\"rtl\">נותן אתה לי לנ׳</span> wilt thou let me have (the animal) for a trial?; a. fr.—Pl. <span dir=\"rtl\">נִסְיוֹנוֹת</span>, <span dir=\"rtl\">נִסְיוֹנִין</span>. <span class=\"citation\">Ab. V, 3</span> עשרה נ׳ נתנסה וכ׳ Abraham underwent ten trials and stood all of them. <span class=\"citation\">Arakh. 15ᵃ</span> <span dir=\"rtl\">עשר נ׳</span>, v. <a href=\"#\" data-headword=\"נסי ²\">נָסָה</a>. <span class=\"citation\">Num. R. s. 17</span> <span dir=\"rtl\">נ׳ אחרים</span> additional trials; a. fr.</div>","alt":["נִיסָּ׳"]},"20023":{"h":"נִסָּיוֹן ²","r":"N00935","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נִסָּיוֹן\">same</a>, <i>sign, test, trial</i>. <span class=\"citation\">Targ. Y. Num. XXVI, 10</span> (h. text <a href=\"#\" data-headword=\"נֵס\">נֵס</a>). <span class=\"citation\">Targ. Y. II, Gen. XXII, 1</span>. <span class=\"citation\">Targ. Y. Ex. XV, 25</span>; a. e.—<span class=\"citation\">Ib. XVII, 7</span>, v. <a href=\"#\" data-headword=\"נִסֵּיתָא\">נִסֵּיתָא</a>.—<span class=\"citation\">Ber. 56ᵇ</span>, v. <a href=\"#\" data-headword=\"נִסָּא II\"><span dir=\"rtl\">נִסָּא</span> I</a>.</div><div class=\"sense\"><b>—2)</b> <i>wonder, providential escape, salvation</i>. <span class=\"citation\">Y. Ter. VIII, end, 46ᶜ</span> <span dir=\"rtl\">לנ׳ הוא מיתחמי</span> he appears as a messenger of salvation; (<span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">על נסין</span>).—Pl. <span dir=\"rtl\">נִסְיוֹנִין</span>, <span dir=\"rtl\">נִסְיוֹנֵי</span>. Targ. II Esth. V, 1; a. e.—<span class=\"citation\">Ab. Zar. 15ᵃ</span> <span dir=\"rtl\">משום נ׳</span> on account of the trials (connected with the purchase of animals, and which the Jewish seller may be induced to attend on the Sabbath eve). <span class=\"citation\">Lam. R. to I, 1</span>, v. <a href=\"#\" data-headword=\"נִסָּא II\"><span dir=\"rtl\">נִסָּא</span> I</a>; a. e.</div>","alt":["נִסְיוֹנָא","נִי׳"]},"20024":{"h":"נַסְיוּתָא","r":"N00936","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְשִׂיאוּתָא\">נְשִׂיאוּתָא</a></div>","alt":[]},"20025":{"h":"נסייא","r":"N00937","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נסיא\">נסיא</a></div>","alt":[]},"20026":{"h":"נְסֵיךְ","r":"N00938","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְסַךְ\">נְסַךְ</a></div>","alt":[]},"20027":{"h":"נָסִיךְ","r":"N00939","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>anointed</i>,] <i>viceroy, prince</i> (contradist. to <a href=\"#\" data-headword=\"מֶלֶךְ\">מֶלֶךְ</a>). <span class=\"citation\">Num. R. s. 20</span> (ref. to <span class=\"citation\">Num. XXII, 4</span>) <span dir=\"rtl\">והלא מתחלה נ׳ היה וכ׳</span> but was he not originally a viceroy?… But when Sihon was slain, they appointed him king in his place; Yalk. ib. 765.</div>","alt":[]},"20028":{"h":"נְסִיכָה","r":"N00940","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"נִיסּוּךְ\">נִיסּוּךְ</a>, q. v.</div>","alt":[]},"20029":{"h":"נָסִיס","r":"N00941","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַס\">נסס</a>) <i>falling away, grief</i>. <span class=\"citation\">Tem. 16ᵃ</span> (interpreting <span dir=\"rtl\">עצבי</span>, <span class=\"citation\">I Chr. IV, 10</span>) <span dir=\"rtl\">הריני הולך בנְסִיסִי לשאול</span> (not <span dir=\"rtl\">לנסיסי</span>) I shall go with my grief to the grave (cmp. <span class=\"citation\">Gen. XXXVII, 35</span>; <span class=\"citation\">XLIV, 31</span>; a. e.); Mekh. Yithro, Amal., s. 2 <span dir=\"rtl\">יורד כבן סיסי</span> (corr. acc.); <span class=\"citation\">Yalk. Josh. 27</span> (a. Ar. s. v. <span dir=\"rtl\">בר</span>) <span dir=\"rtl\">ברסיסי</span> (corr. acc.).</div>","alt":[]},"20030":{"h":"נְסִיס","r":"N00942","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נָסִיס\">same</a>, <i>evil, trouble</i>. Targ. II Esth. I, 3 <span dir=\"rtl\">נ׳ לנונין</span> a trouble to the fish. [<span class=\"citation\">Targ. Koh. V, 16</span> <span dir=\"rtl\">בִּנְסִיס</span>, <a href=\"#\" data-headword=\"ב\">ב</a> radical, v. <a href=\"#\" data-headword=\"בְּנַס\">בְּנַס</a>; perh. to be read: <a href=\"#\" data-headword=\"בְּנָסָא\">בִּנְסָא</a>.]—Pl. <span dir=\"rtl\">נְסִיסִין</span>. <span class=\"citation\">Koh. R. to II, 17</span> <span dir=\"rtl\">תלת נ׳ בישין</span> three great evils.</div><div class=\"sense\"><b>—2)</b>  adj. constr. <i>suffering, weak</i>. <span class=\"citation\">Targ. Y. Lev. XXII, 22</span> נ׳ עיני Ar. (ed. <span dir=\"rtl\">עינוי לקיין</span>).</div>","alt":[]},"20031":{"h":"נסיע","r":"N00943","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to I, 11</span> <span dir=\"rtl\">ענתה נ׳</span>, read: <a href=\"#\" data-headword=\"אֲתָאנַסְיָא\">אֲתָאנַסְיָא</a>.</div>","alt":["נסיעה"]},"20032":{"h":"נְסִיעָה","r":"N00944","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָסַע\">נָסַע</a>) <i>moving, marching</i>. <span class=\"citation\">Y. Erub. V, 22ᶜ</span> bot.; <span class=\"citation\">Men. 95ᵃ</span> <span dir=\"rtl\">בנְסִיעָתוֹ</span> when marching, opp. <a href=\"#\" data-headword=\"הֲנָיָיה\">הֲנִיָּיה</a>. Mekh. Yithro, Baḥod., s. 1; a. e.</div>","alt":[]},"20033":{"h":"נִסֵּיתָא","r":"N00945","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסֵי\">נְסֵי</a>) <i>trial</i>; pr. n. pl. <i>Nissetha, Nistha</i>. <span class=\"citation\">Targ. O. Ex. XVII, 7</span> (Y. <a href=\"#\" data-headword=\"נִסָּיוֹן ²\">נִסְיוֹנָא</a>); <span class=\"citation\">Targ. O. Deut. XXXIII, 8</span> (h. text <span dir=\"rtl\">מסה</span>); a. e.</div>","alt":["נִסְתָא","נִי׳"]},"20034":{"h":"נָסַךְ","r":"N00946","html":"<div class=\"sense\"> (b. h.) <i>to pour, cast</i>. <span class=\"citation\">Y. Ber. I, 2ᵈ</span> top, v. <a href=\"#\" data-headword=\"מָסַךְ II\"><span dir=\"rtl\">מָסַךְ</span> II</a>.</div><div class=\"sense\"><b>Pi. נִסֵּךְ</b> <div class=\"sense\"><b>1)</b> <i>to offer a libation</i>. <span class=\"citation\">Succ. IV, 9</span> <span dir=\"rtl\">ולִמְנַסֵּךְ אומרים לו וכ׳</span> and they said to him who offered the libation (of water), raise thy hand. Ib. <span dir=\"rtl\">שפעם אחת ני׳ אחד וכ׳</span> for once it happened, that a priest poured the libation out at his feet. <span class=\"citation\">Snh. 62ᵇ</span> <span dir=\"rtl\">זיבח … וני׳ וכ׳</span> if one sacrificed, burnt incense, and offered a libation (to an idol) &amp;c.; a. fr.—<span class=\"citation\">Cant. R. to IV, 12</span> <span dir=\"rtl\">מֵאָן היו ישראל מנטרים כל וכ׳</span> (read: <span dir=\"rtl\">מְנַסְּכִים</span></div><div class=\"sense\"><b>—2)</b> <i>to make wine forbidden</i> (<span dir=\"rtl\">יֵין נֶסֶךְ</span>) <i>by the manipulation of a gentile suspected of dedicating it to idolatrous purposes</i>. <span class=\"citation\">Keth. 27ᵃ</span>; <span class=\"citation\">Sabb. 41ᵃ</span> <span dir=\"rtl\">אין פנאי לנַסֵּךְ</span> they do not take the time to manipulate the wine. <span class=\"citation\">Ab. Zar. 56ᵇ</span> (in Chald. dict.) <span dir=\"rtl\">והא קא מנסך בידיה</span> but might he not dedicate it to idolatry by putting his hand into it?; <span dir=\"rtl\">והא קא מנסך ברגל</span> might he not do it with his foot (while treading the wine)? <span class=\"citation\">Gitt. V, 4</span> <span dir=\"rtl\">המנסך</span> he who does damage to his neighbor by touching his wine for idolatrous purposes (v. interpret. <span class=\"citation\">ib. 52ᵇ</span>). Y. Ab. Zar. IV, 44ᵃ bot. <span dir=\"rtl\">מנסך כל הבור</span> he causes all the wine in the pit to be forbidden; a. fr.</div></div><div class=\"sense\"><b>Nif. נִיסָּךְ</b> <div class=\"sense\"><i>to be offered as libation, to be poured on the altar</i>. <span class=\"citation\">Pes. 22ᵃ</span> <span dir=\"rtl\">כמים הנִיסָּסִין</span> like the water which is poured on the altar, opp. <span dir=\"rtl\">הנשפכין</span> which is poured out at the foot of the altar.</div></div><div class=\"sense\"><b>Hithpa. הִתְנַסֵּךְ</b> </div><div class=\"sense\"><b>Nithpa. נִתְנַסֵּךְ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נִסֵּיתָא\">same</a>. Ib. <span dir=\"rtl\">המִתְנַּסְּכִים</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be made forbidden</i> (<i>as dedicated to idolatry</i>). Y. Ab. Zar. l. c. <span dir=\"rtl\">נתנ׳ הבור וכ׳</span> if the wine in the pit has been manipulated and become forbidden, the jet of wine poured into the pit becomes forbidden (affecting the wine in the vessel).</div></div>","alt":[]},"20035":{"h":"נְסַךְ","r":"N00947","html":"<div class=\"sense\">, esp. <i>to offer a libation</i>. <span class=\"citation\">Targ. Cant. IV, 15</span>; a. e.</div><div class=\"sense\"><b>Pa. נַסֵּךְ  נַסֵּיךְ</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"נָסַךְ\">preced.</a> <i>Pi.</i> <span class=\"citation\">Targ. Ex. XXX, 9</span>; a. fr.—<span class=\"citation\">Sabb. 41ᵃ</span> <span dir=\"rtl\">לא מְנַסְּכֵי</span> they will not take the time to manipulate &amp;c., v. <a href=\"#\" data-headword=\"נָסַךְ\">preced.</a></div></div><div class=\"sense\"><b>Ithpa. אִתְנַסַּךְ</b> </div><div class=\"sense\"><b>Ithpe. אִינְּסִיךְ</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"נָסַךְ\">preced.</a> <i>Hithpa.</i> <span class=\"citation\">Targ. Num. XXVIII, 7</span>; a. e.—<span class=\"citation\">Ab. Zar. 71ᵇ</span> <span dir=\"rtl\">קמא קמא אינ׳ ליה</span> every drop as it comes out becomes forbidden.</div></div>","alt":["נְסֵיךְ"]},"20036":{"h":"נֶסֶךְ","r":"N00948","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְסַךְ\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>libation</i>. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">יֵין נ׳</span> wine from which a libation has been poured on the altar.—Pl. <span dir=\"rtl\">נְסָכִים</span>, <span dir=\"rtl\">נְסָכִין</span>; constr. <span dir=\"rtl\">נִסְכֶי</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Zeb. IX, 1</span> <span dir=\"rtl\">הנ׳ ירדו</span> the libations brought on the altar illegally, may be taken down. <span class=\"citation\">Tosef. ib. V, 1</span>; <span class=\"citation\">Men. 15ᵇ</span>, a. e. <span dir=\"rtl\">נסכי בהמה</span> the libations connected with an animal sacrifice. <span class=\"citation\">Ib. II, 4</span> <span dir=\"rtl\">ונְסָכָיו</span> and the libations belonging thereto; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">יֵין נ׳</span> (<span dir=\"rtl\">יין שנתנסך לע&quot;ז</span>; abbrev. <span dir=\"rtl\">י&quot;נ</span>) <i>wine known</i> (or <i>suspected</i>) <i>to have been manipulated by an idolater, wine forbidden to Jews because of such</i> (<i>known or suspected</i>) <i>manipulation</i>. <span class=\"citation\">Ab. Zar. IV, 8</span> (<span class=\"citation\">55ᵃ</span>) <span dir=\"rtl\">ואינו נעשה י׳&#x27;נ וכ׳</span> (Bab. ed. <span dir=\"rtl\">עושה</span>) it does not become (the gentile does not make it) forbidden wine until &amp;c. Ib. V, 1 <span dir=\"rtl\">לעשות עמו ביין נ׳</span> to work with him in wine dedicated to an idol. Ib. 2 <span dir=\"rtl\">יין נ׳ שנפל וכ׳</span> if forbidden wine was poured over grapes. Ib. 74ᵃ bot. <span dir=\"rtl\">יין נ׳</span> really idolatrous wine, opp. <span dir=\"rtl\">סתם יין</span> suspected; a. fr.</div>","alt":[]},"20037":{"h":"נִסְכָּא","r":"N00949","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Ex. XXIX, 40</span> (Y. <a href=\"#\" data-headword=\"נִיסּוּךְ ²\">נִיסּוּכָא</a>); a. fr.—Pl. <span dir=\"rtl\">נִסְכִּין</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Targ. Jer. XIX, 13</span>; a. fr.</div>","alt":["נִי׳ I"]},"20038":{"h":"נִסְכָּא ²","r":"N00950","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"נִסְכָּא\">preced.</a> wds.) <i>cast metal</i>. <span class=\"citation\">Sabb. 59ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲנִיסְכָּא\">אֲנִיסְכָּא</a>.—Esp. <i>a piece of silver</i> or <i>gold, bar</i>, opp. to <a href=\"#\" data-headword=\"מַטְבֵּיעַ\">מטבע</a>, coined metal. <span class=\"citation\">B. Kam. 96ᵇ</span> <span dir=\"rtl\">האי מאן דגזיל נ׳ וכ׳</span> if one steals a piece of metal and makes it into coins. <span class=\"citation\">Ib. 98ᵃ</span> <span dir=\"rtl\">שבח לעניין נ׳</span> he profits by the increased value of the metal. <span class=\"citation\">Keth. 110ᵇ</span> <span dir=\"rtl\">ואימא נ׳</span> but may not ‘silver’ in the agreement mean metal (not coins)?; <span class=\"citation\">Men. 107ᵃ</span>; a. e.—<span class=\"citation\">B. Bath. 33ᵇ</span> <span dir=\"rtl\">היינו נ׳ דר׳ אבא וכ׳</span> this is a case corresponding to that of a metal bar which R. Abba decided, the case being that one took by force a piece of metal &amp;c.; <span class=\"citation\">Shebu. 32ᵇ</span>; a. e.</div>","alt":["נִי׳ II"]},"20039":{"h":"*נִסְכָּא","r":"N00951","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָכַךְ I\">סכך</a>) <i>weaving manipulation</i>. <span class=\"citation\">Sabb. 96ᵇ</span> <span dir=\"rtl\">בני׳ בתרא</span> (Ms. M. <a href=\"#\" data-headword=\"מִסְכָא\">מִסְכָא</a>) at the last manipulation (when the weaver throws the clue through the web for the last time).</div>","alt":["נִי׳ III"]},"20040":{"h":"נֵסֶל","r":"N00952","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיסֵל\">נִיסֵל</a></div>","alt":[]},"20041":{"h":"נְסַס","r":"N00953","html":"<div class=\"sense\"> [<i>to pine away</i>,] <i>to be sick</i>; trnsf. <i>to be troubled</i>. <span class=\"citation\">Targ. Esth. IV, 17</span>.</div><div class=\"sense\"><b>Pa. נַסֵּיס</b> <div class=\"sense\"><i>to trouble</i>. <span class=\"citation\">Targ. II Kings IV, 28</span> (h. text <span dir=\"rtl\">תשלה</span>).</div></div><div class=\"sense\"><b>Ithpa. אִתְנַסֵּיס  אִתְנַס</b> <div class=\"sense\">, <span dir=\"rtl\">אִינַּס</span>, <i>Ithpe.</i> <a href=\"#\" data-headword=\"נְסַס\">אִתְנְסִיס</a>, <span dir=\"rtl\">אִינְּסִיס</span> <i>to be troubled; to grieve; to be weak</i>. <span class=\"citation\">Targ. Gen. XLV, 5</span>. <span class=\"citation\">Ib. XXXIV, 7</span> (O. ed. Berl. <span dir=\"rtl\">אִתְנַסִּיאוּ</span>; v. Berl. Mass., p. 77). <span class=\"citation\">Targ. II Chr. XVI, 10</span>; a. e.—<span class=\"citation\">Sabb. 145ᵇ</span>; <span class=\"citation\">Gitt. 56ᵃ</span>; v. <a href=\"#\" data-headword=\"אִיתְנִיס\">אִיתְנִיס</a>. <span class=\"citation\">Gen. R. s. 50</span> (expl. <span dir=\"rtl\">וילאו</span>, <span class=\"citation\">Gen. XIX, 11</span>) <span dir=\"rtl\">אִינַּסּוּן</span> or <span dir=\"rtl\">אִינְּסוּן</span> they became weak.</div></div>","alt":[]},"20042":{"h":"נָסַע","r":"N00954","html":"<div class=\"sense\"> (b. h.) <i>to move, march</i>. <span class=\"citation\">Tosef. Sot. VIII, 1</span> <span dir=\"rtl\">בכל יום … נוֹסֵעַ אחר וכ׳</span> every day the ark moved behind two standards (divisions), …, but on that day it moved in front; <span class=\"citation\">Sot. 33ᵇ</span>. <span class=\"citation\">Num. R. s. 2</span> <span dir=\"rtl\">לאחר שהיו נוֹסְעִים … נוסעים את המשכן</span> after these two standards had moved, the Levites marched (carrying) the Tabernacle. <span class=\"citation\">Yalk. ib. 686</span> <span dir=\"rtl\">מתקרבים לִיסַּע</span> came together to make ready for the march. Mekh. B’shall., Vayass’a, s. 1 <span dir=\"rtl\">זו נסיעה לא נָסְעוּ וכ׳</span> this march they undertook by the order of Moses, but all other marches they made at the order of the Deity, a. fr.</div><div class=\"sense\"><b>Hif. הִסִּיעַ</b> <div class=\"sense\"><b>1)</b> <i>to remove, cause to depart, to separate, take apart</i>. Mekh. l. c. <span dir=\"rtl\">הִסִּיעָן בעל כרחן במקל</span> he forced them to march, against their will, with the staff. Ib. <span dir=\"rtl\">ע&quot;ז עברה … והִסִּיעָהּ משה וכ׳</span> an idol went with the Israelites across the sea, and Moses removed it &amp;c. <span class=\"citation\">Kel. V, 7</span> <span dir=\"rtl\">צריך להַסִּיעוֹ</span> he must (not only divide, but) separate the parts of the stove entirely. <span class=\"citation\">Sot. 8ᵃ</span> <span dir=\"rtl\">בית דין מַסִּיעִין את העדים וכ׳</span> the court orders the witnesses to change their places; <span class=\"citation\">Tosef. Snh. IX, 1</span> (ed. Zuck. <span dir=\"rtl\">מַשִּׂיאִין</span>). <span class=\"citation\">Gen. R. s. 38</span> (ref. to <span class=\"citation\">Gen. XI, 2</span>) <span dir=\"rtl\">הִסִּיעוּ עצמן מקדמונו וכ׳</span> they removed themselves from the Originator of the world; ib. s. 41 <span dir=\"rtl\">ה׳ עצמו וכ׳</span> he removed himself &amp;c. Mekh. B’shall., Shir., s. 10 <span dir=\"rtl\">גפן שהִסַּעְתָּה ממצרים</span> the vine (Israel) which thou didst transfer from Egypt (<span class=\"citation\">Ps. LXXX, 9</span>); a. fr.—<span class=\"citation\">B. Bath. 8ᵇ</span> <span dir=\"rtl\">להַסִּיעַ על קיצתן</span> to remove (place outside of the protection of the law, Rashi) those who disregard the terms fixed by the authorities.—<span class=\"citation\">Erub. VIII, 5</span> (<span class=\"citation\">86ᵃ</span>) <span dir=\"rtl\">הסעי מלבו</span> (Ms. M. <span dir=\"rtl\">הסירה</span>; ed. Sonc. <span dir=\"rtl\">הסיחה מדעתו</span>, v. Rabb. D. S. a. l. note) he has removed from his mind (the thought of returning to his residence). Mekh. B’shall. s. 3 (ref. to <span dir=\"rtl\">ויסעו</span>, <span class=\"citation\">Ex. XIV, 15</span>) <span dir=\"rtl\"><span dir=\"rtl\">יַסִּיעוּ דברים</span> (<span dir=\"rtl\">שהיו דוברים</span>) <a href=\"#\" data-headword=\"מַלְבֵּן\">מלבן</a></span> let them remove from their hearts the (evil) words which &amp;c.; <span class=\"citation\">Ex. R. s. 21</span>.—<span dir=\"rtl\">ה׳ דעת</span> = <span dir=\"rtl\">הסיח דעת</span>, v. <a href=\"#\" data-headword=\"נָסַח\">נָסַח</a>. Y. Ber. V, 9ᶜ bot.; a. fr.—[Y. Taan. IV, beg. 67ᵇ <span dir=\"rtl\">מפני מסיע</span>, read: <a href=\"#\" data-headword=\"הֶסֵּיעַ\">הֶסֵּיעַ</a>.—<span class=\"citation\">Tosef. Shebi. II, 20</span> <span dir=\"rtl\">מסיעין</span>, read <span dir=\"rtl\">מְסַיְּיעִין</span>.]—2) <i>to signalize</i>, v. <a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>.</div></div><div class=\"sense\"><b>Hof. הוּסַּע</b> <div class=\"sense\"><i>to be removed</i>. <span class=\"citation\">Tosef. Yoma I, 4</span> <span dir=\"rtl\">ה׳ מן הכהונה</span> was removed (deposed) from the high priesthood; Y. Hor. III, 47ᵈ top.</div></div>","alt":[]},"20043":{"h":"נְסַע","r":"N00955","html":"<div class=\"sense\"> <span class=\"citation\">Gen. R. s. 38</span> (ref. to <span class=\"citation\">Gen. XI, 2</span>) <span dir=\"rtl\">נַסְעוּ מן מדינחא וכ׳</span> they moved from the east to go further east.</div><div class=\"sense\"><b>Af. אַסַּע</b> <div class=\"sense\"><i>to remove</i>. Y. Meg. IV, 75ᶜ top <span dir=\"rtl\">אנא מסתכל ולא מַסַּע דעתי</span> I can look (at the priests) without diverting my attention (from my prayers); Y. Taan. IV, beg. 67ᵇ <span dir=\"rtl\">מַסְּעָה</span>; v. <a href=\"#\" data-headword=\"הֶסֵּיעַ\">הֶסֵּעַ</a>.</div></div>","alt":[]},"20044":{"h":"*נֶסַע","r":"N00956","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַע\">preced.</a>) <i>march</i>.—Pl. <span dir=\"rtl\">נְסָעִים</span>. <span class=\"citation\">Num. R. s. 2</span> <span dir=\"rtl\">תחלה לנ׳</span> (Judah was) the first in marching in the desert, opp. <span dir=\"rtl\">חֲנִיּיוֹת</span>.</div>","alt":[]},"20045":{"h":"נָסַק","r":"N00957","html":"<div class=\"sense\"><i>to go up, ascend</i>; v. <a href=\"#\" data-headword=\"מָסַק\">מָסַק</a>.</div><div class=\"sense\"><b>Hif. הִסִּיק</b> <div class=\"sense\"><b>1)</b> <i>to impose a tax, to assess</i>, v. <a href=\"#\" data-headword=\"מַסִּיק II\"><span dir=\"rtl\">מַסִּיק</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>to bring to a conclusion</i>, v. <a href=\"#\" data-headword=\"מַסִּיק I\"><span dir=\"rtl\">מַסִּיק</span> I</a>. I.</div><div class=\"sense\"><b>—3)</b> <i>to put on</i> wood, <i>to make the flame rise</i>; [cmp. <a href=\"#\" data-headword=\"עָלָה\">עָלָה</a> <i>Hif.</i>,] <i>to start a fire, to heat</i>. <span class=\"citation\">Bets. 32ᵃ</span>, a. e. <span dir=\"rtl\">מַסִּיקִין בכלים וכ׳</span> you may, on the Holy Day, use wooden vessels for heating &amp;c. <span class=\"citation\">Pes. 27ᵇ</span> <span dir=\"rtl\">המַסִּיק</span> he who put the wood on. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תנור שהִסִּיקוֹ וכ׳</span> if one heated an oven with wood belonging to the sanctuary &amp;c. <span class=\"citation\">Sabb. III, 1</span> <span dir=\"rtl\">כירה שהִסִּיקוּהָ בקש וכ׳</span> a range which they heated with straw &amp;c. <span class=\"citation\">Tosef. Yoma II, 5</span>; <span class=\"citation\">Yoma 38ᵃ</span> <span dir=\"rtl\">מַסִּיקִין מבפנים</span> placed the fire deep into the stove. <span class=\"citation\">Sabb. 41ᵃ</span>; a. fr.—[<span class=\"citation\">Midr. Till. to Ps. XXVIII</span>, v. infra.]</div></div><div class=\"sense\"><b>Nif. נִיסּוֹק  נִיסָּק</b> <div class=\"sense\">; <i>Hof</i>. <span dir=\"rtl\">הוּסָּק</span> <i>to be heated</i>. Y. Ber. IV, 8ᵇ top <span dir=\"rtl\">נִסּוֹקֶת</span>; ib. IX, 14ᵇ top <a href=\"#\" data-headword=\"נִסָּיוֹן\">נִיסּ׳</a>, v. <a href=\"#\" data-headword=\"מֶרְחָץ\">מֶרְחָץ</a>.—<span class=\"citation\">Pes. 30ᵇ</span> top <span dir=\"rtl\">הא ה׳ התנור</span> but if the oven has been made glowing. <span class=\"citation\">Midr. Till. to Ps. XXVIII</span> <span dir=\"rtl\">אם הוא נ׳ … יהא ני׳ וכ׳</span> if it (the furnace) is usually heated with one bundle, let it now be heated with seven; <span class=\"citation\">ib.</span> <span dir=\"rtl\">אם הוא מסיק בשבעה יהא מסיק וכ׳</span> (corr. acc.) if it is heated with seven bundles, let it be heated &amp;c. <span class=\"citation\">Kel. V, 4</span>. <span class=\"citation\">Tosef. Ḥull. I, 22</span> <span dir=\"rtl\">עד שלא הוּסְּקוּ</span> before they are hardened by heating; a. fr.</div></div>","alt":[]},"20046":{"h":"נְסַק","r":"N00958","html":"<div class=\"sense\">, <i>to go up</i>. Impf. <span dir=\"rtl\">יִסַּק</span>, <span dir=\"rtl\">יֵיסַק</span>; inf. <a href=\"#\" data-headword=\"מִיסַּק\">מִיסַּק</a>, <a href=\"#\" data-headword=\"מִיסַּק\">מֵיסַק</a>; imper. <a href=\"#\" data-headword=\"סַק\">סַק</a>, <span dir=\"rtl\">סוּק</span>. <span class=\"citation\">Targ. II Sam. V, 22</span>, sq. <span class=\"citation\">Targ. O. Num. XX, 19</span> <a href=\"#\" data-headword=\"נָסַק\">נֵיסָּק</a> ed. Berl. <span class=\"citation\">Targ. Gen. XLIV, 17</span>; a. fr.—<span class=\"citation\">Kidd. 50ᵃ</span> <span dir=\"rtl\">אדעתא למֵיסַק וכ׳</span> with the idea of going up to Palestine. <span class=\"citation\">Bets. 27ᵃ</span> <span dir=\"rtl\">אזכי ואִסַּק</span>; <span class=\"citation\">M. Kat. 22ᵃ</span> <span dir=\"rtl\">ואֵיסק</span> (not <span dir=\"rtl\">ואסיק</span>), a. e., v. <a href=\"#\" data-headword=\"זְכֵי\">זְכֵי</a>; a. fr.</div><div class=\"sense\"><b>Af. אַסֵּיק  אֲסֵיק</b> <div class=\"sense\"><b>1)</b> <i>to cause to rise, to bring up, offer</i>. <span class=\"citation\">Targ. Lev. II, 9</span>, a. fr. (h. text <a href=\"#\" data-headword=\"קָטַר I\">הקטיר</a>). <span class=\"citation\">Targ. II Sam. VI, 2</span> <span dir=\"rtl\">לַאֲסָקָא</span> ed. Wil. <span class=\"citation\">Targ. Lev. XI, 3</span>, sq.; a. fr.—<span class=\"citation\">Targ. Josh. XVII, 13</span> מַסְקֵי מסין <i>tributaries</i>.—Y. Keth. XI, 34ᵇ bot. <span dir=\"rtl\">והוה מַסֵּיק לון מזונין וכ׳</span> and he offered them support as long as they lived. <span class=\"citation\">Gitt. 56ᵇ</span>, a. fr. <span dir=\"rtl\">אַסְּקֵיה וכ׳</span>, v. <a href=\"#\" data-headword=\"נְגִידָא III\"><span dir=\"rtl\">נְגִידָא</span> III</a>. Y. Peah I, 15ᶜ <span dir=\"rtl\">אַסְּקוּנֵיה למאתים וכ׳</span> they raised the offer to two hundred, to one thousand; Y. Kidd. I, 61ᵇ top <span dir=\"rtl\">אַסְּקִינֵיה</span>. Y. Maas. Sh. IV, end, 55ᶜ <span dir=\"rtl\">מַסִּיק חסין</span> will produce lettuce; a. fr.</div><div class=\"sense\"><b>—2)</b>  (sub. <a href=\"#\" data-headword=\"בִּישְׂרָא\">בישרא</a>) <i>to produce new flesh, to heal</i>. <span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">לאַסּוּקֵי וכ׳</span></div><div class=\"sense\"><b>—3)</b> <i>to heat</i>. <span class=\"citation\">Targ. Koh. II, 6</span>.</div><div class=\"sense\"><b>—4)</b> <i>to finish</i>. <span class=\"citation\">Succ. 39ᵃ</span> <span dir=\"rtl\">אַסּוּקֵי מילתא</span> the winding up of a proceeding; <span class=\"citation\">Yeb. 106ᵇ</span> Ar. (ed. <span dir=\"rtl\">אפסוקי</span>).</div><div class=\"sense\"><b>—5)</b>  (with <span dir=\"rtl\">בִּשְׁמָא</span>) <i>to name after, to adopt a name</i>. <span class=\"citation\">Yoma 38ᵇ</span> <span dir=\"rtl\">לא מַסְּקִינָן בשמייהו</span> we do not name children after them. <span class=\"citation\">Gitt. 11ᵇ</span> <span dir=\"rtl\">דלא שכיחי ישראל דמַסְּקֵי בשמהתייהו</span> names which Israelites are not in the habit of adopting. <span class=\"citation\">Shebu. 29ᵃ</span> <span dir=\"rtl\"><span dir=\"rtl\">ואסיק להו</span> (<span dir=\"rtl\">שמא</span>) <span dir=\"rtl\">זוזי</span></span> and named them coins; a. e.</div><div class=\"sense\"><b>—6)</b>  (with <span dir=\"rtl\">זוזי</span>, a. <a href=\"#\" data-headword=\"ב\">ב</a> of person) <i>to produce a claim against</i>. <span class=\"citation\">Shebu. 41ᵇ</span> <span dir=\"rtl\">הב לי … דמַסִּיקְנָא בך</span> give me the one hundred Zuz which I claim against thee (which thou owest me). <span class=\"citation\">Keth. 85ᵃ</span> <span dir=\"rtl\">הוו מַסְּקֵּי ביה זוזי וכ׳</span>, v. <a href=\"#\" data-headword=\"חוֹזָאֵי\">חוֹזָאֵי</a>. <span class=\"citation\">B. Kam. 97ᵃ</span> <span dir=\"rtl\">אינשי דמסיק בהו זוזי</span> persons against whom he had a claim; a. e.</div><div class=\"sense\"><b>—7)</b>  (with <span dir=\"rtl\">אדעתא</span>) <i>to have in mind</i>. <span class=\"citation\">Shebu. 29ᵃ</span> <span dir=\"rtl\">דמסקי אדעתייהו וכ׳</span> they might have in mind an idol.</div></div><div class=\"sense\"><b>Ittaf. אִיתַּסַּק</b> <div class=\"sense\"><b>1)</b> <i>to be offered up</i>. <span class=\"citation\">Targ. O. Lev. II, 12</span> <span dir=\"rtl\">יִתַּסְּקוּן</span> ed. Berl. (oth. ed. a. Y. <span dir=\"rtl\">יְתַסְקוּן</span>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be kindled, burnt</i>. <span class=\"citation\">Targ. Ps. LXXVIII, 21</span>; a. e.</div></div>","alt":[]},"20047":{"h":"נִסְקָא","r":"N00959","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִקְצָא\">נִקְצָא</a></div>","alt":[]},"20048":{"h":"נָסַר","r":"N00960","html":"<div class=\"sense\"> [<i>to produce a rough, grating sound</i>; cmp. <a href=\"#\" data-headword=\"גָּרַר I\"><span dir=\"rtl\">גָּרַר</span> I</a>,] <i>to saw, plane</i>. <span class=\"citation\">Gen. R. s. 6</span> <span dir=\"rtl\">כמסר הזה שהוא נוֹסֵר בעץ</span> (the light of the sun produces a sound) like (that of) the plane which planes wood, opp. <span dir=\"rtl\">שף</span> to glide; Midr. Sam. ch. IX. <span class=\"citation\">Y. Ber. I, 2ᶜ</span> bot. <span dir=\"rtl\">עד שהחמה נוֹסֶרֶת ברקיע וכ׳</span> while the sun passes in the sky a journey of &amp;c. <span class=\"citation\">Gen. R. s. 8</span>, beg.; <span class=\"citation\">Lev. R. s. 14</span>, beg. <span dir=\"rtl\">נְסָרוֹ וכ׳</span> he sawed him apart &amp;c., v. <a href=\"#\" data-headword=\"גַּב\">גַּב</a>.</div><div class=\"sense\"><b>Pi. נִסֵּר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נִסְקָא\">same</a>. <span class=\"citation\">Yoma 20ᵇ</span> <span dir=\"rtl\">גלגל חמה שמְנַסֵּר ברקיע וכ׳</span> the globe of the sun which saws in the sky like a carpenter sawing cedars, v. supra. <span class=\"citation\">Gen. R. s. 65</span>, end <span dir=\"rtl\">נתנו … והיו מְנַסְּרִים בו</span> they placed him on a sawing-jack (v. <a href=\"#\" data-headword=\"חֲמוֹר\">חֲמוֹר</a>) and sawed his body; a. e.</div></div><div class=\"sense\"><b>Nif. נִסָּר</b> <div class=\"sense\"><i>to be sawed</i>. <span class=\"citation\">B. Kam. X, 10</span> <span dir=\"rtl\">נִסָּרוֹת</span>, <span dir=\"rtl\">נִסָּרִים</span>, v. <a href=\"#\" data-headword=\"נְסוֹרֶת\">נְסוֹרֶת</a>.</div></div>","alt":[]},"20049":{"h":"נְסַר","r":"N00961","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. I Ex. XIV, 25</span> (h. text <span dir=\"rtl\">וַיָּסַר</span>; cmp. <span class=\"citation\">I Chr. XX, 3</span>).</div><div class=\"sense\"><b>Pa. נַסֵּר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נָסַר\">same</a>, <i>to split</i>. <span class=\"citation\">Targ. Ps. XXIX, 7</span>.—<span class=\"citation\">Yeb. 49ᵇ</span> <span dir=\"rtl\">אתיוה לארזא ונַסְּרוּהָ</span> they brought the cedar and sawed it through; <span class=\"citation\">Yalk. Is. 274</span>. <span class=\"citation\">B. Bath. 75ᵃ</span> מְנסְּרֵי אבנים וכ׳ Ms. M. (ed. <span dir=\"rtl\">מינסרי</span>, corr. acc.) who were cutting precious stones.—V. <a href=\"#\" data-headword=\"מְסַר II\"><span dir=\"rtl\">מְסר</span> II</a>.</div></div>","alt":[]},"20050":{"h":"נֶסֶר","r":"N00962","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  (<a href=\"#\" data-headword=\"נְסַר\">preced.</a>) (<i>planed</i>) <i>board</i>. <span class=\"citation\">Cant. R. to I, 11</span> <span dir=\"rtl\">שחיפה בין נ׳ לנ׳</span> he put gold on between one board and the other; <span class=\"citation\">Y. Shek. VI, 49ᵈ</span> bot. Y. Ḥag. II, 78ᵇ bot.—Pl. <span dir=\"rtl\">נְסָרִים</span>, <span dir=\"rtl\">נְסָרִין</span>. <span class=\"citation\">B. Bath. IV, 6</span> <span dir=\"rtl\">הנ׳</span> the boards in the bath house. <span class=\"citation\">Ib. 67ᵇ</span> <span dir=\"rtl\">בית הנ׳</span> the room in which the boards are stored. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מכר את נ׳</span> sold (with the press) the boards, v. <a href=\"#\" data-headword=\"*יְצִירִין\">יְצִירִין</a>. <span class=\"citation\">Kel. XXII, 10</span>, v. <a href=\"#\" data-headword=\"שָׁגַם\">שָׁגַם</a>. <span class=\"citation\">Y. Sabb. III, 6ᵃ</span> top <span dir=\"rtl\">להיות מגלין את הנ׳</span> to remove the boards (which covered the bathing tank). Bab. <span class=\"citation\">Sabb. 40ᵃ</span>; a. e.—[</div><div class=\"sense\"><b>2)</b> <i>wicker</i>, v. <a href=\"#\" data-headword=\"נֵצֶר III\"><span dir=\"rtl\">נֵצֶר</span> III</a>.]</div>","alt":[]},"20051":{"h":"נִסְרָא","r":"N00963","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נֶסֶר\">same</a>, <i>board</i>.—Pl. <span dir=\"rtl\">נְסָרִין</span>, <a href=\"#\" data-headword=\"נִיסּוּךְ\">נִסְ׳</a>, <a href=\"#\" data-headword=\"נִסָּיוֹן\">נִיסְ׳</a>. <span class=\"citation\">Targ. I Kings VI, 15</span>; a. fr.—<span class=\"citation\">Ib. VII, 30</span> <span dir=\"rtl\">נ׳ דנחש</span> bronze plates (to cover the laver (?); h. text <a href=\"#\" data-headword=\"סרנא\">סרני</a>).</div><div class=\"sense\"><b>—2)</b> <i>veneer</i>. <span class=\"citation\">Sabb. 98ᵇ</span> <span dir=\"rtl\">דני׳</span> veneered boards, opp. <span dir=\"rtl\">שלמין</span> solid.—Pl. constr. <span dir=\"rtl\">נִסְרֵי</span>. <span class=\"citation\">Targ. Hos. VIII, 6</span> <span dir=\"rtl\">נ׳ לווחין</span> gold foils for boards (h. text <span dir=\"rtl\">שבבים</span>; cmp. <a href=\"#\" data-headword=\"שִׁיבָּא\">שִׁיבָּא</a>).</div>","alt":["נִי׳"]},"20052":{"h":"נַסְתּ־","r":"N00964","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְסֵי\">נְסֵי</a></div>","alt":[]},"20053":{"h":"נִסְתָא","r":"N00965","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִסֵּיתָא\">נִסֵּיתָא</a></div>","alt":[]},"20054":{"h":"נְעָא","r":"N00966","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְעֵי\">נְעֵי</a></div>","alt":[]},"20055":{"h":"נָעָא","r":"N00967","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְיָעָא\">נְיָעָא</a></div>","alt":[]},"20056":{"h":"נָעֶה","r":"N00968","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"נָאֶה\">נָאֶה</a>; pl. <a href=\"#\" data-headword=\"נָעִים\">נָעִים</a>, v. <a href=\"#\" data-headword=\"נָאֶה\">נָאֶה</a></div>","alt":[]},"20057":{"h":"נַעֲוָא","r":"N00969","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"עוי\">עוי</a>) [<i>hollowed out</i>,] <i>tank</i> of the press (h. . <span class=\"citation\">Targ. Y. Ex. XXII, 28</span>.—Pl. <span dir=\"rtl\">נַעֲוַיָּא</span>, <a href=\"#\" data-headword=\"נַעֲוָא\">נַעֲוַו׳</a>. <span class=\"citation\">Targ. Joel II, 24</span>. <span class=\"citation\">Targ. O. Gen. XLIX, 12</span>.—[Sachs, Beitr. II, 27: adaptation of Lat. <i>navia</i>.]</div>","alt":["נַעֲוָוא"]},"20058":{"h":"נַעֲוָה","r":"N00970","html":"<div class=\"sense\"> f. h. <a href=\"#\" data-headword=\"נַעֲוָא\">same</a>. <span class=\"citation\">Ab. Zar. 74ᵇ</span> <span dir=\"rtl\">נ׳ ארתחו</span> (Ms. M. <span dir=\"rtl\">ארתוחי</span>) as to a tank (used by gentiles), cleanse it with hot water.</div>","alt":[]},"20059":{"h":"נֵעוֹר","r":"N00971","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"עוּר\">עוּר</a></div>","alt":[]},"20060":{"h":"נְעוּרִים","r":"N00972","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>youth</i>. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">חופת נ׳</span> canopy of youth (bridal canopy).</div>","alt":[]},"20061":{"h":"נעוריתא","r":"N00973","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְשִׁירְתָּא\">נְשִׁירְתָּא</a></div>","alt":[]},"20062":{"h":"נְעוֹרָן","r":"N00974","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַעֲרָן\">נַעֲרָן</a></div>","alt":[]},"20063":{"h":"נְעוֹרֶת","r":"N00975","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> [<i>light matter</i>,] <i>scraps, chips</i>. <span class=\"citation\">Y. Sabb. IV, 6ᵈ</span> bot., v. <a href=\"#\" data-headword=\"נְסוֹרֶת\">נְסוֹרֶת</a>.—Esp. <a href=\"#\" data-headword=\"נ׳\">נ׳</a> (<span dir=\"rtl\">של פשתן</span>) <i>hatcheled flax</i>. <span class=\"citation\">Sabb. IV, 1</span> (<span class=\"citation\">49ᵃ</span>) <span dir=\"rtl\">נ׳ של פ׳ דקה</span> thoroughly beaten flax (cmp. <a href=\"#\" data-headword=\"דַּקְתָּא\">דַקְתָּא</a>). Ib. 11ᵃ, a. e., v. <a href=\"#\" data-headword=\"אֵשׁ\">אֵשׁ</a>. <span class=\"citation\">Snh. 37ᵃ</span>, v. <a href=\"#\" data-headword=\"הִבְהֵב I\">הִבְהֵב</a>; a. fr.</div>","alt":[]},"20064":{"h":"נְעוֹרְתָּא","r":"N00976","html":"<div class=\"sense\"> ch. <a href=\"#\" data-headword=\"נְעוֹרֶת\">same</a>; constr. <a href=\"#\" data-headword=\"נְעוֹרֶת\">נְעוֹרֶת</a>. <span class=\"citation\">Targ. Is. I, 31</span> (Regia <a href=\"#\" data-headword=\"נַעֲרַת\">נַעֲרת</a>).</div>","alt":[]},"20065":{"h":"נֵעוֹת","r":"N00977","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*עוּת\">עוּת</a></div>","alt":[]},"20066":{"h":"נְעֵי","r":"N00978","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"יְעָא\">יְעָא</a>, q. v. (cmp. <span dir=\"rtl\">נצץ</span>).</div>","alt":["נְעָא"]},"20067":{"h":"נְעִילָה","r":"N00979","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָעַל\">נָעַל</a>) </div><div class=\"sense\"><b>1)</b> <i>closing, shutting</i>. <span class=\"citation\">Y. Erub. III, 21ᵃ</span> <span dir=\"rtl\">היא קשירה היא נ׳</span> tying a door (the stem <span dir=\"rtl\">קשר</span>) means the same as shutting (the stem <span dir=\"rtl\">נעל</span>). <span class=\"citation\">Num. R. s. 14</span> (play on <span dir=\"rtl\">נעלי</span>, <span class=\"citation\">Ps. LX, 10</span>) <span dir=\"rtl\">בנְעִילַת גרונו</span> by tying up his throat (strangulation).—נעילת שערים <i>the time of closing the Temple gates</i>; (sub. <a href=\"#\" data-headword=\"תְּפִלָּא\">תְּפִלַּת</a>) <i>the concluding prayer on the Day of Atonement, on public fasts and Maʿămadoth</i> (v. <a href=\"#\" data-headword=\"מַעֲמָד\">מַעֲמָד</a>); <i>the prayer called N’ʿilah</i> <a href=\"#\" data-headword=\"נְעִילָה\">(נְעִילָה</a>). <span class=\"citation\">Taan. IV, 1</span> <span dir=\"rtl\">בשחרית … בנ׳ ש׳</span> during the morning prayer, the Musaf, the Minḥah and the N’ʿilah. <span class=\"citation\">Y. Ber. IV, 7ᶜ</span> top <span dir=\"rtl\">אימתי הוא נ׳</span> when is the time for the N.? <span dir=\"rtl\">בנעילת שערי שמים</span> when the gates of heaven are closed (sunset); <span dir=\"rtl\">בנ׳ שערי היכל</span> when the Temple gates are closed. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דנצלי נ׳ שערים</span> that we may offer the N. prayer. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נ׳ פוטרת וכ׳</span>; <span class=\"citation\">Yoma 87ᵇ</span> <span dir=\"rtl\">תפלת נ׳ וכ׳</span> the concluding prayer exempts from reading the evening prayer; a. fr.—Trnsf. <i>locking up, interruption of business</i>. <span class=\"citation\">Cant. R. to VII, 2</span> (play on <span dir=\"rtl\">בנעלים</span>, ib.) <span dir=\"rtl\">שתי נעלים נ׳ בפסח ונ׳ בחג</span></div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">נעילת הסנדל</span> (or <a href=\"#\" data-headword=\"נְעִילָה\">נעילה</a>) <i>putting on sandals, wearing shoes.</i> <span class=\"citation\">Yoma VIII, 1</span>. <span class=\"citation\">Ib. 74ᵃ</span>; <span class=\"citation\">M. Kat. 15ᵇ</span>; a. fr.—<span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">נ׳ רשות</span> wearing shoes (by the mourner on the Sabbath) is a matter of choice, v. <a href=\"#\" data-headword=\"נת\">נת&quot;ר</a>.</div>","alt":[]},"20068":{"h":"נָעִים I","r":"N00980","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>pleasing, lovely</i>. <span class=\"citation\">Ruth R. to II, 5</span> <span dir=\"rtl\">כיון שראה אותה נ׳ ומעשיה נאים</span> when he saw that she was lovely and her conduct becoming.—Pl. <span dir=\"rtl\">נְעִימִים</span>; <span dir=\"rtl\">נְעִימוֹת</span>. Ib. <span dir=\"rtl\">מעשיה נאים ונ׳</span> her conduct is becoming and lovely. <span class=\"citation\">Midr. Till. to Ps. V</span> <span dir=\"rtl\">כל מה שנתתה לנו טובים ונ׳ הם</span> all the things which thou hast given us are good and pleasing. <span class=\"citation\">Gen. R. s. 23</span>, v. <a href=\"#\" data-headword=\"נַעֲמָה\">נַעֲמָה</a>. <span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">כולכם נ׳ וחסידים וכ׳</span> all of you are welcome, all of you are pious &amp;c.; a. e.</div>","alt":["נְעִימָה"]},"20069":{"h":"נָעִים","r":"N00981","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Ex. XIX, 19</span>.</div>","alt":[]},"20070":{"h":"נָעִים II","r":"N00982","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Naʿim</i> (<i>Nain</i>), in Isachar. <span class=\"citation\">Gen. R. s. 98</span>.</div>","alt":[]},"20071":{"h":"נְעִימָה","r":"N00983","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָעִים II\">preced.</a>) </div><div class=\"sense\"><b>1)</b>  fem. of <a href=\"#\" data-headword=\"נָעִים\">נָעִים</a>.</div><div class=\"sense\"><b>—2)</b> <i>taste, disposition</i>. <span class=\"citation\">Ab. d’R. N. ch. IV</span>, end (<span class=\"citation\">Snh. 38ᵃ</span> <a href=\"#\" data-headword=\"דַּעַת\">דעת</a>).—Pl. <span dir=\"rtl\">נְעִימוֹת</span>. Ib. <span dir=\"rtl\">שינה הקב&quot;ה נ׳ בני אדם זה מזה</span> the Lord made the dispositions of men different one from the other.</div><div class=\"sense\"><b>—3)</b> <i>tune, chant; trill</i>. <span class=\"citation\">Y. Shek. V, 48ᵈ</span> bot. <span dir=\"rtl\">יודע נ׳ יתירה היה</span> he knew an extraordinary way of singing; <span class=\"citation\">Yoma 38ᵇ</span> <span dir=\"rtl\">כשהוא נותן קולו בנ׳</span> when he tuned his voice to a trill. <span class=\"citation\">Kidd. 71ᵃ</span> <span dir=\"rtl\">הבליע שם בנְעִימַת וכ׳</span> he let the Divine Name (the Tetragrammaton which he pronounced) be drowned in the chant of his brother priests; <span class=\"citation\">Num. R. s. 11</span>, end <span dir=\"rtl\">אמרו בתוך נעימת וכ׳</span> he pronounced it during the chant &amp;c. Y. Shek. V, 55ᶜ bot. <span dir=\"rtl\">סורח את הנ׳</span>, v. <a href=\"#\" data-headword=\"אִדְרַבְלִיס\">אִדְרַבְלִיס</a>. <span class=\"citation\">Meg. 32ᵃ</span> <span dir=\"rtl\">הקורא בלא נ׳</span> he who recites Bible verses without chanting; <span class=\"citation\">Treat. Sof’rim III, 10</span>. Cant. R. to VIII, 14 <span dir=\"rtl\">בנ׳ אחת</span> in one accord; a. fr.</div>","alt":[]},"20072":{"h":"נְעִימְתָּא","r":"N00984","html":"<div class=\"sense\">, <i>sweetness, melody</i>. Targ. II Esth. I, 1 <a href=\"#\" data-headword=\"נְעִימָה\">נְעִימַת</a> constr. <span class=\"citation\">Targ. Y. Ex. XIX, 19</span> <span dir=\"rtl\">ונ׳ מַלְיָא</span> and full melody.</div>","alt":["נְעִימָתָא"]},"20073":{"h":"נָעִיץ","r":"N00985","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָעַץ\">נָעַץ</a>) <i>a wedge-like ditch</i>.—Pl. <span dir=\"rtl\">נְעִיצִים</span>, <span dir=\"rtl\">נְעִיצִין</span>. <span class=\"citation\">B. Kam. V, 5</span> (<span class=\"citation\">50ᵇ</span>). <span class=\"citation\">Mikv. V, 6</span>; a. e.</div>","alt":[]},"20074":{"h":"נָעַל","r":"N00986","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to tie</i> (the door), <i>to lock up, close</i>. <span class=\"citation\">B. Kam. VI, 1</span> <span dir=\"rtl\">נ׳ בפניה כראוי</span> if he locked it in (secured the flock) properly. <span class=\"citation\">Tosef. B. Bath. II, 11</span>, a. e. <span dir=\"rtl\">נ׳ וגדר וכ׳</span> if he fastened (something on the property), fenced in or tore down, it is possession <a href=\"#\" data-headword=\"חֲזָקָה\">(חֲזָקָה</a>). <span class=\"citation\">Sabb. XIII, 6</span> <span dir=\"rtl\">ונ׳ אחד בפניו</span> and one blocked it (by placing himself in the entrance). <span class=\"citation\">Ib. 7</span> <span dir=\"rtl\">לנוֹעֵל את ביתו וכ׳</span> it is like one locking up (sitting at the entrance of) his house to guard it. Mekh. Mishp. s. 18 <span dir=\"rtl\">שלא לִנְעוֹל בפני וכ׳</span> in order not to close the door to future proselytes (not to discourage them on account of advanced age). <span class=\"citation\">Snh. 32ᵃ</span>, a. fr. <span dir=\"rtl\">כדי שלא תִנְעוֹל וכ׳</span>, v. <a href=\"#\" data-headword=\"דֶּלֶת\">דֶּלֶת</a>.—Y. Naz. VIII, 57ᵃ bot., v. <a href=\"#\" data-headword=\"וַעַד\">וַעַד</a>. <span class=\"citation\">Tosef. Sot. V, 9</span> [read:] <span dir=\"rtl\">שנעל דלת וכ׳</span> who locked his wife up (to prevent her from going astray); Y. ib. I, 17ᵃ bot.; <span class=\"citation\">Gitt. 90ᵃ</span>; Y. Kidd. IV, 66ᵃ; a. fr.—<span class=\"citation\">Cant. R. to VII, 2</span> (play on <span dir=\"rtl\">בנעלים</span>, ib.) <span dir=\"rtl\">אתם נוֹעֲלִים לפני … ואני נועל וכ׳</span> you lock up (interrupt business) for my sake on Passover …, and I lock up (the rain) for your sake, v. <a href=\"#\" data-headword=\"נְעִילָה\">נְעִילָה</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מה היה … שהיו נועלין בעד כל הצרות</span> how great wa is the beauty of thy steps (pilgrimage to the Temple) which locked up (protected against) all troubles.—Part. pass. <span dir=\"rtl\">נְעוּל</span>; f. <span dir=\"rtl\">נְעוּלָה</span>; pl. <a href=\"#\" data-headword=\"נְעוּרִים\">נְעוּלִים</a>, <span dir=\"rtl\">נְעוּלִין</span>; <span dir=\"rtl\">נְעוּלוֹת</span>. <span class=\"citation\">Midr. Till. to Ps. IV</span> <span dir=\"rtl\">שערי תפלה … נ׳ וכ׳</span> the gates of prayer are sometimes open, sometimes closed, but the gates of tears are never closed; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to tie a sandal, to put shoes on</i>. <span class=\"citation\">Tosef. Sabb. IV</span> (<span class=\"citation\">V), 8</span> <span dir=\"rtl\">לא יִנְעוֹל אדם וכ׳</span> one must not put on a nail-studded sandal &amp;c. <span class=\"citation\">Y. M. Kat. III, 83ᶜ</span> הורי … לנעול בו ביום R. … allowed (the people mourning for R. Yassa) to wear shoes on the same day. <span class=\"citation\">Tosef. Kidd. I, 5</span> <span dir=\"rtl\">נ׳ לו סנדלו וכ׳</span> if the slave tied his sandals for him (the new master) or untied them, it is possession (v. supra); <span class=\"citation\">B. Bath. 53ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"נָעַל\">הִנְעִיל</a>); a. fr.—Part. pass. as ab., <i>shod</i>. <span class=\"citation\">Yalk. Josh. 7</span> <span dir=\"rtl\">וכי במנעלים אתה נ׳ וכ׳</span> dost thou wear shoes and observest not mourning?</div><div class=\"sense\"><b>Hif. הִנְעִיל</b> <div class=\"sense\"><i>to put shoes on a person</i>. B. Bath. l. c.; <span class=\"citation\">Kidd. 22ᵇ</span> <span dir=\"rtl\">הלבישו הִנְעִילוֹ וכ׳</span> if the slave helped him put on his clothes or his shoes or lifted him up (helped him into a conveyance), it is possession.</div></div><div class=\"sense\"><b>Nif. נִנְעַל</b> <div class=\"sense\"><i>to be closed</i>. <span class=\"citation\">Ber. 32ᵇ</span> <span dir=\"rtl\">מיום … נִנְעֲלוּ שערי וכ׳</span> since the day the Temple was destroyed, the gates of prayer have been closed. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שערי דמעה לא ננעלו</span>; <span class=\"citation\">Midr. Till. to Ps. IV</span> <span dir=\"rtl\">נִנְעָלִים</span>, v. supra. <span class=\"citation\">B. Mets. 59ᵃ</span> <span dir=\"rtl\">כל השערים נִנְעָלִים חוץ וכ׳</span> all gates (of prayer) are (at times) closed, except the gates for the cry of oppression. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הפרגוד ננעל</span>, v. <a href=\"#\" data-headword=\"פַּרְגּוֹד\">פַּרְגּוֹד</a>. <span class=\"citation\">Erub. 6ᵇ</span>, a. e. <span dir=\"rtl\">אילמלא דלתותיה נִנְעָלוֹת</span> if its gates were not shut by night; a. fr.—<span class=\"citation\">Sabb. 67ᵃ</span> bot. (in an incantation for a swallowed fish-bone) <span dir=\"rtl\">נִנְעַלְתָּה כתריס</span> (Ms. M. <span dir=\"rtl\">מנעלתה בתריס</span>) thou art locked up as (within) a cuirass.</div></div>","alt":[]},"20075":{"h":"נְעַל","r":"N00987","html":"<div class=\"sense\">, <i>to tie</i> a shoe. Part. pass. <span dir=\"rtl\">נָעִיל</span>, <span dir=\"rtl\">נְעִיל</span>. <span class=\"citation\">Targ. Y. Deut. XXV, 9</span> <span dir=\"rtl\">ויהא נ׳ וכ׳</span></div><div class=\"sense\"><b>Af. אַנְעֵיל</b> <div class=\"sense\"><i>to provide with shoes</i>. <span class=\"citation\">Targ. II Chr. XXVIII, 15</span>. [<span class=\"citation\">Dan. II, 25</span>, a. e. <span dir=\"rtl\">הַנְעִל</span> <i>to bring up</i>, fr. <a href=\"#\" data-headword=\"עֲלַל I\">עֲלַל</a>.]</div></div>","alt":[]},"20076":{"h":"נַעַל","r":"N00988","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְעַל\">preced.</a>) </div><div class=\"sense\"><b>1)</b>  (cmp. Gr. ὑπόδημα) [<i>tied under the foot</i>,] <i>shoe</i>. <span class=\"citation\">Yeb. 102ᵃ</span> <span dir=\"rtl\">התורה … נַעֲלוֹ ולא מנעלו</span> the Law (<span class=\"citation\">Deut. XXV, 9</span>) says, what is tied to his foot, but not what covers his foot (a full shoe, v. <a href=\"#\" data-headword=\"מִנְעוֹל\">מִנְעוֹל</a>). <span class=\"citation\">Sifré Deut. 291</span> (ref. to Deut. l. c.) <span dir=\"rtl\">נעלו שלו</span> his own shoe; a. e.</div><div class=\"sense\"><b>—2)</b> <i>lock, locking up</i>.—Pl. <span dir=\"rtl\">נְעָלִים</span>. <span class=\"citation\">Cant. R. to VII, 2</span>, v. <a href=\"#\" data-headword=\"נְעִילָה\">נְעִילָה</a>.</div>","alt":[]},"20077":{"h":"נעלא","r":"N00989","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Lev. XI, 22</span>, Ar., v. <a href=\"#\" data-headword=\"נִיפּוֹלָא\">נִיפּוֹלָא</a>.</div>","alt":[]},"20078":{"h":"נָעֵם","r":"N00990","html":"<div class=\"sense\"> (b. h.) <i>to be pleasing, lovely</i>.</div><div class=\"sense\"><b>Hif. הִנְעִים</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נעלא\">same</a>. <span class=\"citation\">Snh. 24ᵃ</span> (ref. to <a href=\"#\" data-headword=\"נָעֵם\">נֹעַם</a> <span class=\"citation\">Zech. XI, 7</span>) <span dir=\"rtl\">אלו … שמַנְעִימִים זה לזה וכ׳</span> this refers to the scholars in Palestine who are polite to one another in discussion, opp. <span dir=\"rtl\">מחבלים</span>.</div><div class=\"sense\"><b>—2)</b> <i>to sweeten</i> the voice; <i>to sing, accompany</i>. Y. Shek. V, 48ᵈ bot. <span dir=\"rtl\">היה מַנְעִים את קולו וכ׳</span> he sweetened his voice when singing, v. <a href=\"#\" data-headword=\"נְעִימָה\">נְעִימָה</a>. <span class=\"citation\">Gen. R. s. 23</span> <span dir=\"rtl\">שהיתה מַנְעֶמֶת בתוף וכ׳</span> she sang to the timbrel in honor of idolatry, v. <a href=\"#\" data-headword=\"נַעֲמָה\">נַעֲמָה</a>. <span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">מי מנעים זמירותיהם וכ׳</span> who sweetens Israel’s songs? David &amp;c.; a. e.</div></div>","alt":[]},"20079":{"h":"נְעָמָא","r":"N00991","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַעֲמיתָא\">נַעֲמִיתָא</a></div>","alt":[]},"20080":{"h":"נַעֲמָה","r":"N00992","html":"<div class=\"sense\"> (b. h.) pr. n. f. <i>Naamah</i>, 1) sister of Tubal-Cain.</div><div class=\"sense\"><b>1)</b>  sister of Tubal-Cain. <span class=\"citation\">Gen. R. s. 23</span> (ref. to <span class=\"citation\">Gen. IV, 22</span>) <span dir=\"rtl\">למה היו קורין אותה נ׳ וכ׳</span> why was she (the wife of Noah) called N.? Because her doings were pleasing; ib. <span dir=\"rtl\">נ׳ אחרת היתה וכ׳</span> Tubal-Cain’s sister was a different Naamah, and she was so named &amp;c., v. <a href=\"#\" data-headword=\"נָעֵם\">נָעֵם</a> Hif.; Yalk. ib. 38.</div><div class=\"sense\"><b>—2)</b>  N., the Ammonite, mother of King Rehoboam. <span class=\"citation\">Gen. R. s. 41</span>; <span class=\"citation\">Yeb. 77ᵃ</span>. <span class=\"citation\">Ib. 63ᵃ</span>; a. e.</div>","alt":[]},"20081":{"h":"נָעֳמִי","r":"N00993","html":"<div class=\"sense\"> (b. h.) pr. n. f. <i>Naomi</i>, the mother-in-law of Ruth. <span class=\"citation\">B. Bath. 91ᵃ</span>, v. <a href=\"#\" data-headword=\"חזי\">חָזָה</a>. <span class=\"citation\">Snh. 19ᵇ</span>. <span class=\"citation\">Ruth R. to I, 2</span>; a. e.</div>","alt":[]},"20082":{"h":"נָעֳמִית","r":"N00994","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָעֵם\">נָעֵם</a>; v. Fl. to Levy Targ. Dict. II, p. 569 sq.) <i>ostrich.</i> <span class=\"citation\">Kel. XVII, 14</span> <span dir=\"rtl\">ביצת נ׳ המצופה</span> the glazed shell of an ostrich egg; Tosef. ib., <span class=\"citation\">B. Mets. VII, 6</span>. <span class=\"citation\">Y. Sabb. I, 3ᵈ</span> את בת היענה זו ביצת נ׳ ‘the child of a <i>yaʿănah’</i> (<span class=\"citation\">Lev. XI, 16</span>), this intimates that the egg of an ostrich (and of all other unclean birds) is forbidden; a. e.—Pl. <span dir=\"rtl\">נָעֳמִיּוֹת</span>. <span class=\"citation\">Tosef. Sabb. XIV</span> (<span class=\"citation\">XV), 8</span>; <span class=\"citation\">Sabb. 128ᵃ</span> <span dir=\"rtl\">מפני שהוא מאכל לנ׳</span> because glass pieces are given to ostriches to swallow. <span class=\"citation\">Y. Yoma IV, 41ᵈ</span> top. Midr. Sam. ch. XVIII; a. e.</div>","alt":[]},"20083":{"h":"נַעֲמיתָא","r":"N00995","html":"<div class=\"sense\"> ch. (<span dir=\"rtl\">ברת נ׳</span>, <span dir=\"rtl\">בת נ׳</span>) same. <span class=\"citation\">Targ. Lev. XI, 16</span> (ed. Berl. <a href=\"#\" data-headword=\"נַעֲמיתָא\">נָעָ׳</a>). <span class=\"citation\">Targ. Is. XXXIV, 13</span> <span dir=\"rtl\">בת נַעֲמָא</span> ed. Wil. (ed. Lag. <span dir=\"rtl\">נעמין</span>; some ed. <span dir=\"rtl\">נעמנין</span>, corr. acc.). <span class=\"citation\">Targ. Job XXX, 29</span>.—<span class=\"citation\">Sabb. 110ᵇ</span> <span dir=\"rtl\">ביעתא דנ׳</span> an ostrich egg. <span class=\"citation\">Y. M. Kat. III, 83ᵇ</span> bot. <a href=\"#\" data-headword=\"נ׳\">נ׳</a>; Bab. <span class=\"citation\">M. Kat. 26ᵃ</span> <span dir=\"rtl\">בת נ׳</span>.</div>","alt":["נָעָ׳","נְעָמָא"]},"20084":{"h":"נַעֲמָן I","r":"N00996","html":"<div class=\"sense\"> (b. h.) <i>Naaman</i>, a Syrian general. <span class=\"citation\">Gitt. 57ᵇ</span> נ׳ גר תושב היה N. was a convert &amp;c., v. <a href=\"#\" data-headword=\"גֵּר\">גֵּר</a>. <span class=\"citation\">Ned. 40ᵃ</span> <span dir=\"rtl\">שיזדמנו לו ריעים כנ׳ וכ׳</span> that he may meet with friends like those of N. who cured him of his leprosy. <span class=\"citation\">Deut. R. s. 2</span>; a. fr.</div>","alt":[]},"20085":{"h":"נַעֲמָן II","r":"N00997","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Naaman</i>, name of a planet. <span class=\"citation\">Pirké d’R. El. ch. VI</span> <span dir=\"rtl\">חלון נ׳</span> window of N. (a station of the sun).</div>","alt":[]},"20086":{"h":"נַעְנָא","r":"N00998","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <span dir=\"rtl\">נִינְיָא II</span>) <i>mint</i>. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> <span dir=\"rtl\">נענע</span> ed. Krot. (oth. <a href=\"#\" data-headword=\"נַעְנָא\">נענא</a>).</div>","alt":["נַעְנַע"]},"20087":{"h":"נִעֲנוּעַ","r":"N00999","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נִעֲנֵעַ\">נִעֲנֵעַ</a>) <i>shaking</i> (the Lulab). <span class=\"citation\">Succ. 37ᵇ</span></div>","alt":["נִי׳"]},"20088":{"h":"נִעֲנֵעַ","r":"N01000","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נוּעַ\">נוּעַ</a> h. a. ch.</div>","alt":["נַעְנֵעַ"]},"20089":{"h":"נַעְנַע","r":"N01001","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַעְנָא\">נַעְנָא</a></div>","alt":[]},"20090":{"h":"נָעַץ","r":"N01002","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"עוּץ\">עוץ</a>, <a href=\"#\" data-headword=\"אוּץ\">אוץ</a>) </div><div class=\"sense\"><b>1)</b> <i>to prick, stick; to wedge in</i>. <span class=\"citation\">Men. 64ᵇ</span> <span dir=\"rtl\">נ׳ צפרניו וכ׳</span> the swine pressed its nails against the wall; <span class=\"citation\">Sot. 49ᵇ</span>; <span class=\"citation\">Y. Ber. IV, 7ᵇ</span>, a. e.—<span class=\"citation\">Y. Shek. V, 48ᵈ</span> bot. <span dir=\"rtl\">כשהיה נוֹעֵץ גודלו וכ׳</span> when he inserted his thumb into his month. <span class=\"citation\">Sabb. 17ᵃ</span> <span dir=\"rtl\">נָעֲצוּ חרב וכ׳</span> they stuck a sword into the floor of the college; a. fr.—Part. pass. <span dir=\"rtl\">נָעוּץ</span>. <span class=\"citation\">Bets. 7ᵇ</span>, v. <a href=\"#\" data-headword=\"דֶּקֶר\">דֶּקְר</a>. <span class=\"citation\">Erub. III, 3</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to cut a wedge-like ditch</i> <a href=\"#\" data-headword=\"נָעִיץ\">(נָעִיץ</a>). Y. Sabb. V, 9ᵈ bot.; Y. Kil. VII, 31ᵇ bot., v. <a href=\"#\" data-headword=\"חָרַץ\">חָרַץ</a>; a. e.</div><div class=\"sense\"><b>Nif. נִנְעָץ</b> <div class=\"sense\"><i>to be fixed, stuck in</i>. <span class=\"citation\">Sabb. 67ᵃ</span> bot. (in an incantation, v. <a href=\"#\" data-headword=\"נָעַל\">נָעַל</a>) <span dir=\"rtl\">נִנְעַצְתָּה כמחט</span> (not … <a href=\"#\" data-headword=\"תָּא\">תא</a>) thou art stuck in like a pin.</div></div>","alt":[]},"20091":{"h":"נְעַץ","r":"N01003","html":"<div class=\"sense\"> (transp. <a href=\"#\" data-headword=\"נְצַע\">נְצַע</a>) ch. same. <span class=\"citation\">Targ. Y. Gen. XXX, 38</span> (O. <span dir=\"rtl\">דעץ</span>). <span class=\"citation\">Targ. Y. Deut. XV, 17</span>; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"נָעִיץ\">נְעִיץ</a>; f. <span dir=\"rtl\">נְעִיצָא</span>; pl. <span dir=\"rtl\">נְעִיצִין</span>; <span dir=\"rtl\">נְעִיצָן</span> <i>inserted; perforated</i>. <span class=\"citation\">Targ. O. Gen. XXVIII, 12</span>. <span class=\"citation\">Targ. Cant. II, 2</span>.—Y. Ter. VIII, 45ᵈ top; Y. Ab. Zar. II, 41ᵃ bot. (<a href=\"#\" data-headword=\"ל\">ל</a>)<span dir=\"rtl\">מִיצַּע סכינא וכ׳</span> (or <span dir=\"rtl\">למֵיעץ</span>) to stick a knife into a radish.</div><div class=\"sense\"><b>Pa. נַעַץ</b> <div class=\"sense\"> (transp. <a href=\"#\" data-headword=\"נְצַע\">נַצַּע</a>) same, <i>to plant</i>. <span class=\"citation\">Cant. R. to I, 16</span> <span dir=\"rtl\">וכדון אפי׳ את מְנַעֲצָהּ וכ׳</span> (not <span dir=\"rtl\">מצנעה</span>) and now, even if you tried to stick into it sixty myriads of reeds &amp;c., v. <a href=\"#\" data-headword=\"נְסֵי\">נְסֵי</a>; Y. Taan. IV, 69ᵇ; Y. Meg. I, 70ᵃ bot. <span dir=\"rtl\">מבצע</span> (corr. acc.); <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">כד את נַצְעֲתוֹן</span> (not <span dir=\"rtl\">נצעהון</span>).</div></div>","alt":[]},"20092":{"h":"נַעֲצוּץ","r":"N01004","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְעַץ\">preced.</a>) <i>thorn</i>; (homilet.) <i>a wicked person</i>. <span class=\"citation\">Meg. 10ᵇ</span> (ref. to <span class=\"citation\">Is. LV, 13</span>); <span class=\"citation\">Yalk. Is. 345</span>.</div>","alt":[]},"20093":{"h":"נַעֲצוּצָא","r":"N01005","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">נַעֲצוּצַיָּא</span>. <span class=\"citation\">Targ. Is. VII, 19</span>.</div>","alt":[]},"20094":{"h":"נָעַר I","r":"N01006","html":"<div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"נָעַר II\">next w.</a>) [<i>to be excited, noisy</i>,] esp. (of the ass) <i>to bray</i>. <span class=\"citation\">Ber. 3ᵃ</span>. <span class=\"citation\">Ib. 56ᵃ</span> (in Chald. dict.) <span dir=\"rtl\">דקאי אאיסדן ונוֹעֵר</span> standing at the head of the bed and braying. <span class=\"citation\">B. Kam. 18ᵇ</span>; <span class=\"citation\">Kidd. 24ᵇ</span>; a. e.—[<span class=\"citation\">Cant. R. to IV, 8</span> <span dir=\"rtl\">בתחלה הוא נוער</span>, read: <a href=\"#\" data-headword=\"נֵעוֹר\">נֵעוֹר</a>, v. <a href=\"#\" data-headword=\"עוּר\">עוּר</a>.]</div>","alt":[]},"20095":{"h":"נָעַר II","r":"N01007","html":"<div class=\"sense\"><i>to shake, stir.</i> <span class=\"citation\">Makhsh. I, 4</span> <span dir=\"rtl\">הנוֹעֵר אגודה וכ׳</span> he who shakes (the rain off) a bundle of vegetables. <span class=\"citation\">Ib. V, 7</span>. <span class=\"citation\">Pesik. R. s. 26</span> לאיוב נָעַרְתִּי מן האשפה וכ׳ I shook Job (making him rise) from the dunghill, and concerning thee (Israel) it is written (<span class=\"citation\">Is. LII, 2</span>), shake thyself &amp;c.; a. e.</div><div class=\"sense\"><b>Pi. נִיעֵר</b> <div class=\"sense\"><b>1)</b> <i>to shake</i>. Pesik. Shek., p. 17ᵃ <span dir=\"rtl\">נַעֲרָהּ קפלה</span> shake it (the garment), fold it; <span class=\"citation\">Lev. R. s. 2</span>. <span class=\"citation\">B. Mets. II, 8</span> <span dir=\"rtl\">מצא כסות מְנַעֲרָהּ וכ׳</span> if one found a garment (and holds it in charge waiting for the owner to claim it), he must shake it once in thirty days. <span class=\"citation\">Sabb. 147ᵃ</span> top; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to stir</i>. <span class=\"citation\">Ḥull. VIII, 3</span> <span dir=\"rtl\">נ׳ את הקדרה</span> if he stirred (the meat in) the pot. Y. Ab. Zar. I, 39ᵈ top <span dir=\"rtl\">שמא נ׳ הגוי בקדרה</span> the gentile might have stirred the pot; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to empty; to cause evacuation.</i> <span class=\"citation\">Toh. II, 1</span> <span dir=\"rtl\">מְנָעֶרֶת את הקדרה</span> she may empty (or <i>stir</i>) the dish. <span class=\"citation\">Kel. XXVIII, 2</span> <span dir=\"rtl\">לנָעֵר בו וכ׳</span> used for (lifting and) emptying the pot. <span class=\"citation\">Tosef. Kel. B. Mets. II, 10</span> <span dir=\"rtl\">שהחנוני מְנָעֵר וכ׳</span> which the shop-keeper uses when pouring out &amp;c. (or through which he pours for straining), v. <a href=\"#\" data-headword=\"יַתִּיךְ\">יַתִּיךְ</a>; a. e.—נ׳ את הצאן <i>to use means by which to expedite the discharge of excrements of the flock on the spot to be manured</i> (v. <a href=\"#\" data-headword=\"דּוּר I\"><span dir=\"rtl\">דּוּר</span> I</a>, <i>Pi.</i>). <span class=\"citation\">Tosef. Shebi. II, 20</span>; <span class=\"citation\">M. Kat. 12ᵃ</span>; Y. Shebi. III, 34ᶜ bot. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">השוכר … לנַעֲרָהּ</span> he who hires a flock (for manuring) is forbidden to use means &amp;c.; expl. <span class=\"citation\">ib.</span> <span dir=\"rtl\">מוליכה ממקום וכ׳</span> by driving it from place to place.—<i>Part. pass</i>. <span dir=\"rtl\">מְנוֹעָר</span>; f. <span dir=\"rtl\">מְנוֹעֶרֶת</span>; pl. <span dir=\"rtl\">מְנוֹעָרִים</span>, <span dir=\"rtl\">מְנוֹעָרִין</span>: <span dir=\"rtl\">מְנוֹעָרוֹת</span> <i>empty, vacant</i>. Y. Ber. IV, 7ᵇ bot. (play on <span dir=\"rtl\">שִׁנְ֗עָ֗ר̇</span>) <span dir=\"rtl\">שחם מנ׳ מן המצות וכ׳</span> they (the Babylonians) are vacant of (cannot perform) certain religious observances &amp;c.; <span class=\"citation\">Koh. R. to XII, 7</span>; <span class=\"citation\">Gen. R. s. 37</span> <span dir=\"rtl\">שהיא מנ׳ וכ׳</span> she (Babylonia) is deprived &amp;c. <span class=\"citation\">Ḥag. 14ᵃ</span> (play on <span dir=\"rtl\">נערים</span>, <span class=\"citation\">Is. III, 4</span>) <span dir=\"rtl\">אלו בני אדם שמנ׳ וכ׳</span> that means persons empty of good deeds, opp. <span dir=\"rtl\">ממולא</span>; <span class=\"citation\">Yalk. Is. 261</span>.—[<span class=\"citation\">B. Bath. 74ᵇ</span> <span dir=\"rtl\">ור&quot;י נוער</span> some ed., v. <a href=\"#\" data-headword=\"עוּר I\"><span dir=\"rtl\">עוּר</span> I</a>.—<span class=\"citation\">Ḥull. 51ᵇ</span> <span dir=\"rtl\">ניערה</span>, v. infra.]</div></div><div class=\"sense\"><b>Nif. נִנְעַר</b> <div class=\"sense\"><b>1)</b> <i>to be stirred up; to bestir one’s self</i>. <span class=\"citation\">B. Bath. 74ᵇ</span> <span dir=\"rtl\">וני׳ ר׳&#x27;א</span> and R. El. was stirred up (awoke). <span class=\"citation\">Sot. 5ᵃ</span> <span dir=\"rtl\">אין עפרו נ׳</span> his dust will not be stirred up (for resurrection). <span class=\"citation\">Ex. R. s. 1</span> (play on <span dir=\"rtl\">חלאה ונערה</span>, <span class=\"citation\">I Chr. IV, 5</span>) <span dir=\"rtl\">חלתה ונִנְעֲרָה מחליה וכ׳</span> she (Miriam) was sick, but she bestirred herself (arose) from her sickness, and the Lord restored her to youth. Y. Ber. III, 6ᵈ top (play on <span dir=\"rtl\">מנעריו</span>, <span class=\"citation\">Gen. VIII, 21</span>) <span dir=\"rtl\">משעה שהוא נ׳ ויוצא וכ׳</span> from the moment the embryo bestirs itself to come out into the world; <span class=\"citation\">Gen. R. s. 34</span>; <span class=\"citation\">Yalk. ib. 61</span>. <span class=\"citation\">Ḥull. 51ᵇ</span> ננערה לעמוד וכ׳ Rashi (ed. <span dir=\"rtl\">נִיעֲרָה</span>) if the animal made an effort to get up, although it did not succeed; a. e.</div><div class=\"sense\"><b>—2)</b>  (of flax) <i>to be hatcheled</i>. Y. Sabb. II, beg. 4ᶜ (expl. <a href=\"#\" data-headword=\"חוֹסֶן\">חוסן</a>, ib. II, 1) <span dir=\"rtl\">פשתן שלא ננערה</span> flax which has not yet been hatcheled.</div><div class=\"sense\"><b>—3)</b> <i>to be emptied, poured out</i>. Y. Ber. l. c. (play on <a href=\"#\" data-headword=\"שִׁנְעָר\">שנער</a>) <span dir=\"rtl\">ששם נִנְעֲרוּ וכ׳</span> for into that valley the dead of the generation of the flood were dumped; <span class=\"citation\">Gen. R. s. 37</span>; Koh. R. l. c.—<span class=\"citation\">Snh. 92ᵃ</span> <span dir=\"rtl\">קשתו נִינְעֶרֶת</span> his bow will be empty (his sexual vitality broken).</div></div><div class=\"sense\"><b>Hif. הִנְעִיר</b> <div class=\"sense\"><i>to stir up, to keep awake</i>. <span class=\"citation\">Erub. 53ᵇ</span> (play on <span dir=\"rtl\">נערה</span> &amp;c., v. <a href=\"#\" data-headword=\"אַהֲרוֹנִית\">אַהֲרוֹנִית</a>) <span dir=\"rtl\">והִנְעִירָתוֹ</span> and she kept him awake.</div></div><div class=\"sense\"><b>Hithpa. הִתְנַעֵר</b> <div class=\"sense\"><i>to be emptied</i>; trnsf. <i>to be displaced</i>. <span class=\"citation\">Zeb. 116ᵃ</span> (ref. to <span class=\"citation\">Cant. IV, 16</span>) <span dir=\"rtl\">תִּתְנַעֵר אומה … ותבא וכ׳</span> (v. Rabb. D. S. a. l. note) removed be the (Roman) nation whose sacrifices are slaughtered northward (<span class=\"citation\">Lev. I, 11</span></div></div>","alt":[]},"20096":{"h":"נְעַר","r":"N01008","html":"<div class=\"sense\">, <i>to shake, stir</i>.—<i>Part. pass</i>. <span dir=\"rtl\">נְעִיר</span> <i>waking</i>. <span class=\"citation\">Targ. Job XXI, 32</span> (Ms. <span dir=\"rtl\">נָעִיר</span>; ed. Wil. <span dir=\"rtl\">יְעִיר</span>, v. <a href=\"#\" data-headword=\"עוּר\">עוּר</a>).</div><div class=\"sense\"><b>Pa. נַעֵר</b> <div class=\"sense\"><i>to shake; to empty</i>. <span class=\"citation\">Yalk. Zech. 570</span>; <span class=\"citation\">Cant. R. to IV, 8</span> (ref. to <span class=\"citation\">Zech. II, 17</span>) <span dir=\"rtl\"><span dir=\"rtl\">דמְנַעֲרָה וכ׳</span> (דמְנַעֲרָא</span>), v. <a href=\"#\" data-headword=\"גֵּו\">גֵּו</a> ch.; <span class=\"citation\">Gen. R. s. 75</span>. <span class=\"citation\">Sabb. 142ᵃ</span> <span dir=\"rtl\">ולִינַעֲרִינְהוּ נַעוּרֵי</span> let him shake the fruit out of the basket.</div></div>","alt":[]},"20097":{"h":"נַעַר","r":"N01009","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְעַר\">preced.</a>, <i>tender, young; lad</i>. Tanḥ. Ḥayé 1 <span dir=\"rtl\">שיתכבד הזקן בַּנַּ׳</span> that the old may be honored by the young. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">ילד היה ומנהגו כנ׳</span> he was a child, but his behavior was like that of a lad; a. fr.—Pl. <span dir=\"rtl\">נְעָרִים</span>. <span class=\"citation\">Yoma 75ᵇ</span> <span dir=\"rtl\">לנ׳ לחם וכ׳</span> the manna was bread to the young, oil to the old &amp;c. Tanḥ. Sh’mini 11 <span dir=\"rtl\">אם נ׳ הם וכ׳</span> if they (the elders) are young &amp;c., v. <a href=\"#\" data-headword=\"קָפַץ\">קָפַץ</a>. Ib. <span dir=\"rtl\">הבחורים והנ׳</span> the young men and the lads. <span class=\"citation\">Sot. 46ᵇ</span> <span dir=\"rtl\">נ׳ היו ובזבזו וכ׳</span> they were young men, but behaved contemptibly like children; a. fr.—<i>Fem</i>. <a href=\"#\" data-headword=\"נַעֲוָה\">נַעֲרָה</a> <i>lass, maid</i>, esp. (law) <i>a girl between twelve and twelve and a half years of age</i>, v. <a href=\"#\" data-headword=\"בַּגְרוּת\">בַּגְרוּת</a>. <span class=\"citation\">Esth. R. to V, 1</span>; a. fr.—<span class=\"citation\">Keth. III, 8</span>, contrad. to <span dir=\"rtl\">בוגרת</span> a. <a href=\"#\" data-headword=\"קָטָן\">קטנה</a>. <span class=\"citation\">Ib. IV, 1</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"נַעֲרוּת\">נְעָרוֹת</a>, constr. <a href=\"#\" data-headword=\"נַעֲרוּת\">נַעֲרוֹת</a>. <span class=\"citation\">Ib. III, 1</span> (<span class=\"citation\">29ᵃ</span>). Esth. R. l. c. <span dir=\"rtl\">שתי נַעֲרוֹתֶיהָ</span> her two maids; a. fr.</div>","alt":[]},"20098":{"h":"נַעֲרוּת","r":"N01010","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נַעַר\">preced.</a>) <i>youth; vitality; puerility</i>. <span class=\"citation\">Ex. R. s. 1</span>, v. <a href=\"#\" data-headword=\"נָעַר I\">נָעַר</a> II <i>Nif.</i>—<span class=\"citation\">Kidd. IV, 14</span> <span dir=\"rtl\">משמרתו … בנַעֲרוּתוֹ</span> the Law guards him from all evil while he is young. <span class=\"citation\">Deut. R. s. 8</span>, end. <span class=\"citation\">Gen. R. s. 84</span> (ref. to <span class=\"citation\">Gen. XXXVII, 2</span>) <span dir=\"rtl\">שהיה עושה מעשה נ׳</span> he acted puerilely (was vain); a. fr.—Esp. <i>maidenhood, the age</i> or <i>the legal status of a</i> <a href=\"#\" data-headword=\"נַעֲוָה\">נַעֲרָה</a>. <span class=\"citation\">Y. Yeb. I, 3ᵃ</span> top, v. <a href=\"#\" data-headword=\"בַּגְרוּת\">בַּגְרוּת</a>; <span class=\"citation\">Kidd. 4ᵃ</span> bot. <span dir=\"rtl\">סימני נ׳</span> the symptoms of maidenhood (puberty); a. fr.</div>","alt":[]},"20099":{"h":"נַעֲרוּתָא","r":"N01011","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"נָעַר I\"><span dir=\"rtl\">נָעַר</span> I</a>) <i>roaring, camel’s cry</i>. <span class=\"citation\">Yeb. 120ᵇ</span> ולא אפסקיה לנַעֲרוּתֵיה Rashi (ed. <span dir=\"rtl\">אפסיקתיה</span>) and this did not make the camel cease from crying (until life was entirely extinct).</div>","alt":[]},"20100":{"h":"נַעֲרָן","r":"N01012","html":"<div class=\"sense\"> (b. h.) <i>Naaran</i>, near Jericho. <span class=\"citation\">Lev. R. s. 23</span> (ref. to <span class=\"citation\">Lam. I, 17</span>) <span dir=\"rtl\">כגון … יריחו לנ׳</span> as hostile as Jericho to N.; <span class=\"citation\">Cant. R. to II, 2</span>; Lam. R. to l. c. <a href=\"#\" data-headword=\"נועדן\">נועדן</a> (corr. acc. or <a href=\"#\" data-headword=\"נועדן\">נוֹעֲרָן</a>).—<span class=\"citation\">Ḥull. 5ᵃ</span> (ref. to <span dir=\"rtl\">נערה קטנה</span>, <span class=\"citation\">II Kings V, 2</span>) <span dir=\"rtl\">קטנה דמן נ׳</span> (ed. <a href=\"#\" data-headword=\"נְעוֹרָן\">נְעוֹרָן</a>) a little girl from N.; <span class=\"citation\">Sot. 46ᵇ</span> <a href=\"#\" data-headword=\"נְעוֹרָן\">נעורן</a>.</div>","alt":[]},"20101":{"h":"נְעֹרֶת","r":"N01013","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְעוֹרֶת\">נְעוֹרֶת</a></div>","alt":[]},"20102":{"h":"נַעֲרַת","r":"N01014","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְעוֹרְתָּא\">נְעוֹרְתָּא</a></div>","alt":[]},"20103":{"h":"נָעָתָא","r":"N01015","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָאָתָא\">נָאָתָא</a></div>","alt":[]},"20104":{"h":"נְפָא","r":"N01016","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְפֵי\">נְפֵי</a></div>","alt":[]},"20105":{"h":"נָפָא","r":"N01017","html":"<div class=\"sense\">, Pl. <span dir=\"rtl\">נָפָן</span>, v. <a href=\"#\" data-headword=\"נַפְיָא\">נַפְיָא</a>.</div>","alt":[]},"20106":{"h":"נָפָה I","r":"N01018","html":"<div class=\"sense\"><i>Pi.</i> <span dir=\"rtl\">נִיפָּה</span>, v. <a href=\"#\" data-headword=\"נפי\">נפי</a>.</div>","alt":[]},"20107":{"h":"נָפָה II","r":"N01019","html":"<div class=\"sense\"><i>fan; winnow; sieve</i>. <span class=\"citation\">Men. VI, 7</span>; <span class=\"citation\">X, 4</span>, v. <a href=\"#\" data-headword=\"נפי\">נפי</a>. <span class=\"citation\">Y. Keth. VII, 31ᵇ</span> bot., v. <a href=\"#\" data-headword=\"נָדַר\">נָדַר</a>. <span class=\"citation\">Ḥull. 45ᵃ</span> <span dir=\"rtl\">ניקבה כנ׳</span> if the windpipe has perforations like a sieve. <span class=\"citation\">Sot. 48ᵇ</span>; Y. ib. IX, 24ᵇ bot., v. <a href=\"#\" data-headword=\"נוֹפֶת\">נוֹפֶת</a>. Tanḥ. Ekeb 1; <span class=\"citation\">Yalk. Ps. 676</span>, v. <a href=\"#\" data-headword=\"נוֹפֶת\">נוֹפֶת</a>; a. fr.—<span class=\"citation\">Ab. V, 15</span> <a href=\"#\" data-headword=\"נ׳\">נ׳</a> a scholar who retains the best teachings.—Pl. <span dir=\"rtl\">נָפוֹת</span>. <span class=\"citation\">Men. 76ᵇ</span></div>","alt":[]},"20108":{"h":"נִפְוָותָא","r":"N01020","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְפָפָא\">נְפָפָא</a>, a. <a href=\"#\" data-headword=\"נַפְיָא\">נַפְיָא</a>.</div>","alt":[]},"20109":{"h":"נִפּוֹל","r":"N01021","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"נִיפּוּל\">נִיפּ׳</a>.</div>","alt":["נִפּוּל"]},"20110":{"h":"נְפוּלָא","r":"N01022","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְפִיל\"><span dir=\"rtl\">נְפִילָא</span> II</a></div>","alt":[]},"20111":{"h":"נִפּוֹלִין","r":"N01023","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיפּוֹלִין\">נִיפּוֹלִין</a></div>","alt":[]},"20112":{"h":"נָפוֹס","r":"N01024","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָפַס\">נפס</a>, <span dir=\"rtl\">נפץ</span>) a kind of <i>radish</i>, resembling the carrot as to foliage, and the radish as to taste. <span class=\"citation\">Kil. I, 3</span>; <span class=\"citation\">5</span>; Y. ed. a. Ms. M. <span dir=\"rtl\">ס …</span> (Mish. a. Bab. ed. … <span dir=\"rtl\">ץ</span>). <span class=\"citation\">Ukts. I, 2</span>. [Lat. <i>napus</i> is a kind of <i>turnip</i>.]</div>","alt":["(נָפוֹץ)"]},"20113":{"h":"נָפַח","r":"N01025","html":"<div class=\"sense\"><b>1)</b> <i>to blow, breathe</i>. <span class=\"citation\">Y. Sabb. VII, 10ᵈ</span> <span dir=\"rtl\">הנוֹפֵח כלי זכוכית</span> he who shapes glass vessels by blowing (on the Sabbath); Bab. <span class=\"citation\">Sabb. 75ᵇ</span> <span dir=\"rtl\">המְנַפֵּחַ בכלי וכ׳</span>. <span class=\"citation\">Makhsh. I, 6</span> <span dir=\"rtl\">הנופח בעדשים וכ׳</span> he who breathes at lentils to ascertain their quality. <span class=\"citation\">Tosef. Sabb. XV</span> (<span class=\"citation\">XVI), 2</span> <span dir=\"rtl\">נופח בחוטמו וכ׳</span> you blow into its nostrils and put the teat into its mouth; <span class=\"citation\">Sabb. 128ᵇ</span>; Y. ib. XVIII, end, 16ᶜ <span dir=\"rtl\">מביא יין ונופח וכ׳</span> you take wine and squirt it &amp;c. <span class=\"citation\">B. Mets. 60ᵇ</span> <span dir=\"rtl\">אין נוֹפְחִין בקרביים</span> it is not permitted to blow up entrails (for sale, to give them a delusive appearance); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be blown up, to swell</i>. Tanḥ. K’dosh. 8 <span dir=\"rtl\">נָפְחוּ פניו</span> his face was swollen. Ib. <span dir=\"rtl\">עיניו נְפוּחוֹת</span> his eyes swollen.</div><div class=\"sense\"><b>Nif. נִיפֵּחַ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נָפוֹס\">same</a>. <span class=\"citation\">Sabb. 75ᵇ</span>, v. supra. <span class=\"citation\">Maasr. IV, 5</span> מְנַפֵּיחַ … ואם ני׳ וכ׳ Y. ed. (Bab. ed. <span dir=\"rtl\">מנפח … נפח</span>; Ms. M. <span dir=\"rtl\">מנפיח</span>; Mish. ed. <span dir=\"rtl\">מנפה … נפה</span>, v. Rabb. D. S. a. l. note 7) he may blow out (the chaff of the wheat-ears) from hand to hand and eat, but if he blows and puts the grain in his lap, he is bound (to pay tithes); <span class=\"citation\">Bets. 13ᵇ</span>. <span class=\"citation\">Ib. 14ᵃ</span>. <span class=\"citation\">Ber. 19ᵇ</span>; <span class=\"citation\">Nidd. 57ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"פְּרַס I\">פְּרַס</a>; a. fr.—[Y. Peah VIII, 21ᵇ top <span dir=\"rtl\">המנפח</span>, read <span dir=\"rtl\">המכפח</span>, v. <a href=\"#\" data-headword=\"קָפַח\">קָפַח</a>.]</div></div><div class=\"sense\"><b>Pu. נוּפָּח</b> <div class=\"sense\"><i>to be blown, fanned</i>. <span class=\"citation\">Treat. S’maḥ. ch. VIII</span> <span dir=\"rtl\">מוטב … אש שנוּפְּחָה ולא אש שלא נופחה וכ׳</span> it is better that a fire consume me which has been blown (by man), than a fire that has not been fanned (Gehenna; <span class=\"citation\">Job XX, 26</span>).</div></div><div class=\"sense\"><b>Nif. נִיפַּח</b> <div class=\"sense\"><i>to be blown up, to swell</i>. <span class=\"citation\">Num. R. s. 7</span> <span dir=\"rtl\">תִּנָּפֵחַ כרסי וכ׳</span> my belly may swell and burst.</div></div>","alt":[]},"20114":{"h":"נְפַח","r":"N01026","html":"<div class=\"sense\"><b>1)</b> <i>to blow</i>. <span class=\"citation\">Targ. Gen. II, 7</span>; a. fr.—Y. Bets. II, end, 62ᵇ <span dir=\"rtl\">(<a href=\"#\" data-headword=\"ל\">ל</a>) <span dir=\"rtl\">מִנְפּוֹחַ וכ׳</span></span> to blow meat up. <span class=\"citation\">Gitt. 69ᵃ</span> bot. <span dir=\"rtl\">לִינְפַּח ליה חבריה וכ׳</span> let his neighbor blow white cress-seeds (into his throat) through a straw. <span class=\"citation\">Ḥull. 46ᵇ</span> <span dir=\"rtl\">ונַפְחִינָא לה</span> and we blow the lungs up; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"נְפִיחָה\">נְפִיחַ</a>; f. <a href=\"#\" data-headword=\"נְפִיחָה\">נְפִיחָא</a>; pl. <span dir=\"rtl\">נְפִיחִין</span>; <a href=\"#\" data-headword=\"נְפִיחָה\">נְפִיחָן</a> <i>blown, ignited; blown up, swollen</i>. <span class=\"citation\">Targ. Job XX, 26</span>. <span class=\"citation\">Targ. O. Num. V, 21</span>; a. fr.—<span class=\"citation\">Ḥull. 47ᵇ</span> <span dir=\"rtl\">א&quot;ד דנפיחא</span> (not <span dir=\"rtl\">דנפיחה</span>) some explain <span dir=\"rtl\">דמיא לאופתא</span> (v. <a href=\"#\" data-headword=\"אוּפְתָּא\">אוּפְתָּא</a>) as meaning lungs which look as if distended (white). <span class=\"citation\">Sabb. 33ᵃ</span> <span dir=\"rtl\">נְפִיחֵי כפן</span>, v. <a href=\"#\" data-headword=\"כְּפַן II\">כַּפְנָא</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be blown up, to swell</i>. <span class=\"citation\">Targ. O. Num. V, 27</span>, v. <i>Ithpa.</i> (Y. <span dir=\"rtl\">ותְנָפַח</span>, prob. to be read: <span dir=\"rtl\">ותִתְנְפַח</span>).—<span class=\"citation\">Lev. R. s. 33</span>; <span class=\"citation\">Cant. R. to II, 14</span>, v. <a href=\"#\" data-headword=\"קוּלְתָא\">קוּלְתָא</a>.</div><div class=\"sense\"><b>Pa. נַפַּח</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נָפַח\">same</a>, <i>to blow, cause swelling</i>. <span class=\"citation\">Targ. Y. Num. V, 22</span> (O. <span dir=\"rtl\">לְאַפָּחָא</span>, <i>Af</i>.; ed. Amst. <span dir=\"rtl\">לַאֲפָחָא</span>); a. e.—Part. pass. <span dir=\"rtl\">מְנַפַּח</span>; f. <span dir=\"rtl\">מְנַפְּחָא</span>; pl. <span dir=\"rtl\">מְנַפְּחִין</span>; <span dir=\"rtl\">מְנַפְּחָן</span>. Targ. Y. ib. 21.—<span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כות׳ 1) <span dir=\"rtl\">כל עמא מְנַפְּחִין לי וכ׳</span> (I dreamt) all the people were blowing at me with their full cheeks. Ib. <span dir=\"rtl\">דאינון מנפחין</span> (it meant) that it (the wheat) was swollen (through rain drippings). <span class=\"citation\">Snh. 43ᵃ</span>; <span class=\"citation\">B. Bath. 134ᵇ</span> מְנַפֵּח רב ששת וכ׳ R. Sh. blew into his hand (intimating that the question raised was scurrilous); a. e.</div></div><div class=\"sense\"><b>Af. אַפַּח  אֲפַח</b> <div class=\"sense\"><b>1)</b> <i>to blow, swell</i>. <span class=\"citation\">Targ. O. Num. V, 22</span>, v. supra. <span class=\"citation\">Targ. Ps. XI, 6</span> <span dir=\"rtl\">מַפְּחִין דאשתא</span> (Ms. <span dir=\"rtl\">מפ׳ אש׳</span>) blowers (winds) of fire (h. text <span dir=\"rtl\">פחים אש</span>).</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">נפש</span>) <i>to incite longing, to cause despair</i>. <span class=\"citation\">Targ. Job XXXI, 39</span>. <span class=\"citation\">Targ. I Sam. II, 33</span> (h. text <span dir=\"rtl\">לאדיב</span>).—V. <a href=\"#\" data-headword=\"מַפָּח\">מַפַּח</a>.</div></div><div class=\"sense\"><b>Ittaf. אִתַּפַּח</b> </div><div class=\"sense\"><b>Ithpa. אִתְנַפַּח  אִינַּ׳</b> <div class=\"sense\">; <i>Ithpe.</i> <a href=\"#\" data-headword=\"נְפַח\">אִתְנְפַח</a>, <a href=\"#\" data-headword=\"נְצֵי\">אִינְּ׳</a> </div><div class=\"sense\"><b>1)</b> <i>to be swollen</i>. <span class=\"citation\">Targ. Y. Num. V, 27</span> (v. supra; O. <span dir=\"rtl\">ויִפְּחוּן</span>, ed. Berl. <span dir=\"rtl\">ויִפְחוּן</span>). <span class=\"citation\">Targ. Job XIX, 26</span> (ed. Wil. <a href=\"#\" data-headword=\"נְפַח\">אִתְּפָח</a>; h. text <span dir=\"rtl\">נקפו</span>). <span class=\"citation\">Targ. Koh. XII, 5</span>.—Y. Maas. Sh. IV, end, 55ᶜ <span dir=\"rtl\">אִינַּפְּחָן</span> the wheat shall swell (v. supra).</div><div class=\"sense\"><b>—2)</b> <i>to be blown, ignited</i>. <span class=\"citation\">Sabb. 26ᵃ</span> <span dir=\"rtl\">אינפח בה נורא</span> she caught fire.</div></div>","alt":[]},"20115":{"h":"נֶפֶח","r":"N01027","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְפַח\">preced.</a>) <i>swelling; bulk, volume</i> (v. <a href=\"#\" data-headword=\"אַפּוּחָא\">אַפּוּחָא</a>). <span class=\"citation\">B. Mets. VI, 5</span> <span dir=\"rtl\">הנ׳ קשה כמשאוי</span> an increase of volume makes the load harder for the animal (Bab. ed. 80ᵃ <span dir=\"rtl\">הנ׳ קשה כמשאוי</span> an increase of size is as hard for the animal as an increase of weight), v. <a href=\"#\" data-headword=\"נִפְחָא\">נִפְחָא</a>. <span class=\"citation\">B. Kam. 47ᵃ</span> <span dir=\"rtl\">נִיפְחָהּ</span>, v. <a href=\"#\" data-headword=\"נִפְחָא\">נִפְחָא</a>.</div>","alt":[]},"20116":{"h":"נַפָּח","r":"N01028","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נֶפֶח\">preced.</a> wds.) <i>smith</i>. <span class=\"citation\">Gen. R. s. 84</span>, beg. [read:] <span dir=\"rtl\">נ׳ שהיה מפוחו פתוח באמצע פלטיא ופתח בנו זהבי מפוח כנגדו</span> a smith whose open shop was in the middle of the road, and whose son, a jeweler, opened a smithy opposite him; Tanḥ. Vayesheb 1; a. fr.—<span class=\"citation\">Y. R. Hash. II, 58ᵇ</span> top, a. e. <span dir=\"rtl\">בן הנ׳</span> the smith’s son, i.e. R. Johanan, v. next w.—Pl. <span dir=\"rtl\">נַפָּחִין</span>. Y. B. Bath. II, beg. 13ᵇ <span dir=\"rtl\">ולא של נ׳</span> nor dare an oven for smiths be put up (without the precautions mentioned in the Mishnah).</div>","alt":[]},"20117":{"h":"נַפָּחָא","r":"N01029","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XLIV, 12</span>.—<span class=\"citation\">Gitt. 69ᵇ</span> בנורא דבי נ׳ Rashi (ed. only <span dir=\"rtl\">בי נ׳</span>) by the fire of the smithy. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מיא דבי נ׳</span> water used in the smithy. <span class=\"citation\">Sabb. 25ᵇ</span>, a. fr. <span dir=\"rtl\">ר׳ יצחק נ׳</span> R. Isaac, the smith. <span class=\"citation\">Ḥull. 77ᵃ</span> <span dir=\"rtl\">יצחק בר נ׳</span> (corr. acc.)—<span dir=\"rtl\">בר נ׳</span> a) the smith’s son, v. <a href=\"#\" data-headword=\"יוֹחָנָן\">יוֹחָנָן</a>. <span class=\"citation\">Snh. 96ᵃ</span> <span dir=\"rtl\">טבא דנ׳ מדבר נ׳</span> better is what the smith (R. Isaac) said, than what the smith’s son (R. Johanan) said. <span class=\"citation\">B. Mets. 85ᵇ</span>; a. e.—b) name of <i>a bird</i>. <span class=\"citation\">Ḥull. 62ᵇ</span>.—Pl. <span dir=\"rtl\">נַפָּחִין</span>. <span class=\"citation\">Targ. Jer. VI, 29</span>. <span class=\"citation\">Targ. Jud. V, 26</span> <span dir=\"rtl\">נַפְחִין</span>.</div>","alt":["נַפְּחָא"]},"20118":{"h":"נִפְחָא","r":"N01030","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"נֶפֶח\">נֶפֶח</a>. <span class=\"citation\">B. Mets. 80ᵃ</span> (expl. <span dir=\"rtl\">קשה כמשאוי</span>, v. <a href=\"#\" data-headword=\"נֶפֶח\">נֶפֶח</a>) <span dir=\"rtl\">נ׳ כי תקלא וכ׳</span> the volume of the load is like the weight, i.e. loads of the same volume are considered of the same weight as regards the stress on the animal, and if he added three Kab to the volume bargained for, he is responsible for any injury to the ass; <span class=\"citation\">ib.</span> (expl. <span dir=\"rtl\">קשה למשאוי</span>) <span dir=\"rtl\">תקלא … ונ׳ הוי וכ׳</span> weight is weight, and the volume is an addition, i.e. if he changed the load for a more voluminous one although of the same weight, he is responsible for the additional volume. <span class=\"citation\">Tem. 30ᵇ</span> <span dir=\"rtl\">ניחא ליה בנִיפְחֵיה</span> its fuller appearance is welcome to him; <span class=\"citation\">Ab. Zar. 34ᵇ</span> <span dir=\"rtl\">בנפחיה</span>. <span class=\"citation\">B. Kam. 47ᵃ</span> <span dir=\"rtl\">נ׳ מאי</span> (Ms. F. <span dir=\"rtl\">נִיפְחָהּ</span>) how about the gain in value from its fuller appearance?</div>","alt":["נִי׳"]},"20119":{"h":"נְפָחַיָּא","r":"N01031","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>N’faḥaya</i>. <span class=\"citation\">Targ. Y. Num. XXI, 30</span> (h. text <a href=\"#\" data-headword=\"נָפַח\">נֹפַח</a>).</div>","alt":[]},"20120":{"h":"נָפַט","r":"N01032","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">נִיפֵּט</span> (cmp. <span dir=\"rtl\">נפץ</span>) <i>to beat</i> (<i>cotton</i>). <span class=\"citation\">Sabb. 73ᵇ</span> <span dir=\"rtl\">הדש המנפץ והמְנַפֵּט וכ׳</span> threshing, beating flax and beating cotton are all one kind of labor (threshing). [Ar. s. v. <a href=\"#\" data-headword=\"פַּץ\">פץ</a> reads: <span dir=\"rtl\">והמנפס</span>, v. <a href=\"#\" data-headword=\"נָפַס\">נָפַס</a>.]</div>","alt":[]},"20121":{"h":"נֵפְטְ","r":"N01033","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. a transpos. of <span dir=\"rtl\">נטף</span>, a readaptation of νάφθα) <i>naphtha</i>. <span class=\"citation\">Sabb. II, 2</span>. <span class=\"citation\">Ib. 26ᵃ</span> <span dir=\"rtl\">אין מדליקין בנ׳ לבן וכ׳</span> white naphtha must not be used for lighting … because it is explosive. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומה יעשו … אלא נ׳</span> and what shall the Cappadocians do who have … only naphtha? <span class=\"citation\">Yoma 38ᵇ</span>, sq. <span class=\"citation\">Y. Snh. VII, 24ᵇ</span> bot. (v. <a href=\"#\" data-headword=\"שְׂרֵפָה\">שְׂרֵפָה</a>) <span dir=\"rtl\">בפתילה של נ׳</span> the Mishnah, describing capital punishment by burning, means a wick saturated with naphtha. Y. Sot. VII, beg. 22ᵇ אש כנגד נ׳ שלהן ‘fire’ (<span class=\"citation\">Ps. XVIII, 13</span>) corresponds to the arrows of the human armies tipped in naphtha; <span class=\"citation\">Pesik. R. s. 17</span> <span dir=\"rtl\">רמה בהן נ׳</span> he (the besieger) throws naphtha &amp;c. (βέλη πυροφόρα or πυροβόλα).</div>","alt":[]},"20122":{"h":"נֶפְטָא","r":"N01034","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. II, Ex. XIV, 24</span>. Targ. II Esth. I, 2.—<span class=\"citation\">Sabb. 46ᵃ</span></div>","alt":[]},"20123":{"h":"נַפְטוֹיָא","r":"N01035","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נֶפְטָא\">preced.</a>) <i>dealer in naphtha</i>.—Pl. <span dir=\"rtl\">נַפְטוֹיֵי</span>. <span class=\"citation\">Ned. 91ᵇ</span></div>","alt":[]},"20124":{"h":"נפי","r":"N01036","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">נִיפָּה</span> (denom. of <a href=\"#\" data-headword=\"נפי\">נָפָה</a>) <i>to fan, winnow, sift.</i> <span class=\"citation\">Maasr. IV, 5</span>, v. <a href=\"#\" data-headword=\"נָפַח\">נָפַח</a>. <span class=\"citation\">B. Bath. 94ᵃ</span> <span dir=\"rtl\">אם בא לנַפּוֹת מְנַפֶּה וכ׳</span> if the buyer winnows (a sample of the wheat, and it is found to contain more than the legally allowed refuse), he winnows the entire quantity, and the seller has to indemnify him for the entire quantity lost by winnowing. <span class=\"citation\">Y. Maasr. IV, 51ᵇ</span> bot. <span dir=\"rtl\">ובלבד שלא יְנַפֶּה וכ׳</span> (better <span dir=\"rtl\">יְנַפֵּחַ</span>) but he must not blow the chaff out over a basket; a. e.—Part. pass. <span dir=\"rtl\">מְנוּפֶּה</span>; f. <span dir=\"rtl\">מְנוּפָּה</span>. <span class=\"citation\">Men. X, 4</span>; <span class=\"citation\">VI, 7</span> <span dir=\"rtl\">מנ׳ בשלש עשרה נפה</span> sifted thirteen times. Ib. <span dir=\"rtl\">סלת מנ׳ כל צרכה</span> fine flour sufficiently sifted. Tanḥ. T’tsavveh 5, v. <a href=\"#\" data-headword=\"סָלַת\">סָלַת</a>; a. e.—<span class=\"citation\">Pesik. R. s. 3</span> (ref. to <span dir=\"rtl\">כברת</span>, <span class=\"citation\">Gen. XLVIII, 7</span>) <span dir=\"rtl\">מנ׳ … בכברה בזמן שהארץ</span> (not <span dir=\"rtl\">ככברה</span>) at a season when the ground can be sifted and be shaken in the sieve.</div>","alt":["נָפָה"]},"20125":{"h":"נְפֵי","r":"N01037","html":"<div class=\"sense\">, <i>Pa</i>. <span dir=\"rtl\">נַפֵּי</span>, <a href=\"#\" data-headword=\"נפי\">same</a>. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> bot. <span dir=\"rtl\">כד מְנַפְּיָיא וכ׳</span> when she fans (blows the chaff out, on the Sabbath), she is guilty of an act coming under the category of winnowing. <span class=\"citation\">Ruth R. to III, 3</span> [read:] <span dir=\"rtl\">אזל נַפְּיָיהּ והיא וכ׳</span> go and winnow it (again), and it will yield the remainder; <span class=\"citation\">Yalk. ib. 604</span> <span dir=\"rtl\">זיל נַפֵּי תיבנא וכ׳</span> (not <a href=\"#\" data-headword=\"כפי\">כפי</a>).</div>","alt":["נְפָא"]},"20126":{"h":"נַפְיָא","r":"N01038","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְפֵי\">preced.</a>) = h. <a href=\"#\" data-headword=\"נפי\">נָפָה</a>, <i>fan, winnow, sieve</i>. <span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">והדר ביה כנ׳</span> (Ms. M. <span dir=\"rtl\">כינוֹפָא</span>) and he moves to and fro like a fan. <span class=\"citation\">B. Kam. 97ᵇ</span> <span dir=\"rtl\">אפי׳ כי נ׳</span> (Ms. R. <span dir=\"rtl\">מנפיא</span>, v. Rabb. D. S. a. l. note 80) even if the new coin be of the size of a sieve?; <span class=\"citation\">Ḥull. 124ᵃ</span> <span dir=\"rtl\">אפי׳ כנ׳</span> even if the flesh on the hide be of the size &amp;c.?—<span class=\"citation\">Gitt. 69ᵃ</span> bot. <span dir=\"rtl\">פארי דריש נ׳</span> the bran which comes up to the top of the sieve when shaken.—<span class=\"citation\">Ḥull. 45ᵃ</span> <span dir=\"rtl\">וסימניך נ׳</span> to remember the process required to ascertain the condition of the trachea perforated like a sieve, think of the construction of a sieve; a. e.—Pl. <a href=\"#\" data-headword=\"נִפְוָותָא\">נַפְוָותָא</a>, <a href=\"#\" data-headword=\"נִפְוָותָא\">נִפְוָותָא</a>. <span class=\"citation\">Sabb. 134ᵃ</span>, v. <a href=\"#\" data-headword=\"נְפָפָא\">נְפָפָא</a>. <span class=\"citation\">B. Mets. 74ᵃ</span> <span dir=\"rtl\">איפשר בנ׳</span> the winnowing may be done with a fan (independently of the wind). <span class=\"citation\">Succ. 20ᵇ</span> <span dir=\"rtl\">חזו לפרסי ונ׳</span> can be used for covers and sieves, v. <a href=\"#\" data-headword=\"פְּרָסָא\">פְּרָסָא</a>.—<span class=\"citation\">Y. Sabb. VII, 10ᶜ</span> top <span dir=\"rtl\">נָפָן</span> (fr. <a href=\"#\" data-headword=\"נָפָא\">נָפָא</a>).—[<span class=\"citation\">Tosef. Ḥull. III</span> (<span class=\"citation\">IV), 27</span> <a href=\"#\" data-headword=\"נַפְיָא\">נפיא</a>, v. <a href=\"#\" data-headword=\"אַפְיָין\">אַפְיָין</a>.]</div>","alt":[]},"20127":{"h":"נִפְיוֹרָא","r":"N01039","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*נִיפְרָא\">נִיפְרָא</a></div>","alt":[]},"20128":{"h":"נְפִיחָה","r":"N01040","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָפַח\">נָפַח</a>) <i>blowing, breath</i>. <span class=\"citation\">Y. Sabb. II, 5ᵃ</span> bot. <span dir=\"rtl\">הבעיר וכיבה בנ׳ אחת</span> if he ignited and extinguished in one continued act of blowing. <span class=\"citation\">Gen. R. s. 14</span>, end <span dir=\"rtl\">בעולם הזה בנ׳ וכ׳</span> in this world the breath of life is put in by blowing (<span class=\"citation\">Gen. II, 7</span>), … but in the coming world by placing (<span class=\"citation\">Ez. XXXVII, 6</span>). Ib. <span dir=\"rtl\">ומה אם זה שעשוי בנְפִיחָתוֹ של בשר ודם וכ׳</span> if this (glass) which is produced by the blowing of a human being, can be restored (when broken) &amp;c.; a. e.—<span class=\"citation\">Y. Meg. III, 74ᵇ</span> bot. <span dir=\"rtl\">בנ׳ אחת</span> in one breath (v. <a href=\"#\" data-headword=\"נְשִׁימָה\">נְשִׁימָה</a>).—[<span class=\"citation\">Ruth R. to III, 3</span> <span dir=\"rtl\">אזל נפיחה</span>, v. <a href=\"#\" data-headword=\"נְפֵי\">נְפֵי</a>.]</div>","alt":[]},"20129":{"h":"נָפִיל","r":"N01041","html":"<div class=\"sense\"><i>giants</i>. <span class=\"citation\">Gen. R. s. 26</span> <span dir=\"rtl\">נ׳ שהפילו וכ׳</span> they are called <i>n’filim</i>, because they caused the downfall of the world; a. e.—<span dir=\"rtl\">בֶּן הַנְּ׳</span> a) name of <i>a demon</i>. <span class=\"citation\">Bekh. 44ᵇ</span> רוח בן נ׳ <i>nervous prostration</i>, v. <a href=\"#\" data-headword=\"נָאלָא II\"><span dir=\"rtl\">נָאלָא</span> II</a>.—b) name of a <i>species of lizards</i>, living in the water. Sifra Sh’mini, ch. VI, Par. 5; <span class=\"citation\">Ḥull. 127ᵃ</span> (not <a href=\"#\" data-headword=\"כֵּן I\">כן</a>). <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">בן הפילי׳</span> some ed. (corr. acc.).</div>","alt":["נְפִילִים","נְפִלִ׳"]},"20130":{"h":"נָפִיל ²","r":"N01042","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>giant</i>. <span class=\"citation\">Ruth R. to II, 1</span> <span dir=\"rtl\">נסיב נ׳ לנ׳</span> when a giant marries a giantess.</div><div class=\"sense\"><b>—2)</b> <i>Orion</i>.—Pl. <a href=\"#\" data-headword=\"נָפִיל\">נְפִילִין</a>, v. <a href=\"#\" data-headword=\"נִיפְלָא II\"><span dir=\"rtl\">נִיפְלָא</span> I</a>.</div>","alt":["נְפִילָא I"]},"20131":{"h":"נְפִיל","r":"N01043","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"נֵפֶל\">נֵפֶל</a>, <i>untimely birth, not viable</i>. <span class=\"citation\">Targ. Y. I Lev. XXII, 27</span> <span dir=\"rtl\">דלא נְפִיל</span> (ed. Vien. <a href=\"#\" data-headword=\"נָפִיל\">נָפִיל</a>, ed. Amst. <a href=\"#\" data-headword=\"נָפִיל\">נֵפִיל</a>) that it is not an untimely birth. <span class=\"citation\">Targ. Ps. LVIII, 9</span> Ms. (ed. <a href=\"#\" data-headword=\"נְפוּלָא\">נְפוּלָא</a>). <span class=\"citation\">Targ. Job III, 16</span> <a href=\"#\" data-headword=\"נְפִיל\">נִפְלָא</a> (Bxt. <a href=\"#\" data-headword=\"נִפְלָא I\">נְפֵלָא</a>; Ms. <a href=\"#\" data-headword=\"נִפְלָא I\">נָפְלָא</a>).—Pl. <a href=\"#\" data-headword=\"נִפְלֵי\">נִפְלֵי</a>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">B. Bath. 101ᵇ</span> <span dir=\"rtl\">בדנ׳</span> (v. Rabb. D. S. a. l. note 30, ed. <span dir=\"rtl\">בנ׳</span>) it means a lot set aside for burying untimely births. <span class=\"citation\">Ib. 102ᵇ</span> <span dir=\"rtl\">תרתי בנ׳ וכ׳</span></div>","alt":["נְפִילָא II","(נִפְלָא)"]},"20132":{"h":"נְפִילָה","r":"N01044","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָפַל\">נָפַל</a>) </div><div class=\"sense\"><b>1)</b> <i>falling</i>. <span class=\"citation\">Sot. VIII, 6</span>, a. e. v. <a href=\"#\" data-headword=\"נִיסָה\">נִיסָה</a>. <span class=\"citation\">B. Kam. V, 7</span> (<span class=\"citation\">54ᵇ</span>) <span dir=\"rtl\">לנְפִילַת הבור</span> as to the laws relating to an animal falling into a pit (<span class=\"citation\">Ex. XXI, 33</span> sq.). <span class=\"citation\">Y. Ber. I, 3ᵈ</span> top <span dir=\"rtl\">שתסמכנו מנְפִילָתֵנוּ</span> that thou mayest support us in our downfall.—Pl. <span dir=\"rtl\">נְפִילוֹת</span>. <span class=\"citation\">Yalk. Esth. 1058</span> (ref. to <span class=\"citation\">Esth. VI, 13</span>) <span dir=\"rtl\">שתי נ׳ הללו למה</span> why this double use of <i>nafal?</i></div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"מַפּוֹלֶת\">מַפּוֹלֶת</a>) <i>quantity of seed required for a field.</i> <span class=\"citation\">Peah V, 1</span> <span dir=\"rtl\">נותן לעניים</span> (<a href=\"#\" data-headword=\"ב\">ב</a>) <span dir=\"rtl\">כדי נ׳</span> (Y. ed. <span dir=\"rtl\">נִפְלָהּ לעניים</span>) he must give to the poor as much as the field requires for seed (v. Maim. a. l.; oth. opin.: as much as is generally dropped at cutting); <span class=\"citation\">B. Mets. 105ᵇ</span>. <span class=\"citation\">Ib. IX, 5</span> <span dir=\"rtl\">אם יש בה כדי נ׳</span> (Y. ed. <span dir=\"rtl\">נִיפְלָהּ</span>) if the field yields as much as is required for seed, expl. Y. ib. 12ᵃ <span dir=\"rtl\">כדי הזרע הנופל בה</span>; <span class=\"citation\">Y. Peah. V, 18ᵈ</span> <span dir=\"rtl\">כדי ניפלת</span> (corr. acc.).—[<span class=\"citation\">Y. Orl. I, 60ᵈ</span> top <span dir=\"rtl\">כדי נפילתה</span> R. S. to <span class=\"citation\">Orl. I, 2</span>, v. <a href=\"#\" data-headword=\"טְפִילָה\">טְפִילָה</a>.]</div>","alt":[]},"20133":{"h":"נְפִיצָה","r":"N01045","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָפַץ\">נָפַץ</a>) <i>shattering</i>. Y. Orl. I, 60ᵈ bot. [read:] <span dir=\"rtl\">היא עשייה היא הקמה היא שבירה היא נ׳</span> (some ed. <a href=\"#\" data-headword=\"נְתִיצָה\">נְתִיצָה</a>) ‘making’ an idol is the same as putting up, ‘breaking’ the same as shattering (v. Y. Ab. Zar. IV, 44ᵃ).</div>","alt":[]},"20134":{"h":"נְפִיק","r":"N01046","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְפַק\">נְפַק</a></div>","alt":[]},"20135":{"h":"נָפִיק","r":"N01047","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְפִיק\">preced.</a>; cmp. Syr. <span dir=\"rtl\">נופקא</span>, P. Sm. 2424) <i>quick, alert</i>. <span class=\"citation\">Targ. I Sam. XXIII, 22</span> <span dir=\"rtl\">ערים ונ׳</span> (h. text <span dir=\"rtl\">ערם יערים</span>).</div>","alt":[]},"20136":{"h":"נפיקא","r":"N01048","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 26</span> <span dir=\"rtl\">(<span dir=\"rtl\">מאנויין</span>) <span dir=\"rtl\">מאנין נ׳</span></span> some ed., oth. <a href=\"#\" data-headword=\"פניקא\">פניקא</a>, v. <a href=\"#\" data-headword=\"פָּגָנִיקָא\">פָּגָנִיקָא</a>.</div>","alt":[]},"20137":{"h":"נְפֵישׁ","r":"N01049","html":"<div class=\"sense\"> (interch. with <a href=\"#\" data-headword=\"פּוּשׁ\">פּוּשׁ</a> a. <a href=\"#\" data-headword=\"פְּשֵׁי\">פְּשֵׁי</a>, q. v.) </div><div class=\"sense\"><b>1)</b>  [<i>to be blown up</i>,] <i>to be large; to increase</i>. <span class=\"citation\">Targ. Ex. I, 7</span>; a. e. Imper. <a href=\"#\" data-headword=\"פּוּשׁ\">פּוּשׁ</a>. <span class=\"citation\">Targ. Gen. I, 28</span>; a. e.—</div><div class=\"sense\"><b>*2)</b>  [<i>to be blown away</i>,] <i>to be gone</i>. <span class=\"citation\">B. Bath. 121ᵃ</span>; <span class=\"citation\">Ned. 78ᵃ</span> אתא לנהרדעא … נ׳ Ar. (ed. <span dir=\"rtl\">ולא אשכחיה</span>) he came to N. to see R. S.; he was gone.</div><div class=\"sense\"><b>Af. אַפֵּישׁ</b> <div class=\"sense\"> (interch. with <a href=\"#\" data-headword=\"פּוּשׁ ²\">אָפֵישׁ</a>, a. <a href=\"#\" data-headword=\"פּוּשׁ ²\">אַפְשֵׁי</a>) <i>to extend, enlarge</i>. <span class=\"citation\">Targ. Gen. XLVIII, 4</span> (some ed. <span dir=\"rtl\">מַפְשִׁי׳</span>). <span class=\"citation\">Targ. Y. Num. XIX, 6</span> <span dir=\"rtl\">אַפּוּשֵׁי</span>; a. fr.—<span class=\"citation\">Men. 23ᵇ</span> <span dir=\"rtl\">דא׳ לה תבלין טפי וכ׳</span> when he made the quantity of spices larger than &amp;c. <span class=\"citation\">Bets. 7ᵃ</span> <span dir=\"rtl\">אַפּוּשֵׁי … לא מַפְּשִׁינָן</span> (or <span dir=\"rtl\">אֲפוּשֵׁי … מַפְשִׁי׳</span>) we must not extend the range of unclean things by rabbinical enactments. <span class=\"citation\">Sot. 26ᵃ</span> <span dir=\"rtl\">אפושי … לא לִיפַּשׁ</span> we ought not to increase the number of illegitimate births (by allowing intermarriage between bastards). <span class=\"citation\">B. Bath. 12ᵇ</span> <span dir=\"rtl\">בעינא דא׳ אריסי</span> (Rashi <span dir=\"rtl\">ניחא לי לאפושי</span>) I desire (it is an advantage to me) to have a large number of tenants around me (whom my neighbor must employ). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אפושי לאו מילתא היא</span> this plea about a large number &amp;c., is no plea; a. e.—Y. Kil. IX, 32ᶜ top; Y. Keth. XII, 35ᵇ top <span dir=\"rtl\">נַפֵּישׁ לר׳ וכ׳</span> let us make room for R. H.</div></div>","alt":[]},"20138":{"h":"נְפִישׁ","r":"N01050","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"נְפֵישׁ\">preced.</a>) [<i>blown up</i>,] <i>large, numerous</i> (cmp. <a href=\"#\" data-headword=\"אֲוַשׁ\">אֲוַשׁ</a>). <span class=\"citation\">Targ. Y. Deut. XXV, 9</span>.—<span class=\"citation\">B. Bath. 73ᵇ</span> <span dir=\"rtl\">כמה נ׳ חיליה וכ׳</span> how great is the strength of the tree. <span class=\"citation\">Keth. 66ᵇ</span> <span dir=\"rtl\">דנ׳ זיונא</span> the management of which is a large concern, v. <a href=\"#\" data-headword=\"זִיּוּנָא III\"><span dir=\"rtl\">זִיּוּנָא</span> III</a>.; a. fr.—Pl. <span dir=\"rtl\">נְפִישִׁין</span>, <span dir=\"rtl\">נְפִישֵׁי</span>; <a href=\"#\" data-headword=\"נְפִישׁ\">נְפִישָׁן</a>. Targ. II Esth. VI, 10; a. e.—<span class=\"citation\">Snh. 52ᵃ</span>, v. <a href=\"#\" data-headword=\"הוֹגָנָא\">הוֹגָנָא</a>. <span class=\"citation\">Yeb. 74ᵇ</span> <span dir=\"rtl\">הנך נ׳</span> those (laws relating to dedicated objects) are extensive. B. Bath. l. c. <span dir=\"rtl\">משום דנ׳ מיא</span> because the water is deep; a. fr.</div>","alt":["נְפִישָׁא"]},"20139":{"h":"נָפֵישׁ","r":"N01051","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">נְפֵישִׁים</span>, v. <a href=\"#\" data-headword=\"נָפֵשׁ\">נָפֵשׁ</a>.</div>","alt":[]},"20140":{"h":"נָפִיתָא","r":"N01052","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְפָפִיתָא\">נְפָפִיתָא</a></div>","alt":[]},"20141":{"h":"נֹפֶךְ","r":"N01053","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) name of <i>a jewel</i> in the high priest’s breast plate, <i>emerald</i>. <span class=\"citation\">Ex. R. s. 38</span>, end <span dir=\"rtl\">על נ׳ היה כתוב וכ׳</span> on the <i>nofekh</i> the name of Judah was engraven.</div>","alt":["נוֹ׳"]},"20142":{"h":"נָפַל","r":"N01054","html":"<div class=\"sense\"> (b. h.) <i>to fall, lie down; to be dropped; to occur</i>. <span class=\"citation\">Sabb. XVI, 2</span> <span dir=\"rtl\">נָפְלָה דליקה</span> if a conflagration takes place. <span class=\"citation\">Pes. II, 3</span>, v. <a href=\"#\" data-headword=\"מַפּוֹלֶת\">מַפּוֹלֶת</a>. <span class=\"citation\">Y. Sot. VII, 21ᵈ</span> top (ref. to <a href=\"#\" data-headword=\"יָקִים\">יקים</a>, <span class=\"citation\">Deut. XXVII, 26</span>) <span dir=\"rtl\">וכי יש תורה נוֹפֶלֶת</span> is there a falling law (to need erection)? <span class=\"citation\">Ned. 65ᵇ</span> <span dir=\"rtl\">כל הנוֹפֵל אינו נופל לידי וכ׳</span> he who falls (becomes poor) does not immediately fall into the hands of (become dependent on) the charities (but his friends support him for a time). <span class=\"citation\">B. Kam. IX, 11</span>, a. fr. <span dir=\"rtl\">יִפְּלוּ דמיו לנדבה</span> its equivalent must be surrendered as a donation to the Temple. <span class=\"citation\">B. Bath. IX, 4</span> <span dir=\"rtl\">האחין … שנ׳ אחד מהן לאומנות נ׳ לאמצע</span> if one of two partner brothers (heirs) has been summoned to public service, his salary goes into the common fund. <span class=\"citation\">Y. Shek. V, 49ᵇ</span> top <span dir=\"rtl\">בשביל ששמעתי שנפלה לך ירושה וכ׳</span> since I heard that an inheritance has fallen to thy share at a distant place, take (this as a loan) &amp;c.; a. v. fr.—Imperat. <a href=\"#\" data-headword=\"פּוֹל\">פּוֹל</a>. <span class=\"citation\">Tosef. Dem. VI, 4</span> <span dir=\"rtl\">ופול תחתיי וכ׳</span> (Var. <a href=\"#\" data-headword=\"טוּל I\">טול</a>, some ed. <span dir=\"rtl\">עול</span>) and surrender thyself to public service in my place (v. supra).</div><div class=\"sense\"><b>Hif. הִפִּיל</b> <div class=\"sense\"><i>to cause to fall; to throw down</i>. <span class=\"citation\">Gen. R. s. 26</span>, v. <a href=\"#\" data-headword=\"נָפִיל\">נָפִיל</a>. <span class=\"citation\">B. Kam. III, 10</span> <span dir=\"rtl\">ה׳ את שינו</span> struck out his tooth; <span class=\"citation\">Tosef. ib. IX, 23</span>; a. fr.—Esp. <i>to miscarry</i>. <span class=\"citation\">Nidd. III, 1</span> <span dir=\"rtl\">המַפֶּלֶת וכ׳</span> if a woman loses a lump-shaped embryo; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְנַפֵּל</b> <div class=\"sense\"><i>to prostrate one’s self</i>. <span class=\"citation\">Deut. R. s. 2</span>, v. <a href=\"#\" data-headword=\"נִיפּוּל\">נִיפּוּל</a>.</div></div><div class=\"sense\"><b>Nif. הִנָּפֵל</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"נִיפּוּל\">נִיפּוּל</a>) <i>to fall apart, be spoiled</i>. <span class=\"citation\">Tosef. Sabb. VI</span> (<span class=\"citation\">VII), 14</span> <span dir=\"rtl\">שלא תִינָּפֵל הפת</span>, v. <a href=\"#\" data-headword=\"צָוַוח\">צָוַוח</a>.</div></div>","alt":[]},"20143":{"h":"נְפַל","r":"N01055","html":"<div class=\"sense\"> <span class=\"citation\">Targ. II Sam. I, 4</span>. <span class=\"citation\">Targ. Koh. XI, 3</span> <span dir=\"rtl\">למִנְפַּל</span>; a. v. fr.—Imperat. <a href=\"#\" data-headword=\"פִּיל\">פִּיל</a>. <span class=\"citation\">Targ. Is. L, 11</span>.—Part. <a href=\"#\" data-headword=\"נָפִיל\">נָפֵיל</a>, part. pass. <a href=\"#\" data-headword=\"נְפִיל\">נְפִיל</a>. <span class=\"citation\">Targ. Prov. XI, 5</span> (ed. Wil. <a href=\"#\" data-headword=\"נְפַל\">נְפַל</a>). <span class=\"citation\">Targ. Ps. CXLV, 14</span>; a. e.—<span class=\"citation\">Ḥull. 51ᵃ</span> <span dir=\"rtl\">אי נְפוּל לארעא</span> if they were thrown down (violently). <span class=\"citation\">Ib.ᵇ</span>, v. <a href=\"#\" data-headword=\"נְגִיחוּתָא\">נְגִיחוּתָא</a>. <span class=\"citation\">Ned. 65ᵇ</span> <span dir=\"rtl\">כל דמעני לאו עלי נפיל</span> not every one that becomes poor, falls on me (for support). <span class=\"citation\">B. Mets. 105ᵃ</span> <span dir=\"rtl\">בזרא דנ׳ נ׳</span> a seed (of weeds) once fallen, has fallen (cannot be destroyed by the plough). <span class=\"citation\">Meg. 15ᵇ</span> <span dir=\"rtl\">נַפְלָה ליה מילתא בדעתיה</span> something (a suspicion) had entered his mind; a. fr.</div><div class=\"sense\"><b>Af. אַפֵּיל</b> <div class=\"sense\">, as <a href=\"#\" data-headword=\"נָפַל\">preced.</a> <i>Hif.</i> <span class=\"citation\">Targ. Ps. LXXVIII, 28</span>. <span class=\"citation\">Targ. Y. Ex. XXI, 22</span>; a. fr.—<span class=\"citation\">Ḥull. 42ᵃ</span> top <span dir=\"rtl\">אַפּוּלֵי אפיל</span> (read <a href=\"#\" data-headword=\"אַפְלָא\">אַפְּלָא</a>) she may have miscarried. <span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">ומַפְּלָא ליה</span> and she miscarried through his fault; a. fr.</div></div><div class=\"sense\"><b>Ithpe. אִינְּפִיל</b> <div class=\"sense\"><i>to be upset, fall in</i>. <span class=\"citation\">M. Kat. 2ᵃ</span> <span dir=\"rtl\">דאתי לאִינְּפוּלֵי</span> a caving in (of the ground through which the water makes a road) might occur; <span class=\"citation\">ib.ᵇ</span>; a. e.</div></div>","alt":[]},"20144":{"h":"נָפִל","r":"N01056","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָפִיל\">נָפִיל</a></div>","alt":["נְפִלִים"]},"20145":{"h":"נֵפֶל","r":"N01057","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָפִל\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>capacity for seed</i>, v. <a href=\"#\" data-headword=\"נְפִילָה\">נְפִילָה</a>.</div><div class=\"sense\"><b>—2)</b>  (b. h.) <i>abortion; premature, not viable birth</i>. <span class=\"citation\">Tosef. Ohol. XVI, 13</span>; <span class=\"citation\">Pes. 9ᵃ</span>, a. e.—<span class=\"citation\">Y. Yeb. XI, end, 12ᵇ</span> <span dir=\"rtl\">אינו נ׳</span> is not considered a non-viable birth (for legal purposes); a. v. fr.—Pl. <a href=\"#\" data-headword=\"נָפִל\">נְפָלִים</a>. <span class=\"citation\">Gen. R. s. 26</span> (play on <span dir=\"rtl\">הַנְּפִלִים</span>, <span class=\"citation\">Gen. VI, 4</span>) <span dir=\"rtl\">שמלאו את העולם נ׳ וכ׳</span> they filled the world with abortions by their lascivious life. Tosef. l. c.; a. fr.</div>","alt":["נֵי׳"]},"20146":{"h":"נִפְלָא I","r":"N01058","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"נְפִיל\">נְפִיל</a></div>","alt":["(נְפֵלָא","נָפְלָא)"]},"20147":{"h":"נִפְלָא II","r":"N01059","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>giant</i>, v. <a href=\"#\" data-headword=\"נָפִיל\">נָפִיל</a> ch.,.</div>","alt":[]},"20148":{"h":"נִפְלָא III","r":"N01060","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּלָא\">פָּלָא</a>) <i>miracles</i>. <span class=\"citation\">Midr. Till. to Ps. CVI</span>; v. <a href=\"#\" data-headword=\"פֶּלֶא\">פֶּלֶא</a>.</div>","alt":["נִפְלָאָה","נִפְלָאוֹת"]},"20149":{"h":"נִפְלֵי","r":"N01061","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָפִיל\">נָפִיל</a> ch.</div>","alt":["בַּר נִ׳"]},"20150":{"h":"נִפְנֵף","r":"N01062","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נוּף\">נוּף</a> h.</div>","alt":[]},"20151":{"h":"נָפַס","r":"N01063","html":"<div class=\"sense\">, v. <span dir=\"rtl\">נפץ</span>, <span dir=\"rtl\">נפצא</span>.</div>","alt":["נְפַס","נַפָּסָא"]},"20152":{"h":"נָפַע","r":"N01064","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"פּוּעַ\">פּוּעַ</a>, <a href=\"#\" data-headword=\"פְּעָא\">פָּעָה</a>) <i>to blow, squirt into the mouth</i>. <span class=\"citation\">Ex. R. s. 1</span> (play on <a href=\"#\" data-headword=\"פּוּעָה I\">פועה</a>, <span class=\"citation\">Ex. I, 15</span>) <span dir=\"rtl\">שהיתה נוֹפַעַת יין וכ׳</span> she squirted wine into the child’s mouth after having given its mother to drink, v. <a href=\"#\" data-headword=\"נָפַח\">נָפַח</a>.</div><div class=\"sense\"><b>Hif. הִפִּיעַ</b> <div class=\"sense\"><i>to blow air into the lungs, to revive</i>. Ib. <span dir=\"rtl\">שהיתה מַפִּיעָה את וכ׳</span> (or <span dir=\"rtl\">מְפִיעָה</span>, fr. <a href=\"#\" data-headword=\"פּוּעַ\">פּוּעַ</a>) she revived the child when they said it was dead.</div></div>","alt":[]},"20153":{"h":"נְפַע","r":"N01065","html":"<div class=\"sense\"> (interch. with <a href=\"#\" data-headword=\"נְפַץ\">נְפַץ</a>) <i>to shake</i>.</div><div class=\"sense\"><b>Pa. נַפַּע</b> <div class=\"sense\"><i>to shatter</i>. <span class=\"citation\">Targ. Jer. XXIII, 29</span> ed. Lag. (ed. <span dir=\"rtl\">מפנע</span>, <span dir=\"rtl\">מפגע</span>, corr. acc.; Bxt. <span dir=\"rtl\">נפץ</span>).</div></div><div class=\"sense\"><b>Ithpa. אתְנַפַּע</b> <div class=\"sense\"><i>to be shattered</i>. <span class=\"citation\">Targ. II Chr. XXXIII, 13</span> (ed. Wil. <span dir=\"rtl\">אתכ׳</span>, corr. acc.).</div></div>","alt":[]},"20154":{"h":"נָפַף","r":"N01066","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">נִפֵּף</span>, v. <a href=\"#\" data-headword=\"נוּף\">נוּף</a> h.</div>","alt":[]},"20155":{"h":"נְפַף","r":"N01067","html":"<div class=\"sense\">, <i>Pa</i>. <span dir=\"rtl\">נַפֵּף</span> (<a href=\"#\" data-headword=\"נָפַף\">preced.</a>) <i>to fan, inspire</i>. <span class=\"citation\">Sabb. 134ᵃ</span>, v. <a href=\"#\" data-headword=\"נְפָפָא\">next w.</a></div>","alt":[]},"20156":{"h":"נְפָפָא","r":"N01068","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְפַף\">preced.</a>) <i>fan</i>. <span class=\"citation\">Sabb. 134ᵃ</span> לִינַפְּפֵיה בנ׳ Ms. M. (not <span dir=\"rtl\">ליכ׳</span>; ed. <span dir=\"rtl\">בנִפְוָותָא</span> pl., Rashi <span dir=\"rtl\">בניפ׳</span>, v. <a href=\"#\" data-headword=\"נַפְיָא\">נַפְיָא</a>) let one fan the child with a fan.</div>","alt":[]},"20157":{"h":"נְפָפִיתָא","r":"N01069","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְפָפָא\">preced.</a> wds.) <i>remnant of flour in the sieve</i>. <span class=\"citation\">Yeb. 114ᵇ</span> <span dir=\"rtl\">ס&quot;ד בהאי פורתא דנ׳ וכ׳</span> (Ar. <span dir=\"rtl\">דנפיתא</span>) can it be imagined that he could live on that little remnant of flour which thou hast left to him?</div>","alt":[]},"20158":{"h":"נָפַץ","r":"N01070","html":"<div class=\"sense\"><i>to scatter, shake out, empty.</i> <span class=\"citation\">Bicc. I, 8</span> <span dir=\"rtl\">נוֹפֵץ וכ׳</span> he scatters them on the ground, and does not read. <span class=\"citation\">Tosef. B. Bath. IV, 2</span> <span dir=\"rtl\">נוֹפְצוֹ</span> he shakes the bag out. <span class=\"citation\">Keth. 72ᵃ</span> (the Mishnah means) <span dir=\"rtl\">שתִּמָּלֵא ונוֹפֶצֶת</span> that she should receive (the semen) and then discharge it (by violent movements); a. e.</div><div class=\"sense\"><b>Pi. נִפֵּץ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נְפָפִיתָא\">same</a>. <span class=\"citation\">Kil. V, 7</span> <span dir=\"rtl\">יְנַפֵּץ</span> he must shake the grain out of the ears; Y. ib. 30ᵃ bot. <span class=\"citation\">Deut. R. s. 3</span> <span dir=\"rtl\">וִינַפַּץ אבני וכ׳</span> and scatter the stones prepared for rebuilding the Temple. <span class=\"citation\">Lev. R. s. 10</span>; s. 19 <span dir=\"rtl\">בשעה שאתה מְנַפְּצוֹ אין וכ׳</span> as soon as you shake it out (of its marrow), it is good for nothing. <span class=\"citation\">Midr. Till. to Ps. XVII</span> אני מְנַפֵּץ … כשם שאתה נִפַּצְתָּ וכ׳ I will dash thy babes against the rock, as thou didst my babes; a. e.</div><div class=\"sense\"><b>—2)</b>  (interch. with <a href=\"#\" data-headword=\"נָפַס\">נפס</a>) <i>to beat</i> flax, <i>to hatchel</i> wool. <span class=\"citation\">Sabb. XIII, 4</span> <span dir=\"rtl\">והמְנַפֵּץ</span> (Y. ed. a. Ar. <span dir=\"rtl\">המְנַפֵּס</span>). Ib. VII, 2. Ib. 73ᵇ, v. <a href=\"#\" data-headword=\"נָפַט\">נָפַט</a>. <span class=\"citation\">Ber. 58ᵃ</span> <span dir=\"rtl\">ונִפֵּץ</span>; Tosef. ib. VII (VI), 2 <span dir=\"rtl\">וניפס</span>, ed. Zuck. (Var. <span dir=\"rtl\">נפץ</span>); Y. ib. IX, 13ᶜ top <span dir=\"rtl\">וניפס</span>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to spread</i>. <span class=\"citation\">Midr. Till. to Ps. XXII</span> <span dir=\"rtl\">מְנַפֶּצֶת</span>, v. <a href=\"#\" data-headword=\"נָצַץ\">נָצַץ</a>.</div></div>","alt":[]},"20159":{"h":"נְפַץ","r":"N01071","html":"<div class=\"sense\"><b>1)</b> <i>to scatter, shake out</i>. <span class=\"citation\">Targ. O. Gen. XXIV, 20</span> (ed. Berl. <span dir=\"rtl\">נְפַצַּת</span>). <span class=\"citation\">Targ. Jud. VI, 38</span> ed. Lag. (ed. <span dir=\"rtl\">נפק</span>, incorr.).—<span class=\"citation\">Nidd. 31ᵃ</span> (prov.) <span dir=\"rtl\">פּוּץ מלחא ושדי וכ׳</span> shake the salt off, and throw the meat to the dog (when life escapes, the body decays). <span class=\"citation\">Gen. R. s. 36</span> (ref. to <span dir=\"rtl\">נפצה</span>, <span class=\"citation\">Gen. IX, 19</span>) <span dir=\"rtl\">לדגה … דנַפְצָה עוברה וכ׳</span> like a large fish that scatters its roe &amp;c.; a. e.—<span class=\"citation\">Snh. 67ᵇ</span> <span dir=\"rtl\">דנָפֵיץ</span> (Rashi <span dir=\"rtl\">מְנַפֵּץ</span>) he scattered, i.e. <i>blew his nose</i></div><div class=\"sense\"><b>—2)</b> <i>to shatter, break</i>. <span class=\"citation\">Targ. Jud. VII, 19</span>.</div><div class=\"sense\"><b>—3)</b> <i>to beat, hatchel</i>. <span class=\"citation\">Yoma 20ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲגַר II\"><span dir=\"rtl\">אֲגַר</span> II</a>.—Part. pass. <a href=\"#\" data-headword=\"נְפַץ\">נְפִיץ</a>. <span class=\"citation\">Ḥull. 51ᵇ</span>, a. e. <span dir=\"rtl\">כיתנא דדייק ולא נ׳</span> flax which has been pounded, but not carded (freed of hard substances).</div><div class=\"sense\"><b>—4)</b> <i>to snap</i> a chalked cord for marking. <span class=\"citation\">Targ. Is. XLIV, 13</span>.</div><div class=\"sense\"><b>Pa. נַפֵּיץ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נָפַץ\">same</a>. <span class=\"citation\">Targ. Jer. LI, 34</span>.—<span class=\"citation\">Ib. XXIII, 29</span>, v. <a href=\"#\" data-headword=\"נְפַע\">נְפַע</a>.—<span class=\"citation\">Targ. Esth. I, 11</span> <span dir=\"rtl\">ומְנַפְּסָן</span>.—Part. pass. <span dir=\"rtl\">מְנַפַּץ</span>. <span class=\"citation\">Targ. Is. XXVII, 9</span>.—<span class=\"citation\">B. Kam. 93ᵇ</span> <span dir=\"rtl\">נַפְּצֵיה נַפּוּצֵי</span>, v. <a href=\"#\" data-headword=\"סָרַק II\"><span dir=\"rtl\">סְרַק</span> II</a>. <span class=\"citation\">Sabb. 147ᵃ</span> <span dir=\"rtl\">מְנַפְּצֵי גלימייהו</span> shaking their cloaks. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נַפּוּצוּ וכ׳</span> shake them in his face. <span class=\"citation\">Ḥull. 113ᵃ</span> <span dir=\"rtl\">ומְנַפֵּיץ ליה</span> and shakes the salt off. <span class=\"citation\">Ib. 76ᵇ</span> <span dir=\"rtl\">נַפְּצֵיה וכ׳</span> he split it, and found two nerves; a. e.—[<span class=\"citation\">B. Bath. 45ᵃ</span> <span dir=\"rtl\">מפצי</span>; <span class=\"citation\">Keth. 91ᵇ</span>, sq. <span dir=\"rtl\">מפצינא</span>, v. <a href=\"#\" data-headword=\"פְּצָא\">פְּצָא</a>.]</div></div>","alt":[]},"20160":{"h":"נַפָּצָא","r":"N01072","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְפַץ\">preced.</a>) <i>flax-beater, carder</i>. <span class=\"citation\">Yeb. 118ᵇ</span>; <span class=\"citation\">Keth. 75ᵃ</span> <span dir=\"rtl\">דנ׳ גברא תיקרייה וכ׳</span> though the husband be a carder, his wife will call him out to the threshold and sit down (proud of her husband); [Ar. <span dir=\"rtl\">נפסא</span>: <i>a guardsman in the vegetable garden</i>, denom. of <a href=\"#\" data-headword=\"נָפוֹס\">נָפוֹס</a>.]</div>","alt":["נַפָּסָא"]},"20161":{"h":"נַפְצָא","r":"N01073","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נַפָּצָא\">preced.</a> wds.) <i>scattering</i>. <span class=\"citation\">Nidd. 30ᵇ</span> <span dir=\"rtl\">סמא דנ׳ וכ׳</span> he made them drink a scattering drug (which destroys the semen in the womb).</div>","alt":[]},"20162":{"h":"*נָפַק","r":"N01074","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"פּוּק\">פּוּק</a>) <i>to go out</i>. <span class=\"citation\">Cant. R. to III, 4</span> (play on <span dir=\"rtl\">פ̇ל̇צ̇ו̇ת̇</span>, <span class=\"citation\">Is. XXI, 4</span>) <span dir=\"rtl\">על ידי שנפֹקו לדבר ל̇צ̇ו̇ת̇</span> because they went out for lascivious purposes.</div>","alt":[]},"20163":{"h":"נְפַק","r":"N01075","html":"<div class=\"sense\">(corresp. to h. <span dir=\"rtl\">יצא</span>) <a href=\"#\" data-headword=\"*נָפַק\">same</a>, </div><div class=\"sense\"><b>1)</b> <i>to go out, come out; to result, end</i>. Targ. O. VIII, 7 <span dir=\"rtl\">מִיפַּק</span> ed. Berl. (oth. ed. a. Y. <span dir=\"rtl\">מֵיפַק</span>); a. v. fr.—Y. Ber. I, 2ᶜ top <span dir=\"rtl\">שרי מלכא נ׳ וכ׳</span> when the king begins to march out, even if he has not yet gone out, we say, he has gone out. Ib. 3ᶜ bot. <span dir=\"rtl\">הוינן נַפְקִין לתעניתא</span> we went out for fast and prayer. <span class=\"citation\">Koh. R. to X, 8</span> <span dir=\"rtl\">מִינְּפַק ליה</span> (= <span dir=\"rtl\">מן נ׳</span>) after he came out. <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> <span dir=\"rtl\">מִנַּפְקִין</span> when they came out; <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">מן דנַפְקוּן</span>. Y. l. c. <span dir=\"rtl\">לא נפקון טבאות</span> (Matt. K. to Lam. R. l. c. <span dir=\"rtl\">לא נַפְקַת להון</span>) they did not end well. Pesik. B’shall., p. 94ᵃ <span dir=\"rtl\">וגוש חלבאי נפקין וכ׳</span> and the men of Giscala went out after them with sticks &amp;c.; <span class=\"citation\">Koh. R. to XI, 2</span> <span dir=\"rtl\">וגוש חלב אנפקין</span> (corr. acc.); a. v. fr.—Imperat. <a href=\"#\" data-headword=\"פּוּק\">פּוּק</a>. <span class=\"citation\">Targ. Gen. VIII, 16</span>; a. fr.—<span class=\"citation\">Erub. 14ᵇ</span>, a. e. <span dir=\"rtl\">פ׳ חזי וכ׳</span>, v. <a href=\"#\" data-headword=\"דְּבַר\">דְּבַר</a>. <span class=\"citation\">Sabb. 106ᵃ</span>, a. e. <span dir=\"rtl\">פ׳ תני וכ׳</span>, v. <a href=\"#\" data-headword=\"בַּר\">בַּר</a> I ch.—Part. <a href=\"#\" data-headword=\"נָפִיק\">נָפֵיק</a>. <span class=\"citation\">Targ. I Kings XV, 17</span>; v. <a href=\"#\" data-headword=\"נָפֵק\">next w.</a>; a. fr.—<span dir=\"rtl\">(<span dir=\"rtl\">כנ׳</span>) <span dir=\"rtl\">כד נפיק ביה</span></span> = h. <span dir=\"rtl\">כיוצא בו</span> (v. <a href=\"#\" data-headword=\"יָצָא\">יָצָא</a>) <i>similar to, corresponding</i>. <span class=\"citation\">Targ. Y. II, Gen. II, 18</span>. <span class=\"citation\">Targ. Y. Deut. XIV, 8</span> (not <span dir=\"rtl\">כַּנְפֵיק</span>, <span dir=\"rtl\">כַּנְפַק</span>).—Y. Ber. VI, 10ᵇ bot. <span dir=\"rtl\">נ׳ אנא ידי חובתי</span> do I do my duty?, v. <a href=\"#\" data-headword=\"יָצָא\">יָצָא</a>. <span class=\"citation\">Succ. 36ᵇ</span> <span dir=\"rtl\">ונ׳ בה</span> and used it for doing his duty (for the ceremony of Ethrog).—<span class=\"citation\">Y. Sabb. VI, 8ᵃ</span> top, a. e. <span dir=\"rtl\">מה נָ׳ מן ביניהון</span> what is the outcome from between them?, i.e. what is the difference between them in practice?—<span dir=\"rtl\">נפקא מינה וכ׳</span> the practical difference is &amp;c. <span class=\"citation\">Bets. 6ᵇ</span> <span dir=\"rtl\">למאי נ׳ מינה</span> in regard to what practice is there a difference (whether or not eggs found in a chicken can be hatched)? <span dir=\"rtl\">למקח וממכר</span> it makes a difference in trade (if one bought eggs for breeding). <span class=\"citation\">Keth. 72ᵃ</span> <span dir=\"rtl\">מאי נ׳ לה מינה תיעביד</span> what difference does it make to her? let her do it; a. v. fr.—<span class=\"citation\">Tem. 7ᵃ</span> <span dir=\"rtl\">נ׳ ליה וכ׳</span> it is derived from the Biblical word &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תֵּיפוּק ליה זריקה וכ׳</span> let ‘sprinkling’ be derived from &amp;c.—<span class=\"citation\">Gen. R. s. 52</span> <span dir=\"rtl\">ונֵיפוֹק ידוי</span> and do justice to it (to the verse to be explained), v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to take out, exclude</i>. <span class=\"citation\">Sabb. 74ᵃ</span> <span dir=\"rtl\">ולֵיפוּק חדא וכ׳</span> let him take out one (of the enumerated categories) and insert another one. <span class=\"citation\">Ḥull. 43ᵃ</span> <span dir=\"rtl\">לא תִיפַּק</span>, v. infra.—[<span class=\"citation\">Targ. Am. IX, 13</span>, v. infra.]</div><div class=\"sense\"><b>Af. אַפֵּיק</b> <div class=\"sense\">, <i>Haf</i>. <a href=\"#\" data-headword=\"הֶנְפֵּק\">הַנְפַּק</a> </div><div class=\"sense\"><b>1)</b> <i>to lead forth, carry forth; to bring forth, produce; to derive; to take out, exclude</i>. <span class=\"citation\">Targ. Ex. XVI, 3</span>. <span class=\"citation\">Targ. Am. IX, 13</span> <span dir=\"rtl\">במַפִּיק</span> ed. Lag. (oth. ed. <span dir=\"rtl\">במִפַּק</span>, corr. acc.). <span class=\"citation\">Targ. Job XV, 13</span>; a. fr.—<span class=\"citation\">Ber. 38ᵃ</span> (ref. to <span dir=\"rtl\">המוציא</span> in the benediction over bread) <span dir=\"rtl\">דא׳ משמע</span> it means ‘who has brought forth’; <span dir=\"rtl\">דמַפִּיק משמע</span> it means ‘who brings forth’. Ib. <span dir=\"rtl\">אַפִּיקוּ ליה ריפתא</span> they brought out bread (and placed it) before him. Ib. (ref. to <span dir=\"rtl\">המוציא</span>, <span class=\"citation\">Ex. VI, 7</span>) <span dir=\"rtl\">כד מַפִּיקְנָא לכו … דאַפֵּיקִית וכ׳</span> when I lead you forth, I shall do for you a thing that you may know that it is I who led you forth. <span class=\"citation\">Sot. 16ᵇ</span>; <span class=\"citation\">R. Hash. 13ᵃ</span> <span dir=\"rtl\">לא תַפִּיק נפשך יכ׳</span> do not let thyself go beyond the established rule. <span class=\"citation\">B. Bath. 60ᵃ</span> <span dir=\"rtl\">דהוה מַפִּיק וכ׳</span> which led to (opened towards) etc. <span class=\"citation\">Tem. 3ᵇ</span> <span dir=\"rtl\">מפיק שם וכ׳</span> utters the name of the Lord in vain. <span class=\"citation\">Ib. 7ᵃ</span> <span dir=\"rtl\">מַפְּקִינָן לבמת יחיד</span> we derive from it a rule for individual high-places.—<span class=\"citation\">Ḥull. 42ᵇ</span> <span dir=\"rtl\">אַפֵּיק חדא וכ׳</span> take out one category and insert another. <span class=\"citation\">Ib. 43ᵃ</span> top <span dir=\"rtl\">הנך דאַפְּקַת לא תַפִּיק</span> Tosaf. (ed. <span dir=\"rtl\">לא תיפק</span>) the two which thou didst exclude, do not exclude; a. v. fr.—<span dir=\"rtl\">לְאַפּוּקֵי</span> or <span dir=\"rtl\">לַאֲפוּקֵי</span> <i>to the exclusion of</i>, v. <a href=\"#\" data-headword=\"אַפֵּק\">אַפֵּק</a>.</div><div class=\"sense\"><b>—2)</b> <i>to take out by legal decision; to collect; to claim</i>. <span class=\"citation\">Keth. 76ᵇ</span> <span dir=\"rtl\">מייתי אב ראיה ומפיק</span> the father brings evidence and gets a verdict for collecting, opp. <span dir=\"rtl\">ומוקים</span> for letting the money stand where it is. Y. Gitt. I, end, 43ᵈ <span dir=\"rtl\">ואַפְּקוּן מיניה</span> and collected from him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בעון מִיפְּקָא</span> (v. supra <i>Pe</i>. 2) they wanted to collect. Y. Shebu. VII, 38ᵃ top <span dir=\"rtl\">אתון ואַפְּקוּן דלא וכ׳</span> they came and claimed that he had not given them anything; a. fr.</div></div><div class=\"sense\"><b>Ittaf. אִיתַּפַּק</b> <div class=\"sense\">, <i>Ithaf</i>. <span dir=\"rtl\">אִתְאֵפַּק</span> <i>to be carried forth</i>. <span class=\"citation\">Targ. Gen. XXXVIII, 25</span>; a. fr.—Y. Gitt. VI, 48ᵃ bot. <span dir=\"rtl\">אתא׳ למקטלא</span> was led out to be executed.</div></div>","alt":[]},"20164":{"h":"נָפֵק","r":"N01076","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, constr. <a href=\"#\" data-headword=\"נְפַק\">נְפַק</a> (<a href=\"#\" data-headword=\"נְפַק\">preced.</a>) <i>going out</i>; <span dir=\"rtl\">נְ׳ בַּר</span> <i>a male prostitute; fem</i>. <a href=\"#\" data-headword=\"נִפִקָא\">נַפְקָא</a>, constr. <a href=\"#\" data-headword=\"נַפְקַת\">נַפְקַת</a>; <span dir=\"rtl\">נַפְקַת בָּרָא</span> a) <i>a female prostitute</i>. <span class=\"citation\">Targ. Y. II, Deut. XXIII, 18</span>. <span class=\"citation\">Targ. Gen. XXIV, 35</span>.—b) (sub <span dir=\"rtl\">בית</span>) <i>brothel, prostitution</i>. <span class=\"citation\">Targ. I Kings XIV, 24</span>; a. fr.</div>","alt":[]},"20165":{"h":"נִפִקָא","r":"N01077","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָפֵק\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"צֹאָה\">צֹאָה</a>, <i>excrements</i>. <span class=\"citation\">Gitt. 69ᵇ</span> top.</div><div class=\"sense\"><b>—2)</b>  = h. <a href=\"#\" data-headword=\"מוֹץ ³\">מוֹצָא</a>, <i>outlet, opening</i>; [Ar.: <i>projection</i>].—Pl. <span dir=\"rtl\">נִפְקֵי</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Erub. 87ᵇ</span></div>","alt":["נִי׳"]},"20166":{"h":"נַפְקוּתָא","r":"N01078","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נִפִקָא\">preced.</a> wds.) = h. <a href=\"#\" data-headword=\"הוֹצָאָה\">הוֹצָאָה</a>, <i>expense</i>. <span class=\"citation\">Ned. 7ᵃ</span> <span dir=\"rtl\">לנ׳ בעלמא</span> for general expense (not charity). <span class=\"citation\">Tosef. B. Mets. IX, 13</span> (in a farming contract) <span dir=\"rtl\">ואנא בעמלי ובנַפְקוּת ידיי וכ׳</span> and I shall get one half for my labor and my outlay; <span class=\"citation\">B. Mets. 105ᵃ</span>.—[In Talmud. comment. and casuists: <a href=\"#\" data-headword=\"נ׳\">נ׳</a> <i>outcome, difference</i>, v. <a href=\"#\" data-headword=\"נְפַק\">נְפַק</a>.]—Pl. (fr. <a href=\"#\" data-headword=\"נַפְקָתָא\">נפקתא</a>) <a href=\"#\" data-headword=\"נַפְקָתָא\">נַפְקָתָא</a>. <span class=\"citation\">Pesik. R. s. 31</span>, v. <a href=\"#\" data-headword=\"מְעַלָּתָא\">מְעַלָּתָא</a>.</div>","alt":[]},"20167":{"h":"נַפְקַת","r":"N01079","html":"<div class=\"sense\">, constr. of <a href=\"#\" data-headword=\"נִפִקָא\">נַפְקָא</a>, v. <a href=\"#\" data-headword=\"נָפֵק\">נָפֵק</a></div>","alt":[]},"20168":{"h":"נַפְקָתָא","r":"N01080","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַפְקוּתָא\">נַפְקוּתָא</a></div>","alt":[]},"20169":{"h":"נַפְרָזָא","r":"N01081","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (an adapt. of λεόπαρδος) <i>leopard</i>. <span class=\"citation\">B. Kam. 16ᵃ</span> (Ms. M. <span dir=\"rtl\">נפריא</span>), v. <a href=\"#\" data-headword=\"אָפָא\">אָפָא</a>.</div>","alt":[]},"20170":{"h":"נָפֵשׁ","r":"N01082","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָפֵשׁ\">נָפַשׁ</a>, b. h. <i>Nif.</i>) <i>breathing, resting</i>.—Pl. <span dir=\"rtl\">נְפֵשִׁים</span>, <span dir=\"rtl\">נְפֵשִׁין</span>, <a href=\"#\" data-headword=\"נְפֵי\">נְפֵי׳</a>. Tanḥ. Vaëra 6 (expl. <span dir=\"rtl\">ישעו</span>, <span class=\"citation\">Ex. V, 9</span>) <span dir=\"rtl\">אל יהיו משתעשעין כלומר אל יהיו נ׳</span> (not <span dir=\"rtl\">ואל יהון</span>) let them not play, that is, let them not rest (on the Sabbath); <span class=\"citation\">Ex. R. s. 5</span>.</div>","alt":[]},"20171":{"h":"נְפֵשׁ","r":"N01083","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְפֵישׁ\">נְפֵישׁ</a></div>","alt":[]},"20172":{"h":"נֶפֶשׁ","r":"N01084","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְפֵשׁ\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>resting place</i>, esp. <i>a structure next to</i> or <i>over a tomb.</i> Ohol. VII, 1 <span dir=\"rtl\">נ׳ אטומה</span> a solid tomb-structure (to which there is no access). <span class=\"citation\">Shek. II, 5</span> <span dir=\"rtl\">מותר המת בונין לו נ׳ וכ׳</span> from what is left over of the appropriation for funeral expenses, we build a monument &amp;c.; (<span class=\"citation\">Gen. R. s. 82</span> <a href=\"#\" data-headword=\"בַּיִת\">בַּיִת</a>). <span class=\"citation\">Tosef. Erub. VI</span> (<span class=\"citation\">V), 4</span>, sq.; <span class=\"citation\">Erub. 55ᵇ</span> (contrad. to <span dir=\"rtl\">קבר</span>).—Pl. <span dir=\"rtl\">נְפָשׁוֹת</span>. <span class=\"citation\">Ib. V, 1</span> <a href=\"#\" data-headword=\"נ׳\">נ׳</a> sepulchres (containing a place of shelter). <span class=\"citation\">Y. Shek. II, 47ᵃ</span> top; Gen. R. l. c. <span dir=\"rtl\">אין עושין נ׳ וכ׳</span> no monuments need be put up for the righteous, v. <a href=\"#\" data-headword=\"זִכָּרוֹן\">זִכָּרוֹן</a>. <span class=\"citation\">Tosef. Ohol. XVII, 4</span> <span dir=\"rtl\">חוקת נ׳ שבא&quot;י וכ׳</span> the presumption in the case of sepulchres in Palestine is that they are levitically clean, except those marked.</div><div class=\"sense\"><b>—2)</b> <i>soul, life; person; will, desire, disposition</i>. <span class=\"citation\">B. Mets. IV, 6</span> <span dir=\"rtl\">שאינו אלא נ׳ רעה</span> for it (the refusal of a coin on the ground of a slight abrasion) proves merely a malevolent soul (illiberality in dealing); <span class=\"citation\">ib. 52ᵇ</span>, v. <a href=\"#\" data-headword=\"קְהֵי\">קְהֵי</a>. <span class=\"citation\">Gen. R. s. 14</span> (names of the soul) <span dir=\"rtl\">נ׳ רוח וכ׳</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נ׳ זו הדם</span> <i>nefesh</i> means blood (life). <span class=\"citation\">Ib.</span> (ref. to <span class=\"citation\">Gen. II, 7</span>, a. <span class=\"citation\">VII, 22</span>) <span dir=\"rtl\">כאן הוא עושה נשמה נ׳ וכ׳</span> here the text calls the soul (<a href=\"#\" data-headword=\"נְשָׁמָה\">נשמה</a>) <i>nefesh</i>, and there, <i>ruaḥ</i> (spirit); ib. s. 32.—<span class=\"citation\">Snh. IV, 5</span> <span dir=\"rtl\">נ׳ אחת</span> one (person’s) life. <span class=\"citation\">Y. Taan. III, beg. 66ᵇ</span> <span dir=\"rtl\">מכיון שנתנו ב&quot;ד נַפְשָׁן וכ׳</span> as soon as the court has declared its will to do a thing. <span class=\"citation\">Nidd. 65ᵇ</span>, a. fr. <span dir=\"rtl\">בעל נ׳</span> one who is master over his desire, <i>a conscientious man</i>.—<span class=\"citation\">Ber. 44ᵇ</span> <span dir=\"rtl\">כל נ׳ משיב את הנ׳</span> all life (animal food) restores life; <span dir=\"rtl\">וכל קרוב לנ׳ וכ׳</span> and what is nearest life (the neck which contains the jugular vein) &amp;c.—<span class=\"citation\">Y. Keth. V, 30ᵇ</span> top <span dir=\"rtl\">דברים שהן קיום נ׳</span> things required for sustaining life. <span class=\"citation\">Yoma 74ᵇ</span> <span dir=\"rtl\">אבידת נ׳</span>, v. <a href=\"#\" data-headword=\"אֲבֵילָה\">אֲבֵירָה</a>; a. v. fr.—<span dir=\"rtl\">דחה נ׳</span>, v. <a href=\"#\" data-headword=\"דָּחָה\">דָּחָה</a>.—Sifra M’tsorʿa, Zab., Par. 3, ch. VI <span dir=\"rtl\">ואם נַפְשְׁךָ לומר וכ׳</span> (= <span dir=\"rtl\">ואיבעית אימא</span>, v. <a href=\"#\" data-headword=\"בְּעֵי I\">בְּעֵי</a>) or if you prefer (another argument); <span class=\"citation\">Ḥull. 78ᵇ</span> bot. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מה ואם נפשך לומר</span> why should you prefer another argument?, i.e. what objection can there be to the argument offered before?—(<a href=\"#\" data-headword=\"מ\">מ</a>)<span dir=\"rtl\">מה נפשך</span>, v. <a href=\"#\" data-headword=\"מָה\">מָה</a>.—<span class=\"citation\">Ḥull. IV, 7</span> (<span class=\"citation\">77ᵃ</span>) <span dir=\"rtl\">נ׳ היפה</span> <i>one not fastidious</i>.—<span class=\"citation\">B. Bath. 89ᵃ</span> נ׳ מאזנים <i>the opening in which the tongue of scales rests</i> (agina).—Pl. as ab. <span dir=\"rtl\">דיני נ׳</span>, v. <a href=\"#\" data-headword=\"דִּין II\"><span dir=\"rtl\">דִּין</span> II</a>. Snh. l. c. <span dir=\"rtl\">עדי נ׳</span> witnesses in capital cases.—<span class=\"citation\">Yoma VIII, 6</span> <span dir=\"rtl\">ספק נ׳</span> the possibility of danger to human life; <span class=\"citation\">Sabb. 129ᵃ</span>; a. fr.</div>","alt":[]},"20173":{"h":"נְפַשׁ","r":"N01085","html":"<div class=\"sense\"><b>1)</b> <i>monument</i>. Pesik. B’shall., p. 79ᵇ <span dir=\"rtl\">ועבדון ליה נ׳ וכ׳</span> and they erected a monument to him (the dog that saved their lives), and to this day they call it <span dir=\"rtl\">נ׳ דכלבא</span> the dog’s monument. <span class=\"citation\">Y. Erub. V, 22ᵇ</span> bot. <span dir=\"rtl\">נ׳ דסיריקין</span>, v. <a href=\"#\" data-headword=\"סְרִיקִין\">סְרִיקִין</a>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>soul, will</i> &amp;c. (v. <a href=\"#\" data-headword=\"נֶפֶשׁ\">preced.</a>). <span class=\"citation\">Targ. Gen. I, 20</span>. <span class=\"citation\">Ib. XXIII, 8</span>; a. fr.—<span class=\"citation\">Cant. R. to II, 16</span>, v. <a href=\"#\" data-headword=\"נְסַב\">נְסַב</a>. <span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">בשר נ׳ חלף נ׳</span> meat (is a necessary of life), life for life, v. preced.—<span dir=\"rtl\">נח נַפְשֵׁיה</span>, v. <a href=\"#\" data-headword=\"נוּחַ\">נוּחַ</a> ch. <span class=\"citation\">Pes. 68ᵇ</span> <span dir=\"rtl\">נַפְשָׁאִי</span>, v. <a href=\"#\" data-headword=\"חֲדֵי\">חֲדֵי</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אדעתא דנפשיה</span> with the intention of benefiting himself. <span class=\"citation\">Sot. 16ᵇ</span>, a. e. <span dir=\"rtl\">לא תפיק נַפְשָׁךְ</span>, v. <a href=\"#\" data-headword=\"נְפַק\">נְפַק</a>; a. v. fr.—Pl. <a href=\"#\" data-headword=\"נְפַשׁ\">נַפְשָׁן</a>, <span dir=\"rtl\">נַפְשָׁתָא</span>. <span class=\"citation\">Targ. Jud. XVIII, 25</span> (ed. Lag. sing.). <span class=\"citation\">Targ. Gen. XIV, 21</span>; a. fr.—[<span class=\"citation\">Targ. Y. Lev. XXVI, 15</span> <span dir=\"rtl\">נַפְשָׁתֵיכוֹן</span> (sing.).]—Y. Ab. Zar. III, 42ᶜ, v. <a href=\"#\" data-headword=\"סָכַן II\"><span dir=\"rtl\">סְכן</span> II</a>.</div>","alt":["נַפְשָׁא","נַפְשָׁה"]},"20174":{"h":"נֹפֶת","r":"N01086","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נוֹפֶת\">נוֹפֶת</a></div>","alt":[]},"20175":{"h":"נִפְתָּאֵי","r":"N01087","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִפְתִּי\">נִפְתִּי</a></div>","alt":[]},"20176":{"h":"נַפְתּוֹחָא","r":"N01088","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַבְטָיָיא\">נַבְטָיָיא</a></div>","alt":["נַפְתּוֹחָאָה","נַפְתֹּחָ׳"]},"20177":{"h":"נִפְתִּי","r":"N01089","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נַפְתּוֹחָא\">preced.</a>) <i>Nabataean</i>. <span class=\"citation\">Y. Sabb. XIV, beg. 14ᵇ</span>, v. <a href=\"#\" data-headword=\"נִיוְתִּי\">נִיוְתִּי</a>. Ib. XVI, end, 15ᵈ; <span class=\"citation\">Y. Yoma VIII, 45ᵇ</span>.—Pl. <a href=\"#\" data-headword=\"נִפְתָּאֵי\">נִפְתָּאֵי</a>. <span class=\"citation\">Y. B. Bath. VIII, 16ᵇ</span> bot. <span class=\"citation\">Y. Snh. IX, end, 27ᵇ</span></div>","alt":["נִפְתַּיי","נִפְתָּיָיא","… יָיה","נִי׳"]},"20178":{"h":"נֵץ I","r":"N01090","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>sprouting, flower, blossom.</i> <span class=\"citation\">Ukts. II, 1</span> <span dir=\"rtl\">והנץ שלה</span> and the flower-like substance on cucumbers. <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">הנץ שלו</span> the sproutings on the pomegranate; (Tosef. ib. I, 8 <a href=\"#\" data-headword=\"סֵיאָר\">סיאר</a>, <span dir=\"rtl\">שיער</span>). <span class=\"citation\">Y. Shebi. IV, end, 35ᶜ</span> (ref. to <span dir=\"rtl\">משינצו</span>, ib. IV, 10) <span dir=\"rtl\">לאי דו נץ שהוא וכ׳</span> what blossoming is meant? Such as promises one Robʿa of olives. <span class=\"citation\">Cant. R. to II, 3</span> <span dir=\"rtl\">נִיצּוֹ קודם לעליו</span> its blossoms come out before its leaves. <span class=\"citation\">Tosef. Par. XII</span> (<span class=\"citation\">XI), 1</span> <span dir=\"rtl\">משישיר את ניצו</span> when it has shed its blossoms; a. fr.—<span class=\"citation\">Gen. R. s. 28</span> נץ השדרה Ar. (ed. <a href=\"#\" data-headword=\"לוּז\">לוּז</a> q. v.).—<span dir=\"rtl\">נץ החלכ</span>, v. <a href=\"#\" data-headword=\"חָלָב\">חָלָב</a>.</div><div class=\"sense\"><b>—2)</b>  <a href=\"#\" data-headword=\"נֵץ\">נֵץ</a>, <a href=\"#\" data-headword=\"הַנֵּץ\">הַנֵּץ</a> name of <i>a coin</i> (Blossom) = 7/8 of an As (v. <a href=\"#\" data-headword=\"דָּרוֹסָה\">דָּרוֹסָה</a>). <span class=\"citation\">Kidd. 12ᵃ</span>; <span class=\"citation\">Tosef. B. Bath. V, 12</span> ed. Zuck. (Var. <span dir=\"rtl\">הינץ</span>, some ed. <a href=\"#\" data-headword=\"חָצַץ I\">חיצץ</a>, corr. acc.).—Pl. <span dir=\"rtl\">נִיצִּים</span>, <a href=\"#\" data-headword=\"הִינְצִין\">הִינְצִין</a>. Y. Kidd. I, 58ᵈ; Bab. ib. l. c.; Tosef. l. c.; v. <a href=\"#\" data-headword=\"הַנֵּץ\">הַנֵּץ</a>.</div>","alt":[]},"20179":{"h":"נֵץ","r":"N01091","html":"<div class=\"sense\">, <i>blossom</i>. <span class=\"citation\">Targ. O. Gen. XL, 10</span>. <span class=\"citation\">Targ. O. Num. XVII, 23</span> (ed. Berl. <a href=\"#\" data-headword=\"נֵץ\">נָץ</a>). <span class=\"citation\">Targ. Job XIV, 2</span> (ed. Lag. <a href=\"#\" data-headword=\"צִיצָא\">ציצא</a>). <span class=\"citation\">Targ. Y. II, Deut. XXVIII, 40</span> <span dir=\"rtl\">נִצָהּ</span>; a. e.—Pl. <span dir=\"rtl\">נִצִּין</span>, <span dir=\"rtl\">נֵיצִין</span>. Targ. Y. Num. l. c. <span class=\"citation\">Targ. Job XXXI, 8</span> <span dir=\"rtl\">נִצַּיי</span> (not <span dir=\"rtl\">נצרי</span>); a. e.—נִצַּיָּא <i>the blooming stage</i>. Y. Maass Sh. IV, 55ᵇ bot., v. <a href=\"#\" data-headword=\"חֲבָטָא\">חֲבָטָא</a>; <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כות׳<sup>2</sup>) <a href=\"#\" data-headword=\"נִצְבָּא\">נצבא</a> (corr. acc.).</div>","alt":["נֵיץ","נִיצָּא"]},"20180":{"h":"נֵץ II","r":"N01092","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> prob. fr. its far-sightedness, , <i>Hif.</i>) <i>hawk</i>. <span class=\"citation\">Ḥull. III, 1</span>; <span class=\"citation\">Tosef. ib. III, 3</span>; a. e.</div>","alt":[]},"20181":{"h":"נַצָּא","r":"N01093","html":"<div class=\"sense\">(mostly <span dir=\"rtl\">בר נ׳</span>) <a href=\"#\" data-headword=\"נֵץ II\">same</a>. <span class=\"citation\">Targ. O. Lev. XI, 16</span>; <span class=\"citation\">Deut. XIV, 15</span>. <span class=\"citation\">Targ. Job XXXIX, 26</span> (Ms. <a href=\"#\" data-headword=\"נֵיץ\">נֵיצָא</a>).—Pl. <a href=\"#\" data-headword=\"צָנַן\">נֵצָן</a>. Targ. II Esth. I, 2.</div>","alt":["נָצָא I"]},"20182":{"h":"נָצָא II","r":"N01094","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"נְצֵי\">נְצֵי</a>) </div><div class=\"sense\"><b>1)</b>  (adj.) <i>shrunk, withered</i>.—Pl. f. <a href=\"#\" data-headword=\"צָנַן\">נָצַן</a>. <span class=\"citation\">Targ. Gen. XLI, 23</span> (h. text <span dir=\"rtl\">צנמות</span>).</div><div class=\"sense\"><b>—2)</b> <i>lean</i> (<i>low</i>) <i>ground</i>. <span class=\"citation\">M. Kat. 10ᵇ</span> <a href=\"#\" data-headword=\"נַצָּא\">נצא</a> (Ms. M. <span dir=\"rtl\">צנא</span>, v. Rabb. D. S. a. l. note); <span class=\"citation\">B. Bath. 54ᵃ</span>, v. <a href=\"#\" data-headword=\"מוּלְיָא\">מוּלְיָא</a>.</div>","alt":[]},"20183":{"h":"נְצָא","r":"N01095","html":"<div class=\"sense\"><i>to quarrel</i>, v. <a href=\"#\" data-headword=\"נְצֵי\">נְצֵי</a>.</div>","alt":[]},"20184":{"h":"נָצָא III","r":"N01096","html":"<div class=\"sense\"> (or <a href=\"#\" data-headword=\"נַצָּא\">נַצָּא</a>) m. (<a href=\"#\" data-headword=\"נְצָא\">preced.</a>) <i>strife</i>; pr. n. m. <i>Natsa</i>. <span class=\"citation\">Sabb. 56ᵇ</span> (transl. <span dir=\"rtl\">מריב</span>, <span class=\"citation\">I Chr. VIII, 34</span>, a. ref. to <span dir=\"rtl\">וירב</span>, <span class=\"citation\">I Sam. XV, 5</span>) <span dir=\"rtl\">נ׳ בר נ׳</span> Strife (Mephibosheth), son of Strife (Saul), v. <a href=\"#\" data-headword=\"נַחַל\">נַחַל</a>.</div>","alt":[]},"20185":{"h":"נָצַב","r":"N01097","html":"<div class=\"sense\"><i>to put up, place</i>, v. <a href=\"#\" data-headword=\"יָצַב\">יָצַב</a>.</div><div class=\"sense\"><b>Nif. נִצָּב</b> <div class=\"sense\"><i>to stand</i> (<i>defiantly</i>). <span class=\"citation\">Num. R. s. 18</span>, v. <a href=\"#\" data-headword=\"הַצָּבָה\">הַצָּבָה</a>.</div></div>","alt":[]},"20186":{"h":"נְצַב","r":"N01098","html":"<div class=\"sense\">, <i>to put up, plant</i>. <span class=\"citation\">Targ. Gen. IX, 20</span> (h. text <span dir=\"rtl\">נטע</span>). <span class=\"citation\">Targ. Y. Deut. XXXII, 50</span> (cmp. <a href=\"#\" data-headword=\"נָטַע\">נָטַע</a>); a. fr.—<span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">למִנְצַב נציבין</span> to plant (trees); <span class=\"citation\">Koh. R. to II, 20</span> <span dir=\"rtl\">למִינְצַב</span>. Y. Orl. I, 61ᵃ top <span dir=\"rtl\">ונ׳ לון בארץ</span> and planted them in the land (Palestine); a. fr.—Part. pass. <a href=\"#\" data-headword=\"נְצִיב\">נְצִיב</a>, <a href=\"#\" data-headword=\"נְצִיב ²\">נְצִיבָא</a>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\"><span dir=\"rtl\">חד גופנא … והוה נ׳</span> (<a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a>) <span dir=\"rtl\">וכ׳</span></span> we had a vine which was planted on our father’s grave.</div><div class=\"sense\"><b>Af. אַנְצַב</b> <div class=\"sense\"><i>to point, sharpen</i> (cmp. <a href=\"#\" data-headword=\"נִצְבָּא\">נצבתא</a>, <span class=\"citation\">Dan. II, 41</span>). <span class=\"citation\">Targ. I Sam. XIII, 21</span> <span dir=\"rtl\">לאַנְצָבָא</span>, (Ar. <span dir=\"rtl\">לאנצא</span>, v. <a href=\"#\" data-headword=\"*אֲנַץ\">אֲנַץ</a>; h. text <span dir=\"rtl\">להציב</span>).</div></div>","alt":["נְצֵיב"]},"20187":{"h":"נִצְבָּא","r":"N01099","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְצַב\">preced.</a>) <i>plant, shoots</i>. <span class=\"citation\">Targ. Job XIV, 8</span>, sq. (Ms. <a href=\"#\" data-headword=\"נְצִיב\">נְצִיב</a>). <span class=\"citation\">Targ. Is. LVII, 3</span>. <span class=\"citation\">Targ. Mic. I, 6</span> ed. Lag. (ed. <span dir=\"rtl\">מִצְבַת</span>). [<span class=\"citation\">Targ. Ez. XVII, 5</span>, v. <a href=\"#\" data-headword=\"נִסְבָּא\">נִסְבָּא</a>.]—Pl. <span dir=\"rtl\">נְצִיבִין</span>, v. <a href=\"#\" data-headword=\"נְצִיב ²\">נְצִיבָא</a>.</div>","alt":["נִי׳","נִצְבְּתָא","נִי׳"]},"20188":{"h":"נָצָה","r":"N01100","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נצי\">נצי</a></div>","alt":[]},"20189":{"h":"נִצּוּחַ","r":"N01101","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיצּוּחַ\">נִיצּוּחַ</a></div>","alt":[]},"20190":{"h":"נָצוֹחָא","r":"N01102","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְצַח\">נְצַח</a>) <i>victor</i>. <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">ולית … מאן הוא נ׳</span> (some ed. <span dir=\"rtl\">נצח</span>) and we do not know which is the victor; <span class=\"citation\">Yalk. Lev. 651</span> <span dir=\"rtl\">הי דין ניצוחיה</span> (corr. acc.); (Pesik. Ul’kaḥ., p. 180ᵃ <span dir=\"rtl\">הידין נצח</span>). Lev. R. l. c. <span dir=\"rtl\">דהוא נצוחייא</span> (corr. acc.)—Pl. <span dir=\"rtl\">נָצוֹחַיָּיא</span>. Ib. <span dir=\"rtl\">דישראל אינון נ׳</span> that the Israelites are the victors; Pesik. l. c., p. 180ᵇ. Ib. <span dir=\"rtl\">ניצוחייא</span> (corr. acc.); Yalk. l. c. <span dir=\"rtl\">נוצח׳</span> (corr. acc.).</div>","alt":[]},"20191":{"h":"נָצוֹחוֹת","r":"N01103","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָצוֹחָא\">preced.</a>) <i>illustrious men</i>. <span class=\"citation\">Cant. R. to II, 13</span> (play on <span dir=\"rtl\">הנצנים</span>, <span class=\"citation\">ib. 11</span>) <span dir=\"rtl\">הנ׳ נראו וכ׳</span> the illustrious appear in the land.</div>","alt":[]},"20192":{"h":"נְצוּלָה","r":"N01104","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָצַל\">נָצַל</a>; v. <a href=\"#\" data-headword=\"נִיצּוֹלֶת\">נִיצּוֹלֶת</a>) <i>place for refuse, dumping ground, mire</i>. <span class=\"citation\">Ber. 9ᵇ</span> כנ׳ שאין בה דגה Ar. (ed. <span dir=\"rtl\">כמְצוּלָה</span>).</div>","alt":[]},"20193":{"h":"נִצּוֹק","r":"N01105","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָצַק\">יָצַק</a>) <i>uninterrupted flow</i> of a liquid poured from vessel to vessel. <span class=\"citation\">Toh. VIII, 9</span> <span dir=\"rtl\">הנ׳ … אינן חבור וכ׳</span> an uninterrupted flow, a current on slanting ground and …, are not considered a connection (of the two liquids) either for communicating uncleanness or for producing cleanness. <span class=\"citation\">Ab. Zar. 56ᵇ</span>, a. fr. <span dir=\"rtl\">נ׳ חיבור</span>, v. <a href=\"#\" data-headword=\"חִיבּוּר\">חִיבּוּר</a>. <span class=\"citation\">Yad. IV, 7</span>. <span class=\"citation\">Naz. 50ᵇ</span> <span dir=\"rtl\">יש נ׳ לאוכלין וכ׳</span> does, or does not, the law regarding a connected flow apply to eatable things (e.g. melted fat)?; a. fr.</div>","alt":["נִיצּ׳"]},"20194":{"h":"נָצוֹר","r":"N01106","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נֵצֶר IV\"><span dir=\"rtl\">נֵצֶר</span> IV</a></div>","alt":[]},"20195":{"h":"*נָצוֹרָא","r":"N01107","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">יצר</span>) <i>joiner’s frame, clasps</i> to keep glued objects in shape. <span class=\"citation\">Targ. Is. XLIV, 13</span> ed. Lag. (oth. ed. <span dir=\"rtl\">נְצוֹרִין</span> pl.; Var. ed. Lag. <span dir=\"rtl\">נצוריין</span>; ed. Ven. I a. Levita Var. <a href=\"#\" data-headword=\"נִצְמִין\">נִצְמִין</a>; h. text <span dir=\"rtl\">מְחוּגָה</span>).</div>","alt":[]},"20196":{"h":"נָצַח","r":"N01108","html":"<div class=\"sense\"> [<i>to be bright, pure</i>,] (cmp. <a href=\"#\" data-headword=\"זָכָה\">זָכָה</a>) <i>to be victorious, win, prevail</i>. Y. Sabb. VII, 5ᵇ top <span dir=\"rtl\">אם לִנְצוֹחַ אם להִינָּצֵחַ</span> whether to conquer or to be conquered. <span class=\"citation\">Pes. 119ᵃ</span> (play on <span dir=\"rtl\">לַמְנַצֵּחַ</span>) <span dir=\"rtl\">זמרו למי שנוֹצְחִין אותו ושמח</span> sing to him who rejoices when they conquer him (prevail over him to change his evil decrees); <span class=\"citation\">Midr. Till. to Ps. IV. Pesik. R. s. 4</span>0 נָצַחְתִּי לדור וכ׳ I conquered the generation of the flood and was the loser by it, because I destroyed &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נְצָחַנִי משה וכ׳</span> Moses conquered me …, and I gained all those masses; a. fr.—Part. pass. <a href=\"#\" data-headword=\"נִצּוּחַ\">נָצוּחַ</a>. <span class=\"citation\">Ib.</span><span class=\"citation\">Pesik. R. s. 40</span> נָצַחְתִּי לדור וכ׳ I conquered the generation of the flood and was the loser by it, because I destroyed &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נְצָחַנִי משה וכ׳</span> Moses conquered me …, and I gained all those masses; a. fr.—Part. pass. <a href=\"#\" data-headword=\"נִצּוּחַ\">נָצוּחַ</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בשעה שאני נוצח … ובשעה שאני נ׳ וכ׳</span> when I prevail, I lose, but when I am prevailed over, I gain; a. e.</div><div class=\"sense\"><b>Pi. נִצֵּחַ</b> <div class=\"sense\"><b>1)</b> <i>to make illustrious, to glorify</i>. Midr. Till. l. c. (expl. <span dir=\"rtl\">למנצח</span>) <span dir=\"rtl\">למי שהוא נאה לנַצֵּחַ</span> to him whom it is befitting to glorify.</div><div class=\"sense\"><b>—2)</b> <i>to conquer, prevail over</i>. Ib. <span dir=\"rtl\">מלך ב&quot;וד מְנַצְּחִים אותו וכ׳</span> a human king is angry when people defeat him (in argument; cmp. <a href=\"#\" data-headword=\"זְכֵי\">זְכֵי</a> <i>Pa</i>.); Pes. l. c.—<span class=\"citation\">B. Mets. 59ᵇ</span> <span dir=\"rtl\">נִצְּחוּנִי בני</span> (or <span dir=\"rtl\">נְצָחוּנִי</span>) my children have won over me. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תלמידי חכמים שמנצחים וכ׳</span> scholars who defeat one another in discussion. <span class=\"citation\">Snh. 91ᵃ</span> <span dir=\"rtl\">אם יְנַּצְּחוּנִי … נַצַּחְתֶּם</span> if they defeat me, say to them, you have defeated an ignoramus among us; <span dir=\"rtl\">ואם אני אֲנַצֵּחַ … תורת משה נִצְּחַתְכֶם</span> and if I defeat them, say to them, the law of Moses has defeated you; a. fr.—Part. pass. <span dir=\"rtl\">מְנוּצָּח</span>. Midr. Till. l. c. <span dir=\"rtl\">למי שמנ׳ וכ׳</span> to him who allows himself to be won over by his creatures (v. supra); a. e.</div></div><div class=\"sense\"><b>Nif. נִיצַּח</b> <div class=\"sense\"><i>to be defeated</i>. Y. Sabb. II, 5ᵇ top v. supra.</div></div>","alt":[]},"20197":{"h":"נְצַח","r":"N01109","html":"<div class=\"sense\"><b>1)</b> <i>to be glad, to sing</i>. Targ. II Esth. I, 2 <span dir=\"rtl\">והוה נָצַח וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>to succeed, thrive</i>. <span class=\"citation\">Targ. Koh. XI, 2</span>.</div><div class=\"sense\"><b>—3)</b> <i>to be victorious</i>. <span class=\"citation\">Targ. O. Ex. XXXII, 18</span>, v. <a href=\"#\" data-headword=\"נַצְחָא\">נַצְחָא</a>; a. e.—<span class=\"citation\">Y. Sot. IX, 24ᵇ</span> <span dir=\"rtl\">נַצְחוּ טליא</span> the boys (John Hyrcan’s sons) have won the battle; Bab. <span class=\"citation\">Sot. 33ᵃ</span>; <span class=\"citation\">Tosef. ib. XIII, 5</span>. <span class=\"citation\">Tam. 32ᵃ</span>, v. <a href=\"#\" data-headword=\"סְטַן II\">סִטְנָא</a>; a. e.</div><div class=\"sense\"><b>Pa. נַצֵּחַ</b> <div class=\"sense\"><i>to conquer, overpower</i>. <span class=\"citation\">Targ. Y. Num. XVI, 14</span>; a. e.—<span class=\"citation\">Lam. R. to I, 13</span> (expl. <span dir=\"rtl\">וירדנה</span> ib.) <span dir=\"rtl\">נַצְּחָהּ</span> (not <a href=\"#\" data-headword=\"נַצְחָא\">נצחא</a>) he conquered her.</div></div><div class=\"sense\"><b>Af. אַנְצַח</b> <div class=\"sense\"><i>to cheer up, play</i>. Y. Ter. VIII, end, 46ᶜ <span dir=\"rtl\">וא׳ קדמיהון</span> and played before them; (<span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">מוזגה</span>, v. <a href=\"#\" data-headword=\"מְזַג\">מְזַג</a>).</div></div><div class=\"sense\"><b>Ithpe. אִתְנְצַח</b> <div class=\"sense\"><b>1)</b> <i>to be bright, shine, excel</i>. <span class=\"citation\">Targ. Ez. XIX, 11</span>. <span class=\"citation\">Ib. XXXI, 8</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be defeated</i>. <span class=\"citation\">Targ. Y. Ex. XXXII, 18</span>.</div></div>","alt":[]},"20198":{"h":"נִצֵּחַ","r":"N01110","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְצַח\">preced.</a>) <i>successful, convincing, irrefutable</i>. <span class=\"citation\">Snh. 105ᵃ</span> (ref. to <span class=\"citation\">Jer. VIII, 5</span>) <span dir=\"rtl\">תשובה נ׳ השיבה וכ׳</span> the congregation of Israel defeated the prophets with an irrefutable argument.</div>","alt":["נִצַּחַת"]},"20199":{"h":"נֶצַח","r":"N01111","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נִצֵּחַ\">preced.</a>) <i>success, endurance</i>; (adv.) <i>forever</i>. <span class=\"citation\">Erub. 54ᵃ</span> <span dir=\"rtl\">כל מקום שנאמר נ׳ וכ׳</span> wherever the Biblical text has the words <i>netsaḥ, selah</i>, or <i>vaʿed</i>, it means &amp;c., v. <a href=\"#\" data-headword=\"הֶפְסֵק\">הֶפְסֵק</a>.—Pl. <span dir=\"rtl\">נְצָחִים</span>. <span class=\"citation\">Midr. Till. to Ps. IV</span>, v. <a href=\"#\" data-headword=\"נִיצּוּחַ\">נִיצּוּחַ</a>.</div>","alt":[]},"20200":{"h":"נַצְחָא","r":"N01112","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נֶצַח\">preced.</a> wds.) <i>victor</i>.—Pl. <span dir=\"rtl\">נַצְחִין</span>. Targ. II Esth. I, 2 <span dir=\"rtl\">כליל ריש דנ׳</span> the crown of the chief of victors. <span class=\"citation\">Targ. Ex. XXXII, 18</span> (O. ed. Berl. <span dir=\"rtl\">דנָצְחִין</span>, v. <a href=\"#\" data-headword=\"נְצַח\">נְצַח</a>).</div>","alt":[]},"20201":{"h":"נִצָּחוֹן","r":"N01113","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נַצְחָא\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>victory, strength</i>. <span class=\"citation\">Sot. VIII, 1</span> <span dir=\"rtl\">בנִיצְחוֹנוֹ של וכ׳</span> (Y. ed. <span dir=\"rtl\">בנצחת ב&quot;וד</span>, corr. acc.) relying on the strength of &amp;c.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>praise, song</i>. <span class=\"citation\">Midr. Till. to Ps. LXXXIV</span>; <span class=\"citation\">Yalk. Ps. 833</span> <span dir=\"rtl\">כל מי שרואה … נותן עליה נ׳</span> whoever sees that wine press (<span class=\"citation\">Is. LXIII, 1</span> sq.), gives forth songs over it.</div>","alt":["נִי׳"]},"20202":{"h":"נַצְחָן","r":"N01114","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נִצָּחוֹן\">preced.</a> wds.) <i>victorious, strong</i>. <span class=\"citation\">Targ. Job XXII, 8</span> Ms. (ed. v. <a href=\"#\" data-headword=\"נִצְחָן\">next w.</a>).</div>","alt":[]},"20203":{"h":"נִצְחָן","r":"N01115","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>strength, victory</i>. <span class=\"citation\">Targ. Job XXII, 8</span> (h. text <a href=\"#\" data-headword=\"זְרוֹעַ\">זְרוֹעַ</a>; Ms., v. <a href=\"#\" data-headword=\"נַצְחָן\">preced.</a>). <span class=\"citation\">Targ. Jud. VII, 18</span>. <span class=\"citation\">Targ. Ps. XXXV, 23</span>; a. fr.—Pl. <span dir=\"rtl\">נִצְחָנִין</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>; constr. <span dir=\"rtl\">נִצְחָנֵי</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Targ. Jud. V, 28</span>. <span class=\"citation\">Targ. Y. II, Ex. XIV, 14</span>; a. e.</div>","alt":["נִצְחָנָא","נִי׳"]},"20204":{"h":"נִצְחָנָה","r":"N01116","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Nitsḥana</i>. <span class=\"citation\">Koh. R. to II, 8</span>.</div>","alt":[]},"20205":{"h":"נִצְחָנוּתָא","r":"N01117","html":"<div class=\"sense\"> f., constr. <a href=\"#\" data-headword=\"נִצְחָנוּתָא\">נִצְחָנוּת</a> = <a href=\"#\" data-headword=\"נִצְחָן\">נִצְחָנָא</a>. <span class=\"citation\">Targ. Y. I Ex. XIV, 14</span>; a. e.</div>","alt":[]},"20206":{"h":"נִצַּחַת","r":"N01118","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִצֵּחַ\">נִצּחַ</a>.—[<span class=\"citation\">Sot. VIII, 1</span> (<span class=\"citation\">3</span>), Y. ed. <span dir=\"rtl\">נצחת ב&quot;וד</span>, v. <a href=\"#\" data-headword=\"נִצָּחוֹן\">נִצָּחוֹן</a>.]</div>","alt":[]},"20207":{"h":"נצי","r":"N01119","html":"<div class=\"sense\"><i>to press; Nif.</i> <span dir=\"rtl\">נִצָּה</span> (b. h.; cmp. <a href=\"#\" data-headword=\"חָבַל\">חָבַל</a>) <i>to wrangle, fight</i>.</div><div class=\"sense\"><b>Hithpa. הִתְנַצֶּה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נִצַּחַת\">same</a>. Tanḥ. Ḥuck. ed. Bub. 1; <span class=\"citation\">Num. R. s. 18</span>, end <span dir=\"rtl\">ראה שני צפרים מִתְנַצִּין וכ׳</span></div></div>","alt":["נָצָה"]},"20208":{"h":"נְצֵי","r":"N01120","html":"<div class=\"sense\"><b>1)</b> <i>to be pressed; to shrink, be lean</i>, v. <a href=\"#\" data-headword=\"נָצָא II\"><span dir=\"rtl\">נָצָא</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>to wrangle</i>. <span class=\"citation\">Targ. Gen. XXVI, 20</span>, sq.; a. fr.—Part. <a href=\"#\" data-headword=\"נְצֵי\">נָצֵי</a>, <span dir=\"rtl\">נָאצֵי</span>; f. <a href=\"#\" data-headword=\"נִצַּיָּא\">נַצְיָא</a>; pl. <a href=\"#\" data-headword=\"צָנַן\">נָצָן</a>. <span class=\"citation\">Targ. Prov. XXVI, 17</span> <span dir=\"rtl\">נא׳</span> ed. Lag. (ed. Wil. <a href=\"#\" data-headword=\"נְצֵי\">נְצֵי</a>, corr. acc.). <span class=\"citation\">Ib. XXVII, 15</span>. <span class=\"citation\">Targ. Ex. II, 13</span>; a. e.—<span class=\"citation\">M. Kat. 16ᵃ</span> <span dir=\"rtl\">דנְצִינָן וכ׳</span></div><div class=\"sense\"><b>Ithpa. אִתְנַצֵּי</b> </div><div class=\"sense\"><b>Ithpe. אִתְנְצֵי  אִינְּ׳</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נצי\">same</a>. <span class=\"citation\">Targ. O. Lev. XXIV, 10</span>. <span class=\"citation\">Targ. Gen. XLV, 24</span>; a. fr.—<span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">הוה קא מִינַּצְיָא וכ׳</span> his wife was quarrelling with &amp;c. <span class=\"citation\">Kidd. 76ᵃ</span> <span dir=\"rtl\">נשי דכי מִינְּצוּ בהדי הדדי בעריות הוא דמִינְּצוּ</span> when women quarrel with one another, they will eventually reproach one another with unchaste conduct; <span dir=\"rtl\">גברי … ביוחסין הוא דמינצו</span> when men quarrel, they will reproach each other with spurious descent (if there is any rumor about it). Ib.ᵇ. <span dir=\"rtl\">כיון דמִנְּצוּ בהדי אינשי</span> (or <span dir=\"rtl\">דמְנַצּוּ</span> <i>Pa</i>.) because they (charity collectors) expose themselves to reproaches. Ib. <span dir=\"rtl\">והוה קא מִנְּצֵי איהו וכ׳</span> (or <span dir=\"rtl\">מְנַצֵּי</span>) he and Rab Bibi strove with each other, one saying, I want the town office &amp;c. <span class=\"citation\">Meg. 24ᵃ</span> <span dir=\"rtl\">משום דאתי לאִינַּצּוּיֵי</span> because it may come to quarrels between them. <span class=\"citation\">Ib. 24ᵇ</span> אינצי אביו ומינצי רבו Ms. M. (ed. <a href=\"#\" data-headword=\"נִיצּוּיֵי\">נִיצּוּיֵי</a>) his father may take up the quarrel for him, or his teacher. <span class=\"citation\">B. Kam. 117ᵃ</span> <span dir=\"rtl\">מנצו</span>, v. <a href=\"#\" data-headword=\"שׁוּתָא II\"><span dir=\"rtl\">שׁוּתָא</span> III</a>; a. e.</div></div><div class=\"sense\"><b>Pa. נַצֵּי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נצי\">same</a>. <span class=\"citation\">Targ. Koh. III, 7</span>; a. e.—<span class=\"citation\">Meg. 24ᵃ</span> <span dir=\"rtl\">קטן בר נַצּוּיֵי הוא</span> will a minor quarrel (about precedence)? <span class=\"citation\">Ber. 56ᵃ</span> <span dir=\"rtl\">מְנַצּוּ</span> (Beth N. <span dir=\"rtl\">מִינְּצֵי</span>); a. e. (v. supra).</div></div>","alt":["נְצָא"]},"20209":{"h":"נִצַּיָּא","r":"N01121","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נֵץ\">נֵץ</a> ch.</div>","alt":[]},"20210":{"h":"נְצֵיב","r":"N01122","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְצַב\">נְצַב</a></div>","alt":[]},"20211":{"h":"נָצִיב","r":"N01123","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָצַב\">נָצַב</a>; cmp. <a href=\"#\" data-headword=\"יַצִּיב ²\">יַצִּיבָא</a>) <i>permanent resident</i>, opp. <a href=\"#\" data-headword=\"גֵּר\">גֵּר</a>. <span class=\"citation\">Gen. R. s. 64</span> (ref. to <a href=\"#\" data-headword=\"שְׁכַן\">שְׁכֹן</a>, <span class=\"citation\">Gen. XXVI, 2</span>) <span dir=\"rtl\">עשה שכונה הוי נוטע הוי זורע הוי נ׳ …</span> make a settlement in the land of Israel, be a planter, be a sower, be a citizen.</div>","alt":[]},"20212":{"h":"נְצִיב","r":"N01124","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>officer, post</i>; (in a secret letter) <i>month</i>. <span class=\"citation\">Snh. 12ᵃ</span> <span dir=\"rtl\">לקבוע נ׳ אחד</span> to establish one post (to intercalate one month).</div>","alt":[]},"20213":{"h":"נְצִיב ²","r":"N01125","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, q. v. <span class=\"citation\">Targ. Job XIV, 8</span>, sq. Ms.—Pl. <span dir=\"rtl\">נְצִיבִין</span>. <span class=\"citation\">Targ. Ps. CXLIV, 12</span>.—<span class=\"citation\">Lev. R. s. 25</span>, v. <a href=\"#\" data-headword=\"נְצַב\">נְצַב</a>; a. e.—<span class=\"citation\">Targ. Y. Ex. XXVI, 15</span> <span dir=\"rtl\">כאורח נְצִיבֵיהוֹן</span> the way they grow, v. <a href=\"#\" data-headword=\"גְּדִילָה I\"><span dir=\"rtl\">גְּדִילָה</span> I</a>.</div>","alt":["נְצִיבָא"]},"20214":{"h":"*נִצְיָיא","r":"N01126","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"נָצָא II\"><span dir=\"rtl\">נָצָא</span> II</a>) <i>lean land</i>. <span class=\"citation\">Targ. Ps. LXV, 11</span> <span dir=\"rtl\">נִצְיָיהָא תבריך</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">צִמְחָהָא</span>; h. text <span dir=\"rtl\">צִמְחָהּ</span>). Ib. <span dir=\"rtl\">נִצְיָינָהָא רוי</span> Ms. (ed. <span dir=\"rtl\">מרביני צמחהא</span>; h. text <span dir=\"rtl\">תלמיה</span>).</div>","alt":[]},"20215":{"h":"נִּצְיָינָּא","r":"N01127","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*נִצְיָיא\">preced.</a></div>","alt":[]},"20216":{"h":"נְצֵיף","r":"N01128","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְצַף\">נְצַף</a></div>","alt":[]},"20217":{"h":"נָצִיר","r":"N01129","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>guarded</i>; (homiletically interpreted = <span dir=\"rtl\">יצר</span>) <i>that which is being formed, embryo, premature birth</i>.—Pl. <span dir=\"rtl\">נְצִירִים</span>, constr. <span dir=\"rtl\">נְצִירֵי</span>. <span class=\"citation\">Y. Shebi. IV, end, 35ᶜ</span> <span dir=\"rtl\">אפילו נפלים וכ׳</span> even premature births will have a share in the resurrection, as we read (<span class=\"citation\">Is. XLIX, 6</span></div>","alt":[]},"20218":{"h":"נָצֵית","r":"N01130","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צוּת\">צוּת</a></div>","alt":[]},"20219":{"h":"נָצַל","r":"N01131","html":"<div class=\"sense\"><i>to remove, set aside</i>.</div><div class=\"sense\"><b>Pi. נִצֵּל</b> <div class=\"sense\"><i>to empty, ransack</i>. <span class=\"citation\">Esth. R. to III, 9</span> <span dir=\"rtl\">עד שנִצְּלוּ את מצרים</span> so that they ransacked Egypt.</div></div><div class=\"sense\"><b>Nif. נִצַּל  נִיצַּל</b> <div class=\"sense\">, <span dir=\"rtl\">נִיצּוֹל</span> </div><div class=\"sense\"><b>*1)</b> <i>to be fit for throwing away</i> (as <a href=\"#\" data-headword=\"נֵצֶל\">נֵצֶל</a>), <i>to be decayed</i>. Y. Naz. VII, 56ᵇ bot. <span dir=\"rtl\">בשר המת שנִצַּל</span> Ar. (Ar. ed. Rome <span dir=\"rtl\">שנצול</span>; ed. <span dir=\"rtl\">שנתוק</span>), v. <a href=\"#\" data-headword=\"נֵצֶל\">נֵצֶל</a>.</div><div class=\"sense\"><b>—2)</b>  (b. h.) <i>to be rescued, saved</i>. <span class=\"citation\">Midr. Till. to Ps. I</span> לא נִצַּלְתִּי מידו I did not escape his power; <span class=\"citation\">Yalk. Num. 750</span> <span dir=\"rtl\">נוצלתי</span> (read: <a href=\"#\" data-headword=\"נִצּוֹק\">נִיצַּ׳</a>; ed. Liv. <span dir=\"rtl\">נִצּוֹלְתִּי</span>). <span class=\"citation\">Yoma 86ᵇ</span> <span dir=\"rtl\">כגון שבאת … ונ׳ הימנה</span> when an opportunity to sin offered itself to him once and again, and he escaped it; <span class=\"citation\">Kidd. 39ᵇ</span>. <span class=\"citation\">Esth. R. to II, 7</span> <span dir=\"rtl\">עתידין לִינָּצֵל וכ׳</span> are destined to be saved through me; <span dir=\"rtl\">עתידין להִנָּצֵל על ידיה</span> be saved through her. <span class=\"citation\">B. Bath. 164ᵇ</span> <span dir=\"rtl\">שלש … אין אדם ניצול מהן וכ׳</span> there are three sins which man cannot escape &amp;c.; a. fr.</div></div><div class=\"sense\"><b>Hif. הִצִּיל</b> <div class=\"sense\"><i>to save, rescue</i>. <span class=\"citation\">Num. R. s. 18</span> <span dir=\"rtl\">אשתו הִצִּילָתוֹ</span> his wife saved him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">משה … הַצִּילֵנוּ</span> O Moses …, save us! <span class=\"citation\">Sabb. XVI, 1</span> <span dir=\"rtl\">מַצִּילִין אותן וכ׳</span> we must save them from fire (on the Sabbath). <span class=\"citation\">Snh. VIII, 7</span> <span dir=\"rtl\">שמצילין אותן בנפשן</span> whom we must save (prevent from committing a crime) even at the risk of their lives. <span class=\"citation\">Ib. 73ᵃ</span> <span dir=\"rtl\">ניתן להַצִּילָהּ בנפשו</span> it is a duty to save her (from rape) at the expense of the assailant’s life; a. fr.—Trnsf. (in ritual and levitical law) <i>to protect</i>. <span class=\"citation\">Ḥull. 55ᵇ</span> <span dir=\"rtl\">כל … מַצִּיל בגלודה</span> every part of the skin (which has remained unaffected) protects a flayed animal from being declared <i>ṭ’refah</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מהו שיַצִּיל וכ׳</span> does it form a protection from &amp;c.? Ohol. V, 3 <span dir=\"rtl\">מַצֶּלֶת על הכל</span> protects everything in it from uncleanness; a. v. fr.</div></div><div class=\"sense\"><b>Hof. הוּצַּל</b> <div class=\"sense\"><i>to be saved</i>. <span class=\"citation\">Esth. R. to V, 3</span> כבר הוּצְּלוּ חנניה וכ׳ Hananiah and his colleagues have long ere this been delivered from the furnace; a. e.</div></div>","alt":[]},"20220":{"h":"נְצַל","r":"N01132","html":"<div class=\"sense\">, <i>to save</i>. <span class=\"citation\">Taan. 9ᵇ</span> <span dir=\"rtl\">רחמנא לִיצְּלַן</span>, v. <a href=\"#\" data-headword=\"כִּיסּוּפָא\">כִּיסּוּפָא</a>; a. e.</div><div class=\"sense\"><b>Af. אַצֵּיל</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נָצַל\">same</a>. <span class=\"citation\">Snh. 72ᵇ</span> <span dir=\"rtl\">דלא מצי אַצּוּלֵיה</span> when he cannot save him. <span class=\"citation\">Sabb. 115ᵃ</span> <span dir=\"rtl\">השתא אַצּוּלֵי מַצִּילִינָן וכ׳</span> since we are bound to save them (on the Sabbath), is it necessary to say that they require burying (when defective)?; a. fr.</div></div><div class=\"sense\"><b>Ittaf. אִתַּצַּל</b> <div class=\"sense\"><i>to be saved</i>. <span class=\"citation\">Ab. Zar. 18ᵃ</span> bot. <span dir=\"rtl\">ומִתַּצְּלַת</span> and thou shalt be saved.</div></div>","alt":[]},"20221":{"h":"נֵצֶל","r":"N01133","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְצַל\">preced.</a> wds.) [<i>that which is thrown away</i>,] <i>decayed matter</i>, esp. (in levitical law) <i>liquid and coagulated portions of a corpse.</i> Ohol. II, 1; <span class=\"citation\">Naz. VII, 2</span>. Y. ib. VII, 56ᵇ bot. <span dir=\"rtl\">איזהו נ׳ בשר המת שנתוק ומוהל וכ׳</span> (Ar. <span dir=\"rtl\">שנצל</span>) what is <i>netsel</i> (in levitical law)? A corpse which is dissolving &amp;c., v. <a href=\"#\" data-headword=\"מוֹהַל\">מוֹהַל</a>; Bab. ib. 50ᵃ <span dir=\"rtl\">איזהו נ׳ בשר המת שקרש ומוהל שהרתיח</span> a secretion from a corpse which became coagulated, and a liquid secretion exposed to heat. <span class=\"citation\">Tosef. Ohol. III, 6</span>; a. e.</div>","alt":["נֵי׳"]},"20222":{"h":"נִצְמִין","r":"N01134","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צָמַם\">צמם</a>) <i>clasps</i>, v. <a href=\"#\" data-headword=\"*נָצוֹרָא\">נָצוֹרָא</a>.</div>","alt":[]},"20223":{"h":"נִצְנֵץ","r":"N01135","html":"<div class=\"sense\">, v. <span dir=\"rtl\">נצץ</span></div>","alt":["נַצְנֵץ"]},"20224":{"h":"נְצַע","r":"N01136","html":"<div class=\"sense\"> transpos. of <a href=\"#\" data-headword=\"נְעַץ\">נְעַץ</a> q. v.</div>","alt":[]},"20225":{"h":"נְצַף","r":"N01137","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"צַפְצֵף\">צפצף</a>) <i>to chirp, squeal</i>. <span class=\"citation\">Targ. Is. XXIX, 4</span>; a. e.</div><div class=\"sense\"><b>Pa. נַצֵּיף</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נְצַע\">same</a>. Ib. XXXVIII, 14 (some ed. <span dir=\"rtl\">מַנְצֵיף</span> <i>Af</i>.). Ib. XIII, 22; a. fr.</div></div>","alt":["נְצֵיף"]},"20226":{"h":"נִצְפָּה","r":"N01138","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>caper-bush.</i> <span class=\"citation\">Dem. I, 1</span> <span dir=\"rtl\">והנ׳</span>; expl. <span class=\"citation\">Ber. 40ᵇ</span> <a href=\"#\" data-headword=\"פִּרְחָה\">פִּרְחָהּ</a> the flower of the caper-bush. <span class=\"citation\">Ib. 36ᵃ</span> <span dir=\"rtl\">מיני נ׳</span> (identical with <a href=\"#\" data-headword=\"צְלָף\">צְלָף</a>) the various products of the caper-bush which are eatable; the leaves &amp;c.—<span class=\"citation\">Y. Sabb. XV, end, 15ᵇ</span> <span dir=\"rtl\">סוכה אחת של נ׳</span> one bush of &amp;c.; <span class=\"citation\">Lev. R. s. 34</span>, end <span dir=\"rtl\">אילן של נ׳</span>; (<span class=\"citation\">Sabb. 150ᵇ</span> <span dir=\"rtl\">צלף</span>).</div>","alt":[]},"20227":{"h":"נָצַץ","r":"N01139","html":"<div class=\"sense\"><i>to sparkle, blossom</i>. <span class=\"citation\">Erub. 54ᵃ</span> <span dir=\"rtl\">נוֹצְצִין</span>, v. <a href=\"#\" data-headword=\"הָלָה\">הָלָה</a>.</div><div class=\"sense\"><b>Hif. הֵנֵץ</b> <div class=\"sense\"><b>1)</b> <i>to sparkle</i>. Y. Ber. I, 2ᶜ <span dir=\"rtl\">עד שתָּנֵץ החמה</span>; <span class=\"citation\">Gen. R. s. 50</span>, a. e. (<span class=\"citation\">Pes. 93ᵇ</span> <span dir=\"rtl\">עד הנץ</span>), v. <a href=\"#\" data-headword=\"הָנֵץ\">הָנֵץ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to blossom, sprout.</i> <span class=\"citation\">Shebi. IV, 10</span> <span dir=\"rtl\">משיָנֵצּוּ</span>; <span class=\"citation\">Pes. 53ᵃ</span> <span dir=\"rtl\">משיָנֵיצּוּ</span> (or <span dir=\"rtl\">משיָנִיצוּ</span>) as soon as they blossom (expl. Y. Shebi. IV, end, 35ᶜ <span dir=\"rtl\">משהכניסו רובע</span>, v. <a href=\"#\" data-headword=\"נֵץ\">נֵץ</a>). <span class=\"citation\">B. Bath. 147ᵃ</span> <span dir=\"rtl\">בשעה שיניצו</span> (Ms. M. <span dir=\"rtl\">שהֵנֵיצּוּ</span>) when they are in blossom. <span class=\"citation\">Koh. R. to XII, 5</span>, v. <a href=\"#\" data-headword=\"צוּץ\">צוּץ</a>; a. fr.—2) <i>to cause to sprout</i>. <span class=\"citation\">Gen. R. s. 28</span> מֵנֵיץ Ar. (ed. <span dir=\"rtl\">מציץ</span>), v. <a href=\"#\" data-headword=\"צוּץ\">צוּץ</a>.</div></div><div class=\"sense\"><b>Pilp. נִצְנֵץ</b> <div class=\"sense\"><b>1)</b> <i>to sparkle, be enkindled</i>. <span class=\"citation\">Gen. R. s. 84</span> <span dir=\"rtl\">נִיצְנְצָה בו רוה&quot;ק</span> the spirit of prophecy was enkindled within him; <span class=\"citation\">Cant. R. to I, 12</span>. <span class=\"citation\">Midr. Till. to Ps. XC</span>, end, <span dir=\"rtl\">נ׳ עליו מזיו וכ׳</span> a ray of the Divine Glory shone upon him, v. <a href=\"#\" data-headword=\"זָהֵר\">זָהַר</a>.</div><div class=\"sense\"><b>—2)</b> <i>to sprout, grow</i>. <span class=\"citation\">Cant. R. to VI, 10</span> <span dir=\"rtl\">מְנַצְנֶצֶת ובאה</span> spreads wider and wider; (<span class=\"citation\">Midr. Till. to Ps. XXII</span> <span dir=\"rtl\">מנפצת</span>).</div></div>","alt":["(נוּץ)"]},"20228":{"h":"נְצַץ","r":"N01140","html":"<div class=\"sense\">, <i>to sprout, grow forth, bloom</i>. <span class=\"citation\">Targ. Ps. XCII, 8</span>. <span class=\"citation\">Ib. LXXII, 16</span> יִנְצֵץ Ms. (ed. <i>Pa</i>.).</div><div class=\"sense\"><b>Pa. נַצֵּץ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נָצַץ\">same</a>, v. supra.—2) </div><div class=\"sense\"><i>to sparkle</i>. <span class=\"citation\">Targ. Ez. I, 7</span> Levita (ed. <span dir=\"rtl\">מְנַצְנְצָן</span> <i>Palpel</i>).</div></div>","alt":[]},"20229":{"h":"נְצָצָא","r":"N01141","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"נַצָּא\">נַצָּא</a>, <a href=\"#\" data-headword=\"נָטוֹזָא\">בַּר נ׳</a> <i>hawk</i>. <span class=\"citation\">Targ. Y. Lev. XI, 16</span>; <span class=\"citation\">Targ. Y. Deut. XIV, 15</span> <a href=\"#\" data-headword=\"נְצָצָא\">(נָצְצָא</a>). <span class=\"citation\">Targ. Y. Lev. XX, 25</span> <a href=\"#\" data-headword=\"מני\">נִי׳</a>.</div>","alt":["נִיצְצָא"]},"20230":{"h":"נָצַר","r":"N01142","html":"<div class=\"sense\"><i>to preserve, guard</i>. <span class=\"citation\">B. Bath. 91ᵇ</span> (play on <span dir=\"rtl\">היוצרים</span>, <span class=\"citation\">I Chr. IV, 23</span>) <span dir=\"rtl\">שנָצְרוּ שבועות וכ׳</span> who guarded their father’s oath (of abstinence). <span class=\"citation\">Ber. 17ᵃ</span> <span dir=\"rtl\">נְצוֹר תורתי וכ׳</span> keep my law in thy heart. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נצור לשוני מרע</span> guard my tongue from evil. Tanḥ. B’midbar 13 <span dir=\"rtl\">עד היכן נְצָרָן</span> up to what degree did He guard them?; <span class=\"citation\">Num. R. s. 2</span>. <span class=\"citation\">Midr. Till. to Ps. CXL</span> <span dir=\"rtl\">רצונך שאֶצָּרְךָ נצור וכ׳</span> if it is thy desire that I guard thee, guard thou my law; a. fr.</div>","alt":[]},"20231":{"h":"נְצַר","r":"N01143","html":"<div class=\"sense\"> (cmp. Arab. ṣarṣara, a. <a href=\"#\" data-headword=\"צַרְצוּר\">צַרְצוּר</a>) <i>to chirp</i>. <span class=\"citation\">Lev. R. s. 33</span> end (play on <span dir=\"rtl\">נבוכד נצר</span>) <span dir=\"rtl\">נבח … נ׳ כצרצרא</span> bark like a dog …, chirp like a cricket; <span dir=\"rtl\">מיד … נ׳ וכ׳</span> presently he … chirped &amp;c.; <span class=\"citation\">Cant. R. to II, 14</span>.</div>","alt":[]},"20232":{"h":"נֵצֶר I","r":"N01144","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְצַר\">preced.</a>) <i>cricket.</i>—Pl. <span dir=\"rtl\">נְצָרִין</span>. <span class=\"citation\">Tosef. Ḥull. III, 25</span> (<span class=\"citation\">Ḥull. 65ᵇ</span> <span dir=\"rtl\">צרצור</span>).</div>","alt":[]},"20233":{"h":"נֵצֶר II","r":"N01145","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> cmp. Arab. naḍara, <i>sprout, offshoot</i>. Tanḥ. Lekh, ed. Bub. 9 <span dir=\"rtl\">אם ניטלין נ׳ מהם וכ׳</span> if you take a shoot of them (the felled trees) and plant it &amp;c.; Tanḥ. ib. 5 <span dir=\"rtl\">ונוטעין מנִצְרָה שלהן</span>.</div>","alt":[]},"20234":{"h":"נֵצֶר III","r":"N01146","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מָצַר II\"><span dir=\"rtl\">מֵצַר</span> II</a>) [<i>twist</i>,] <i>willow, wicker</i>. <span class=\"citation\">Erub. 58ᵃ</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"חֲבַל I\">חבל</a>) <span dir=\"rtl\">של נ׳</span></span> a wicker rope.—Pl. <span dir=\"rtl\">נְצָרִים</span>. Ib. <span class=\"citation\">Kel. XX, 2</span> <span dir=\"rtl\">כלי נ׳</span> (ed. Dehr. <span dir=\"rtl\">נְסָרִים</span>) vessels of wickerwork. <span class=\"citation\">Bicc. III, 8</span> <span dir=\"rtl\">סלי נ׳</span> (Ms. M. <span dir=\"rtl\">נס׳</span>) wicker baskets; a. fr.—<span class=\"citation\">Tosef. Toh. XI, 16</span> <a href=\"#\" data-headword=\"נוֹצְרִין\">נוֹצְרִין</a>.</div>","alt":[]},"20235":{"h":"נֵצֶר IV","r":"N01147","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><b>1)</b> <i>Netsar</i>, one of the alleged disciples of Jesus of Nazareth. <span class=\"citation\">Snh. 43ᵃ</span> Ms. M. a. ed. Ven. (omitted in later edit., v. <a href=\"#\" data-headword=\"בּוּנִי\">בּוּנִי</a>).</div><div class=\"sense\"><b>—2)</b>  בֶּן נ׳ <i>Ben-Netsar</i> (<i>son of Nassor</i>) name of a chief of robbers who became founder of a dynasty, i.e. <i>Odenathus</i> of Palmyra (v. Cyclop. Brit. s. v. Palmyra, Ersch u. Gruber II, Vol. 27, p. 185, Fürst Gloss., p. 145). <span class=\"citation\">Keth. 51ᵇ</span> (opp. to <span dir=\"rtl\">מלכות אחשורוש</span> the legitimate Persian dynasty). <span class=\"citation\">Gen. R. s. 76</span>; Yalk. Dan. 1064 <span dir=\"rtl\">בן נָצוֹר</span>. <span class=\"citation\">Y. Ter. VIII, 46ᵇ</span> bot. <span dir=\"rtl\">בר ניצור</span>.</div>","alt":[]},"20236":{"h":"נִצְרָא","r":"N01148","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>wicker-basket</i>. <span class=\"citation\">Y. Maasr. IV, 51ᵇ</span> <span dir=\"rtl\">אפי׳ נ׳</span> even an ordinary basket of figs, opp. to <a href=\"#\" data-headword=\"כַּלְכָּלָה\">כַּלְכָּלָה</a>.—Pl. <a href=\"#\" data-headword=\"נִצְמִין\">נִצְרִין</a>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. Y. Ab. Zar. IV, 44ᵃ bot.—[<span class=\"citation\">Targ. Job XXXI, 8</span> <span dir=\"rtl\">נצרי</span>, read with ed. Lag. a. oth. <span dir=\"rtl\">נִצַּיי</span>, v. <a href=\"#\" data-headword=\"נֵץ\">נֵץ</a> ch.]</div>","alt":["נִצְרָה I","נִי׳"]},"20237":{"h":"נִצְרָה II","r":"N01149","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>shoot</i>, v. <a href=\"#\" data-headword=\"נֵצֶר II\"><span dir=\"rtl\">נֵצֶר</span> II</a>.</div>","alt":[]},"20238":{"h":"נִצְרְפֵי","r":"N01150","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (fr. <a href=\"#\" data-headword=\"צְרַף I\">צרף</a>, a cacophemistic disguise of <span dir=\"rtl\">נוֹצְרָאֵי</span>, v. <a href=\"#\" data-headword=\"נוֹצְרִי\">נוֹצְרִי</a>); <span dir=\"rtl\">בי נ׳</span> <i>a Christian place of worship</i>, contrad. to <span dir=\"rtl\">בֵּי אֲבֵידָן</span>. <span class=\"citation\">Sabb. 116ᵃ</span> (Ms. O. <span dir=\"rtl\">נצרפו</span>, v. Rabb. D. S. a. l. note 30).</div>","alt":[]},"20239":{"h":"נְקָא","r":"N01151","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְקֵי\">נְקֵי</a></div>","alt":[]},"20240":{"h":"נָקָא","r":"N01152","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָאקְתָא\">נָאקְתָא</a>.—[Y. Shek. VII, 50ᶜ bot. <span dir=\"rtl\">נ׳ כי קא</span>, v. <a href=\"#\" data-headword=\"נוּקָנִיקָה\">נוּקָנִיקָה</a>.]</div>","alt":[]},"20241":{"h":"נָקַאי","r":"N01153","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Nacai</i> (<i>Lucas</i>, v. Neub., v. Neub. Stud. Bibl. I, p. 61); <span dir=\"rtl\">נ׳ ספרא</span> N. the scribe (or teacher). <span class=\"citation\">Gen. R. s. 79</span> <span dir=\"rtl\">שמע קליה דנ׳ ס׳</span> he heard N. say; <span class=\"citation\">Koh. R. to X, 8</span> <span dir=\"rtl\">קליה דינ׳ ס׳</span>; <span class=\"citation\">Yalk. Gen. 133</span> <span dir=\"rtl\">דנקא׳</span>; Pesik. B’shall., p. 90ᵃ <span dir=\"rtl\">דמינקי</span> (corr. acc.).</div><div class=\"sense\"><b>—2)</b>  N., one of the disciples of Jesus of Nazareth. <span class=\"citation\">Snh. 43ᵃ</span> Ms. M. a. early eds. (v. <a href=\"#\" data-headword=\"נֵצֶר IV\"><span dir=\"rtl\">נֵצֶר</span> IV</a>).</div>","alt":["נָקַי"]},"20242":{"h":"נקאני","r":"N01154","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נוּקָנִיקָה\">נוּקָנִיקָה</a></div>","alt":["נ׳ קא"]},"20243":{"h":"נָקַב","r":"N01155","html":"<div class=\"sense\"><b>1)</b> <i>to bore, perforate</i>. <span class=\"citation\">Snh. 97ᵇ</span> <span dir=\"rtl\">מקרא זה נוֹקֵב וכ׳</span> this verse bores and penetrates to the depth. <span class=\"citation\">Ib. 6ᵇ</span>, a. e. <span dir=\"rtl\">יִקּוֹב הדין וכ׳</span>, v. <a href=\"#\" data-headword=\"דִּין II\"><span dir=\"rtl\">דִּין</span> II</a>; a. e.—Part. pass. <a href=\"#\" data-headword=\"נָקוּב\">נָקוּב</a>; f. <a href=\"#\" data-headword=\"נְקוּבָה\">נְקוּבָה</a>; pl. <span dir=\"rtl\">נְקוּבִים</span>, <span dir=\"rtl\">נְקוּבִין</span>; <span dir=\"rtl\">נְקוּבוֹת</span>. <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> top; <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> top; (<span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">נקופה</span>), v. <a href=\"#\" data-headword=\"אָרוֹן\">אָרוֹן</a>. <span class=\"citation\">Cant. R. to VIII, 5</span> מצאתי חככם נ׳ וכ׳ I found your palate perforated, unable to receive blessings.—Esp. <a href=\"#\" data-headword=\"נְקוּבָה\">נקובה</a> <i>the case of an animal found to have a vital organ perforated</i>. <span class=\"citation\">Ḥull. III, 1</span> <span dir=\"rtl\">נְקוּבַת הושט</span>, v. <a href=\"#\" data-headword=\"וֶשֶׁט\">וֶשֶׁט</a>. <span class=\"citation\">Ib. 43ᵃ</span>; a. fr.—Esp. (<span dir=\"rtl\">נְקָבִים</span>) <span dir=\"rtl\">נְקוּבִים</span> <i>female parts</i>. <span class=\"citation\">Y. Meg. I, 71ᵈ</span> bot. (reported as one of the changes adopted in the Greek translation of the Pentateuch, ref. to <span class=\"citation\">Gen. I, 27</span>, a. <span class=\"citation\">V, 2</span>) <span dir=\"rtl\">זכר ונְקוּבָיו בראם</span> a male with corresponding female parts created he them; <span class=\"citation\">Gen. R. s. 8</span>; Mekh. Bo, s. 14 (v. Gen. R. l. c., beg.).—[<span class=\"citation\">Y. Meg. I, 71ᶜ</span> <span dir=\"rtl\">לנקוביו</span>, v. <a href=\"#\" data-headword=\"נֶקֶב\">נֶקֶב</a>.]—2) (cmp. <a href=\"#\" data-headword=\"אָרַר\">אָרַר</a>) <i>to curse, blaspheme</i>. <span class=\"citation\">Snh. 56ᵃ</span> (ref. to <span class=\"citation\">Lev. XXIV, 16</span>) <span dir=\"rtl\">ממאי דהאי נוֹקֵב וכ׳</span> whence do you prove that this <i>noḳeb</i> is used in the sense of blasphemy?… perhaps it means <i>to perforate?</i> Ib. <span dir=\"rtl\">למימרא דנוקב וכ׳</span> to indicate that <i>noḳeb</i> means curse.</div><div class=\"sense\"><b>—3)</b> <i>to point out, to pronounce</i>. Ib. <span dir=\"rtl\">אימא פרושי שמיה חוא</span> I might say, <i>noḳeb</i> means uttering His name (the Tetragrammaton)? Tanḥ. Emor 24 <span dir=\"rtl\">התחיל לִנְקוֹב וכ׳</span> he began to pronounce the Name and curse Him.—[<span class=\"citation\">Midr. Till. to Ps. I</span> <span dir=\"rtl\">ונקובות ידים</span>; ed. Bub. <span dir=\"rtl\">נקיבת ירק</span>, read: <span dir=\"rtl\">קְנִיבַת ירק</span>, v. <a href=\"#\" data-headword=\"קְנִיבָה\">קְנִיבָה</a>.]</div><div class=\"sense\"><b>Nif. נִיקַּב  נִקַּב</b> <div class=\"sense\"><i>to be perforated, punctured</i>. <span class=\"citation\">Ḥull. III, 1</span> <span dir=\"rtl\">הריאה שנִיקְּבָה</span> if a lung is found to be perforated. Ib. <span dir=\"rtl\">עד שתִּינָּקֵב וכ׳</span> until the puncture reaches &amp;c. Ib. 43ᵃ <span dir=\"rtl\">נ׳ זה בלא זה</span> if only one of the two is perforated. <span class=\"citation\">Bekh. 44ᵇ</span> <span dir=\"rtl\">אם נִקְּבוּ זה וכ׳</span> if there is a perforation going from one channel to the other; a. fr.</div></div>","alt":[]},"20244":{"h":"נְקַב","r":"N01156","html":"<div class=\"sense\">, <i>to perforate</i>. <span class=\"citation\">Targ. II Kings XII, 10</span>; a. fr.—<span class=\"citation\">Ḥull. 48ᵃ</span> <span dir=\"rtl\">אי האי נְקִיב וכ׳</span> whether this lobe is perforated or the other; a. e.</div><div class=\"sense\"><b>Pa. נַקֵּיב</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נָקַב\">same</a>. Ib.ᵇ <span dir=\"rtl\">נַקּוּבֵי נקיב ואתאי</span> the needle perforated (the entrails) and came into the lungs.</div></div><div class=\"sense\"><b>Ithpe. אִינְּקִיב  אִינְּקַב</b> <div class=\"sense\"><i>to be perforated</i> Ib. Ib. 45ᵃ; a. e.</div></div>","alt":[]},"20245":{"h":"נֶקֶב","r":"N01157","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְקַב\">preced.</a>) <i>hole, perforation, incision</i>. <span class=\"citation\">Ḥull. 45ᵃ</span> <span dir=\"rtl\">נ׳ אחד ארוך</span> one lengthy incision; a. fr.—Pl. <span dir=\"rtl\">נְקָבִים</span>, <span dir=\"rtl\">נְקָבִין</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נ׳ שיש בהן חסרון</span> perforations connected with loss of substance (holes); <span dir=\"rtl\">נ׳ שאין בהן חסרון</span> mere punctures. <span class=\"citation\">Bekh. 44ᵇ</span> <span dir=\"rtl\">שני נ׳ יש בו וכ׳</span> two channels are in the membrum. <span class=\"citation\">Gen. R. s. 1</span>, beg.; a. fr.—Esp. <i>the organs of the extremities, urinary organ</i> &amp;c. <span class=\"citation\">Tosef. Ber. II, 18</span> <span dir=\"rtl\">ויהא צריך לנְקָבָיו</span> when needing to ease himself; <span class=\"citation\">Ber. 23ᵃ</span>; <span class=\"citation\">Y. Meg. I, 71ᶜ</span> <span dir=\"rtl\">לנְקוּבָיו</span>. <span class=\"citation\">Sabb. 152ᵃ</span>; a. fr.</div>","alt":[]},"20246":{"h":"נִקְבָּא","r":"N01158","html":"<div class=\"sense\"> <span class=\"citation\">Lev. R. s. 12</span> <span dir=\"rtl\">חזא נו׳ בתרעא</span> saw a hole in the door. <span class=\"citation\">Sabb. 90ᵃ</span> <span dir=\"rtl\">בנ׳ דמרגניתא</span> in the cavity wherein the pearl is seated; a. e.—Pl. <span dir=\"rtl\">נְקָבִין</span>, <span dir=\"rtl\">נִיקְבִּין</span>, constr. <span dir=\"rtl\">נִקְבֵּי</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Targ. Ez. XXVIII, 13</span> <a href=\"#\" data-headword=\"נִיקּוּף\">נְקָ׳</a> (ed. Lag. <span dir=\"rtl\">נִיקְ׳</span>). <span class=\"citation\">Targ. II Chr. XXXIII, 11</span>; a. e.—<span class=\"citation\">Nidd. 62ᵃ</span> <span dir=\"rtl\">נ׳ מרגניתא</span>, v. supra; a. e.</div>","alt":["נִי׳","נוּ׳"]},"20247":{"h":"נְקֵבָה","r":"N01159","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נִקְבָּא\">preced.</a> wds.) <i>female sex, female; female gender</i>. <span class=\"citation\">Nidd. III, 2</span>, a. fr. <span dir=\"rtl\">תשב לנ׳</span> she must observe the laws of cleanness for the birth of a female child (<span class=\"citation\">Lev. XII, 5</span>). Ib. 31ᵇ, v. <a href=\"#\" data-headword=\"נָּקִי I\"><span dir=\"rtl\">נָקִי</span> I</a>; a. v. fr.—<span dir=\"rtl\">לשון נ׳</span> feminine gender. <span class=\"citation\">Kidd. 2ᵇ</span>, v. <a href=\"#\" data-headword=\"זָכָר\">זָכָר</a>; a. fr.—<span class=\"citation\">Y. Yeb. VIII, end, 9ᵈ</span> <span dir=\"rtl\">ממקום נ׳</span>, v. next w.—Pl. <a href=\"#\" data-headword=\"נְקֵבוּת\">נְקֵבוֹת</a>, <a href=\"#\" data-headword=\"נְקֵבָה\">נְקֵי׳</a>. <span class=\"citation\">Kidd. 82ᵇ</span>; a. v. fr.—<span class=\"citation\">Succ. 12ᵇ</span> <span dir=\"rtl\">חצין נ׳</span>, v. <a href=\"#\" data-headword=\"חֵץ\">חֵץ</a>.</div>","alt":["נְקֵי׳"]},"20248":{"h":"נְקֵבוּת","r":"N01160","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְקֵבָה\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>female genitals, female sex</i>. <span class=\"citation\">Snh. 82ᵇ</span>; (Y. ib. X, 28ᵈ bot., a. e. <a href=\"#\" data-headword=\"קֵיבָה\">קיבה</a>). <span class=\"citation\">Yeb. 83ᵇ</span> <span dir=\"rtl\">בנ׳ שלו</span> at his (the hermaphrodite’s) female organ; (Y. ib. VIII, end, 9ᵈ <span dir=\"rtl\">מקום נְקֵיבָה</span>). Ib. <span dir=\"rtl\">צר נְקֵיבוּתוֹ</span> (ed. Krot. <span dir=\"rtl\">נְקֵיבָתוֹ</span>) inasmuch as he is a female, v. <a href=\"#\" data-headword=\"זַכְרוּת\">זַכְרוּת</a>.</div><div class=\"sense\"><b>—2)</b> <i>the broadside of a double tool</i>. <span class=\"citation\">Bets. 31ᵇ</span>, v. <a href=\"#\" data-headword=\"זַכְרוּת\">זכְרוּת</a>.</div>","alt":["נְקֵי׳"]},"20249":{"h":"נְקֵבְתָּא","r":"N01161","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְקִיפְתָּא\">נְקִיפְתָּא</a></div>","alt":["נְקֵבְתָּה"]},"20250":{"h":"נָקַד I","r":"N01162","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"קָדַד\">קָדַד</a>) <i>to sting, point, puncture, break through</i>. <span class=\"citation\">Y. Keth. II, 26ᵇ</span> bot. <span dir=\"rtl\">לבי נוֹקְדֵינִי</span> my conscience stings me (I am afraid that I may have sinned); <span class=\"citation\">Y. Yeb. X, 11ᵃ</span> top <span dir=\"rtl\">נוקריני</span> (corr. acc.). <span class=\"citation\">Gitt. 56ᵃ</span> (play on <span dir=\"rtl\">נ̇ק̇ד̇ימון</span>) <span dir=\"rtl\">שנָ֗קְ֗דָ֗ה לו חמה בעבורו</span> for his sake did the sun break through again (after being obscured); <span class=\"citation\">Yalk. Deut. 809</span>; <span class=\"citation\">Taan. 20ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">שנקדרה</span>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אילו לא נ׳ החמה</span> Ms. M. (ed. <span dir=\"rtl\">נקדרה</span>). [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">שלשה נקדה</span> Ms. M. (ed. <span dir=\"rtl\">נקדמה</span>, read, as <span class=\"citation\">Ab. Zar. 25ᵃ</span>: <a href=\"#\" data-headword=\"עמדה\">עמדה</a>.]—2) (Massorah) <i>to dot, mark with diacritical points</i>. <span class=\"citation\">Ab. d’R. N. ch. XXXIV</span>, <span dir=\"rtl\">כבר נָקַדְתִּי עליהן</span> I (Ezra) have marked these words with dots.—Part. pass. <a href=\"#\" data-headword=\"נָקִיד\">נָקיּד</a>. Ib. <span dir=\"rtl\">נ׳ על י׳ שביניך</span> there is a dot over the Yod of <i>benekhah</i> (<span class=\"citation\">Gen. XVI, 6</span>). <span class=\"citation\">Snh. 43ᵇ</span> <span dir=\"rtl\">למה נ׳ על לנו וכ׳</span> why are there dots over <i>lanu</i> &amp;c. (<span class=\"citation\">Deut. XXIX, 28</span>)? <span class=\"citation\">Pes. IX, 2</span> <span dir=\"rtl\">לפיכך נ׳ על וכ׳</span> therefore the Hé (of <span dir=\"rtl\">רחקה</span>, <span class=\"citation\">Num. IX, 10</span>) is marked &amp;c.; a. fr.</div><div class=\"sense\"><b>Nif. נִיקָּד</b> <div class=\"sense\"><i>to be spotted.</i> <span class=\"citation\">Maasr. I, 3</span> <span dir=\"rtl\">החרובים משיִנָּקְדוּ</span> carobs are subject to tithes as soon as they get dark spots; Y. ib. 48ᵈ bot. <span dir=\"rtl\">משיִנָּקֵידוּ</span>.</div></div>","alt":[]},"20251":{"h":"נָקַד II","r":"N01163","html":"<div class=\"sense\"> (dialect. interch. with <a href=\"#\" data-headword=\"נָקַר I\">נָקַר</a>) <i>to be clean</i>, v. <a href=\"#\" data-headword=\"נָקַר II\"><span dir=\"rtl\">נָקַר</span> II</a>.</div>","alt":[]},"20252":{"h":"נְקַד","r":"N01164","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"נְקַר\">נְקַר</a></div>","alt":[]},"20253":{"h":"נַקְדּוּד","r":"N01165","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"נוֹקֵד\">נוֹקֵד</a>) <i>herder</i>. <span class=\"citation\">Lev. R. s. 1</span> <span dir=\"rtl\">אין גנאי … נַקְדּוּדוֹ</span> it is not beneath a king’s dignity to speak with his herder (the Lord spoke to Noah).—<span class=\"citation\">Y. Ber. I, 3ᶜ</span> bot. (ref. to <span class=\"citation\">I Kings VIII, 54</span>) <span dir=\"rtl\">כגין הדין נקדים היה עומד</span> (Var. <a href=\"#\" data-headword=\"נקריס\">נקריס</a>; corr. acc.) Solomon stood before the Lord like a herder (giving an account of the Temple expenses), expl. by R. El. bar A. <span dir=\"rtl\">ככפים הללו וכ׳</span>.</div>","alt":[]},"20254":{"h":"נקדים","r":"N01166","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַקְדּוּד\">preced.</a></div>","alt":[]},"20255":{"h":"נַקְדִּימוֹן","r":"N01167","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Naḳdimon</i> (Nicodemus) ben Gorion, a wealthy citizen of Jerusalem during the siege by Vespasian and Titus. <span class=\"citation\">Gitt. 56ᵃ</span>. <span class=\"citation\">Taan. 20ᵃ</span> (ed. Pes. <span dir=\"rtl\">נִיקוֹדִימוֹן</span>); <span class=\"citation\">Ab. Zar. 25ᵃ</span>; <span class=\"citation\">Yalk. Deut. 809</span>; <span class=\"citation\">Yalk. Josh. 21</span>. <span class=\"citation\">Gen. R. s. 42</span>. <span class=\"citation\">Lam. R. to I, 16</span>; <span class=\"citation\">Pesik. R. s. 29—30</span>—30.</div>","alt":[]},"20256":{"h":"נַקְדָּן","r":"N01168","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נָקַד I) <i>a punctilious person, caviller</i>. <span class=\"citation\">Der. Er. Zuta ch. VI</span> <a href=\"#\" data-headword=\"נֹפֶךְ\">נוֹ׳</a>).—Pl. <span dir=\"rtl\">נַקְדָּנִין</span>, <a href=\"#\" data-headword=\"נַקְדָּנָא\">נוֹקְדָ׳</a>. <span class=\"citation\">Tosef. Ber. V, 18</span> <span dir=\"rtl\">והנו׳ תופשין וכ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">והנקד׳</span>) the cavillers (overscrupulous) take him to task for it; Y. ib. VII, 11ᶜ top <span dir=\"rtl\">הנו׳</span> (ed. Lehm. <span dir=\"rtl\">חניקרנין</span>); Bab. <span class=\"citation\">ib. 50ᵃ</span> <span dir=\"rtl\">נקד׳</span> (Ar. <span dir=\"rtl\">נקר׳</span>), v. <a href=\"#\" data-headword=\"נַקְרָן\">נַקְרָן</a>.</div>","alt":["נוֹקְדָן"]},"20257":{"h":"נַקְדָּנָא","r":"N01169","html":"<div class=\"sense\"> <span class=\"citation\">Y. Ber. VII, 11ᶜ</span> top <span dir=\"rtl\">בגין דצווח … נו׳</span> (ed. Lehm. <span dir=\"rtl\">נוקר׳</span>) because R. … called R. … a caviller.—Pl. <span dir=\"rtl\">נַקְדָּנֵי</span>. <span class=\"citation\">Ned. 49ᵇ</span> <span dir=\"rtl\">הלין נ׳ דהוצל</span> those fastidious persons of Hutzal.</div>","alt":["נוֹקְדָ׳"]},"20258":{"h":"נָקָה I","r":"N01170","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"נְאָקָה II\"><span dir=\"rtl\">נְאָקָה</span> II</a></div>","alt":[]},"20259":{"h":"נָקָה II","r":"N01171","html":"<div class=\"sense\"><i>to be clean</i>, v. <a href=\"#\" data-headword=\"נקי\">נקי</a>.</div>","alt":[]},"20260":{"h":"נָקוּב","r":"N01172","html":"<div class=\"sense\"> m., pl. <span dir=\"rtl\">נְקוּבִים</span>, v. <a href=\"#\" data-headword=\"נָקַב\">נָקַב</a> a. <a href=\"#\" data-headword=\"נֶקֶב\"><a href=\"#\" data-headword=\"נֶקֶב\">נֶקֶב</a>.</a></div>","alt":[]},"20261":{"h":"נְקוּבָא","r":"N01173","html":"<p class=\"morphology\">m.</p><div class=\"sense\">—Pl. <span dir=\"rtl\">נְקוּבֵי</span>. <span class=\"citation\">Ḥull. 42ᵇ</span> <span dir=\"rtl\">נ׳ תמניא הוו</span> there are eight cases of perforations (which cause the animal so afflicted to be declared <i>ṭ’refah</i>). <span class=\"citation\">Ib. 54ᵇ</span></div>","alt":[]},"20262":{"h":"נְקוּבָה","r":"N01174","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  v. <a href=\"#\" data-headword=\"נָקַב\">נָקַב</a>.</div><div class=\"sense\"><b>—2)</b>  בֵּית נְ׳ <i>anus, buttock</i>. <span class=\"citation\">Pes. VII, 1</span> <span dir=\"rtl\">בית נְקוּבָתוֹ</span>; a. e.</div>","alt":[]},"20263":{"h":"נְקוּבְתָּא","r":"N01175","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְקִיפְתָּא\">נְקִיפְתָּא</a></div>","alt":[]},"20264":{"h":"נִקּוּד","r":"N01176","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיקּוּד\">נִיקּוּד</a></div>","alt":[]},"20265":{"h":"נָקוֹד","r":"N01177","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>speckled</i>.—Pl. <span dir=\"rtl\">נְקוּדִּים</span>. Tanḥ. Vayetsé 11 <span dir=\"rtl\">היה מתהפך עליו מן העקודים לנ׳ ומן הנ׳ וכ׳</span> he turned around (changing his wages) from the ring-streaked to the speckled and from the speckled to the ring-streaked; a. e.</div>","alt":[]},"20266":{"h":"נְקוּדָּה","r":"N01178","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>point, dot, drop</i>. <span class=\"citation\">Y. Sabb. VII, 10ᵈ</span> top <span dir=\"rtl\">יש שהוא כותב נ׳ אחת וכ׳</span> sometimes a man writes one dot (a touch of the pen by which a Daleth is changed into a Resh &amp;c.). <span class=\"citation\">Y. Ḥag. II, 77ᶜ</span> <span dir=\"rtl\"><span dir=\"rtl\">והוא מראה להן בנ׳</span> (<span dir=\"rtl\">של מעלן</span>) <span dir=\"rtl\">וכ׳</span></span> and it (the letter Beth) points with its upper stroke (saying), He above (has created me); <span class=\"citation\">ib.</span> <span dir=\"rtl\">נ׳ לאחריו</span> the projecting point (of the Beth) beneath to the right side; <span class=\"citation\">Pesik. R. s. 21</span>; (<span class=\"citation\">Gen. R. s. 1</span> <a href=\"#\" data-headword=\"עוּקָץ\">עוקץ</a>); a. fr.—Pl. <span dir=\"rtl\">נְקוּדּוֹת</span>. <span class=\"citation\">Y. Gitt. II, 44ᵇ</span> top <span dir=\"rtl\">אפי׳ עירב נ׳</span> even if he connected the dots (which he had dropped to form letters, v. <a href=\"#\" data-headword=\"נָטַף\">נָטַף</a>); a. fr.—Esp. (Massorah) <i>mark by diacritical dots above letters</i>. <span class=\"citation\">Ab. d’R. N. ch. XXXIV</span> <span dir=\"rtl\">מעליהן</span>) <span dir=\"rtl\">אעביר נ׳</span> (not <span dir=\"rtl\">אעבור</span>) I will remove the dots from above them. <span class=\"citation\">Gen. R. s. 48</span>, v. <a href=\"#\" data-headword=\"כְּתָב\">כְּתָב</a>; a. fr.—Pl. as ab. Ab. d’R. N. l. c.; <span class=\"citation\">Treat. Sof’rim VI, 3</span> <span dir=\"rtl\">עשר נ׳ בתורה</span> there are ten passages in the Torah marked with dots; a. fr.</div>","alt":[]},"20267":{"h":"נְקוֹטָאֵי","r":"N01179","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְקַט\">נְקַט</a>) (<i>laborers</i>) <i>gathered from different places</i>. <span class=\"citation\">B. Mets. 83ᵇ</span> (Ms. H. <a href=\"#\" data-headword=\"לְקוֹטָאֵי\">לְקוֹטָאֵי</a>).</div>","alt":[]},"20268":{"h":"נִקּוּי","r":"N01180","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיקּוּי\">נִיקּוּי</a></div>","alt":[]},"20269":{"h":"נקוניא","r":"N01181","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נוּקָנִיקָה\">נוּקָנִיקָה</a></div>","alt":["נקוניקא"]},"20270":{"h":"נָקוֹסָא","r":"N01182","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Naḳosa</i>. <span class=\"citation\">B. Kam. 81ᵇ</span> יהודה בן נ׳ Ms. M. (ed. <span dir=\"rtl\">קנוסא</span>); Y. Ber. II, end, 5ᵈ ed. Lehm. (ed. <a href=\"#\" data-headword=\"פַּפּוּס\">פפוס</a>). <span class=\"citation\">Koh. R. to I, 8</span>; <span class=\"citation\">VII, 26</span> (some ed. <span dir=\"rtl\">נקיסא</span>).</div>","alt":["נָקוֹסָה"]},"20271":{"h":"נִקּוּף","r":"N01183","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיקּוּף\">נִיקּוּף</a></div>","alt":[]},"20272":{"h":"נְקוֹפָא","r":"N01184","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נְקַף I) <i>striking against, bruise</i>. <span class=\"citation\">Targ. Ps. LVI, 14</span> (ed. Wil. <a href=\"#\" data-headword=\"נְקִיפָא\">נְקִיפָא</a>).</div>","alt":[]},"20273":{"h":"נִקּוּר","r":"N01185","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"נִיקּוּד\">נִיקּ׳</a>.</div>","alt":["נִקּוּרָא"]},"20274":{"h":"נְקוֹרוֹת","r":"N01186","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (נָקַר I) <i>those sharpening the millstones, chisellers</i>. <span class=\"citation\">Tosef. Kidd. V, 14</span>; <span class=\"citation\">Kidd. 82ᵃ</span></div>","alt":[]},"20275":{"h":"נִקּוּשָׁא","r":"N01187","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיקּוּשָׁא\">נִיקּוּשָׁא</a></div>","alt":[]},"20276":{"h":"נָקַז","r":"N01188","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"קְזַז\">קְזַז</a> a. <a href=\"#\" data-headword=\"נָקַד I\"><span dir=\"rtl\">נָקַד</span> I</a>) <i>to puncture</i>.</div><div class=\"sense\"><b>Hif. הִקִּיז</b> <div class=\"sense\"> (mostly with <a href=\"#\" data-headword=\"דָּם\">דָּם</a>) <i>to let blood; to be bled</i>. <span class=\"citation\">Bekh. V, 2</span> <span dir=\"rtl\">אין מַקִּיזִין לו דם</span> you must not bleed it; <span dir=\"rtl\">יַקִּיז</span> one may &amp;c. <span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">ה׳ דם ונצטנן</span> if one feels chilly after having been bled. <span class=\"citation\">Ib. 129ᵇ</span> <span dir=\"rtl\">ה׳ דם ועמד</span> if one stands up after &amp;c. <span class=\"citation\">Ab. Zar. 29ᵃ</span>. <span class=\"citation\">Ned. 54ᵇ</span> <span dir=\"rtl\">אין מקיזין על וכ׳</span> you must not be bled after having eaten &amp;c. <span class=\"citation\">Sot. 22ᵇ</span> (expl. <span dir=\"rtl\">פרוש קיזאי</span>) <span dir=\"rtl\">המַקִּיז דם לכתלים</span> who bleeds himself by striking against the walls (walking with closed eyes from sanctimoniousness). <span class=\"citation\">Ber. 60ᵃ</span> <span dir=\"rtl\">הנכנס להַקִּיז דם</span> he who enters (the surgeon’s office) to be bled; a. fr.</div></div>","alt":[]},"20277":{"h":"נְקַז","r":"N01189","html":"<div class=\"sense\"><i>Af</i>. <span dir=\"rtl\">אַקֵּיז</span> <a href=\"#\" data-headword=\"נָקַז\">same</a>. Y. Ber. III, 5ᶜ bot. [V. <a href=\"#\" data-headword=\"קְזַז\">קְזַז</a>.]</div>","alt":[]},"20278":{"h":"נָקַט","r":"N01190","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"לָקַט\">לָקַט</a>) <i>to hold in hand, take, seize</i>. [נקטה Pesik. B’shall., p. 81ᵇ; <span class=\"citation\">Yalk. Ex. 225</span>, v. <a href=\"#\" data-headword=\"קוּט\">קוּט</a>.]</div><div class=\"sense\"><b>Pi. נִיקֵּט</b> <div class=\"sense\"><i>to cause to hold, to procure</i>. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">ומְנַקֵּט להם שני וכ׳</span> (some ed. <span dir=\"rtl\">ומלקט</span>) and provided for them two balls (breast-shaped stones); (<span class=\"citation\">Sot. 11ᵇ</span> <span dir=\"rtl\">ומלקט</span>; <span class=\"citation\">Yalk. Ex. 164</span> <span dir=\"rtl\">ומלקט</span>; <span class=\"citation\">Yalk. Ez. 354</span> <span dir=\"rtl\">ונותן</span>).</div></div>","alt":[]},"20279":{"h":"נְקַט","r":"N01191","html":"<div class=\"sense\"> (corresp. to h. <a href=\"#\" data-headword=\"אָחַז\">אָחַז</a>). <span class=\"citation\">Targ. Esth. VI, 1</span>; a. fr.—Part. act. <a href=\"#\" data-headword=\"נָקֵיט\">נָקֵיט</a>, pass. <a href=\"#\" data-headword=\"נָקֵיט\">נְקִיט</a> <i>holding</i>. <span class=\"citation\">Ib. VIII, 15</span>; a. fr.—<span class=\"citation\">Shebu. 38ᵇ</span> <span dir=\"rtl\">נ׳ חפצא וכ׳</span> he held an object in his hand (on being sworn). <span class=\"citation\">Ab. Zar. 30ᵃ</span> <span dir=\"rtl\">הוה נקיט חמרא בהדיה</span> was carrying wine with him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">סירכא דגברא נְקִיטָה</span> she holds fast (clings to) the habit of her (deceased) husband. Sanh. 5ᵃ נְקִיטְנָא רשותא I hold a license (to teach). <span class=\"citation\">M. Kat. 28ᵃ</span>, a. e. <span dir=\"rtl\">נְקוֹט לך מיהא וכ׳</span> hold at least half of it in thy hand, i.e. admit as certain &amp;c.; <span class=\"citation\">Snh. 90ᵇ</span> <span dir=\"rtl\">נְקוֹטוּ</span> (not <span dir=\"rtl\">נקוטי</span>); a. v. fr.—<span class=\"citation\">Ḥull. 53ᵃ</span>, a. fr. <span dir=\"rtl\">נַקְטִינָן</span>, <span dir=\"rtl\">נְקִיטִינָן</span> we hold a tradition.—<span class=\"citation\">Sabb. 116ᵇ</span> top <span dir=\"rtl\">נקיט שמא וכ׳</span> quoted in Levy Talm. Dict. (ed. <span dir=\"rtl\">שקיל</span>) had the reputation that &amp;c. <span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">נְקוֹט נפשך בקצירי</span> have thyself counted among the sick, i.e. have the report spread that thou art sick. <span class=\"citation\">Ḥull. 87ᵃ</span> <span dir=\"rtl\">נקוט לי זימנא וכ׳</span> keep time for me &amp;c., i.e. allow me three days’ time.—Trnsf. <i>to contract a habit</i>. <span class=\"citation\">B. Kam. 57ᵃ</span>, v. <a href=\"#\" data-headword=\"נִיגְרָא\">נִיגְרָא</a>.</div><div class=\"sense\"><b>Af. אַנְקֵיט  אַקֵּיט</b> <div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"נָקֵיט\">נַקֵּיט</a> </div><div class=\"sense\"><b>1)</b> <i>to cause to hold, to give, hand</i>. Targ. II Esth. IV, 16.—<span class=\"citation\">Pes. 110ᵃ</span> <span dir=\"rtl\">מְנַקְּטָא ליה אימיה וכ׳</span> (not <span dir=\"rtl\">מנקיט</span>, v. Rabb. D. S. a. l. note) his mother was ready to hand him two cups. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מַנְקֵיט ליה וכ׳</span> (or <a href=\"#\" data-headword=\"מְלַקֵּיט\">מְנַקֵּיט</a>) his servant was ready to hand him &amp;c. <span class=\"citation\">B. Kam. 85ᵇ</span> <span dir=\"rtl\">לאַנְקוּטֵיה גוונא דבישריה</span> to make him regain the natural color of flesh; a. e.—<span class=\"citation\">B. Bath. 22ᵃ</span> <span dir=\"rtl\">נַקֵּיט ליה שוקא</span> make him take the market, i.e. give him the monopoly of sale.</div><div class=\"sense\"><b>—2)</b> <i>to pick up, gather</i>. <span class=\"citation\">Ned. 50ᵃ</span> <span dir=\"rtl\">וכ׳</span> (read <span dir=\"rtl\">הות … מְנַקְּטָא</span>) <span dir=\"rtl\">הוה קא מנקיט</span> she picked the straw out of his hair.</div><div class=\"sense\"><b>—3)</b> <i>to cause to contract a habit, train</i>. <span class=\"citation\">B. Kam. 118ᵇ</span>; <span class=\"citation\">B. Bath. 88ᵃ</span> <span dir=\"rtl\">אַנְקְטִינְהוּ וכ׳</span>, v. <a href=\"#\" data-headword=\"נִיגְרָא\">נִיגְרָא</a>.</div><div class=\"sense\"><b>—4)</b>  *<i>to carry</i>. <span class=\"citation\">Targ. Y. Ex. XXI, 37</span> <span dir=\"rtl\">אַקְּטֵיה בגנבותיה</span> he carried it (on his shoulder) when he stole it.</div></div><div class=\"sense\"><b>Ithpe. אִנְּקִיט</b> <div class=\"sense\"><i>to receive</i>. <span class=\"citation\">Yeb. 42ᵇ</span> <span dir=\"rtl\">מִנְּקִיט ואזיל הלכתא וכ׳</span> received instruction from him while walking.</div></div>","alt":[]},"20280":{"h":"נְקַטְמוֹן","r":"N01192","html":"<div class=\"sense\">, v. <span dir=\"rtl\">נִיקַטְ׳</span></div>","alt":[]},"20281":{"h":"נקי","r":"N01193","html":"<div class=\"sense\"> (b. h.) [<i>to be rubbed off, be white</i>,] <i>to be clean, clear</i> (cmp. <a href=\"#\" data-headword=\"זָכָה\">זָכָה</a>).</div><div class=\"sense\"><b>Pi. נִיקָּה</b> <div class=\"sense\"><b>1)</b> <i>to cleanse</i>. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">ומְנַקֶּה אותם</span> and cleansed them (the new-born); <span class=\"citation\">Yalk. ib. 164</span>; <span class=\"citation\">Yalk. Ez. 354</span>; (<span class=\"citation\">Sot. 11ᵇ</span> <span dir=\"rtl\">מנקיר</span>). <span class=\"citation\">B. Kam. 93ᵇ</span> <span dir=\"rtl\">פשתן ונִיקָּהוּ</span> if he stole flax and cleansed (bleached) it; <span class=\"citation\">Tosef. ib. X, 2</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to clear, let go unpunished</i>. <span class=\"citation\">Yoma 86ᵃ</span> (ref. to <span class=\"citation\">Ex. XXXIV, 7</span>) <span dir=\"rtl\">מנקה הוא וכ׳</span> he clears the repentant sinners &amp;c. <span class=\"citation\">Tem. 3ᵇ</span>. <span class=\"citation\">Pesik. R. s. 42</span> <span dir=\"rtl\">כדי לנַקּוֹת את שרה</span> in order to clear Sarah (from suspicion); a. fr.—Part. pass. <span dir=\"rtl\">מְנוּקֶּה</span>, pl. <span dir=\"rtl\">מְנוּקִּין</span> <i>clear, clean, bare</i>. <span class=\"citation\">Snh. 49ᵃ</span> <span dir=\"rtl\">מנ׳ מגזל</span> innocent of robbery. <span class=\"citation\">Sot. 28ᵃ</span>. <span class=\"citation\">Snh. 36ᵇ</span>, a. e. <span dir=\"rtl\">כשם שב&quot;ד מנ׳ בצדק … מנ׳ מכל מום</span> as the judges must be clear (from suspicion) as to righteousness, so must they be clear of every blemish (of descent). <span class=\"citation\">Gitt. 86ᵃ</span> <span dir=\"rtl\">מ׳ מכל מום</span> free from all objectionable qualities; a. e.</div></div><div class=\"sense\"><b>Nif. נִקָּה  נִיקָּה</b> </div><div class=\"sense\"><b>Hithpa. הִתְנַקֶּה</b> <div class=\"sense\"><i>to be cleared, vindicated</i>. <span class=\"citation\">Tosef. Sot. II, 3</span> <span dir=\"rtl\">שנ׳ ונקתה נִקְּתָה מכל פורעניות וכ׳</span> (v. ed. Zuck. note) the text says (<span class=\"citation\">Num. V, 28</span>) ‘and she shall be cleared’, she shall be cleared (released) from all the evils which might come upon her deservedly (because she gave rise to suspicion through her conduct). Ib. <span dir=\"rtl\">שניקללה ניוולה</span> (Var. <span dir=\"rtl\">שניקל</span>) read: <span dir=\"rtl\">שניקתה בניוולה</span> she is released from further visitation (being sufficiently punished) by her exposure to disgrace. Pesik. R. l. c. <span dir=\"rtl\">היאך … מִתְנַקֵּת</span> by what severe means has Sarah been vindicated!</div></div><div class=\"sense\"><b>*. הִנְקָה</b> <div class=\"sense\"><i>to clear, remove</i>. <span class=\"citation\">Kidd. 62ᵃ</span> (ref. to <span dir=\"rtl\">הִנָּקִי</span>, <span class=\"citation\">Num. V, 19</span>) <span dir=\"rtl\">הַנְקִי כתיב</span> it may be read <i>hanḳi</i>, clear thy life out of thy body (die, if thou art guilty); v. <a href=\"#\" data-headword=\"חָנַק\">חָנַק</a>.</div></div>","alt":["נָקָה"]},"20282":{"h":"נְקֵי","r":"N01194","html":"<div class=\"sense\"> [<span class=\"citation\">Targ. Prov. XVII, 3</span>, v. <a href=\"#\" data-headword=\"בְּקָא\">בְּקָא</a>.]</div><div class=\"sense\"><b>Pa. נַקֵּי</b> <div class=\"sense\"><i>to cleanse, clear</i>. <span class=\"citation\">Targ. Is. I, 25</span>.—<span class=\"citation\">Keth. 87ᵃ</span> <span dir=\"rtl\">נַקִּו נפשך בשבועתא</span> clear thyself by means of an oath. Part. pass. <span dir=\"rtl\">מְנַקֵּי</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מְנַקִּית משבועתא</span> thou art free from the obligation of an oath.</div></div><div class=\"sense\"><b>Ithpa. אִתְנַקָּא  אִתְנַקֵּי</b> <div class=\"sense\"><i>to be cleansed</i>. <span class=\"citation\">Targ. Ez. XVI, 4</span>; v. <a href=\"#\" data-headword=\"נָקַר II\"><span dir=\"rtl\">נְקַר</span> II</a>.</div></div>","alt":["נְקָא"]},"20283":{"h":"נָּקִי I","r":"N01195","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְקֵי\">preced.</a>) <i>clean, clear; bare</i>. <span class=\"citation\">Tosef. Toh. III, 8</span>, opp. <span dir=\"rtl\">מלוכלך</span>. <span class=\"citation\">Pes. 22ᵇ</span> (ref. to <span class=\"citation\">Ex. XXI, 28</span>) as one says to his neighbor <span dir=\"rtl\">יצא פלוני נ׳ מנכסיו</span> that man went out of his possessions empty-handed; <span class=\"citation\">B. Kam. 41ᵃ</span>. <span class=\"citation\">Ib. 41ᵇ</span> <span dir=\"rtl\">נ׳ מחצי כופר</span> free from paying the half-fine. <span class=\"citation\">Taan. 23ᵃ</span> (ref. to <span class=\"citation\">Job XXII, 30</span>) <span dir=\"rtl\">דור שלא היה נ׳ וכ׳</span> thou hast saved with thy prayer a generation which was not clear from sin. <span class=\"citation\">Y. Meg. I, 71ᶜ</span>; <span class=\"citation\">Y. Ber. II, 4ᵈ</span> top (ref. to <span class=\"citation\">Koh. V, 17</span>) <span dir=\"rtl\">שמור … שתהא טהור ונ׳</span> guard thy foot, that thou be pure and guiltless when thou art called to the house of God; a. fr.—<span class=\"citation\">Erub. 62ᵇ</span>, a. fr. <span dir=\"rtl\">קב ונ׳</span> only a Kab (little in quantity), but well-sifted (v. infra).—(Adv.) <span dir=\"rtl\">נְקֵי נדר</span>, <span dir=\"rtl\">נ׳ שבועה</span> without vow (as an oath), without oath; or: cleared by means of a vow &amp;c. <span class=\"citation\">Keth. 87ᵃ</span>.—Pl. <span dir=\"rtl\">נְקִיִּים</span>, <span dir=\"rtl\">נְקִיִּין</span>. <span class=\"citation\">Gen. R. s. 98</span>, v. <a href=\"#\" data-headword=\"נִקָּיוֹן\">נִקָּיוֹן</a>. <span class=\"citation\">Gitt. IX, 10</span> <span dir=\"rtl\">נְקִיֵּי הדעת</span> the pure-minded; a. e.—<i>Fem</i>. <a href=\"#\" data-headword=\"נְקִיָּה\">נְקִיָּה</a>, <a href=\"#\" data-headword=\"נְקִיָּיה\">נְקִיָּיה</a>. <span class=\"citation\">Nidd. 31ᵇ</span> <span dir=\"rtl\">נ̇ק̇ב̇ה̇ נ̇ק̇ייה ב̇אה</span> a female comes into the world poor (without the means of making a livelihood). <span class=\"citation\">Y. Maasr. II, 49ᵈ</span> <span dir=\"rtl\">דעתו נ׳</span> his mind is clear (he is wise). <span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> top <span dir=\"rtl\">אין דעתן נ׳</span> their minds are not clear enough (for esoteric wisdom). <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">כדי שתהיי נ׳ לבעליך וכ׳</span> in order that thou be clean for thy husband through these waters. <span class=\"citation\">Y. Shek. V, 48ᵈ</span> bot. <span dir=\"rtl\">פת נ׳</span> bread of fine (sifted) flour; <span class=\"citation\">Pes. 37ᵃ</span>, v. <a href=\"#\" data-headword=\"הַדְרָאָה\">הַדְרָאָה</a>. <span class=\"citation\">Kidd. 82ᵇ</span> <span dir=\"rtl\">אומנות נ׳ וקלה</span> a cleanly and easy trade; <span class=\"citation\">Tosef. ib. V, 15</span>; a. fr.</div>","alt":[]},"20284":{"h":"נָקִי II","r":"N01196","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָּקִי I\">preced.</a>) <i>a young lamb</i> (v. Syr. <span dir=\"rtl\">נקיא</span>, P. Sm. 2446). <span class=\"citation\">Sabb. 54ᵃ</span>; <span class=\"citation\">Shebu. 6ᵇ</span>, v. <a href=\"#\" data-headword=\"כָּבַן\">כָּבַן</a>.</div>","alt":[]},"20285":{"h":"נָקַי","r":"N01197","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָקַאי\">נָקַאי</a></div>","alt":[]},"20286":{"h":"נְקֵיבָה","r":"N01198","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">נְקֵב׳</span>.—[<span dir=\"rtl\">נקיבת ירק</span>, <span class=\"citation\">Midr. Till. to Ps. I</span> ed. Bub., v. <a href=\"#\" data-headword=\"קְנִיבָה\">קְנִיבָה</a>.]</div>","alt":["נְקֵיבוּת"]},"20287":{"h":"נָקִיד","r":"N01199","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (נְקַד II) <i>Naḳid</i> (<i>Cleanliness</i>). <span class=\"citation\">Pes. 111ᵃ</span>, v. <a href=\"#\" data-headword=\"אִיסְרָא I\">אִיסְרָא</a>.</div>","alt":[]},"20288":{"h":"נְקִידָא","r":"N01200","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"נָקִיד\">preced.</a>) <i>pure, clear</i>. <span class=\"citation\">Gitt. 69ᵃ</span> bot. <span dir=\"rtl\">חמרא נ׳</span> clear (not dark) wine.—Pl. <span dir=\"rtl\">נְקִידֵי</span>. <span class=\"citation\">Sabb. 110ᵇ</span> מוניני נ׳ Ms. O. (Ar. <span dir=\"rtl\">דנקידי</span>; ed. <span dir=\"rtl\">דנקירי</span>) clear fish-brine, v. <a href=\"#\" data-headword=\"נְקִירָא\">נְקִירָא</a>.</div>","alt":[]},"20289":{"h":"נְקִיָּה","r":"N01201","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָּקִי I\"><span dir=\"rtl\">נָקִי</span> I</a></div>","alt":[]},"20290":{"h":"נִקָּיוֹן","r":"N01202","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>purity, innocence; clearness</i>. <span class=\"citation\">Ruth R. to I, 1</span> (play on <span dir=\"rtl\">ולבן שנים וכ׳</span>, <span class=\"citation\">Gen. XLIX, 12</span>) <span dir=\"rtl\">שהיו סודרין … בשְׁנַיִם עד שהיו מוציאין אותה בנ׳ כחלב</span> (the Sanhedrin) that used to discuss the points of law in couples (v. <span class=\"citation\">Snh. V, 5</span>), until they brought them out with a clearness like that of milk; <span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">שהיו … בשינים עד שהן מוציאין אותן נְקִיִּים כחלב</span> (read <span dir=\"rtl\">בשְׁנַיִם</span>).</div>","alt":["נִי׳"]},"20291":{"h":"נְקִיּוּת","r":"N01203","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נִקָּיוֹן\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>cleanliness</i>. <span class=\"citation\">Yeb. 46ᵇ</span> <span dir=\"rtl\">ודילמא נ׳ בעלמא</span> perhaps mere cleanliness of appearance is intended? (not levitical purification). <span class=\"citation\">Sot. IX, 15</span>; <span class=\"citation\">Y. Shek. III, end, 47ᶜ</span>; <span class=\"citation\">Ab. Zar. 20ᵇ</span> <span dir=\"rtl\">זריזות מביאה לידי נ׳</span> zeal leads to cleanliness, <span dir=\"rtl\">נ׳ מביאה וכ׳</span> cleanliness leads to levitical purity. <span class=\"citation\">Y. Pes. VII, 35ᵇ</span> bot. <span dir=\"rtl\">אינה אלא נ׳</span> it is a mere matter of cleanliness.</div><div class=\"sense\"><b>—2)</b> <i>innocence, expiation</i>. <span class=\"citation\">Tem. 3ᵇ</span> <span dir=\"rtl\">ואימא … נ׳ כלל</span> may I not say, it means that there is no expiation for him?; a. e.</div><div class=\"sense\"><b>—3)</b> <i>respectability, dignity</i>. Sifra K’dosh., Par. 2, ch. IV <span dir=\"rtl\">מתפרנס בנ׳</span> he will make a decent living (not be dependent on charity). <span class=\"citation\">Gen. R. s. 99</span>; a. e.</div>","alt":[]},"20292":{"h":"נַקְיוּתָא","r":"N01204","html":"<div class=\"sense\">, <i>cleanliness</i>; v. <a href=\"#\" data-headword=\"מְנַקִּירוּתָא\">מְנַקִּירוּתָא</a>.</div>","alt":["נְקִיּוּתָא"]},"20293":{"h":"נָקִיט","r":"N01205","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קוּט\">קוּט</a>) [<i>shrinking</i>,] <i>feeling aversion, disgusted</i>. Pesik. Dibré, p. 111ᵃ <span dir=\"rtl\">ונפשו נ׳ עליו ממנה</span> and he has a disgust for it; Yalk. Lam. 998; <span class=\"citation\">Yalk. Prov. 932</span> <a href=\"#\" data-headword=\"קָנִיט\">קניטה</a> (corr. acc.); v. <a href=\"#\" data-headword=\"קָנִיט\">קָנִיט</a>.</div>","alt":["נְקִיטָה"]},"20294":{"h":"נָקֵיט","r":"N01206","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְקַט\">נְקַט</a></div>","alt":["נְקִיט","נְקִיטָא"]},"20295":{"h":"נְקִיטָא","r":"N01207","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (read: <span dir=\"rtl\">נִיקִי׳</span>, νικῆτα, Vocat. of νικήτης) <i>O, conqueror!</i> Lam. R. introd. (R. <span class=\"citation\">Josh. 2</span>), v. <a href=\"#\" data-headword=\"בַּרְבַּרוֹן\">בַּרְבַּרוֹן</a>; <span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">נ׳ ברבריא</span>.</div>","alt":["נְקִיטָה"]},"20296":{"h":"נְקִיָּיה","r":"N01208","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָּקִי I\"><span dir=\"rtl\">נָקִי</span> I</a></div>","alt":[]},"20297":{"h":"נְקִימָה","r":"N01209","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָקַם\">נָקַם</a>) <i>revenge, retaliation; use of the root</i> <span dir=\"rtl\">נקם</span>. Sifra K’dosh., Par. 2, ch. IV; <span class=\"citation\">Yoma 23ᵃ</span> (defining the difference between <a href=\"#\" data-headword=\"נ׳\">נ׳</a> and <a href=\"#\" data-headword=\"נְטִירָה\">נְטִירָה</a>). <span class=\"citation\">Snh. 52ᵇ</span> נ׳ זו סייף <i>n’ḳimah</i> (<span class=\"citation\">Ex. XXI, 20</span>) means putting to death by the sword; Y. ib. VI, 24ᵇ bot.</div>","alt":[]},"20298":{"h":"נְקִיפָא","r":"N01210","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְקוֹפָא\">נְקוֹפָא</a></div>","alt":[]},"20299":{"h":"נְקִיפֵי","r":"N01211","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> gent. <i>Beth N’ḳifé</i>. <span class=\"citation\">Y. Yeb. I, 3ᵃ</span> bot. <span dir=\"rtl\">משפחת בית נ׳</span>; v. <a href=\"#\" data-headword=\"קוּפָּאֵי\">קוּפָּאֵי</a>.</div>","alt":["בֵּית נְ׳"]},"20300":{"h":"נְקִיפְתָּא","r":"N01212","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>N’ḳifta</i> (<i>Hollow</i>) <i>of Iyon</i> (Merġ ʿAyun), in the north of Palestine (v. Hildesh. Beitr., p. 37, sq.). <span class=\"citation\">Tosef. Shebi. IV, 11</span> (Var. <span dir=\"rtl\">נְקוּבְ׳</span>, <span dir=\"rtl\">נְקִיבְ׳</span>, <a href=\"#\" data-headword=\"נְקֵבְתָּא\">נְקֵבְתָּא</a>); <span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">נקבתה רעיון</span>; Y. Shebi. VI, 36ᶜ <span dir=\"rtl\">נוקב׳ דעוון</span>; <span class=\"citation\">Yalk. Deut. 874</span> <span dir=\"rtl\">נקיב׳ רעוין</span> (corr. acc.).</div>","alt":["נְ׳ דְעִיּוֹן"]},"20301":{"h":"נָקִיק","r":"N01213","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>cleft</i>. <span class=\"citation\">Yalk. Cant. 986</span> <span dir=\"rtl\">ליונה … ונכנסה לנְ׳ הסלע</span> like a dove that, fleeing before a hawk, entered the cleft of a rock.—Pl. <span dir=\"rtl\">נְקִיקִים</span>, constr. <span dir=\"rtl\">נְקִיקֵי</span>. <span class=\"citation\">Tosef. Zab. II, 9</span>; <span class=\"citation\">Pes. 81ᵇ</span>; a. e.</div>","alt":[]},"20302":{"h":"נְקִירָא","r":"N01214","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">נְקִירֵי</span> (נְקַר I) </div><div class=\"sense\"><b>1)</b>  name of <i>small birds</i> (<i>pickers</i>). <span class=\"citation\">Sabb. 110ᵇ</span> <span dir=\"rtl\">מוניני דנ׳</span> brine of small birds; v. <a href=\"#\" data-headword=\"נְקִידָא\">נְקִידָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>bite</i>, v. <a href=\"#\" data-headword=\"נִיקּוּרָא\">נִיקּוּרָא</a>.</div>","alt":[]},"20303":{"h":"נְקִירָה","r":"N01215","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְקִירָא\">preced.</a>) <i>picking, bite.</i> <span class=\"citation\">Toh. III, 8</span> <span dir=\"rtl\">נְקִירַת תרנגולים</span> (Ar. <span dir=\"rtl\">נִקְרַת</span>) traces of hens’ pickings.</div>","alt":[]},"20304":{"h":"נְקִירְתָּא","r":"N01216","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְקִירָה\">preced.</a> wds.; cmp. b. h. <a href=\"#\" data-headword=\"נִקְרָה\">נִקְרָה</a>) <i>cave, underground passage</i>. <span class=\"citation\">Ab. Zar. 10ᵇ</span> <a href=\"#\" data-headword=\"נְקַרְתָּא\">נְקַרְתָּא</a>.—Pl. <a href=\"#\" data-headword=\"נְקִירְתָּא\">נְקִירָתָא</a>. <span class=\"citation\">Targ. Job XXX, 6</span> (h. text <a href=\"#\" data-headword=\"חֹרֵי\">חֹרֵי</a>).—<span class=\"citation\">Ber. 54ᵇ</span> top (Ms. M. <span dir=\"rtl\">נהורתא</span>); <span class=\"citation\">Yalk. Num. 764</span>.</div>","alt":[]},"20305":{"h":"נְקֵישׁ","r":"N01217","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְקַשׁ\">נְקַשׁ</a></div>","alt":[]},"20306":{"h":"נְקִישָׁא","r":"N01218","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְקָשָׁא\">נְקָשָׁא</a></div>","alt":[]},"20307":{"h":"נִקְלְבָס","r":"N01219","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">נִיקְ׳</span>.</div>","alt":[]},"20308":{"h":"נִקְלָה","r":"N01220","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּנְקְלַי II\"><span dir=\"rtl\">אוּנְקְלַי</span> II</a></div>","alt":[]},"20309":{"h":"נקלוגוס","r":"N01221","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיקוֹלוֹגוֹס\">נִיקוֹלוֹגוֹס</a></div>","alt":[]},"20310":{"h":"נִקְלְוָוס","r":"N01222","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">נִיקְ׳</span>.</div>","alt":[]},"20311":{"h":"נַקְלְטִין","r":"N01223","html":"<div class=\"sense\"> m. pl. ch. = <a href=\"#\" data-headword=\"נַקְלִיטִין\">next w.</a> <span class=\"citation\">Targ. Esth. I, 6</span>.</div>","alt":[]},"20312":{"h":"נַקְלִיטִין","r":"N01224","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָלַט\">קָלַט</a>, cmp. <a href=\"#\" data-headword=\"נָזִיד\">נָזִיד</a> fr. <a href=\"#\" data-headword=\"זוּד\">זוּד</a>) [<i>retirement</i>] <i>the poles of the bedstead, connected by a cross-pole</i> over which a net is spread so as to form a slanting cover, <i>curtain-frame.</i> <span class=\"citation\">Kel. XII, 2</span>. <span class=\"citation\">Ib. XVIII, 3</span> <span dir=\"rtl\">נַקְלִיטֵי המטה</span>; <span class=\"citation\">Succ. I, 3</span>; Y. ib. 52ᵇ bot. <a href=\"#\" data-headword=\"נִיקְלִיטִין\">נִיקְלִיטֵי</a>. Bab. <span class=\"citation\">ib. 10ᵇ</span> נ׳ שנים וכ׳ <i>naḳliṭin</i> means a frame with two poles (one on each side), <i>ḳinofoth</i>, one with four poles; a. fr.</div>","alt":[]},"20313":{"h":"נָקַם","r":"N01225","html":"<div class=\"sense\"><b>1)</b> <i>to take revenge</i>. <span class=\"citation\">Sabb. 63ᵃ</span> <span dir=\"rtl\">נוֹקֵם ונוטר כנחש</span> revengeful and grudge-bearing like a serpent. <span class=\"citation\">Yoma 23ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be hostile, do evil</i>. <span class=\"citation\">Midr. Till. to Ps. CXLIX, 7</span> <span dir=\"rtl\">מה שנָקְמוּ</span>, v. <a href=\"#\" data-headword=\"נְקָמָה\">נְקָמָה</a>.</div>","alt":[]},"20314":{"h":"נְקַם","r":"N01226","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. XIX, 18</span>.</div><div class=\"sense\"><b>Ithpa. אִתְנַקַּם</b> <div class=\"sense\"><i>to be punished</i>. <span class=\"citation\">Targ. Y. II, Ex. XXI, 20</span>.</div></div>","alt":[]},"20315":{"h":"נִקְמָא","r":"N01227","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְקַם\">preced.</a>) <i>revenge; judgment</i>. <span class=\"citation\">Targ. Y. I Deut. XXXII, 43</span> (ed. Amst. <a href=\"#\" data-headword=\"נִקְמָא\">נְקָמָא</a>); Y. II (ed. Amst. <a href=\"#\" data-headword=\"נִקְמְתָא\">נִקְמָתָא</a>). Targ. Y. II ib. 35.</div>","alt":["נִקְמְתָא"]},"20316":{"h":"נְקָמָה","r":"N01228","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(b. h.) <a href=\"#\" data-headword=\"נִקְמָא\">same</a>. <span class=\"citation\">Ber. 33ᵃ</span> (ref. to <span class=\"citation\">Ps. XCIV, 1</span>) <span dir=\"rtl\">גדולה נ׳ וכ׳</span> divine judgment is something great, for it is placed between two divine names. <span class=\"citation\">Ex. R. s. 20</span> <span dir=\"rtl\">עד שאנקום קְמָתָן וכ׳</span>. until I execute judgment for the slaughter of the Ephraimites. <span class=\"citation\">Midr. Till. to Ps. CXLIX, 7</span> <span dir=\"rtl\">איזו היא נ׳ … מה שנקמו לישראל</span> what revenge is meant here?… the revenge for the evil they did to Israel. Ib. <span dir=\"rtl\">ולא נִקְמַת אדם</span> nor will it be a revenge executed by man; a. fr.—Pl. <span dir=\"rtl\">נְקָמוֹת</span>. Ib. <span dir=\"rtl\">כל הנ׳ האילו יש וכ׳</span> all these retaliations are reserved with the Lord for the wicked; a. e.—[Ber. l. c. <span dir=\"rtl\">שתי נ הללו וכ׳</span> why these two judgments (<i>n’ḳamah</i> in the plural)?; v., however, <a href=\"#\" data-headword=\"הוֹפָעָה\">הוֹפָעָה</a>.]</div>","alt":[]},"20317":{"h":"נַקְמָן","r":"N01229","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְקָמָה\">preced.</a>) <i>revengeful</i>. <span class=\"citation\">Gen. R. s. 99</span>, end <span dir=\"rtl\">כשם שנחש נ׳ וכ׳</span> as the serpent is revengeful, so was Samson.</div>","alt":[]},"20318":{"h":"נִקְמְתָא","r":"N01230","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִקְמָא\">נִקְמָא</a></div>","alt":[]},"20319":{"h":"נקסטן","r":"N01231","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיקְסִינָה\">פִּיקְסִינוֹן</a></div>","alt":[]},"20320":{"h":"נֶקַע","r":"N01232","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"נָקִיק\">נָקִיק</a>) <i>cleft, cavity, ravine.</i> <span class=\"citation\">Kil. V, 4</span>. <span class=\"citation\">Tosef. Erub. III (II), 3</span>; a. e.—Pl. <span dir=\"rtl\">נְקָעִים</span>. <span class=\"citation\">B. Bath. VII, 1</span>. <span class=\"citation\">Ib. 103ᵃ</span>; <span class=\"citation\">Kidd. 61ᵃ</span> <span dir=\"rtl\">נ׳ מלאים מים</span> ravines filled with water; v. <a href=\"#\" data-headword=\"נָאגָנָא\">נָאגָנָא</a>.—<span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> top <span dir=\"rtl\">נ׳ שתחת הזתים</span> cavities under olive trees; cmp. <a href=\"#\" data-headword=\"אוּגְיָא\">אוּגְיָא</a>.</div>","alt":[]},"20321":{"h":"נָקַף I","r":"N01233","html":"<div class=\"sense\"><i>to bring in close contact; to knock, strike against, wound</i>. <span class=\"citation\">Ḥull. 7ᵇ</span> <span dir=\"rtl\">אין אדם נוֹקֵף וכ׳</span> no one on earth bruises his finger, unless it is decreed &amp;c. <span class=\"citation\">Ber. 7ᵇ</span>; <span class=\"citation\">Meg. 6ᵇ</span> <span dir=\"rtl\">מי שלבו נוֹקְפוֹ</span> he whom his heart smites (who has no clear conscience). <span class=\"citation\">Nidd. 3ᵇ</span>, a. e. <span dir=\"rtl\">לבו נוקפו ופורש</span> he may have scruples and separate himself entirely from his wife. <span class=\"citation\">Midr. Till. to Ps. IX</span>, v. <a href=\"#\" data-headword=\"נֶקֶף\">נֶקֶף</a>.—<span class=\"citation\">Maas. Sh. V, 15</span>; <span class=\"citation\">Sot. IX, 10</span> <span dir=\"rtl\">הנוֹקְפִים</span> those who knocked the sacrifices on their heads; expl. <span class=\"citation\">ib. 48ᵃ</span>; Y. ib. IX, 24ᵃ bot.—Part. pass. <a href=\"#\" data-headword=\"נִקּוּף\">נָקוּף</a>; f. <span dir=\"rtl\">נְקוּפָה</span>; pl. <span dir=\"rtl\">נְקוּפִים</span>, <span dir=\"rtl\">נְקוּפִין</span>; <span dir=\"rtl\">נְקוּפוֹת</span>. <span class=\"citation\">Tosef. Ḥull. III, 24</span> <span dir=\"rtl\">ביצים נ׳ לקערה</span> eggs cracked open into a dish (<span class=\"citation\">Ḥull. 64ᵃ</span> <span dir=\"rtl\">טרופות</span>).</div><div class=\"sense\"><b>Hif. הִנְקִיף  הִקִּיף</b> <div class=\"sense\"><b>1)</b> <i>to cause a knocking together</i>. <span class=\"citation\">Sot. 22ᵇ</span> (expl. <a href=\"#\" data-headword=\"נִקְפִּי\">נקפי</a>) <span dir=\"rtl\">המַנְקִיף את רגליו</span> he who knocks his feet against each other (by his mincing walk; Rashi: who causes his feet to strike against objects on the road); cmp. <a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to bring closely together</i>. <span class=\"citation\">Bekh. VII, 6</span> <span dir=\"rtl\">שמַקִּיף</span>, v. <a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>. <span class=\"citation\">Nidd. X, 7</span> <span dir=\"rtl\">ומַקֶּפֶת</span> and brings the vessel which contains the Ḥallah near the dough; <span class=\"citation\">T’bul Yom IV, 3</span>, sq. <span class=\"citation\">Bets. IV, 5</span> <span dir=\"rtl\">ואין מַקִּיפִין שתי וכ׳</span> and you must not move two wine vessels together to put upon them &amp;c.—Esp. (ritual law, in examining an organic defect found in a slaughtered animal) <i>to create a defect similar and near to the one found</i>, in order to ascertain whether the latter was not the result of an accident after slaughtering; in gen. <i>to compare</i>. <span class=\"citation\">Ḥull. 50ᵃ</span> <span dir=\"rtl\">מַקִּיפִים בבני מעים</span> we may compare defects in entrails in which was found a perforation the origin of which is doubtful by making a hole next to it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מקיפין בקנה</span> we may compare defects in windpipes; a. fr.—<span class=\"citation\">Kidd. 40ᵃ</span> <span dir=\"rtl\">אין מקיפין בחילול השם</span> no comparing (balancing of sins against good deeds) is granted when the Name of God is profaned; (oth. interpret., v. <a href=\"#\" data-headword=\"נָקַף II\"><span dir=\"rtl\">נָקַף</span> II</a>).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מוּקָּף\">מוּקָּף</a> <i>brought near</i>. <span class=\"citation\">Erub. 30ᵇ</span>; <span class=\"citation\">Ḥull. 7ᵃ</span>; a. fr. <span dir=\"rtl\">לתרום שלא מן המ׳</span> to take T’rumah out of a mass which is not in close neighborhood of those products which are to be redeemed; <span class=\"citation\">Bicc. II, 5</span>; <span class=\"citation\">Ter. IV, 3</span>; a. e.</div></div>","alt":[]},"20322":{"h":"נְקַף","r":"N01234","html":"<div class=\"sense\">, <i>to strike, knock, push down</i>. <span class=\"citation\">Targ. Ps. CXL, 5</span>. <span class=\"citation\">Targ. O. Ex. XXXIV, 20</span> <span dir=\"rtl\">ותִיקְּפֵיה</span> ed. Berl. (oth. ed., a Y. <span dir=\"rtl\">ותִנְקְ׳</span>; ed. Vien. <span dir=\"rtl\">ותַנְקְ׳</span> <i>Af</i>.; h. text <span dir=\"rtl\">וערפתו</span>). <span class=\"citation\">Targ. Deut. XXI, 4</span> (O. ed. Berl. <span dir=\"rtl\">ויַקְּ׳</span>, <i>Af</i>.); a. e.—Part. pass. <span dir=\"rtl\">נְקִיף</span>; f. <a href=\"#\" data-headword=\"נְקִיפָא\">נְקִיפָא</a>. Ib. 6 (O. ed. Vien. <a href=\"#\" data-headword=\"נְקֶפְתָּא\">נְקֶפְתָּא</a>).—<span class=\"citation\">Erub. 53ᵇ</span> (enigmatic speech) <span dir=\"rtl\">עלת נַקְפַת בכד ידאון וכ׳</span> the ladle strikes against the jug, shall the eagles fly to their nests (the wine is gone, shall the students go home)?</div><div class=\"sense\"><b>Pa. נַקֵּף</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נָקַף I\">same</a>. <span class=\"citation\">Targ. Ps. CXL, 12</span> (Ms. <i>Pe</i>.).—Part. pass. <span dir=\"rtl\">מְנַקַּף</span>. <span class=\"citation\">Ber. 6ᵃ</span> <span dir=\"rtl\">כרעי דמְנַקְּפֵי</span> bruised feet; <span class=\"citation\">Yoma 53ᵃ</span>, v. <a href=\"#\" data-headword=\"נְגַף\">נְגַף</a>.</div></div><div class=\"sense\"><b>Af. אַנְקֵף  אַקֵּף</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נָקַף I\">same</a>; v. supra.—2) </div><div class=\"sense\"><i>to knock the feet against each other, to mince</i> (v. <a href=\"#\" data-headword=\"נָקַף I\">preced.</a><i>Hif.</i>). <span class=\"citation\">Targ. Is. III, 16</span> (h. text <a href=\"#\" data-headword=\"טָפַף I\">טפף</a>).</div><div class=\"sense\"><b>—2)</b> <i>to compare defects</i> (v. <a href=\"#\" data-headword=\"נָקַף I\">preced.</a><i>Hif.</i>). <span class=\"citation\">Ḥull. 50ᵃ</span> <span dir=\"rtl\">אַקְּפִינְהוּ ולא וכ׳</span> they compared them, and they did not look alike.</div></div><div class=\"sense\"><b>Ithpa. אִתְנַקֵּף</b> <div class=\"sense\"><i>to knock against, to stumble</i>. Targ. II Esth. IV, 13.—Yoma l. c. <span dir=\"rtl\">מִינַּקְּפִין</span> Ar. ed. Koh., v. <a href=\"#\" data-headword=\"נְגַף\">נְגַף</a>.</div></div>","alt":[]},"20323":{"h":"נָקַף II","r":"N01235","html":"<div class=\"sense\"><i>to circle; to bore</i>.—Part. pass. <a href=\"#\" data-headword=\"נִקּוּף\">נָקוּף</a>; f. <span dir=\"rtl\">נְקוּפָה</span>. <span class=\"citation\">Gen. R. s. 100</span>, v. <a href=\"#\" data-headword=\"נָקַב\">נָקַב</a>.</div><div class=\"sense\"><b>Hif. הִקִּיף</b> <div class=\"sense\"><b>1)</b> <i>to surround</i>. <span class=\"citation\">Erub. I, 8</span> (<span class=\"citation\">15ᵇ</span>) <span dir=\"rtl\">והִקִּיפוּהָ</span> (<a href=\"#\" data-headword=\"ב\">ב</a>)<span dir=\"rtl\">כלי בהמה</span> and they surrounded it (the camp) with utensils of travel (wagons, saddles &amp;c.). Ib. 9 <span dir=\"rtl\">מַקִּיפִין שלשה וכ׳</span> you may surround the camp with three ropes &amp;c. (for Sabbath purposes). Ib. 53ᵇ מצאתי שמקיפין אותה גנות וכ׳ I found that gardens and orchards surrounded the town (making it inaccessible); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to cause to go around</i>. Mekh. B’shall. s. 1 אַקִּיפֵם במדבר וכ׳ I shall make them go around in the desert forty years; ib. <span dir=\"rtl\">הריני מַקִּיפָן וכ׳</span>. <span class=\"citation\">Snh. VIII, 1</span> <span dir=\"rtl\">עד שיַקִּיף וכ׳</span> until he has grown hair around &amp;c., v. <a href=\"#\" data-headword=\"זָקֵן I\">זָקֵן</a>.</div><div class=\"sense\"><b>—3)</b> <i>to cut all around</i>, esp. (with ref. to <span class=\"citation\">Lev. XIX, 27</span>) <i>to cut around the corners of the hair of the head</i>. <span class=\"citation\">Naz. 57ᵇ</span> <span dir=\"rtl\">אחד המַקִּיף ואחד הנִיקָּף</span> he who cuts and he whose hair is cut are alike guilty; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to sell on terms</i> (v. <a href=\"#\" data-headword=\"תְּקוּפָה\">תְּקוּפָה</a>), <i>to lend.</i> <span class=\"citation\">Ab. III, 16</span> <span dir=\"rtl\">החנוני מַקִּיף</span> the shopkeeper allows credit (the Lord is long-suffering). <span class=\"citation\">B. Kam. 79ᵃ</span> top <span dir=\"rtl\">גנב וה׳</span> if he stole an animal and sold it on credit (and has received no pay); a. fr.—<span class=\"citation\">Kidd. 40ᵃ</span> <span dir=\"rtl\">אין מַקִּיפִין וכ׳</span> no loan on time is granted (no chance for repentance is allowed), when the Name of the Lord is profaned; (oth. interpret., v. <a href=\"#\" data-headword=\"נָקַף I\"><span dir=\"rtl\">נָקַף</span> I</a>).</div></div><div class=\"sense\"><b>Hof. הוּקָּף</b> <div class=\"sense\"><i>to be surrounded</i>. <span class=\"citation\">Arakh. 33ᵇ</span>; <span class=\"citation\">Meg. 3ᵇ</span> <span dir=\"rtl\">שה׳ ולבסוף וכ׳</span> it was surrounded (a fort was built) and then settled; a. fr.—Part. <a href=\"#\" data-headword=\"מוּקָּף\">מוּקָּף</a>; f. <span dir=\"rtl\">מוּקֶּפֶת</span>; pl. <span dir=\"rtl\">מוּקָּפִין</span>; <span dir=\"rtl\">מוּקָּפוֹת</span>. Ib. I, 1 <span dir=\"rtl\">המ׳ חומה וכ׳</span> fortified since the days of Joshua. Ib. 2ᵇ. Ib. 4ᵇ. <span class=\"citation\">Gen. R. s. 39</span>, v. <a href=\"#\" data-headword=\"פָּתִיל\">פָּתִיל</a>; a. fr.—Mekh. B’shall., s. 1 מוקפות <i>semicircular</i></div></div><div class=\"sense\"><b>Nif. נִיקָּף</b> <div class=\"sense\"><i>to have one’s hair cut all around</i>. Naz. l. c., v. supra. Ib. <span dir=\"rtl\">כל היכא דנ׳ מיחייב וכ׳</span> whenever he who has his hair cut &amp;c. is punishable (is not a minor or a woman), the cutter is punishable; a. e.</div></div><div class=\"sense\"><b>Pi. נִיקֵּף</b> <div class=\"sense\"><b>1)</b> <i>to collect fruit which remained in the crown of the tree</i> (v. <a href=\"#\" data-headword=\"נִיקּוּף ²\"><span dir=\"rtl\">נִיקּוּף</span> II</a>), <i>to glean olives</i> (corresp. to <a href=\"#\" data-headword=\"פְּאֵר\">פֵּאֵר</a>, <span class=\"citation\">Deut. XXIV, 20</span>). <span class=\"citation\">Gitt. V, 8</span> <span dir=\"rtl\">עני המְנַקֵּף … מה שתחתיו גזל</span> when the poor man does the gleaning on the top of the olive tree, what falls down under him is forbidden to any other person; Y. ed. <span dir=\"rtl\">המנ׳ בראש הזית גזל</span> (corr. acc.; v. ib. 47ᶜ top).</div><div class=\"sense\"><b>—2)</b> <i>to cut all around, trim</i>. <span class=\"citation\">B. Kam. 119ᵇ</span>; <span class=\"citation\">Tosef. ib. XI, 18</span> <span dir=\"rtl\">מְנַקְּפֵי היגין</span> those who trim shrubs. Ib. <span dir=\"rtl\">השוכר … לנַקֵּף עמו וכ׳</span></div></div>","alt":[]},"20324":{"h":"נְקַף ²","r":"N01236","html":"<div class=\"sense\">—<i>Af</i>. <a href=\"#\" data-headword=\"נְקַף\">אַקֵּף</a> as <a href=\"#\" data-headword=\"נָקַף II\">preced.</a> <i>Hif.</i> <span class=\"citation\">Targ. Jud. XI, 18</span>.—<span class=\"citation\">Targ. Lev. XIX, 27</span>; a. fr. Part. pass. <span dir=\"rtl\">מַקֵּף</span> (= h. <a href=\"#\" data-headword=\"מוּקָּף\">מוּקָּף</a>, v. <a href=\"#\" data-headword=\"נָקַף II\">preced.</a> <i>Hof</i>.). <span class=\"citation\">Ib. XXV, 31</span>. <span class=\"citation\">Targ. Is. XXIX, 2</span>; a. fr.—<span class=\"citation\">Snh. 69ᵃ</span> <span dir=\"rtl\">מקמיה דלַקִּיף זקן</span> before his hair around the genitals is grown.—<span class=\"citation\">Y. Ber. IX, 14ᵇ</span> bot., a. e. (expl. <span dir=\"rtl\">ניקפי</span>) <span dir=\"rtl\">אַקֵּיף לי וכ׳</span> (the Pharisee that says,) Lend me that I may do a certain pious work; a. fr.</div>","alt":[]},"20325":{"h":"נֶקֶף","r":"N01237","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נָקַף I) </div><div class=\"sense\"><b>1)</b> <i>bruise</i>.—Pl. <span dir=\"rtl\">נְקָפִים</span>. <span class=\"citation\">Sabb. 62ᵇ</span> (expl. <a href=\"#\" data-headword=\"קפי\">נקפה</a>, <span class=\"citation\">Is. III, 24</span>); <span class=\"citation\">Yalk. Is. 264</span>.</div><div class=\"sense\"><b>—2)</b> <i>beating</i> (of the heart), <i>scruples, doubt</i>. <span class=\"citation\">Midr. Till. to Ps. IX, 2</span> <span dir=\"rtl\">שלא יהא בלבי נ׳</span> that there be no struggle in my heart (ed. Bub., a. Yalk. ib. 642: <span dir=\"rtl\">שלא יהא לבי נוֹקֵף</span>, v. <a href=\"#\" data-headword=\"נָקַף I\"><span dir=\"rtl\">נָקַף</span> I</a>).</div>","alt":[]},"20326":{"h":"נְקֶפְתָּא","r":"N01238","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָקַף I\"><span dir=\"rtl\">נְקַף</span> I</a></div>","alt":[]},"20327":{"h":"נִקְפִּי","r":"N01239","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָקַף I\">נקף</a>) <i>knocker</i>, or <i>borrower</i>, an opprobrious epithet for a sort of sanctimonious Pharisees. <span class=\"citation\">Sot. 22ᵇ</span>, v. <a href=\"#\" data-headword=\"נָקַף I\"><span dir=\"rtl\">נָקַף</span> I</a>; Y. ib. V, 20ᶜ bot.; <span class=\"citation\">Y. Ber. IX, 14ᵇ</span> bot., v. <a href=\"#\" data-headword=\"נָקַף II\"><span dir=\"rtl\">נְקַף</span> II</a>.</div>","alt":["נִי׳"]},"20328":{"h":"נִקְצָא","r":"N01240","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">קצץ</span>) <i>piece, splinter</i>. <span class=\"citation\">Targ. Prov. XXVI, 8</span> <span dir=\"rtl\">נ׳ דטסא</span> ed. (ed. Lag. a. oth. <a href=\"#\" data-headword=\"נִיסְקָא\">ניסקא</a>, transp. of <span dir=\"rtl\">ניקסא</span>, cmp. <a href=\"#\" data-headword=\"קֵיסָא\">קֵיסָא</a>) a splinter of foil (<i>mica</i>; h. text <span dir=\"rtl\">צרור אבן</span>).</div>","alt":["נִי׳"]},"20329":{"h":"נָקַר I","r":"N01241","html":"<div class=\"sense\"><b>1)</b> <i>to dig, chisel</i>, esp. <i>to whet a millstone</i>. <span class=\"citation\">M. Kat. 10ᵃ</span> <span dir=\"rtl\">נוֹקְרִין ריחים וכ׳</span> you may roughen a millstone during the festive week. <span class=\"citation\">Sot. 46ᵇ</span> <span dir=\"rtl\">ולִנְקוֹר</span>, v. infra.</div><div class=\"sense\"><b>—2)</b> <i>to bore, perforate; to put out</i>. <span class=\"citation\">Sabb. 130ᵃ</span> <span dir=\"rtl\">יִקְּרוּ את מוחו</span> they shall perforate (or put out) his brain. <span class=\"citation\">Sot. I, 8</span> <span dir=\"rtl\">נָקְרוּ פלשתים וכ׳</span> (or <span dir=\"rtl\">נִקְּרוּ</span>) the Philistines put out his eyes; a. e.</div><div class=\"sense\"><b>—3)</b>  (of birds, mice, serpents &amp;c.) <i>to pick, gnaw at</i>. <span class=\"citation\">Tosef. Ter. VII, 17</span>. Y. ib. III, beg. 42ᵃ <span dir=\"rtl\">בשראו אותו נוֹקֵר</span> when they saw the bird pick; a. fr.—[<span class=\"citation\">Y. Yeb. X, 11ᵃ</span> top <span dir=\"rtl\">לבי נוקריני</span>, v. <a href=\"#\" data-headword=\"נָקַד I\"><span dir=\"rtl\">נָקַד</span> I</a>.]—Part. pass. <a href=\"#\" data-headword=\"נִקּוּר\">נָקוּר</a>; pl. <a href=\"#\" data-headword=\"נְעוּרִים\">נְקוּרִים</a>, <span dir=\"rtl\">נְקוּרִין</span>. Y. Ter. l. c. Tosef. l. c. <span dir=\"rtl\">שמא נ׳ היו</span> may be they were already picked at (by birds); a. e.</div><div class=\"sense\"><b>Pi. נִיקֵּר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נִקְצָא\">same</a>. M. Kat. l. c. <span dir=\"rtl\">מְנַקֵּר ריחים</span>, v. supra. <span class=\"citation\">Sot. IX, 5</span> <span dir=\"rtl\">ולנַקֵּר שם וכ׳</span> (<span class=\"citation\">ib. 46ᵇ</span> <span dir=\"rtl\">ולנקור</span>) and to chisel stones there.—<span class=\"citation\">Pes. 8ᵇ</span> <span dir=\"rtl\">תרנגולתך מְנַקֶּרֶת וכ׳</span> (not <span dir=\"rtl\">מנקר</span>) thy hen shall be picking in the dunghill &amp;c. <span class=\"citation\">Toh. IV, 3</span> <span dir=\"rtl\">היו מְנַקְּרִין בהן וכ׳</span> if they have been picking them (the pieces of carrion) on the ground; a. e.</div></div><div class=\"sense\"><b>Nif. נִיקַּר</b> <div class=\"sense\"><i>to be picked at</i>. Y. Ter. VIII, 45ᶜ top <span dir=\"rtl\">תאנים שנִיקְּרוּ …</span> figs or grapes which have been picked at.</div></div>","alt":[]},"20330":{"h":"נְקַר","r":"N01242","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Num. XXI, 35</span>. <span class=\"citation\">Targ. I Sam. XI, 2</span> <a href=\"#\" data-headword=\"מֵיקַר\">מִיקַּר</a> (ed. Wil. <a href=\"#\" data-headword=\"מֵיקַר\">מֵיקַר</a>); a. e.—<span class=\"citation\">Yalk. Prov. 963</span> <span dir=\"rtl\">דין נָקֵיר וכ׳</span> the one (the raven) picks the eye out, and the other (the eagle) eats it; Midr. Sam. ch. VII <a href=\"#\" data-headword=\"נָאקֵר\">נָאקֵר</a>.—Pesik. B’shall., p. 93ᵇ one worm <span dir=\"rtl\">דעתידא דנַקְרָא וכ׳</span> which shall bite me behind the ear.—<span class=\"citation\">Y. Sabb. XII, beg. 13ᶜ</span> <span dir=\"rtl\">ההן דנ׳ כיפין וכ׳</span> he who chisels stones, columns, millstones &amp;c.; a. e.—Part. pass. <span dir=\"rtl\">נְקִיר</span>. <span class=\"citation\">Kidd. 80ᵇ</span> <span dir=\"rtl\">אם איתא דנ׳ וכ׳</span> if it had been picked at (by the hens after drinking of a red liquid), it would have been noticeable.</div><div class=\"sense\"><b>Pa. נַקֵּר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נָקַר I\">same</a>. Y. Ter. VIII, 45ᶜ top <span dir=\"rtl\">הוה מְנַקְּרָא בתאינייא</span> a serpent had been biting at figs.—<span class=\"citation\">M. Kat. 10ᵃ</span> <span dir=\"rtl\">דקא מְנַקֵּר ריחיא</span> (Ms. M. <a href=\"#\" data-headword=\"נָקַר I\">נְקַרִ</a></div></div>","alt":[]},"20331":{"h":"נָקַר II","r":"N01243","html":"<div class=\"sense\"> (interch. with <a href=\"#\" data-headword=\"נָקַד I\">נָקַד</a>; cmp. <a href=\"#\" data-headword=\"נקי\">נָקָה</a>) <i>to be clean</i>. [Sifra Aḥăré, Par. 9, ch. XIII שלא תִנְקוֹר ‘Rabad’, be not <i>foppish</i> in dress in order to attract the admiration of women; v., however, <a href=\"#\" data-headword=\"נָחַשׁ\">נָחַשׁ</a>.]</div><div class=\"sense\"><b>Pi. נִקֵּר</b> <div class=\"sense\"><i>to keep clean</i>. <span class=\"citation\">Ḥull. 41ᵇ</span> <span dir=\"rtl\">הרוצה לנַקֵּר וכ׳</span> (Ar. <span dir=\"rtl\">לוַקֵּד</span>) he who wishes to keep his court clean.</div></div><div class=\"sense\"><b>Hif. הִנְקִיר</b> <div class=\"sense\"><i>to cleanse</i>. <span class=\"citation\">Sot. 11ᵇ</span> <span dir=\"rtl\">מנְקִיר</span>, v. <a href=\"#\" data-headword=\"נקי\">נָקָה</a>.</div></div>","alt":[]},"20332":{"h":"נְקַר ²","r":"N01244","html":"<div class=\"sense\">; <i>Ithpa.</i> <a href=\"#\" data-headword=\"נְקֵי\">אִתְנַקֵּר</a>, <i>Ithpe.</i> <a href=\"#\" data-headword=\"נְטַר\">אִתְנְקִיר</a>, <a href=\"#\" data-headword=\"נְצֵי\">אִינְּ׳</a> <i>to be cleansed</i>. <span class=\"citation\">Targ. Ez. XVI, 4</span> ed. Lag. <span dir=\"rtl\">לאִתְנַקָּדָא</span> (Var. <span dir=\"rtl\">לאִתְנַקָּרָא</span>; ed. Wil. <span dir=\"rtl\">לאתנקאה</span>; h. text <span dir=\"rtl\">למשעי</span>).—<span class=\"citation\">B. Mets. 103ᵇ</span> <span dir=\"rtl\">בעינא דתִינְּקַּר ארעאי</span> (Ar. <span dir=\"rtl\">דתִינְּקִיד</span>) I desire that my field be clear (of stubble).</div>","alt":[]},"20333":{"h":"נֶקֶר","r":"N01245","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נָקַר I) <i>bite, trace of a bite</i>. <span class=\"citation\">Tosef. Ter. VII, 16</span> <span dir=\"rtl\">נ׳ בתאינה וכ׳</span> if there was a bite to be seen in a fig, and it shrivelled (v. <a href=\"#\" data-headword=\"גְּרוֹגֶרֶת\">גְּרוֹגֶרֶת</a>,—which is an indication that it was not a serpent’s bite). Y. ib. VIII, 46ᵃ top <span dir=\"rtl\">מקום הנ׳ אכלו</span> they (the birds) ate from a spot which had been bitten at (by a serpent); a. e.—V. <a href=\"#\" data-headword=\"נִיקּוּר\">נִיקּוּר</a>.</div>","alt":[]},"20334":{"h":"נִקְרָא","r":"N01246","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נְקַר I) </div><div class=\"sense\"><b>1)</b> <i>cleft.</i> <i>—</i> Pl. <span dir=\"rtl\">נִקְרַיָּא</span>. <span class=\"citation\">Targ. Y. I Num. XXIV, 21</span> (Y. II <span dir=\"rtl\">כבקרת</span>, read: <span dir=\"rtl\">בנִקְרָתָא</span>, v. <a href=\"#\" data-headword=\"נְקִירְתָּא\">נְקִירְתָּא</a>).</div><div class=\"sense\"><b>—2)</b> <i>rag, lint</i>. <span class=\"citation\">Sabb. 134ᵇ</span> האי נ׳ מסי Ms. O. a. Ar. (ed. <span dir=\"rtl\">הני כתיתין מסו</span>) a compress of lint has a healing effect (and is not merely a protection).</div><div class=\"sense\"><b>—3)</b> <i>pickings, worms which hens pick</i>. <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">נִי׳ מקילקלתא</span> (Ms. M. <span dir=\"rtl\">נִיקְרֵי</span> <i>pl.</i>) worms from a dunghill.</div>","alt":["נִי׳"]},"20335":{"h":"נִקְרָה","r":"N01247","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (נָקַר I) </div><div class=\"sense\"><b>1)</b> <i>offal at chiselling, stone-dust</i>. <span class=\"citation\">Ḥull. 88ᵇ</span> <span dir=\"rtl\">נִקְרַת פסולין</span> dust of chiselled millstones.</div><div class=\"sense\"><b>—2)</b> <i>bite.</i> <span class=\"citation\">Toh. III, 8</span> Ar., v. <a href=\"#\" data-headword=\"נְקִירָה\">נְקִירָה</a>.</div>","alt":[]},"20336":{"h":"נקריס","r":"N01248","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַקְדּוּד\">נַקְדּוּד</a></div>","alt":[]},"20337":{"h":"נַקְרָן","r":"N01249","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נָקַר I) [<i>picker</i>,] <i>carper, fault-finder.</i> <i>—</i> Pl. <span dir=\"rtl\">נַקְרָנִים</span>, <span dir=\"rtl\">נַקְרָנִין</span>, <a href=\"#\" data-headword=\"נֹפֶךְ\">נוֹ׳</a>. Y. Snh. X, 28ᵈ bot.; <span class=\"citation\">Num. R. s. 20</span>, end; <span class=\"citation\">Sifré Num. 131</span> <span dir=\"rtl\">החקרנים</span> (some ed. <span dir=\"rtl\">התיקר׳</span>; corr. acc.); <span class=\"citation\">Yalk. ib. 771</span> <span dir=\"rtl\">נקדנין</span> (some ed. <span dir=\"rtl\">נקרבין</span>; corr. acc.).—V. <a href=\"#\" data-headword=\"נַקְדָּן\">נַקְדָּן</a>.</div>","alt":["נוֹקְרָן"]},"20338":{"h":"נְקַרְתָּא","r":"N01250","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְקִירְתָּא\">נְקִירְתָּא</a></div>","alt":[]},"20339":{"h":"נָקַשׁ","r":"N01251","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קִשְׁקֵשׁ I\"><span dir=\"rtl\">קִשְׁקַשׁ</span> I</a>) <i>to strike against; to touch closely</i>. <span class=\"citation\">Bekh. VII, 6</span> (<span class=\"citation\">45ᵃ</span>) (expl. <span dir=\"rtl\">עיקל</span>) <span dir=\"rtl\">כל שמקיף … נוֹקְשׁוֹת וכ׳</span> (Mish. ed. <span dir=\"rtl\">נושקות</span>) he whose legs do not touch each other when he puts his feet together. <span class=\"citation\">Meg. 12ᵇ</span>, v. infra.</div><div class=\"sense\"><b>Hif. הִקִּישׁ</b> <div class=\"sense\"><b>1)</b> <i>to cause striking against; to knock</i>. Bekh. l. c. (44ᵇ) <span dir=\"rtl\">המַקִּישׁ בקרסוליו וכ׳</span> he who knocks his ankle-bones against each other (in walking, because his legs are bent outward), or rubs his legs against each other (his feet being bent outward). Midr. Sam. ch. IX <span dir=\"rtl\">מַקֶּשֶׁת ברגליה ומקשת בקרניה</span> she knocks (creates a loud sound) with her feet and with her horns. <span class=\"citation\">Zab. IV, 1</span>, sq. <span dir=\"rtl\">ה׳ על וכ׳</span> if he knocked against &amp;c. <span class=\"citation\">Meg. 12ᵇ</span> (play on <span dir=\"rtl\">בן קיש</span>, <span class=\"citation\">Esth. II, 5</span>) <span dir=\"rtl\">שה׳ על וכ׳</span> (Ms. M. <span dir=\"rtl\">שנָקַשׁ</span>) he (Mordecai) knocked at the gates of mercy &amp;c.; a. fr.—Esp. (cmp. <a href=\"#\" data-headword=\"נָגַן\">נָגַן</a>, <a href=\"#\" data-headword=\"נָכָה\">נָכָה</a>) <i>to strike an instrument, play</i>. <span class=\"citation\">Tam. VII, 3</span>. <span class=\"citation\">Gen. R. s. 18</span> (play on <span dir=\"rtl\">הפעם</span>, <span class=\"citation\">Gen. II, 23</span>) <span dir=\"rtl\">עתידה להַקִּישׁ עלי כזוג</span> (‘Rashi’: <span dir=\"rtl\">לקשקש</span>) she is destined to be loud against me like a bell. <span class=\"citation\">Pesik. R. s. 31</span>; <span class=\"citation\">Midr. Till. to Ps. CXXXVII</span> אני מבקש שתעמדו ותַקִּישׁוּ … כדרך שהייתם מַקִּישִׁין וכ׳ I desire that you play on the cithern before me and the idol, as you played before your God. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אנו עומדים להַקִּישׁ וכ׳</span> shall we stand playing before this dwarf (Nebuchadnezzar) and this idol? <span class=\"citation\">Midr. Till. to Ps. XCII</span>, end (play on <a href=\"#\" data-headword=\"יַקְשָׁן\">יקשן</a>, <span class=\"citation\">Gen. XXV, 2</span>) <span dir=\"rtl\">שהיו מקישין בתוף לעכו&quot;ם</span> they struck the timbrel before idols; Yalk. Chr. 1073; <span class=\"citation\">Gen. R. s. 61</span> <span dir=\"rtl\">מקשין בית׳</span> (corr. acc.).—2) (cmp. <a href=\"#\" data-headword=\"נָקַף I\">נָקַף</a>) <i>to bring under the same category by juxtaposition, to compare</i>. <span class=\"citation\">Kidd. 5ᵃ</span>, a. fr. (ref. to <span dir=\"rtl\">ויצאה</span> a. <span dir=\"rtl\">והיתה</span> in the same verse, <span class=\"citation\">Deut. XXIV, 2</span>) <span dir=\"rtl\">מקיש הויה ליציאה</span>, v. <a href=\"#\" data-headword=\"הֲוָיָה\">הֲוָיָה</a>. <span class=\"citation\">Snh. 60ᵇ</span> (ref. to <span class=\"citation\">Ex. XXII, 19</span> a. <span class=\"citation\">XXXIV, 14</span>) <span dir=\"rtl\">זביחה בכלל … להַקִּישׁ אליה</span> slaughtering for the idol would have been included in worshipping, and why is it singled out? To compare all other idolatrous functions with it: as slaughtering is a function performed inside &amp;c. <span class=\"citation\">Zeb. 5ᵇ</span> <span dir=\"rtl\">הִקִּישׁוֹ הכתוב וכ׳</span> the text (<span class=\"citation\">Lev. VII, 37</span>) places it side by side with peace offerings; a. fr.</div></div><div class=\"sense\"><b>Hof. הוּקַּשׁ</b> <div class=\"sense\"><i>to be placed side by side, to be compared</i>. <span class=\"citation\">Ker. 3ᵃ</span> (ref. to <span class=\"citation\">Num. XV, 29</span>, sq.) <span dir=\"rtl\">הוּקְּשָׁה כל התורה וכ׳</span> all the laws of the Torah are here placed on an equality with idolatry (as regards conditions of punishment). Ib. 2ᵇ <span dir=\"rtl\">הוּקְּשׁוּ כל העריות כולן וכ׳</span> all laws concerning incest are put on an equality with &amp;c. (<span class=\"citation\">Lev. XVIII, 29</span>); a. fr.—Part. <a href=\"#\" data-headword=\"מוּקָּשׁ\">מוּקָּשׁ</a>. <span class=\"citation\">Gen. R. s. 35</span> (play on <span dir=\"rtl\">קשתי</span>, <span class=\"citation\">Gen. IX, 13</span>) <span dir=\"rtl\">דבר שהוא מ׳ לי</span> something comparable with me (with the Divine Glory); Yalk. ib. 61; v. <a href=\"#\" data-headword=\"קִישׁוּת II\"><span dir=\"rtl\">קִישׁוּת</span> II</a>.</div></div>","alt":[]},"20340":{"h":"נְקַשׁ","r":"N01252","html":"<div class=\"sense\">, <i>to strike against; to knock, drive in</i>. Targ. II Esth. VI, 10, sq. <span class=\"citation\">Targ. Jud. IV, 21</span> (ed. Wil. <span dir=\"rtl\">נקיש׳</span>); a. e.—<span class=\"citation\">Snh. 25ᵇ</span> אנא ידענא למִנְקַשׁ וכ׳ Ar. (ed. <a href=\"#\" data-headword=\"לַקּוּשֵׁי\">לנַקּוּשֵׁי</a>, <i>Pa</i>.; Rashi <span dir=\"rtl\">בנְקָשָׁא</span>) I know better how to clap (at the pigeon-race). <span class=\"citation\">B. Kam. 52ᵇ</span> <span dir=\"rtl\">איבעי ליה למיזיל ומִינְקַשׁ עליה</span> it was his duty to go and knock upon it (to try the soundness of the board). <span class=\"citation\">B. Mets. 59ᵃ</span> (prov.) <span dir=\"rtl\">כמִשְׁלַם … נָקֵישׁ ואזיל תיגרא</span> when the barley is gone out of the pitcher, quarrel knocks and comes in; a. e.</div><div class=\"sense\"><b>Pa. נַקֵּשׁ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נָקַשׁ\">same</a>, v. supra.</div></div><div class=\"sense\"><b>Af. אַקֵּישׁ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נָקַשׁ\">same</a>. Y. B. Bath. IV, end, 15ᶜ; Y. Gitt. III, end, 45ᵇ <span dir=\"rtl\">מַקְּשִׁין על גרבא וכ׳</span> they knock at the vessel outside and know what is in it. <span class=\"citation\">Lev. R. s. 6</span> <span dir=\"rtl\">נסתיה … ואַקְּשֵׁיה לארעא</span> he took the cane and knocked it against the floor; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to compare</i>. <span class=\"citation\">Targ. Job XXX, 19</span> (sec. Vers.).—<span class=\"citation\">Zeb. 5ᵇ</span> <span dir=\"rtl\">מאי חזית דאַקְּשַׁת … אַקְּשָׁהּ לחטאת</span> (ed. <a href=\"#\" data-headword=\"נְקַשׁ\">אַקֵּישׁ</a>) why do you compare it with peace offerings? Compare it with sin offerings; <span class=\"citation\">Yalk. Lev. 470</span>. <span class=\"citation\">Snh. 15ᵃ</span> <span dir=\"rtl\">לאַקּוּשֵׁי וכ׳</span> to place on an equal footing &amp;c.; a. e.</div></div><div class=\"sense\"><b>Ithpe. אִתְנְקַשׁ</b> <div class=\"sense\"><i>to be knocked together</i>. <span class=\"citation\">Targ. Koh. XII, 3</span> (of the trembling hands of the age-stricken; h. text <span dir=\"rtl\">התעותו</span>).</div></div><div class=\"sense\"><b>Ittaf. אִיתַּקַּשׁ</b> <div class=\"sense\"><i>to be set side by side, be compared</i>. <span class=\"citation\">Pes. 61ᵃ</span> (ref. to <span class=\"citation\">Ex. XII, 4</span>) <span dir=\"rtl\">א׳ אוכלין למנויין</span> those who partake of the Passover lamb are placed on an equal footing with those who are entered as shareholders, i.e. it must be slaughtered in behalf only of those entered and of such among them as are able to partake. <span class=\"citation\">Snh. 15ᵃ</span> <span dir=\"rtl\">עבד א׳ לקרקעות</span> a slave is classed with landed estate. <span class=\"citation\">Ib. 63ᵃ</span> <span dir=\"rtl\">אִיתַּקּוּשֵׁי אִיתַּקּוּשׁ</span> they (the bowing and the sacrificing to the idol) are legally alike; a. fr.</div></div>","alt":[]},"20341":{"h":"נְקָשָׁא","r":"N01253","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְקַשׁ\">preced.</a>) <i>knocking, rattling</i>. <span class=\"citation\">Snh. 25ᵇ</span> <span dir=\"rtl\">בנ׳ תליא מילתא</span> (Ar. <span dir=\"rtl\">בנְקִישָׁא</span>) the winning of the race depends on the clapping, v. preced.—V. <a href=\"#\" data-headword=\"נִיקּוּשָׁא\">נִיקּוּשָׁא</a>.</div>","alt":[]},"20342":{"h":"נקשונין","r":"N01254","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיקְסִינָה\">פִּיקְסִינוֹן</a></div>","alt":["נקשנון"]},"20343":{"h":"נֵר","r":"N01255","html":"<div class=\"sense\"> c. (b. h.; v. <a href=\"#\" data-headword=\"נוּר\">נוּר</a>) <i>light</i>. <span class=\"citation\">Sabb. 22ᵇ</span>; <span class=\"citation\">Men. 86ᵇ</span> <span dir=\"rtl\">נר מערבי שנותנין וכ׳</span> the westernmost light (on the candlestick in the Temple) into which as much oil was put as all the others together contained. <span class=\"citation\">Sabb. 22ᵃ</span> <span dir=\"rtl\">מנר לנר מדליקין</span> you may light one Ḥanuckah light on the other; a. v. fr.—<span class=\"citation\">Ber. 28ᵇ</span>, a. e. <span dir=\"rtl\">נר ישראל</span> light of Israel (great scholar).—<span class=\"citation\">Ex. R. s. 36</span> <span dir=\"rtl\">נֵרִי</span> my (the Lord’s) light (the Law), <span dir=\"rtl\">נֵרְךָ</span> thy (man’s) light (the soul); <span class=\"citation\">Lev. R. s. 31</span> <span dir=\"rtl\">נֵרִי</span> (the Lord’s light in the Temple).—Pl. <span dir=\"rtl\">נֵרוֹת</span>. <span class=\"citation\">Tam. VI, 1</span> <span dir=\"rtl\">שני נ׳ מזרחיים</span> (Talm. ed. <span dir=\"rtl\">שתי נ׳ מערביים</span>, corr. acc.) the two easternmost lights. Ib. III, 9 (30ᵇ) <span dir=\"rtl\">שתי נ׳ מזרחיות</span> (Talm. ed. <span dir=\"rtl\">ב׳ נ׳ מערבית</span>, read <span dir=\"rtl\">מערביות</span> or <span dir=\"rtl\">מערביים</span>); a. fr.</div>","alt":[]},"20344":{"h":"נָרָא","r":"N01256","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"נֵר\">preced.</a>) <i>violet</i> (color), <i>violet</i> (flower). <span class=\"citation\">Gitt. 19ᵇ</span> <span dir=\"rtl\">בדקינן ליה במיא דנ׳</span> we examine the sheet with a violet-colored liquid (to bring out any faded writing). <span class=\"citation\">Ab. Zar. 28ᵇ</span> אודדא דנ׳ Ar. (ed. <span dir=\"rtl\">אודרא דנדא</span>; Ms. M. <span dir=\"rtl\">דנורא</span>) violet-dyed wool. [R. Ḥan.: <span dir=\"rtl\">מיא דנ׳</span> decoction of the bark of the <i>pomegranate-tree</i>, Pers. nâr, Perl. Et. St., p. 37, sq.]</div>","alt":[]},"20345":{"h":"נַרְגָּא","r":"N01257","html":"<div class=\"sense\"> c. (transpos. of <a href=\"#\" data-headword=\"נַגְרָא\">נַגְרָא</a>, v. <a href=\"#\" data-headword=\"נַגָּר ²\">נַגָּרָא</a>) <i>axe</i>. <span class=\"citation\">Targ. Y. Num. XXI, 35</span>.—<span class=\"citation\">Ber. 54ᵇ</span> שקל נ׳ בר וכ׳ Moses took an axe measuring ten cubits. <span class=\"citation\">Keth. 10ᵇ</span>, v. <a href=\"#\" data-headword=\"דִּקְלָא\">דִּקְלָא</a>. <span class=\"citation\">R. Hash. 13ᵃ</span> <span dir=\"rtl\">שדא ביה נ׳</span> he swung an axe at it, i.e. disproved the opinion; <span class=\"citation\">Succ. 12ᵃ</span>; <span class=\"citation\">Snh. 30ᵇ</span>; <span class=\"citation\">Pes. 32ᵇ</span>; a. e.—Pl. <span dir=\"rtl\">נַרְגִּין</span>, <span dir=\"rtl\">נַרְגַּיָּא</span>, <span dir=\"rtl\">נַרְגֵּי</span>. Targ. II Esth. I, 2 (3). <span class=\"citation\">Targ. Job XLI, 21</span> (ed. Wil. <span dir=\"rtl\">נִרְ׳</span>).—<span class=\"citation\">Yoma 37ᵇ</span>; <span class=\"citation\">Bets. 33ᵇ</span> <span dir=\"rtl\">קתתא דנ׳ וחציני</span> (Ms. M. a. Ar. <span dir=\"rtl\">נגרי</span>, v. Rabb. D. S. a. l. note) the helves of axes and adzes. <span class=\"citation\">Snh. 96ᵇ</span> <span dir=\"rtl\">תלת … נ׳ וכ׳</span> (not <a href=\"#\" data-headword=\"נַרְגָּא\">נרגא</a>) three hundred mule loads of axes of iron that has power over iron (steel).</div>","alt":[]},"20346":{"h":"נֵרְגוֹל","r":"N01258","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נֵרְגַל\">נֵרְגַל</a></div>","alt":[]},"20347":{"h":"נִרְגָּז","r":"N01259","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָגַז\">רָגַז</a></div>","alt":[]},"20348":{"h":"נרגזא","r":"N01260","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 45</span> ed. Bub. (oth. ed. <span dir=\"rtl\">נרגזין</span>), read: <a href=\"#\" data-headword=\"בַּרְגְּזָא\">בַּר גַּזָּא</a> or <span dir=\"rtl\">בַּר גַּזִּין</span>, v. <a href=\"#\" data-headword=\"גַּזָּא\">גַּזָּא</a></div>","alt":[]},"20349":{"h":"נַרְגִּילָא","r":"N01261","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. nârgil, Perl. Et. St. p. 38) <i>cocoanut, cocoanut-palm</i> the bast of which is used for making ropes. <span class=\"citation\">Erub. 58ᵃ</span>, v. <a href=\"#\" data-headword=\"נְבָרָא\">נְבָרָא</a>.</div>","alt":[]},"20350":{"h":"נֵרְגַל","r":"N01262","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Nergal</i>, </div><div class=\"sense\"><b>1)</b>  a deity of the Cutheans (v. Schr. KAT<sup>2</sup>, p. 282, sq.). <span class=\"citation\">Snh. 63ᵇ</span> (quoting <span class=\"citation\">II Kings XVII, 30</span> <a href=\"#\" data-headword=\"נֵרְגוֹל\">נרגול</a>), expl. <a href=\"#\" data-headword=\"תַּרְנְגוֹל\">תרנגול</a> a cock; <span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> top <span dir=\"rtl\">ריגליה דיעקב וריגליה דיוסף וכ׳</span> Nergal has the meaning of <i>luck</i> in the sense in which the Scripture speaks of the luck of Jacob (<span class=\"citation\">Gen. XXX, 27</span> <span dir=\"rtl\">בגללך</span>, for which <span dir=\"rtl\">לרגלו</span> in verse 30) and the luck of Joseph (ib. XXXIX, 5 <span dir=\"rtl\">בגלל</span>), v. <a href=\"#\" data-headword=\"רֶגֶל ²\">רִגְלָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>N.</i> <i> Sarezzar</i>, one of the princes of Nebuchadnezzar. Targ. II Esth. I, 2 (3).</div>","alt":[]},"20351":{"h":"נִרְגָּל","r":"N01263","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָגַל\">רָגַל</a></div>","alt":[]},"20352":{"h":"נִרְגָּן","r":"N01264","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָגַן\">רָגַן</a></div>","alt":[]},"20353":{"h":"נֵרְדְּ","r":"N01265","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>Nard</i>, an aromatic herb, <i>Valerian</i>. <span class=\"citation\">Ker. 6ᵃ</span>; <span class=\"citation\">Y. Yoma IV, 41ᵈ</span>, v. <a href=\"#\" data-headword=\"שִׁיבּוֹלֶת\">שִׁיבּוֹלֶת</a>.—<span class=\"citation\">B. Mets. 86ᵃ</span> bot. <span dir=\"rtl\">ככרין דנ׳ וכ׳</span> talents’ worth of N. [<span class=\"citation\">Cant. R. to I, 12</span> <span dir=\"rtl\">נרדי</span>, expl. by R. M. <a href=\"#\" data-headword=\"סִירְיִי\">סיריי</a> my ill odor, v. next w.]</div>","alt":[]},"20354":{"h":"נִרְדָּא","r":"N01266","html":"<div class=\"sense\"> believed to smell badly. <span class=\"citation\">Targ. Cant. I, 12</span> (ed. Lag. a. oth. <a href=\"#\" data-headword=\"נידא\">נידא</a>, corr. acc.).</div>","alt":["נִי׳"]},"20355":{"h":"נַרְדִּינוֹן","r":"N01267","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (νάρδινον, sub. μῦρον) <i>nard-oil</i>. <span class=\"citation\">Cant. R. to IV, 14</span> (expl. <a href=\"#\" data-headword=\"נֵרְדְּ\">נֵרְדְּ</a> ib.).</div>","alt":[]},"20356":{"h":"נַרְדְּשִׁיר","r":"N01268","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. a. Arab. <i>nard</i>, also <i>nardshir</i>) <i>Nardshir</i>, name of a game, <i>checkers</i>. <span class=\"citation\">Keth. 61ᵇ</span> Ar. (ed. <span dir=\"rtl\">נדר׳</span>).</div><div class=\"sense\"><b>. נ</b> <div class=\"sense\"><span dir=\"rtl\">רווד</span>, <span class=\"citation\">Neg. VII, 4</span> Ar. (ed. <span dir=\"rtl\">גדווד</span>, ed. Dehr. <a href=\"#\" data-headword=\"נדוד\">נדוד</a>) pr. n. pl., prob. a corrupt fragment of <span dir=\"rtl\">בְּרוּנְדִּיסִין</span> <i>Brundisium</i>, v. <a href=\"#\" data-headword=\"בַּלְדַּרְסִין\">בלדרסין</a>.—[Ohol. VI, 1 Ar., v. <a href=\"#\" data-headword=\"נִדְבָּךְ\">נִדְבָּךְ</a>.]</div></div>","alt":[]},"20357":{"h":"נָרוּס","r":"N01269","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (naurûz, Koh. Ar. Compl. s. v.) <i>narus</i>, the Persian and Median <i>New-Year’s Festival</i>, at the vernal equinox. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span></div>","alt":[]},"20358":{"h":"נָרוֹק","r":"N01270","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָקַק\">רָקַק</a></div>","alt":[]},"20359":{"h":"נרמקי","r":"N01271","html":"<div class=\"sense\">, <span class=\"citation\">Yeb. 102ᵇ</span> top <span dir=\"rtl\">זוגי נ׳</span> Ar., misreading of <span dir=\"rtl\">דמוֹקֵי</span> (ed. <span dir=\"rtl\">זוזי מוקי</span>).</div>","alt":[]},"20360":{"h":"נרקום","r":"N01272","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַרְקֵיס\">next w.</a></div>","alt":["נרקוס"]},"20361":{"h":"נַרְקֵיס","r":"N01273","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (νάρκισσος) <i>narcissus</i>, prob. <i>White Daffodil</i>. <span class=\"citation\">Targ. Cant. II, 1</span> (some ed. <a href=\"#\" data-headword=\"ברקום\">ברקום</a>, corr. acc.).—<span class=\"citation\">Ber. 43ᵇ</span> נרקס דגנוניתא Ar. (ed. <a href=\"#\" data-headword=\"נרקום\">נרקום</a>; Ms. M. <span dir=\"rtl\">נרכום</span>) garden narcissus, <span dir=\"rtl\">דדברא</span> wild n.</div>","alt":["נַרְקֵס"]},"20362":{"h":"נָרָשׁ","r":"N01274","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Narash</i> (<i>Ners</i>), <i>Narse</i> in Babylonia. <span class=\"citation\">B. Mets. 93ᵇ</span> <span dir=\"rtl\">גמלא דנ׳</span> the crossing of N. (v. <a href=\"#\" data-headword=\"גַּמְלָא I\">גַּמְלָא</a>). <span class=\"citation\">Nidd. 67ᵇ</span>. <span class=\"citation\">Erub. 56ᵃ</span>; <span class=\"citation\">Ḥull. 127ᵃ</span>, v. <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a>. <span class=\"citation\">Yoma 81ᵇ</span> בירי דנ׳ Beray near N.; a. e. (v. Berl. Beitr. z. Geogr., p. 54).—<span class=\"citation\">B. Kam. 115ᵃ</span> bot. <span dir=\"rtl\">נַרְשָׁא</span>.</div>","alt":[]},"20363":{"h":"נַרְשָׁאָה","r":"N01275","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָרָשׁ\">preced.</a>) <i>of Narash</i>. <span class=\"citation\">Ḥull. 127ᵃ</span> <span dir=\"rtl\">נ׳ נשקיך וכ׳</span> if a Narashean kissed thee, count thy teeth. <span class=\"citation\">B. Kam. 115ᵃ</span> <span dir=\"rtl\">נ׳ גנב וכ׳</span> a Narashean stole &amp;c. <span class=\"citation\">Sabb. 60ᵃ</span>; <span class=\"citation\">140ᵃ</span> אדא נ׳ Ada of N.; a. e.—Pl. <span dir=\"rtl\">נַרְשָׁאֵי</span>. <span class=\"citation\">B. Mets. 68ᵃ</span> חכירי נ׳ Narashean tenancies, i.e. the owner gives a field in pledge for a debt and takes it back in tenancy, v. <a href=\"#\" data-headword=\"מַשְׁכֵּן\">מַשְׁכֵּן</a>.</div>","alt":[]},"20364":{"h":"נַרְתֵּיק","r":"N01276","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (νάρθηξ) [<i>narthex</i>, a small umbelliferous plant with a hollow pithy stalk, which may be used as a receptacle; in gen.] <i>case, casket</i>. <span class=\"citation\">Y. Ber. V, 9ᵇ</span> top <span dir=\"rtl\">נַרְתֵּיקוֹ של רופא</span> a physician’s medicine chest. <span class=\"citation\">Y. R. Hash. I, 57ᵇ</span>. [<span class=\"citation\">Lam. R. to I, 9</span> נוורתוק Vers. in Ar. (corr. acc.), v. <a href=\"#\" data-headword=\"*לַבְרָטוֹן\">לַבְרָטוֹן</a>.]—<span class=\"citation\">Y. Erub. I, 19ᵇ</span> bot. <span dir=\"rtl\">(<span dir=\"rtl\">של קרן</span>) <span dir=\"rtl\">נרתיקו</span></span> the pithy hollow part of the horn, opp. <a href=\"#\" data-headword=\"זַכְרוּת\">זַכְרוּת</a>. <span class=\"citation\">Gen. R. s. 6</span> <span dir=\"rtl\">גלגל חמה יש לו נ׳</span> the globe of the sun has a sheath; <span class=\"citation\">ib.</span> <span dir=\"rtl\">הקב&quot;ה מערטלו מנרתיקו</span> (Ar. <span dir=\"rtl\">מנושתקו</span>) the Lord will denude it of its sheath; <span class=\"citation\">Koh. R. to I, 5</span> (v. <a href=\"#\" data-headword=\"נַשְׁתֵּק\">נַשְׁתֵּק</a>); <span class=\"citation\">Ab. Zar. 3ᵇ</span> bot., a. e.—[<span class=\"citation\">Y. Yoma IV, 41ᵈ</span> top, v. <a href=\"#\" data-headword=\"נַשְׁתֵּק\">נַשְׁתֵּק</a>.]</div>","alt":["נַרְתֵּק"]},"20365":{"h":"נַרְתֵּיקָא","r":"N01277","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ruth IV, 7</span> sq. <span dir=\"rtl\">נרתק יד</span> <i>sleeve</i> (h. text <span dir=\"rtl\">נעל</span>).—Pl. <span dir=\"rtl\">נַרְתֵּיקִין</span>. <span class=\"citation\">Targ. Y. I Deut. XXV, 13</span> (weight-chests).</div>","alt":["נַרְתֵּקָא"]},"20366":{"h":"נרתיקות","r":"N01278","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to IV, 4</span> <a href=\"#\" data-headword=\"נ׳\">נ׳</a>, read: <span dir=\"rtl\">נִרְתָּקוֹת</span>, v. <a href=\"#\" data-headword=\"רָתַק\">רָתַק</a></div>","alt":[]},"20367":{"h":"נַרְתֵּק","r":"N01279","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַרְתֵּיק\">נַרְתֵּיק</a>, <a href=\"#\" data-headword=\"נַרְתֵּיקָא\"><a href=\"#\" data-headword=\"נַרְתֵּיקָא\">נַרְתֵּיקָא</a>.</a></div>","alt":["נַרְתֵּקָא"]},"20368":{"h":"נָשׁ","r":"N01280","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"אֱינָשׁ\">אִינָשׁ</a>, only in <a href=\"#\" data-headword=\"נָטוֹזָא\">בַּר נ׳</a> <i>son of man, human being</i>. <span class=\"citation\">Targ. Job VII, 1</span>; <span class=\"citation\">20</span>; a. fr.—<span class=\"citation\">Y. Dem. I, 22ᵃ</span> top; a. v. fr.—Pl. <a href=\"#\" data-headword=\"נשי\">נָשָׁא</a>, <span dir=\"rtl\">בְּנֵי נָשׁ</span>, also <span dir=\"rtl\">בְּנֵי נָשֵׁי</span>. <span class=\"citation\">Targ. Ps. LXII, 10</span>; a. fr.—<span class=\"citation\">Gen. R. s. 60</span>. <span class=\"citation\">Y. Shek. V, end, 49ᵇ</span>; a. fr.</div>","alt":["נָשָׁא I"]},"20369":{"h":"נְשָׁא I","r":"N01281","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָשׁ\">preced.</a>) <i>woman</i>. <span class=\"citation\">Targ. Y. Deut. XXII, 5</span>.—Pl. <span dir=\"rtl\">נְשִׁין</span>, <a href=\"#\" data-headword=\"נְשַׁיָּיא\">נְשַׁיָּא</a>, <a href=\"#\" data-headword=\"נְשֵׁי\">נְשֵׁי</a>. <span class=\"citation\">Targ. Ruth I, 4</span>. <span class=\"citation\">Targ. Gen. VI, 2</span>; a. fr.—<span class=\"citation\">Tam. 32ᵃ</span> <span dir=\"rtl\">מחוזא דכוליה נ׳</span> a place inhabited by women only. <span class=\"citation\">Ber. 17ᵃ</span> הני נשי מאי זכיין Ms. M. (ed. <span dir=\"rtl\">נשים</span>) whereby can women acquire merits? <span class=\"citation\">M. Kat. 28ᵇ</span> <span dir=\"rtl\">נ׳ דשכנציב</span> the lamenting women of &amp;c.; a. v. fr.—<a href=\"#\" data-headword=\"נִמְרָה\">בֵּי נ׳</a> a) <i>the wife’s family, father-in-law</i> &amp;c.—b) <i>the paternal house after the father’s death</i>. <span class=\"citation\">B. Bath. 12ᵇ</span> <span dir=\"rtl\">אמצרא דבי נְשֵׁיה</span> contiguous to the estate of his father-in-law (Rashi: of his deceased father). <span class=\"citation\">Sabb. 23ᵇ</span>. <span class=\"citation\">Ib. 156ᵃ</span> <span dir=\"rtl\">בי נשיה</span> in the house of his deceased father (Ms. M. <a href=\"#\" data-headword=\"נְשִׂיאָה I\">נשיאה</a>, v. <a href=\"#\" data-headword=\"גַּבָּלָא\">גַּבָּלָא</a>). <span class=\"citation\">Yeb. 35ᵃ</span> <span dir=\"rtl\">בי נְשַׁיְהוּ</span> their (the women’s) paternal home; a. e.</div>","alt":[]},"20370":{"h":"נָשָׁא II","r":"N01282","html":"<div class=\"sense\"><i>to forget</i>, v. <a href=\"#\" data-headword=\"נשי\">נשי</a>.</div>","alt":["נְשָׁא II"]},"20371":{"h":"נָשָׁא III","r":"N01283","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> name of a <i>plant</i> the sap of which is used as a depilatory. <span class=\"citation\">B. Kam. 86ᵃ</span> <span dir=\"rtl\">סָכוֹ נ׳ וכ׳</span> he smeared <i>nasha</i> over it so that the hair will not grow again. <span class=\"citation\">Macc. 20ᵇ</span>. <span class=\"citation\">Naz. 40ᵃ</span>.—V. <a href=\"#\" data-headword=\"נֶשֶׁם\">נֶשֶׁם</a>.</div>","alt":[]},"20372":{"h":"נָשָׂא","r":"N01284","html":"<div class=\"sense\"><b>1)</b> <i>to lift up, carry</i>. <span class=\"citation\">Sot. 35ᵃ</span> <span dir=\"rtl\">נ׳ ארון את נוֹשְׂאָיו</span> the Ark carried its carriers. <span class=\"citation\">Ab. ch. VI</span> <span dir=\"rtl\">נוֹשֵׂא בעול וכ׳</span> helps his brother to bear his yoke. <span class=\"citation\">Ber. III, 1</span> <span dir=\"rtl\">נוֹשְׂאֵי המטה</span>, v. <a href=\"#\" data-headword=\"מִטָּה\">מִטָּה</a>. <span class=\"citation\">Meg. 9ᵃ</span> (one of the changes in translating the Bible into Greek) <span dir=\"rtl\">נוֹשֵׂא בני אדם</span> a carrier of men (for <a href=\"#\" data-headword=\"חֲמוֹר\">חֲמֹר</a>, <span class=\"citation\">Ex. IV, 20</span>); a. v. fr.—<span class=\"citation\">Pesik. R. s. 6</span> אני מרומם ונושא את ראשם I will raise and elevate their head; v. infra.—<span dir=\"rtl\">נ׳ כפים</span>, v. <a href=\"#\" data-headword=\"כַּף\">כַּף</a>.—נ׳ פנים <i>to lift up the face, to respect, favor, spare, be partial</i>. <span class=\"citation\">Ḥag. 14ᵃ</span> (expl. <span dir=\"rtl\">נשוא פנים</span>, <span class=\"citation\">Is. III, 3</span>) <span dir=\"rtl\">זה שנוֹשְׂאִין פ׳ לדורו בעבורו</span> he for whose sake his generation is favored in heaven. <span class=\"citation\">Sabb. 13ᵇ</span> <span dir=\"rtl\">שלא נ׳ פ׳ לתורה</span> who spared him not for the sake of his scholarship. <span class=\"citation\">Yoma 87ᵃ</span> <span dir=\"rtl\">שנָשְׂאוּ לו פ׳ בעה&quot;ז</span> that indulgence was shown him (by the Lord) in this world. <span class=\"citation\">Num. R. s. 11</span> <span dir=\"rtl\">לא אֶשָּׂא פ׳ מפניך</span> shall I not favor thee for thy own sake? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כשם שהם נוֹשְׂאִין לי וכ׳</span> as they (the Israelites) honor me (by saying grace even after a scanty meal), so do I favor them; a. fr.—נ׳ נפש אל <i>to lift up the soul to, to long for</i>. <span class=\"citation\">Midr. Till. to Ps. XXV, 1</span> <span dir=\"rtl\">למה אתה נושא נפשך אלי</span> why dost thou lift up thy soul to me (why dost thou depend on me)?; <span class=\"citation\">Yalk. ib. 701</span>.—נ׳ קרבן <i>to offer up a sacrifice</i>. <span class=\"citation\">Ib. 702</span> <span dir=\"rtl\">אדם חוטא ונושא ק׳</span> if a man sinned, he offered &amp;c.; Midr. Till. l. c. <span dir=\"rtl\">נושא ומביא ק׳</span> (corr. acc.)—Part. pass. <a href=\"#\" data-headword=\"*נָשׂוּא\">נָשׂוּא</a>, f. <span dir=\"rtl\">נְשׂוּאָה</span> &amp;c. Ib. <span dir=\"rtl\">עכשו … הרי נפשנו נ׳ לך</span> now that we have no sacrifices, our soul is lifted up to thee.</div><div class=\"sense\"><b>—2)</b> <i>to lift, remove</i>. Pesik. R. l. c. (ref. to the double meaning of <a href=\"#\" data-headword=\"נ׳\">נ׳</a>, <i>to raise</i> a. <i>to remove</i>) <span dir=\"rtl\">לכו שְׂאוּ את ראשו</span> go and remove (or lift up) his head; a. fr.—נ׳ עון <i>to forgive</i>. <span class=\"citation\">Y. Snh. X, beg., 27ᶜ</span> (ref. to <span class=\"citation\">Ex. XXXIV, 7</span>) <span dir=\"rtl\">נושא עוונות אין וכ׳</span> the text does not say, ‘removing iniquities’, but ‘removing iniquity’, the Lord takes away (from the scales) one bond of man’s sins, and the merits prevail &amp;c.; <span class=\"citation\">Y. Peah I, 16ᵇ</span> bot. (corr. acc.); <span class=\"citation\">Yalk. Ex. 400</span>; v. <a href=\"#\" data-headword=\"שְׁטַר\">שְׁטַר</a>. <span class=\"citation\">Pesik. R. s. 45</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to take</i>, esp. <span dir=\"rtl\">נ׳ ונתן</span> <i>to take and give, to deal; to transact, argue</i>. <span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">נָשָׂאתָ ונתת באמונה</span> hast thou (while on earth) been dealing honestly? <span class=\"citation\">B. Mets. 48ᵃ</span> <span dir=\"rtl\">הנושא ונותן בדברים</span> he who concludes a bargain verbally. Tanḥ. Sh’moth 18 <span dir=\"rtl\">כשם שנושאין ונותנין בהלכה וכ׳</span> as well as they debate on the law below, so do they above. Ib. <span dir=\"rtl\">שנושאין ונותנין בדין וכ׳</span> they argue in court, and the Lord argues with them; a. fr.</div><div class=\"sense\"><b>—4)</b>  <span dir=\"rtl\">נ׳ אשה</span>, or <a href=\"#\" data-headword=\"נ׳\">נ׳</a> <i>to take a wife into one’s house, to marry</i>. <span class=\"citation\">Keth. II, 1</span> <span dir=\"rtl\">בתולה נְשָׂאתַנִי</span> thou hast married me as a virgin; <span dir=\"rtl\">אלמנה נְשָׂאתִיךְ</span> I married thee as a widow. <span class=\"citation\">Yeb. 37ᵇ</span> <span dir=\"rtl\">לא יִשָּׂא אדם וכ׳</span> one may not marry in one country and go away &amp;c. <span class=\"citation\">M. Kat. I, 7</span> <span dir=\"rtl\">אין נושאין נשים וכ׳</span> no marriages may take place during the festive week; a. v. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"*נָשׂוּא\">נָשׂוּי</a> (followed by accus.) <i>having married</i>; f. <span dir=\"rtl\">נְשׂוּאָה</span> (followed by <a href=\"#\" data-headword=\"ל\">ל</a>) <i>being married to; </i> pl. <span dir=\"rtl\">נְשׂוּאִים</span>, … <a href=\"#\" data-headword=\"אִין I\">אִין</a>; <span dir=\"rtl\">נְשׂוּאוֹת</span>. <span class=\"citation\">Yeb. III, 6</span> <span dir=\"rtl\">ואחד נ׳ נכרית</span> one of them has married a stranger. Ib. <span dir=\"rtl\">ומתו הנ׳ את האחיות</span> and those brothers who had married two sisters died. Ib. I, 2 (2ᵇ) <span dir=\"rtl\">היתה … נשואה לאחיו</span> Y. ed. (Mish. ed. <span dir=\"rtl\">נשואת</span>, corr. acc.; Bab. ed. <span dir=\"rtl\">נשואות</span>) if his daughter or … was married to &amp;c.; a. fr.—Tosef. ib. VI, 5 <span dir=\"rtl\">נָשׂאוּי</span>.</div><div class=\"sense\"><b>Nif. נִישָּׂא</b> <div class=\"sense\"><b>1)</b> <i>to be lifted up, removed</i> &amp;c. Pesik. R. l. c. <span dir=\"rtl\">כבר … שיִנָּשְׂאוּ את ראשם וכ׳</span> it had been decreed that their head should be lifted (v. supra): turn its meaning and elevate their head.</div><div class=\"sense\"><b>—2)</b>  f. <span dir=\"rtl\">נִישֵּׂאת</span>, <a href=\"#\" data-headword=\"נִישּׂוּאִין\">נִשֵּׂ׳</a>, <span dir=\"rtl\">נִישֵּׂת</span>, <a href=\"#\" data-headword=\"*יָסַת\">נִיסֵּת</a> <i>to be married</i>. <span class=\"citation\">Keth. I, 1</span> <span dir=\"rtl\">בתולה נ׳ וכ׳</span> a virgin’s marriage takes place on the fourth day of the week. <span class=\"citation\">Ib. V, 2</span> <span dir=\"rtl\">הגיע … ולא נִשְּׂאוּ</span> if the time set for marriage expired and they were not taken in marriage. <span class=\"citation\">Yeb. II, 10</span> <span dir=\"rtl\">מותרות לִינָּשֵׂא להם</span> they may marry them. <span class=\"citation\">Ib. 88ᵇ</span> <span dir=\"rtl\">הרי זו לא תִנָּשֵׂא ואם ניסת וכ׳</span> she must not marry again, and if she does &amp;c.; <span class=\"citation\">Keth. 22ᵇ</span>; a. v. fr.</div></div><div class=\"sense\"><b>Hif. הִשִּׂיא</b> <div class=\"sense\"><b>1)</b> <i>to lift up, to announce by signals</i> (the New Moon). <span class=\"citation\">R. Hash. II, 2</span>, a. e. <span dir=\"rtl\">מַשִּׂיאִין</span>, v. <a href=\"#\" data-headword=\"מַשּׂוּאָה\">מַשּׂוּאָה</a>. Y. ib. II, 58ᵃ top <span dir=\"rtl\">אין משיאין לילי זמנו</span> we do not raise signals in the night of the regular New Moon (from the 29<sup>ᵗʰ</sup> to the 30<sup>ᵗʰ</sup>) &amp;c.; a. fr.—Tosef. ib. II (I), 2 <span dir=\"rtl\">מַסִּיעִין את החדש</span> ed. Zuck. (<span dir=\"rtl\">משיא׳ על</span>, <span dir=\"rtl\">מסיא׳</span>) we signalize the New Moon.</div><div class=\"sense\"><b>—2)</b> <i>to transfer</i>. <span class=\"citation\">Deut. R. s. 11</span> (ref. to <span dir=\"rtl\">ישא</span>, Ps. IXXV, 5) <span dir=\"rtl\">יַשִּׂיא ברכה לאחרים</span> he will bring blessing upon others.</div><div class=\"sense\"><b>—3)</b> <i>to move, remove, pass</i>. <span class=\"citation\">Bets. III, 7</span> <span dir=\"rtl\">מַשִּׂיאָהּ על גבי חברתה</span> he may pass one knife over the other (to whet it). <span class=\"citation\">Tosef. Par. X</span> (<span class=\"citation\">IX), 3</span> <span dir=\"rtl\">הִשִּׂיאוֹ לדבר אחר</span> he diverted his mind towards another subject; <span class=\"citation\">Ab. Zar. II, 5</span>. Y. ib. II, 41ᶜ bot. <span dir=\"rtl\">היה לו להַשִּׂיאוֹ וכ׳</span>, v. <a href=\"#\" data-headword=\"הֶשֵּׂיאָה\">הֶשֵּׂיאָה</a>.</div><div class=\"sense\"><b>—4)</b> <i>to transfer, transcribe, translate</i>. <span class=\"citation\">Tosef. Sot. VIII, 6</span> <span dir=\"rtl\">הִשִּׂיאוּ את הכתב וכ׳</span> they transcribed the inscription on the stones in seventy languages; <span class=\"citation\">Sot. 35ᵇ</span>; Y. ib. VII, 21ᵈ bot.</div><div class=\"sense\"><b>—5)</b> <i>to give away in marriage; to cause to marry</i>. <span class=\"citation\">Keth. 111ᵇ</span> <span dir=\"rtl\">כל המַשִּׂיא בתו וכ׳</span> he who marries his daughter to a scholar. <span class=\"citation\">Ib. 67ᵇ</span> top <span dir=\"rtl\">מַשִּׂיאִין את היתומה וכ׳</span> we must first help the fatherless maiden to marry, and then the fatherless lad. <span class=\"citation\">Kidd. 29ᵃ</span> <span dir=\"rtl\">האב חייב … ולהַשִּׂיאוֹ אשה</span> a father is bound to …, and to provide a wife for him; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְנַשֵּׂא</b> <div class=\"sense\"><i>to be raised; to exalt one’s self, to boast</i>. <span class=\"citation\">Ab. Zar. 44ᵃ</span>, v. <a href=\"#\" data-headword=\"הָלַם\">הָלַם</a>. <span class=\"citation\">Ber. 63ᵇ</span> <span dir=\"rtl\">להִתְנַשֵּׂא</span>, v. <a href=\"#\" data-headword=\"נָבָל I\">נָבַל</a>; a. e.</div></div>","alt":[]},"20373":{"h":"נְשָׂא","r":"N01285","html":"<div class=\"sense\"><b>1)</b> <i>to lift up</i>, v. <a href=\"#\" data-headword=\"נְסֵי\">נְסֵי</a>.</div><div class=\"sense\"><b>—2)</b> <i>to bring, offer</i>. Pesik. B’shall., p. 90ᵇ, sq. <span dir=\"rtl\">אימיה נשא</span> (Ms. O. <span dir=\"rtl\">נַשְׂאָה</span>) his mother was bringing (the bread); v., however, <a href=\"#\" data-headword=\"נְסַח\">נְסַח</a>.</div><div class=\"sense\"><b>—3)</b>  (neut. verb) <i>to move, stir</i>. <span class=\"citation\">Taan. 24ᵃ</span>; <span class=\"citation\">B. Mets. 85ᵇ</span>, v. <a href=\"#\" data-headword=\"נְשַׁב\">נְשַׁב</a>.</div>","alt":[]},"20374":{"h":"נָשַׁב","r":"N01286","html":"<div class=\"sense\"> (b. h.) <i>to blow</i>. <span class=\"citation\">Ber. 3ᵇ</span> <span dir=\"rtl\">בא … ונוֹשֶׁבֶת בו</span> (Ms. M. <span dir=\"rtl\">ומְנַשֶּׁבֶת</span> <i>Pi.</i>) the north wind came and blew at him. <span class=\"citation\">Ab. III, 17</span> <span dir=\"rtl\">אפילו … ונוֹשְׁבוֹת בו</span> even if all the winds of the world came and blew at it (to uproot it) &amp;c.; <span class=\"citation\">Taan. 20ᵃ</span>; a. fr.</div><div class=\"sense\"><b>Pi. נִשֵּׁב</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נְשָׂא\">same</a>. <span class=\"citation\">Cant. R. to IV, 16</span>. <span class=\"citation\">Yoma 21ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to cause to blow</i>. <span class=\"citation\">Keth. 111ᵇ</span> <span dir=\"rtl\">הקב&quot;ה … ומְנַשְּׁבָהּ עליה</span> the Lord brings a wind … and lets it pass over it (the wheat).</div></div><div class=\"sense\"><b>Hif. הִשִּׁיב</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נְשָׂא\">same</a>. <span dir=\"rtl\">מַשִּׁיב הרוח ומוריד הגשם</span> ‘who causes the wind to blow and the rain to descend’, a clause inserted in <i>G’buroth</i> (v. <span dir=\"rtl\">גְּבוּרוֹת</span>) during the winter season. <span class=\"citation\">Taan. 3ᵇ</span> <span dir=\"rtl\">אמר משיב הרוח אין וכ׳</span> if he said in his prayers, ‘Who causes the wind to blow’ only. <span class=\"citation\">Ib. 24ᵃ</span> <span dir=\"rtl\">אמר מ׳ הרוח וכ׳</span> as soon as he said, ‘Who causes &amp;c.’, a wind arose; a. e.</div></div>","alt":[]},"20375":{"h":"נְשַׁב","r":"N01287","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XL, 7</span>; a. e.—<span class=\"citation\">Taan. 24ᵃ</span>, sq. <span dir=\"rtl\">ונ׳ זיקא</span> (ed. once <span dir=\"rtl\">ונשא</span>, v. <a href=\"#\" data-headword=\"נְשָׂא\">נְשָׂא</a>), v. <a href=\"#\" data-headword=\"נָשַׁב\">preced.</a>; <span class=\"citation\">B. Mets. 85ᵇ</span> <span dir=\"rtl\">ונַשְׁבָהזיקא</span> (Ms. M. <span dir=\"rtl\">נשא</span>; Ms. R. <a href=\"#\" data-headword=\"נַשְׁיָא\">נַשְׂיָא</a>; v. Rabb. D. S. a. l. note).</div>","alt":[]},"20376":{"h":"נִשְׁבָּא","r":"N01288","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. Prov. VI, 5</span> (some ed. <span dir=\"rtl\">נשכא</span>, corr. acc.). <span class=\"citation\">Ib. XXII, 5</span> (some ed. <i>pl.</i>).—<i>Pl.</i> <span dir=\"rtl\">נִשְׁבֵּי</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">B. Mets. 85ᵇ</span> גדילנא ני׳ וכ׳ I plaited nets and caught deer; <span class=\"citation\">Keth. 103ᵇ</span></div>","alt":["נִי׳"]},"20377":{"h":"נִשְׁבִּים","r":"N01289","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">נשב</span>; cmp. <a href=\"#\" data-headword=\"פַּח I\">פַּח</a>) <i>trap, snare, net</i>. <span class=\"citation\">Y. Sabb. XIII, 14ᵃ</span> bot.; <span class=\"citation\">Y. Bets. III, 62ᵃ</span> top <span dir=\"rtl\">מחוסר נ׳</span> that which must be caught by snares to be available. <span class=\"citation\">Sabb. 90ᵇ</span> <span dir=\"rtl\">מצניעין אותן לנ׳</span> they (the horse’s hairs) are laid aside to be used for bird snares. <span class=\"citation\">B. Kam. VII, 7</span> (<span class=\"citation\">79ᵇ</span>) <span dir=\"rtl\">אין פורסין נשבים וכ׳</span> (Talm. ed. <a href=\"#\" data-headword=\"נישובים\">נישובים</a>; Ms. M. <a href=\"#\" data-headword=\"נִשְׁבִּים\">נשבין</a>; Rashi to <span class=\"citation\">Ḥull. 116ᵃ</span> quotes <a href=\"#\" data-headword=\"רִישְׁבָּא\">רישבין</a></div>","alt":["נִשְׁבִּין","נִי׳"]},"20378":{"h":"נִשְׁדּוּר","r":"N01290","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִישְׁדּוּר\">נִישְׁדּוּר</a></div>","alt":[]},"20379":{"h":"נָשָׁה","r":"N01291","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נשי\">נשי</a></div>","alt":[]},"20380":{"h":"נָשֶׁה","r":"N01292","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נָשָׁה\">preced.</a>) <i>movable</i>; <span dir=\"rtl\">גִּיד הַנָּ׳</span>, v. <a href=\"#\" data-headword=\"גִּיד\">גִּיד</a>.</div>","alt":[]},"20381":{"h":"*נָשׂוּא","r":"N01293","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>) <i>burden</i>, <i>affairs</i> (v. <a href=\"#\" data-headword=\"מַשּׂוֹא\">מַשּׂוֹא</a>). <span class=\"citation\">Num. R. s. 3</span> <span dir=\"rtl\">נשא נְשׂוּאָן של וכ׳</span> (some ed. <a href=\"#\" data-headword=\"נִשּׂוּאִין\">נְשׂוּאִין</a>, pl.) he administered the affairs of Israel.—V. <a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a></div>","alt":[]},"20382":{"h":"נִשּׂוּאִין","r":"N01294","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִישּׂוּאִין\">נִישּׂוּאִין</a></div>","alt":[]},"20383":{"h":"נִשְׁוָאר","r":"N01295","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*נתזואי\">נתזואי</a></div>","alt":[]},"20384":{"h":"נִשְׁוָורָא","r":"N01296","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (collect. noun; <a href=\"#\" data-headword=\"שְׁאַר I\">שאר</a>, <i>Pa</i>. <a href=\"#\" data-headword=\"שְׁאַר I\">שַׁיֵּיר</a>) <i>crumbs, leavings</i>. <span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">נ׳ בביתא וכ׳</span> to leave crumbs lie around in the house, is bad for poverty. <span class=\"citation\">Ḥull. 105ᵇ</span> (not … <a href=\"#\" data-headword=\"ראי\">ראה</a>).</div>","alt":[]},"20385":{"h":"נשוותא","r":"N01297","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְשִׂיאוּתָא\">נְשִׂיאוּתָא</a></div>","alt":[]},"20386":{"h":"נִשּׁוֹפוֹת","r":"N01298","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִישּׁוֹבֶת\">נִישּׁוֹבֶת</a></div>","alt":[]},"20387":{"h":"נְשַׁט","r":"N01299","html":"<div class=\"sense\"> (v. P. Sm. 2475) <i>to flay</i>, v. <a href=\"#\" data-headword=\"נָטַשׁ I\">נְטשׁ</a>.</div>","alt":[]},"20388":{"h":"נשי","r":"N01300","html":"<div class=\"sense\"><b>1)</b> <i>to move, slip</i>. <span class=\"citation\">Ḥull. 91ᵃ</span> it is called <i>gid hannasheh</i> (v. <a href=\"#\" data-headword=\"גִּיד\">גִּיד</a>), <span dir=\"rtl\">שנ׳ ממקזמו וכ׳</span> because it slipped from its place and went up; <span class=\"citation\">Yalk. Gen. 133</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">א&quot;ר חנניא … שנשא את מקומו</span> R. Ḥ. said, … because it left its place; <span class=\"citation\">Gen. R. s. 78</span> <span dir=\"rtl\">שנשה ממקומו</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to discard, forget</i>. <span class=\"citation\">Ned. 50ᵇ</span> <span dir=\"rtl\">אבותינו אמרו נָשִׁינוּ טובה וכ׳</span> our fathers said (<span class=\"citation\">Lam. III, 17</span>), we have forgotten the good times: we have not even seen them &amp;c. <span class=\"citation\">Snh. 102ᵇ</span> (play on <span dir=\"rtl\">מנ̇ש̇ה̇</span>) <span dir=\"rtl\">שנ̇ש̇ה יה̇</span> he forgot Yah. <span class=\"citation\">Pesik. R. s. 45</span> (ref. to <span dir=\"rtl\">נְשׂוּי</span>, <span class=\"citation\">Ps. XXXII, 1</span>) <span dir=\"rtl\">אל תהי … ש&quot;ין נְשׁוּי</span> read it not with Samekh (<i>n’suy</i>), but with Shin, <i>n’shuy</i>, whose sin is forgotten; a. e.</div><div class=\"sense\"><b>—3)</b>  (with <a href=\"#\" data-headword=\"ב\">ב</a>, cmp. <a href=\"#\" data-headword=\"נְסַק\">נְסַק</a> <i>Af</i>.) [<i>to raise, collect</i>,] <i>to have a claim against; to be a creditor of</i>. <span class=\"citation\">B. Mets. 75ᵇ</span> <span dir=\"rtl\">נוֹשֶׁה בחבירו מנה</span> he who has a claim &amp;c., to whom his neighbor owes money. <span class=\"citation\">Men. 85ᵇ</span> נושה בי וכ׳ I owe him &amp;c.; a. e.</div><div class=\"sense\"><b>Hif. הִשִּׁיא</b> <div class=\"sense\"><b>1)</b> <i>to carry away; to incite, allure</i>. <span class=\"citation\">Gen. R. s. 19</span> (expl. <span dir=\"rtl\">השיאני</span>, <span class=\"citation\">Gen. III, 13</span>) <span dir=\"rtl\">הטעני</span> he led me astray; v. <a href=\"#\" data-headword=\"גָּרָה\">גָּרָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>to make a loan to; to collect, distrain; to pledge</i>. Ib. (expl. <span dir=\"rtl\">השיאני</span>) <span dir=\"rtl\">חייבני</span> he made me a debtor (guilty, v. <a href=\"#\" data-headword=\"חוּב\">חוּב</a>). <span class=\"citation\">Cant. R. to II, 7</span> (ref. to <a href=\"#\" data-headword=\"אֶשָּׁא\">אֶשָּׂא</a>, <span class=\"citation\">Ps. XXV, 1</span>) <span dir=\"rtl\">אַשִּׁיא כתיב</span> it may be read <i>ashshi</i>, I pledge (my soul); <span dir=\"rtl\">שהיו מַשִּׁיאִין נפשם על וכ׳</span> they (the martyrs) pledged their lives for the sanctification &amp;c. (v. <span class=\"citation\">Midr. Till. to Ps. XXV</span> <span dir=\"rtl\">שנתמשכנו וכ</span>); ib. <span dir=\"rtl\">משיאין … מהם</span> they (the torturers) take their lives as pledges; <span class=\"citation\">Midr. Till. to Ps. XVI</span>; <span class=\"citation\">Yalk. Ps. 667</span> <span dir=\"rtl\">משיחין</span> (corr. acc.).</div><div class=\"sense\"><b>—3)</b>  הִנְשִׁי <i>to cause to forget</i>. Snh. l. c. (play on <span dir=\"rtl\">מנ̇ש̇ה</span>) <span dir=\"rtl\">שהנ̇ש̇י את ישראל לאביהם וכ׳</span> he made Israel forget their Father in heaven; <span class=\"citation\">Yalk. Kings 245</span> <span dir=\"rtl\">שהִנְשִׁיא</span>.</div></div>","alt":["נָשָׁה","נָשָׁא"]},"20389":{"h":"נְשֵׁי","r":"N01301","html":"<div class=\"sense\">, <i>to forget</i>. <span class=\"citation\">Targ. Deut. VIII, 19</span> (O. ed. Berl. <i>Ithpe.</i>).</div><div class=\"sense\"><b>Af. אַנְשִׁי</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נשי\">same</a>. <span class=\"citation\">Targ. Ps. CXXXVII, 5</span>; a. e.—Y. Dem. IV, 24ᵃ [read:] <span dir=\"rtl\">דילמא אַנְשִׁיתָה מתקנה</span> perhaps thou didst forget to prepare it (by giving tithes)? <span class=\"citation\">Keth. 20ᵃ</span> <span dir=\"rtl\">ומַנְשֵׁי חר וכ׳</span> and one of the witnesses has forgotten (that he knows of the case). <span class=\"citation\">Ḥull. 93ᵇ</span> <span dir=\"rtl\">אַנְשְׁיוּהָ לדר׳ וכ׳</span> they have forgotten R. Judah’s opinion. <span class=\"citation\">Gen. R. s. 77</span> <span dir=\"rtl\">דילמא אַנְשִׁינָן כלום</span> perhaps we forgot something (left behind). <span class=\"citation\">Gen. R. s. 78</span> אַנְשִׁית מאה I forgot one hundred (of the fables); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to cause to forget</i>. <span class=\"citation\">Targ. Lam. II, 6</span> (ed. Vien. <a href=\"#\" data-headword=\"נְשֵׁי\">אינשי</a>, corr. acc.); a. e.</div></div><div class=\"sense\"><b>Ithpe. אִתְנְשֵׁי  אִינְּשֵׁי</b> <div class=\"sense\"><i>to forget</i>. <span class=\"citation\">Targ. O. Deut. VIII, 19</span> (v. supra); a. e.—Y. Shek. VII, 50ᶜ bot. <span dir=\"rtl\">ואִינְשְׁתָהּ</span> and forgot to take it out; a. e.</div></div>","alt":["נְשָּׁא"]},"20390":{"h":"נָשַׂח","r":"N01302","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָסַח\">נָסַח</a></div>","alt":[]},"20391":{"h":"נַשְׁיָא","r":"N01303","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"נָשֶׁה\">נָשֶׁה</a>. <span class=\"citation\">Targ. Gen. XXXII, 33</span> <span dir=\"rtl\">גידא דנ׳</span>.—<span class=\"citation\">Ḥull. 97ᵇ</span> <span dir=\"rtl\">גידא נ׳</span>, v. <a href=\"#\" data-headword=\"גִּידָא\">גִּידָא</a></div>","alt":[]},"20392":{"h":"נָשִׂיא","r":"N01304","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>prince, chief, ruler, officer</i>. <span class=\"citation\">Num. R. s. 1</span> <span dir=\"rtl\">לנ׳ שנכנס וכ׳</span> like unto a chief that entered a country. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שלא מנה נ׳ לשבט וכ׳</span> he appointed no prince for the tribe of Levi. [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">נשיא שבטים</span>, read <span dir=\"rtl\">נְשִׂיאֵי</span>]. <span class=\"citation\">Hor. II, 6</span>; a. v. fr.—Pl. <span dir=\"rtl\">נְשִׂיאִים</span>. <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">למה נזדרזו הנ׳ וכ׳</span> why were the princes so anxious to be the first &amp;c.? <span class=\"citation\">Num. R. s. 3</span>; a. v. fr.—Esp. <i>Nasi</i>, the chief of the Great Sanhedrin in Jerusalem and of its successor in Palestinian places (v. <a href=\"#\" data-headword=\"אַבָּא I\">אָב</a>). <span class=\"citation\">Taan. II, 1</span>. <span class=\"citation\">Pes. 66ᵃ</span> <span dir=\"rtl\">מינוהו נ׳ עליהם</span> they elected him as their Nasi; a. fr.—R. Judah the Nasi, v. <a href=\"#\" data-headword=\"רַבִּי\">רַבִּי</a>.—<i>Pl.</i> as ab. <span class=\"citation\">Ḥag. II, 2</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>pl.</i> as ab. <i>clouds</i>. <span class=\"citation\">Kidd. 32ᵇ</span> <span dir=\"rtl\">להק&quot;בה … מעלה נ׳ וכ׳</span></div>","alt":[]},"20393":{"h":"נְשִׂיאָה I","r":"N01305","html":"<div class=\"sense\">, <i>prince, Nasi</i>. <span class=\"citation\">Ḥull. 98ᵃ</span> a. fr. <span dir=\"rtl\">דבי נ׳</span> those of the Nasi’s (R. Judah’s) house. <span class=\"citation\">Ib. 124ᵃ</span> <span dir=\"rtl\">חתניה דבי נ׳</span> the son-in-law of the Nasi’s (the Resh Gelutha’s) house. <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> bot. <span dir=\"rtl\">אין אנא מתעביד נ׳</span> if I am made Nasi; a. fr.—<span class=\"citation\">Y. Erub. VII, end, 24ᵈ</span> <span dir=\"rtl\">ר׳ יודן נסייא</span>.</div>","alt":["נְשִׂיָּיא","נְשִׂיָּיה","נְסִ׳"]},"20394":{"h":"נְשִׂיאָה II","r":"N01306","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>) </div><div class=\"sense\"><b>1)</b> <i>lifting up</i>; <span dir=\"rtl\">נְשִׂיאַת כפים</span> <i>pronouncing the priestly benediction</i>, v. <a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>, a. <a href=\"#\" data-headword=\"כַּף\">כַּף</a>. <span class=\"citation\">Taan. 26ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>carrying, loading</i>. <span class=\"citation\">Ex. R. s. 4</span>, v. <a href=\"#\" data-headword=\"עֲמִיסָה\">עֲמִיסָה</a>. <span class=\"citation\">Gen. R. s. 89</span> (ref. to <span class=\"citation\">Ps. LXXII, 3</span>) <span dir=\"rtl\">נשאו הרים נְשִׂיאָתָן וכ׳</span> when the mountains bear their load (of fruits), there is peace for the people.—3) <span dir=\"rtl\">נְשִׂיאַת ראש</span> <i>taking the sum, census</i>. <span class=\"citation\">Num. R. s. 6</span> (ref. to <span class=\"citation\">Num. IV, 2</span>, sq.) <span dir=\"rtl\">למה הקדים … לנ׳ ר׳</span> why does the Biblical text give Kehath the first place in taking the census?; v. <a href=\"#\" data-headword=\"נְשִׂיאוּת\">next w.</a></div>","alt":[]},"20395":{"h":"נְשִׂיאוּת","r":"N01307","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>, v. <a href=\"#\" data-headword=\"נְשִׂיאָה II\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>lifting, carrying</i>. <span class=\"citation\">Num. R. s. 6</span> <span dir=\"rtl\">נאמר בהן נ׳ ראש</span> the expression ‘lifting up the head’ (<span class=\"citation\">Num. IV, 1</span>; <span class=\"citation\">21</span>; v. <a href=\"#\" data-headword=\"נְשִׂיאָה II\">preced.</a>) is used in connection with them. Ib. <span dir=\"rtl\">נ׳ ראש של בני קהת … בנ׳ הארון</span> the taking the census of the sons of Kehath (v. <a href=\"#\" data-headword=\"נְשִׂיאָה II\">preced.</a>) is not made dependent on their genealogical descent but on their office of carrying the Ark. <span class=\"citation\">Num. R. s. 16</span> (ref. to <span class=\"citation\">Ps. CVI, 26</span>, a. <span class=\"citation\">Num. XIV, 1</span>) <span dir=\"rtl\">נ׳ יד כנגד נ׳ קול</span> lifting up the hand (for oath) against lifting up the voice (for murmuring).—נ׳ עון <i>carrying sin, responsibility</i>. <span class=\"citation\">Tosef. Shebu. III, 4</span> (ref. to <span class=\"citation\">Lev. V, 1</span>) <span dir=\"rtl\">תלה הכתוב נ׳ ע׳ וכ׳</span> the text makes the responsibility dependent on the telling. <span class=\"citation\">Y. Ter. I, 40ᶜ</span> bot. (ref. to <span class=\"citation\">Num. XVIII, 32</span>) <span dir=\"rtl\">את שהוא בנ׳ ע׳ וכ׳</span> only he who is responsible can separate T’rumah; ib. II, end, 41ᵈ <span dir=\"rtl\">ממה שהוא בנ׳ ע׳ וכ׳</span> from the fact that he is made responsible, you learn that his act is valid. <span class=\"citation\">Y. Shebu. I, 33ᵃ</span> bot.; a. e.—2) (denom. of <a href=\"#\" data-headword=\"נָשִׂיא\">נָשִׂיא</a>) <i>elevation to office, dignity</i>. <span class=\"citation\">Num. R. s. 4</span> (ref. to <span class=\"citation\">Num. IV, 2</span>) <span dir=\"rtl\">אינו אומר פקוד … לשון נ׳</span> the text does not read <i>p’ḳod</i>, but <i>naso</i> …, which expresses elevation; <span dir=\"rtl\">קבלו נ׳ מתוך וכ׳</span> they were given a superiority over the other sons of Levi.—Esp. <i>the office of the Nasi</i>. <span class=\"citation\">Keth. 103ᵇ</span> <span dir=\"rtl\">נהוג נְשִׂיאוּתְךָ וכ׳</span>, v. <a href=\"#\" data-headword=\"דָּמִים\">דָּמִים</a>. <span class=\"citation\">Sabb. 15ᵃ</span> <span dir=\"rtl\">נהגו נְשִׂיאוּתָן וכ׳</span> occupied their office &amp;c.; a. e.</div>","alt":[]},"20396":{"h":"נְשִׂיאוּתָא","r":"N01308","html":"<div class=\"sense\">, <i>the office of the Nasi, the house of the Nasi</i>. <span class=\"citation\">Y. Pes. VI, 33ᵃ</span> bot. <span dir=\"rtl\">דשרון גרמון מן נ׳ וכ׳</span> who resigned from the Nasiate and appointed him (Hillel) &amp;c.; <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> <span dir=\"rtl\">מנשיאותיה</span> (corr. acc.) Y. Sabb. XII, 93ᶜ bot. <span dir=\"rtl\">אתחתנון בנ׳</span> they married into the Nasi family. Y. Peah III, 21ᵃ bot. <span class=\"citation\">Y. Kil. IX, 32ᵃ</span> bot. <span dir=\"rtl\">ביתא דנְשִׂיּוּתָה הוא משועבד הוא לנישיותה</span> it is the Nasi’s official residence, and is pledged to those who occupy the office (and the widow must leave); <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> top <a href=\"#\" data-headword=\"נשוותא\">נשוותא</a> (corr. acc.); <span class=\"citation\">Gen. R. s. 100</span>. <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> <span dir=\"rtl\">אילין דנַשְׂיָתָא</span> those of the family of the Nasi. <span class=\"citation\">Y. Sot. IX, end, 24ᶜ</span> <span dir=\"rtl\">ניסיותיה</span> (corr. acc.), v. <a href=\"#\" data-headword=\"חֲתַן\">חֲתַן</a>.</div>","alt":["נְשִׂיּיוּתָא","נְסִי׳"]},"20397":{"h":"נְשִׂיָּיא","r":"N01309","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְשִׂיאָה I\">נְשִׂיאָה</a></div>","alt":[]},"20398":{"h":"נְשַׁיָּיא","r":"N01310","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"נְשָׁא I\"><span dir=\"rtl\">נְשָׁא</span> I</a>.</div>","alt":[]},"20399":{"h":"נְשִׂיּיוּתָא","r":"N01311","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְשִׂיאוּתָא\">נְשִׂיאוּתָא</a></div>","alt":[]}};
